package com.osrstelemetry.plugin.events;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project.
 *
 * Covers TelemetryEventListener registration/notification directly
 * against the real EventLedger -- no mocking. This is also test letter
 * S from the wiring task's own list ("malformed/failed session
 * persistence -> telemetry ledger remains unaffected"), verified here
 * at its true source: a listener that throws must never affect the
 * durable write, since EventLedger is the one place that guarantee is
 * actually implemented.
 */
public class EventLedgerListenerTest
{
	private static final long TEST_ACCOUNT_HASH = 999_222_333L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;

	@Before
	public void setUp() throws Exception
	{
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	@Test
	public void addedListener_isNotifiedSynchronouslyOnAppend()
	{
		List<EventType> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(type));

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		// No sleep/await at all -- notifyListeners() runs synchronously on
		// the calling thread, before append() even returns (see
		// EventLedger's own javadoc); this must already be true the
		// instant append() returns, unlike the durable disk write below.
		assertEquals(1, seen.size());
		assertEquals(EventType.QUEST_COMPLETED, seen.get(0));
	}

	@Test
	public void addedListener_isNotifiedOnAppendAndWaitToo()
	{
		List<EventType> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(type));

		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.BOSS_KILL,
			new EventPayloads.BossKill("zulrah", "Zulrah", 1, "AUTHORITATIVE"), 2000);

		assertEquals(1, seen.size());
	}

	@Test
	public void removedListener_receivesNoFurtherEvents()
	{
		AtomicInteger count = new AtomicInteger();
		TelemetryEventListener listener = (accountHash, type, payload, observedAt) -> count.incrementAndGet();

		ledger.addListener(listener);
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));
		assertEquals(1, count.get());

		ledger.removeListener(listener);
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 2, 3, 20));
		assertEquals("a removed listener must never be notified again", 1, count.get());
	}

	@Test
	public void reAddingAfterRemove_stillReceivesExactlyOneNotificationPerEvent()
	{
		// Regression coverage for the exact class of bug this project's
		// own client-thread lifecycle audit already found for EventBus
		// registration: addListener() on every re-enable without a
		// matching removeListener() on disable would silently accumulate
		// duplicate listeners.
		AtomicInteger count = new AtomicInteger();
		TelemetryEventListener listener = (accountHash, type, payload, observedAt) -> count.incrementAndGet();

		ledger.addListener(listener);
		ledger.removeListener(listener);
		ledger.addListener(listener);

		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals("re-adding after a proper removal must never result in double notification", 1, count.get());
	}

	@Test
	public void listenerThatThrows_neverPreventsOrCorruptsTheDurableWrite() throws Exception
	{
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated session-persistence failure");
		});

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("the durable telemetry event must be written regardless of a failing listener", 1, lines.size());
	}

	@Test
	public void oneListenerThrowing_neverPreventsOtherListenersFromRunning()
	{
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated failure in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void listenerReceivesTheSameAccountHashTypeAndPayloadPassedToAppend()
	{
		List<Object[]> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(new Object[] {accountHash, type, payload, observedAt}));

		EventPayloads.QuestCompleted payload = new EventPayloads.QuestCompleted(42, "A_QUEST", "A Quest");
		Instant before = Instant.now();
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED, payload);
		Instant after = Instant.now();

		assertEquals(1, seen.size());
		Object[] call = seen.get(0);
		assertEquals(TEST_ACCOUNT_HASH, call[0]);
		assertEquals(EventType.QUEST_COMPLETED, call[1]);
		assertTrue("the exact same payload instance must be passed through, never a copy", call[2] == payload);
		Instant observedAt = (Instant) call[3];
		assertTrue(!observedAt.isBefore(before) && !observedAt.isAfter(after));
	}

	@Test
	public void appendBeforeStart_neverNotifiesListeners()
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		AtomicInteger count = new AtomicInteger();
		neverStarted.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		neverStarted.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals(
			"an event that was never durably queued must never be reported to a session listener either",
			0, count.get());
	}

	@Test
	public void appendAfterShutdown_neverNotifiesListeners()
	{
		// ADVERSARIAL HARDENING PASS, item 13.B -- this is the structural
		// proof of the enforced order, not just an exception-catching
		// test. EventLedger.append() now submits the durable write FIRST
		// and only calls notifyListeners() if that submission succeeds
		// (see EventLedger's own ordering comment). Once shutdown() has
		// been called, executor.submit() throws RejectedExecutionException
		// and append() returns before notifyListeners() is ever reached.
		// If the old (buggy) order were still in place -- notify first,
		// submit second -- this listener WOULD still fire even though the
		// write itself is rejected, since nothing about calling the
		// listener depends on the executor at all. This test can only
		// pass under the fixed order.
		AtomicInteger count = new AtomicInteger();
		ledger.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		ledger.shutdown();

		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals(
			"a durable write that was rejected (executor shut down) must never reach a session listener either -- "
				+ "proves submit-then-notify ordering, not just that exceptions are caught",
			0, count.get());
	}

	@Test
	public void appendAndWaitAfterShutdown_neverNotifiesListenersAndReturnsFalse()
	{
		// Same structural proof as above, for appendAndWait(): the
		// RejectedExecutionException path returns false immediately,
		// before notifyListeners() is reached.
		AtomicInteger count = new AtomicInteger();
		ledger.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		ledger.shutdown();

		boolean result = ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 10), 2000);

		assertEquals("a rejected durable write must report failure to the caller", false, result);
		assertEquals(
			"a durable write that was rejected (executor shut down) must never reach a session listener either",
			0, count.get());
	}

	@Test
	public void listenerObservesEventBeforeAppendReturns_confirmingSynchronousNotificationAfterAcceptance()
	{
		// Confirms the OTHER half of the contract: when durable acceptance
		// DOES succeed (the normal case), notification is still
		// synchronous on the calling thread -- a session listener does
		// not need to poll or wait for a separate async callback. This
		// combined with the two tests above pins down the full order:
		// build envelope -> durable accept (submit) -> notify, all before
		// append()/appendAndWait() return to the caller.
		List<EventType> seenBeforeReturnCheck = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seenBeforeReturnCheck.add(type));

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(7, "B_QUEST", "B Quest"));

		assertEquals("notification must have already happened by the time append() returns",
			1, seenBeforeReturnCheck.size());
	}

	@Test
	public void listenerThatThrowsAssertionError_neverPropagatesOutOfAppend() throws Exception
	{
		// TARGETED CORRECTNESS AUDIT, item 2: AssertionError extends
		// Error, NOT RuntimeException -- the original bug description
		// specifically called out that the old `catch (RuntimeException
		// e)` would NOT have caught this. This project has hit real
		// AssertionErrors during RuneLite development (per the audit
		// request), so this is not a theoretical case. If
		// notifyListeners() only caught RuntimeException, this
		// append() call would throw AssertionError right back out to
		// US -- the simulated collector -- which is exactly the failure
		// this test proves does not happen: append() must return
		// normally, and the durable write must still land on disk.
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated session-runtime bug, not a RuntimeException");
		});

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("an AssertionError thrown by a listener must never prevent the durable write either",
			1, lines.size());
	}

	@Test
	public void listenerThatThrowsAssertionError_neverPropagatesOutOfAppendAndWaitAndDurableResultUnaffected()
	{
		// Same proof as above, for appendAndWait() specifically: the
		// listener's AssertionError must not propagate to the collector
		// AND must not change the durable result the collector is
		// waiting on (the future's own outcome was already decided in
		// step (1), before notifyListeners() ever ran -- see
		// EventLedger's own updated ordering javadoc).
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated session-runtime bug in a shutdown-critical caller's listener");
		});

		boolean result = ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.BOSS_KILL,
			new EventPayloads.BossKill("zulrah", "Zulrah", 1, "AUTHORITATIVE"), 2000);

		assertEquals("a listener's AssertionError must never affect the durable write's own success result",
			true, result);
	}

	@Test
	public void oneListenerThrowingAssertionError_neverPreventsOtherListenersFromRunning()
	{
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated bug in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void laterListenerStillRunsAfterAnEarlierOneThrowsRuntimeException()
	{
		// FINAL CORRECTION PASS: explicit "later listeners still run"
		// coverage for the RuntimeException case, matching the same
		// already-existing coverage for AssertionError below.
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated failure in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void listenerThatThrowsAFatalVirtualMachineError_isNotSwallowed()
	{
		// FINAL CORRECTION PASS: proves the narrowed catch boundary.
		// notifyListeners() now deliberately re-throws VirtualMachineError/
		// ThreadDeath rather than logging-and-swallowing them (see
		// EventLedger's own updated javadoc for the reasoning). A real
		// OutOfMemoryError/StackOverflowError can't be safely triggered
		// on demand in a test, so this uses a minimal anonymous
        // VirtualMachineError subclass -- a real, genuine instance of the
		// exact type the boundary is defined against, without actually
		// destabilizing the test JVM -- as the representative fatal case.
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new VirtualMachineError("simulated fatal JVM condition") {};
		});

		boolean propagated;
		try
		{
			ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
				new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));
			propagated = false;
		}
		catch (VirtualMachineError expected)
		{
			propagated = true;
		}

		assertTrue("a genuine VirtualMachineError thrown by a listener must propagate out of append(), "
			+ "not be logged and silently suppressed", propagated);
	}

	private void awaitQuiescence() throws InterruptedException
	{
		TimeUnit.MILLISECONDS.sleep(200);
	}
}

package com.osrstelemetry.plugin.events;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — this environment has no network access to
 * pull the RuneLite client jar this test compiles against (see
 * plugin/README.md). Run with `./gradlew test` locally as part of the
 * verification pass.
 *
 * Covers what's actually feasible to unit-test here: file-level
 * behavior of the ledger itself (unique IDs, one valid JSON object per
 * line, session ID stability within a run). It deliberately does not
 * try to test collector -> event routing, since that needs a live
 * Client/EventBus, which belongs in integration/manual testing instead
 * of being mocked into a false sense of coverage here.
 *
 * appendAndWait() TESTS: added
 * alongside the new synchronous/waitable append primitive introduced to
 * fix a bug where a fire-and-forget append() could be
 * dropped if EventLedger.shutdown() ran before its graceful drain
 * window got a chance to complete the queued write. These exercise
 * appendAndWait()'s actual success/rejection lifecycle end to end
 * (real file I/O, real executor), not just its return type.
 */
public class EventLedgerTest
{
	private static final long TEST_ACCOUNT_HASH = 999_000_111L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;

	@Before
	public void setUp() throws Exception
	{
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		// EventLedger now requires
		// start() before append() will do anything (see its
		// lifecycle javadoc) — this test was calling append() against
		// a ledger that had never been started, which is not how the
		// plugin actually uses it (start() is called from
		// OsrsTelemetryPlugin.startUp()).
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	@Test
	public void appendedEventsHaveUniqueIds() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332));
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 70, 71, 737627));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(2, lines.size());

		JsonObject first = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		JsonObject second = new JsonParser().parse(lines.get(1)).getAsJsonObject();

		assertNotEquals(
			"Two distinct events must never share an eventId — this is the entire idempotency mechanism",
			first.get("eventId").getAsString(),
			second.get("eventId").getAsString()
		);
	}

	@Test
	public void everyLineIsExactlyOneValidJsonObjectWithRequiredEnvelopeFields() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2343, "DESERT_TREASURE_II__THE_FALLEN_EMPIRE", "Desert Treasure II - The Fallen Empire"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());

		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		assertTrue(event.has("eventId"));
		assertTrue(event.has("accountHash"));
		assertTrue(event.has("eventType"));
		assertTrue(event.has("occurredAt"));
		assertTrue(event.has("sessionId"));
		assertTrue(event.has("schemaVersion"));
		assertEquals("QUEST_COMPLETED", event.get("eventType").getAsString());
	}

	@Test
	public void sessionIdIsStableWithinARunAndChangesOnNewSession() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "QUEST_A", "Quest A"));
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2, "QUEST_B", "Quest B"));
		awaitQuiescence();

		ledger.startNewSession();
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(3, "QUEST_C", "Quest C"));
		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		String sessionA = new JsonParser().parse(lines.get(0)).getAsJsonObject().get("sessionId").getAsString();
		String sessionB = new JsonParser().parse(lines.get(1)).getAsJsonObject().get("sessionId").getAsString();
		String sessionC = new JsonParser().parse(lines.get(2)).getAsJsonObject().get("sessionId").getAsString();

		assertEquals("Events within one session must share a sessionId", sessionA, sessionB);
		assertNotEquals("startNewSession() must actually produce a new session id", sessionB, sessionC);
	}

	@Test
	public void appendBeforeStartIsSafeNoOp() throws Exception
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		neverStarted.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332));
		awaitQuiescence();

		assertTrue(
			"append() before start() must not produce a file",
			!TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH).exists()
		);
	}

	@Test
	public void enableDisableEnableCycleProducesAWorkingLedgerEachTime() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 100));
		ledger.shutdown();

		// Re-start (simulates plugin disable -> re-enable within one
		// client process) — must not throw and must still work.
		ledger.start();
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 2, 3, 300));
		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("both the pre- and post-restart appends must have been written", 2, lines.size());
	}

	// =====================================================================
	// appendAndWait() — synchronous/waitable append primitive
	// (bank-snapshot shutdown-durability pass)
	// =====================================================================

	@Test
	public void appendAndWait_returnsTrueAndEventIsOnDiskBeforeItReturns() throws Exception
	{
		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("MINING", 50, 51, 123456), 2000);

		assertTrue("appendAndWait() must report success for a normal append", success);

		// No awaitQuiescence() sleep here at all — the entire point of
		// appendAndWait() is that the event is already durable the
		// instant it returns.
		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());
		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		assertEquals("LEVEL_UP", event.get("eventType").getAsString());
	}

	@Test
	public void appendAndWait_buildsTheSameEnvelopeShapeAsAppend() throws Exception
	{
		ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(9001, "A_QUEST", "A Quest"), 2000);

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());
		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();

		assertTrue(event.has("eventId"));
		assertTrue(event.has("accountHash"));
		assertTrue(event.has("eventType"));
		assertTrue(event.has("occurredAt"));
		assertTrue(event.has("sessionId"));
		assertTrue(event.has("schemaVersion"));
	}

	@Test
	public void appendAndWait_beforeStartReturnsFalseAndWritesNothing() throws Exception
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		boolean success = neverStarted.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 1, 2, 10), 2000);

		assertFalse("appendAndWait() before start() must report failure, not success", success);
		assertFalse(
			"appendAndWait() before start() must not produce a file",
			TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH).exists()
		);
	}

	@Test
	public void appendAndWait_afterShutdownReturnsFalseAndWritesNothing() throws Exception
	{
		ledger.shutdown();

		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 10), 2000);

		assertFalse("appendAndWait() must report failure once the ledger has been shut down", success);
	}

	@Test
	public void appendAndWait_ordersConsistentlyWithOrdinaryAppendOnTheSameLedger() throws Exception
	{
		// append() (async) followed immediately by appendAndWait() —
		// both go through the SAME single-writer executor, so
		// appendAndWait() returning must mean append()'s event landed
		// first (submission order == disk order for one writer thread).
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "FIRST", "First"));
		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2, "SECOND", "Second"), 2000);

		assertTrue(success);

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(2, lines.size());
		JsonObject firstPayload = new JsonParser().parse(lines.get(0)).getAsJsonObject().getAsJsonObject("payload");
		JsonObject secondPayload = new JsonParser().parse(lines.get(1)).getAsJsonObject().getAsJsonObject("payload");
		assertEquals("First", firstPayload.get("questName").getAsString());
		assertEquals("Second", secondPayload.get("questName").getAsString());
	}

	@Test
	public void appendAndWait_enableDisableEnableCycleStillWorksEachTime() throws Exception
	{
		assertTrue(ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 100), 2000));

		ledger.shutdown();
		ledger.start();
		ledger.startNewSession();

		assertTrue(ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 2, 3, 300), 2000));

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("both the pre- and post-restart appendAndWait() calls must have succeeded and persisted", 2, lines.size());
	}

	private void awaitQuiescence() throws InterruptedException
	{
		// The ledger's writer executor is a single background thread;
		// give it a moment to drain rather than asserting immediately
		// after a fire-and-forget append().
		TimeUnit.MILLISECONDS.sleep(200);
	}
}

package com.osrstelemetry.plugin.storage;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.nio.file.Files;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere.
 *
 * Covers: the plugin can be enabled, disabled, and
 * re-enabled within one client process without a RejectedExecutionException
 * or a dead writer, and shutdown() actually drains queued writes
 * rather than dropping them.
 */
public class LocalStateStoreTest
{
	/**
	 * FIX: plain Java, no Lombok — the test source set doesn't have
	 * Lombok on its compile classpath (real javac error: "package
	 * lombok does not exist"), and production dependency
	 * configuration is intentionally left alone rather than churned
	 * just to make a test fixture compile.
	 */
	private static class Doc
	{
		private String value;

		public Doc()
		{
		}

		public Doc(String value)
		{
			this.value = value;
		}

		public String getValue()
		{
			return value;
		}

		public void setValue(String value)
		{
			this.value = value;
		}
	}

	private static final Gson TEST_GSON = new Gson();

	private File targetFile;

	@Before
	public void setUp()
	{
		targetFile = new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-test-" + System.nanoTime() + ".json");
	}

	@After
	public void tearDown()
	{
		targetFile.delete();
		new File(targetFile.getParentFile(), targetFile.getName() + ".tmp").delete();
	}

	@Test
	public void writeBeforeStartIsSafeNoOp() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		// Deliberately not calling start() — simulates a caller bug,
		// which must not throw.
		store.write(TestFilepaths.fromFile(targetFile), new Doc("should not be written"));
		TimeUnit.MILLISECONDS.sleep(100);
		assertFalse("write before start() must not produce a file", targetFile.exists());
	}

	@Test
	public void writeAfterShutdownIsSafeNoOp() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();
		store.shutdown();

		store.write(TestFilepaths.fromFile(targetFile), new Doc("should not be written either"));
		TimeUnit.MILLISECONDS.sleep(100);
		assertFalse("write after shutdown() must not produce a file", targetFile.exists());
	}

	@Test
	public void shutdownDrainsQueuedWrites() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("hello"));
		// No sleep — shutdown() itself is what must wait for this
		// queued write to complete before returning.
		store.shutdown();

		assertEquals("hello", readValue(targetFile));
	}

	@Test
	public void enableDisableEnableCycleProducesAWorkingStoreEachTime() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);

		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("first"));
		store.shutdown();
		assertEquals("first", readValue(targetFile));

		// Re-enable — this must not throw RejectedExecutionException,
		// and must produce a live writer again.
		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("second"));
		store.shutdown();
		assertEquals("second", readValue(targetFile));
	}

	@Test
	public void onWrittenCallbackDoesNotRunWhenTheWriteFails() throws Exception
	{
		// A write to a target whose
		// parent directory does not exist must fail (writeNow()
		// returns false), and the dependent callback must NOT run —
		// this is exactly the bug that could have let a BANK_SNAPSHOT
		// event reference a file that never reached disk.
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();

		File badTarget = new File(
			new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-nonexistent-" + System.nanoTime()),
			"file.json"
		);

		final boolean[] callbackRan = {false};
		store.write(TestFilepaths.fromFile(badTarget), new Doc("irrelevant"), () -> callbackRan[0] = true);
		TimeUnit.MILLISECONDS.sleep(200);

		assertFalse("write to a path with a missing parent directory must fail", badTarget.exists());
		assertFalse("onWritten must not run when the write failed", callbackRan[0]);

		store.shutdown();
	}

	@Test
	public void writeAndWaitReturnsFalseOnFailureAndTrueOnSuccess() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();

		File badTarget = new File(
			new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-nonexistent-" + System.nanoTime()),
			"file.json"
		);
		assertFalse(store.writeAndWait(TestFilepaths.fromFile(badTarget), new Doc("irrelevant"), 1000));
		assertTrue(store.writeAndWait(TestFilepaths.fromFile(targetFile), new Doc("ok"), 1000));
		assertEquals("ok", readValue(targetFile));

		store.shutdown();
	}

	private String readValue(File file) throws Exception
	{
		String json = new String(Files.readAllBytes(file.toPath()));
		// Cheap extraction, avoids pulling Gson into the test just to
		// read one field back.
		int start = json.indexOf(':') + 1;
		return json.substring(start).replaceAll("[\"{}\\s]", "");
	}
}

package com.osrstelemetry.plugin.storage;

import java.io.File;
import java.nio.file.Path;
import net.runelite.client.util.Filepath;

/**
 * Test-only Filepath construction/bridging.
 *
 * Filepath.Unchecked is deliberately confined to this test helper.
 * Production code must obtain Filepath instances through RuneLite's
 * supported plugin-directory/Filepath APIs.
 */
public final class TestFilepaths
{
    private TestFilepaths()
    {
    }

    public static Filepath rooted(Path path)
    {
        return Filepath.Unchecked.getRooted(path.toAbsolutePath().normalize());
    }

    public static Path path(Filepath filepath)
    {
        return Filepath.Unchecked.getPath(filepath);
    }

    public static File file(Filepath filepath)
    {
        return Filepath.Unchecked.getFile(filepath);
    }

    /**
     * Wrap an ordinary test-fixture File while keeping its parent as the
     * Filepath root. This allows production code under test to access sibling
     * temp files without exposing anything outside the fixture directory.
     */
    public static Filepath fromFile(File file)
    {
        Path path = file.toPath().toAbsolutePath().normalize();
        Path parent = path.getParent();

        if (parent == null)
        {
            throw new IllegalArgumentException("Test file must have a parent: " + file);
        }

        return Filepath.Unchecked.getRooted(parent)
            .joinSegment(path.getFileName().toString());
    }
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.LootTrackerSnapshot;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Covers the pure,
 * Swing-free static methods {@link LootTrackerView} exposes specifically
 * so the flashing/freeze fixes could be unit-tested without constructing
 * any JPanel/JScrollPane: {@link LootTrackerView#computeRenderKey} (the
 * presentation fingerprint that lets {@code render()} skip a
 * {@code removeAll()}/rebuild entirely when nothing visible changed),
 * {@link LootTrackerView#capRecords} and
 * {@link LootTrackerView#allowedIndividualCount} (the total
 * individual-record rendering budget), and
 * {@link LootTrackerView#truncateSourceName}/{@link LootTrackerView#buildHeaderSubtitleText}
 * (pure display-formatting helpers for the width fix and the
 * kill-count/GP-per-kill subtitle).
 *
 * Real {@link LootTrackerSnapshot.SourceEntry}/{@code RecordEntry}
 * instances are used throughout (both have private constructors reachable
 * only via {@link LootTrackerSnapshot#from}), never hand-rolled fakes --
 * same convention as {@code LootTrackerSnapshotTest}.
 */
public class LootTrackerViewTest
{
	private static final long TEST_ACCOUNT_HASH = 424_242_424L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final Gson TEST_GSON = new Gson();

	private LootTrackerPreferences preferences;
	private Path testRoot;

	@Before
public void setUp() throws Exception
{
testRoot = Files.createTempDirectory("loot-tracker-view-test");
TelemetryPaths.init(TestFilepaths.rooted(testRoot));
deleteAccountDir();
preferences = new LootTrackerPreferences(new LocalStateStore(TEST_GSON));
preferences.loadForAccount(TEST_ACCOUNT_HASH);
}

	@After
public void tearDown() throws Exception
{
deleteAccountDir();
Files.deleteIfExists(testRoot);
}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	private static LootTrackerRecord record(String eventId, String sourceName, Integer sourceId, Instant at, LootTrackerItem... items)
	{
		return new LootTrackerRecord(eventId, sourceName, sourceId, at, Arrays.asList(items));
	}

	private List<LootTrackerSnapshot.SourceEntry> twoSources()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 100)));
		index.apply(record("e2", "Gargoyles", 412, T0.plusSeconds(60), new LootTrackerItem(561, "Nature rune", 5)));
		return LootTrackerSnapshot.from(index, preferences).getAllSources();
	}

	private static String key(List<LootTrackerSnapshot.SourceEntry> sources, boolean favoritesOnly, boolean individualView, String searchText, boolean showHidden, long valuationVersion)
	{
		return LootTrackerView.computeRenderKey(sources, sources, favoritesOnly, individualView, searchText, showHidden, valuationVersion, Collections.emptyMap());
	}

	// ------------------------------------------------------------------
	// computeRenderKey
	// ------------------------------------------------------------------

	@Test
	public void computeRenderKey_sameInputs_produceEqualKeys()
	{
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String key1 = key(sources, false, false, "", false, 0L);
		String key2 = key(sources, false, false, "", false, 0L);

		assertEquals(key1, key2);
	}

	@Test
	public void computeRenderKey_differentSearchText_producesDifferentKey()
	{
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String key1 = key(sources, false, false, "", false, 0L);
		String key2 = key(sources, false, false, "scales", false, 0L);

		assertNotEquals(key1, key2);
	}

	@Test
	public void computeRenderKey_differentFavoritesOnlyFlag_producesDifferentKey_evenWithIdenticalSourceList()
	{
		// The SAME sources list object is passed both times -- proves the
		// All/Favorites tab distinction is captured by the flag itself
		// (needed for the totals-footer label, "Total:" vs "Favorites
		// total:"), not merely inferred from source-list content, which
		// would wrongly collapse to the same key when every source
		// happens to be favorited.
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String allKey = key(sources, false, false, "", false, 0L);
		String favoritesKey = key(sources, true, false, "", false, 0L);

		assertNotEquals(allKey, favoritesKey);
	}

	@Test
	public void computeRenderKey_differentIndividualViewFlag_producesDifferentKey()
	{
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String groupedKey = key(sources, false, false, "", false, 0L);
		String individualKey = key(sources, false, true, "", false, 0L);

		assertNotEquals(groupedKey, individualKey);
	}

	@Test
	public void computeRenderKey_differentShowHiddenFlag_producesDifferentKey()
	{
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String key1 = key(sources, false, false, "", false, 0L);
		String key2 = key(sources, false, false, "", true, 0L);

		assertNotEquals(key1, key2);
	}

	@Test
	public void computeRenderKey_differentValuationVersion_producesDifferentKey()
	{
		// Confirms an async GE/HA price resolution (ItemValuationCache's
		// own version counter, not part of LootTrackerSnapshot itself)
		// still forces a real rebuild on the next tick rather than being
		// permanently skipped once render-key skipping is in place.
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();

		String key1 = key(sources, false, false, "", false, 0L);
		String key2 = key(sources, false, false, "", false, 1L);

		assertNotEquals(key1, key2);
	}

	@Test
	public void computeRenderKey_reorderedSources_producesDifferentKey()
	{
		// A source being promoted to the top of its group (new drop)
		// must actually change the fingerprint -- otherwise the ordering
		// fix and the render-key skip would silently fight each other.
		List<LootTrackerSnapshot.SourceEntry> sources = twoSources();
		List<LootTrackerSnapshot.SourceEntry> reversed = new ArrayList<>(sources);
		Collections.reverse(reversed);

		String key1 = key(sources, false, false, "", false, 0L);
		String key2 = key(reversed, false, false, "", false, 0L);

		assertNotEquals(key1, key2);
	}

	@Test
	public void computeRenderKey_individualView_changeWithinCappedWindow_producesDifferentKey()
	{
		// Control for the "beyond cap" test below: a change to a RECENT
		// record (inside the rendered/fingerprinted window) must still be
		// detected, proving the cap doesn't just make the fingerprint
		// blind to everything.
		LootTrackerSnapshot.SourceEntry sourceA = buildSourceWithRecentItem(1L);
		LootTrackerSnapshot.SourceEntry sourceB = buildSourceWithRecentItem(2L);

		String keyA = key(Arrays.asList(sourceA), false, true, "", false, 0L);
		String keyB = key(Arrays.asList(sourceB), false, true, "", false, 0L);

		assertNotEquals(keyA, keyB);
	}

	@Test
	public void computeRenderKey_individualView_changeBeyondCapWindow_producesEqualKey()
	{
		// The direct regression test for the EDT-freeze fix: a source
		// with more than DEFAULT_INDIVIDUAL_REVEAL_PER_SOURCE records
		// only fingerprints (and LootTrackerView only ever renders) its
		// most recent revealed window -- so fingerprinting cost, like
		// rendering cost, never scales with a source's full historical
		// record count. Only the OLDEST record's timestamp differs
		// between the two builds (its item stays identical, so item
		// TOTALS -- unaffected by the cap -- are identical too); that
		// record falls outside the capped window, so the two keys must
		// be equal.
		int totalRecords = LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL_PER_SOURCE + 1;
		LootTrackerSnapshot.SourceEntry sourceA = buildSourceWithOldestRecordAt(T0.minusSeconds(1000), totalRecords);
		LootTrackerSnapshot.SourceEntry sourceB = buildSourceWithOldestRecordAt(T0.minusSeconds(500), totalRecords);

		String keyA = key(Arrays.asList(sourceA), false, true, "", false, 0L);
		String keyB = key(Arrays.asList(sourceB), false, true, "", false, 0L);

		assertEquals(keyA, keyB);
	}

	@Test
	public void computeRenderKey_individualView_loadMoreReveal_producesDifferentKey()
	{
		LootTrackerSnapshot.SourceEntry source = buildSourceWithOldestRecordAt(T0.minusSeconds(1000), LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL_PER_SOURCE + 1);
		List<LootTrackerSnapshot.SourceEntry> sources = Arrays.asList(source);

		Map<String, Integer> defaultReveal = Collections.emptyMap();
		Map<String, Integer> expandedReveal = new HashMap<>();
		expandedReveal.put(source.getSourceKey(), LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL_PER_SOURCE + LootTrackerView.INDIVIDUAL_REVEAL_INCREMENT);

		String keyBefore = LootTrackerView.computeRenderKey(sources, sources, false, true, "", false, 0L, defaultReveal);
		String keyAfter = LootTrackerView.computeRenderKey(sources, sources, false, true, "", false, 0L, expandedReveal);

		assertNotEquals(keyBefore, keyAfter);
	}

	@Test
	public void computeRenderKey_globalTotalChange_producesDifferentKey_evenWhenNotInFilteredSources()
	{
		// The Favorites tab shows a narrower `sources` list, but the
		// global total header (see LootTrackerView class javadoc) must
		// still reflect ALL sources -- a change to a non-favorited source
		// must still change the key while sitting on the Favorites tab.
		List<LootTrackerSnapshot.SourceEntry> allA = twoSources();
		List<LootTrackerSnapshot.SourceEntry> favoritesOnlyA = Collections.emptyList();

		LootTrackerIndex indexB = new LootTrackerIndex();
		indexB.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 999)));
		indexB.apply(record("e2", "Gargoyles", 412, T0.plusSeconds(60), new LootTrackerItem(561, "Nature rune", 5)));
		List<LootTrackerSnapshot.SourceEntry> allB = LootTrackerSnapshot.from(indexB, preferences).getAllSources();

		String keyA = LootTrackerView.computeRenderKey(favoritesOnlyA, allA, true, false, "", false, 0L, Collections.emptyMap());
		String keyB = LootTrackerView.computeRenderKey(favoritesOnlyA, allB, true, false, "", false, 0L, Collections.emptyMap());

		assertNotEquals(keyA, keyB);
	}

	private LootTrackerSnapshot.SourceEntry buildSourceWithRecentItem(long mostRecentQuantity)
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e0", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 1)));
		index.apply(record("e1", "Zulrah", 2042, T0.plusSeconds(1), new LootTrackerItem(2444, "Zulrah's scales", mostRecentQuantity)));
		return LootTrackerSnapshot.from(index, preferences).getAllSources().get(0);
	}

	private LootTrackerSnapshot.SourceEntry buildSourceWithOldestRecordAt(Instant oldestAt, int totalRecords)
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e0", "Zulrah", 2042, oldestAt, new LootTrackerItem(2444, "Zulrah's scales", 1)));
		for (int i = 1; i < totalRecords; i++)
		{
			index.apply(record("e" + i, "Zulrah", 2042, T0.plusSeconds(i), new LootTrackerItem(2444, "Zulrah's scales", 1)));
		}
		return LootTrackerSnapshot.from(index, preferences).getAllSources().get(0);
	}

	// ------------------------------------------------------------------
	// capRecords
	// ------------------------------------------------------------------

	@Test
	public void capRecords_withinCap_returnsSameListUnchanged()
	{
		List<LootTrackerSnapshot.RecordEntry> records = buildRecords(5);

		List<LootTrackerSnapshot.RecordEntry> capped = LootTrackerView.capRecords(records, 100);

		assertSame(records, capped);
	}

	@Test
	public void capRecords_exactlyAtCap_returnsSameListUnchanged()
	{
		List<LootTrackerSnapshot.RecordEntry> records = buildRecords(5);

		List<LootTrackerSnapshot.RecordEntry> capped = LootTrackerView.capRecords(records, 5);

		assertSame(records, capped);
	}

	@Test
	public void capRecords_beyondCap_returnsLastNInOriginalOldestFirstOrder()
	{
		List<LootTrackerSnapshot.RecordEntry> records = buildRecords(10);

		List<LootTrackerSnapshot.RecordEntry> capped = LootTrackerView.capRecords(records, 3);

		assertEquals(3, capped.size());
		// buildRecords(10) produces records at T0+0 .. T0+9, oldest first;
		// the last 3 (most recent) are T0+7, T0+8, T0+9, still oldest-first.
		assertEquals(T0.plusSeconds(7), capped.get(0).getObservedAt());
		assertEquals(T0.plusSeconds(8), capped.get(1).getObservedAt());
		assertEquals(T0.plusSeconds(9), capped.get(2).getObservedAt());
	}

	// ------------------------------------------------------------------
	// newestFirst (Loot Tracker Load More placement/ordering fix --
	// CONFIRMED live: Individual records rendered oldest-of-the-revealed-
	// window first instead of newest-first, with the Load More control
	// above them instead of below. This is the pure, Swing-independent
	// piece of that fix: capRecords()'s oldest-first output must be
	// reversed before display -- see newestFirst()'s own javadoc.)
	// ------------------------------------------------------------------

	@Test
	public void newestFirst_reversesOldestFirstInputToNewestFirst()
	{
		List<LootTrackerSnapshot.RecordEntry> oldestFirst = buildRecords(3);

		List<LootTrackerSnapshot.RecordEntry> newestFirst = LootTrackerView.newestFirst(oldestFirst);

		assertEquals(3, newestFirst.size());
		assertEquals(T0.plusSeconds(2), newestFirst.get(0).getObservedAt());
		assertEquals(T0.plusSeconds(1), newestFirst.get(1).getObservedAt());
		assertEquals(T0.plusSeconds(0), newestFirst.get(2).getObservedAt());
	}

	@Test
	public void newestFirst_composedWithCapRecords_showsNewestOfTheRevealedWindowFirst()
	{
		// The exact end-to-end shape buildIndividualDropsPanel() now
		// renders: capRecords() selects the most recent 3 of 10 (T0+7,
		// T0+8, T0+9, oldest-first), then newestFirst() reverses that
		// window for display -- T0+9 (newest overall) first, T0+7 (the
		// oldest of the currently-revealed window) last, exactly the
		// "newest record ... oldest currently revealed record" shape QA
		// specified.
		List<LootTrackerSnapshot.RecordEntry> records = buildRecords(10);
		List<LootTrackerSnapshot.RecordEntry> capped = LootTrackerView.capRecords(records, 3);

		List<LootTrackerSnapshot.RecordEntry> displayed = LootTrackerView.newestFirst(capped);

		assertEquals(T0.plusSeconds(9), displayed.get(0).getObservedAt());
		assertEquals(T0.plusSeconds(8), displayed.get(1).getObservedAt());
		assertEquals(T0.plusSeconds(7), displayed.get(2).getObservedAt());
	}

	@Test
	public void newestFirst_neverMutatesItsInput()
	{
		// capRecords() can return the ORIGINAL backing list unmodified
		// when already within the cap (see capRecords_withinCap_...
		// above) -- newestFirst() must never reorder that shared list out
		// from under any other reader of it.
		List<LootTrackerSnapshot.RecordEntry> records = buildRecords(3);
		List<LootTrackerSnapshot.RecordEntry> snapshotBeforeCall = new ArrayList<>(records);

		LootTrackerView.newestFirst(records);

		assertEquals(snapshotBeforeCall, records);
	}

	@Test
