	private static List<String> sourceNames(List<LootTrackerSnapshot.SourceEntry> sources)
	{
		List<String> names = new java.util.ArrayList<>();
		for (LootTrackerSnapshot.SourceEntry entry : sources)
		{
			names.add(entry.getSourceName());
		}
		return names;
	}

	/** Actual (unsorted) sourceKey order, as rendered -- use this to assert real ordering, never a sorted-vs-sorted comparison. */
	private static List<String> sourceKeys(List<LootTrackerSnapshot.SourceEntry> sources)
	{
		List<String> keys = new java.util.ArrayList<>();
		for (LootTrackerSnapshot.SourceEntry entry : sources)
		{
			keys.add(entry.getSourceKey());
		}
		return keys;
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

/**
 * Covers
 * {@link HistoryView#computeRenderKey} -- the pure, Swing-free
 * presentation fingerprint {@code render()} uses to skip a full rebuild
 * when the entry set on screen hasn't actually changed -- without
 * constructing the Swing view itself (this project has no Mockito, and
 * HistoryView needs SkillIconManager/ItemManager/ClientThread, none of
 * which can be faked here; same "test only the pure static methods"
 * convention LootTrackerViewTest already establishes).
 *
 * {@link #heightBoundedPanel_maximumHeightTracksPreferredHeight} and
 * {@link #heightBoundedPanel_widthStaysUnbounded} cover
 * {@link HistoryView#heightBoundedPanel}. Unlike the rest of this class,
 * {@code heightBoundedPanel} needs NO RuneLite dependency at all --
 * {@code JPanel}/{@code Dimension} are plain {@code javax.swing}/
 * {@code java.awt}, so this is a real, runnable, non-mocked test of the
 * exact behavior the fix depends on: that the returned panel's maximum
 * height always equals its OWN current preferred height (never a
 * hardcoded constant), while its maximum width stays unbounded so it
 * can still stretch to fill a row's width as before.
 */
public class HistoryViewTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static HistoryEntry buildEntry()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();
		return HistoryEntry.from(finalized);
	}

	@Test
	public void computeRenderKey_emptyList_isStableAndNotNull()
	{
		String key = HistoryView.computeRenderKey(Collections.emptyList());
		assertEquals(key, HistoryView.computeRenderKey(Collections.emptyList()));
	}

	@Test
	public void computeRenderKey_sameEntries_sameKey()
	{
		List<HistoryEntry> entries = Arrays.asList(buildEntry(), buildEntry());
		assertEquals(HistoryView.computeRenderKey(entries), HistoryView.computeRenderKey(entries));
	}

	@Test
	public void computeRenderKey_differentEntryCount_differentKey()
	{
		HistoryEntry entry = buildEntry();
		String keyOne = HistoryView.computeRenderKey(Collections.singletonList(entry));
		String keyTwo = HistoryView.computeRenderKey(Arrays.asList(entry, entry));
		assertNotEquals(keyOne, keyTwo);
	}

	@Test
	public void heightBoundedPanel_maximumHeightTracksPreferredHeight()
	{
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		panel.add(new JLabel("row content"));
		Dimension preferred = panel.getPreferredSize();

		assertEquals("maximum height must equal the panel's own current preferred height, never a hardcoded value",
			preferred.height, panel.getMaximumSize().height);
	}

	@Test
	public void heightBoundedPanel_widthStaysUnbounded()
	{
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		assertEquals(Integer.MAX_VALUE, panel.getMaximumSize().width);
	}

	@Test
	public void heightBoundedPanel_maximumHeightUpdatesWhenContentGrows()
	{
		// Regression guard for the exact bug this fixes: a card's maximum
		// height must track ITS OWN content (e.g. collapsed vs. expanded),
		// never stay pinned to whatever it happened to be at construction.
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		int heightBefore = panel.getMaximumSize().height;

		panel.add(new JLabel("<html>a fairly tall<br>multi-line<br>label</html>"));
		int heightAfter = panel.getMaximumSize().height;

		assertTrue("maximum height should grow to match new preferred height once content is added",
			heightAfter >= heightBefore);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionAggregates;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import com.osrstelemetry.plugin.session.SessionSnapshot;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import java.time.Instant;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat
 * documented across this project's other Java test files (see
 * SessionLifecycleEngineTest). Josh's own `.\gradlew.bat clean test`
 * run is what actually executes these.
 *
 * Pure tests for
 * {@link LootPricing}'s own arithmetic/ordering. Resolving an actual
 * unit price is CurrentSessionView's job (RuneLite's ItemManager,
 * exercised only by the real client) -- these tests supply a plain
 * lambda price lookup instead, exactly the seam LootPricing was split
 * out for (this project has no Mockito dependency). LootEntry
 * instances are obtained the same way CurrentSessionSnapshotTest
 * builds its own fixtures (a real SessionLifecycleEngine +
 * SessionSnapshot.capture()), since LootEntry's own constructor is
 * package-private to ui.model.
 */
public class LootPricingTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	// ------------------------------------------------------------------
	// Sorting is by TOTAL stack value, never unit price alone
	// -- the task's own "rune platebody (38k x 2 = 76k) outranks coins
	// (50k total)" example, under GE-sourced prices.
	// ------------------------------------------------------------------
	@Test
	public void valueAndSort_ordersByTotalStackValueDescending_underGeMode()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(995, "Coins", 50_000L),
			item(1127, "Rune platebody", 2L));

		Map<Integer, Long> gePrices = new HashMap<>();
		gePrices.put(995, 1L);
		gePrices.put(1127, 38_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> gePrices.getOrDefault(id, 0L));

		assertEquals(2, rows.size());
		assertEquals("Rune platebody", rows.get(0).getItemName());
		assertEquals(76_000L, rows.get(0).getTotalValue());
		assertEquals("Coins", rows.get(1).getItemName());
		assertEquals(50_000L, rows.get(1).getTotalValue());
	}

	// Same "total stack value, not unit price" rule, exercised again
	// under a completely different (High Alch) price source, so GE and
	// HA are each covered by their own test.
	@Test
	public void valueAndSort_ordersByTotalStackValueDescending_underHighAlchMode()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(561, "Nature rune", 40L),
			item(1201, "Amulet of glory", 1L));

		Map<Integer, Long> haPrices = new HashMap<>();
		haPrices.put(561, 90L);
		haPrices.put(1201, 3_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> haPrices.getOrDefault(id, 0L));

		// Nature rune: 40 x 90 = 3,600 -- outranks the single Amulet of
		// glory at 3,000.
		assertEquals(2, rows.size());
		assertEquals("Nature rune", rows.get(0).getItemName());
		assertEquals(3_600L, rows.get(0).getTotalValue());
		assertEquals("Amulet of glory", rows.get(1).getItemName());
		assertEquals(3_000L, rows.get(1).getTotalValue());
	}

	@Test
	public void valueAndSort_tiesBrokenByItemNameAscending()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(2, "Zulrah's scales", 100L),
			item(1, "Ancient shard", 100L));

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> 10L);

		assertEquals("Ancient shard", rows.get(0).getItemName());
		assertEquals("Zulrah's scales", rows.get(1).getItemName());
	}

	// ------------------------------------------------------------------
	// The compact total-session-loot-value figure.
	// ------------------------------------------------------------------
	@Test
	public void sumTotalValue_isTheSumOfEveryRow()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(995, "Coins", 1_000L),
			item(1127, "Rune platebody", 2L));

		Map<Integer, Long> gePrices = new HashMap<>();
		gePrices.put(995, 1L);
		gePrices.put(1127, 38_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> gePrices.getOrDefault(id, 0L));

		assertEquals(77_000L, LootPricing.sumTotalValue(rows));
	}

	// An unresolvable price (e.g. no GE listing) must never crash the
	// panel -- see LootPricing.safeLookup()'s own javadoc.
	@Test
	public void valueAndSort_unresolvableItemIsPricedAtZero_notSkipped()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(item(9999, "Mystery item", 5L));

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id ->
		{
			throw new RuntimeException("no price available");
		});

		assertEquals(1, rows.size());
		assertEquals(0L, rows.get(0).getTotalValue());
	}

	private static List<CurrentSessionSnapshot.LootEntry> lootEntries(SessionAggregates.LootItemAggregate... items)
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session session = engine.getCurrentSession();

		SessionAggregates.LootDropGroup group = new SessionAggregates.LootDropGroup();
		group.setSourceName("Gargoyle");
		group.setObservedAt(T0.toString());
		group.setItems(Arrays.asList(items));
		session.getAggregates().getLootDrops().add(group);

		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(SessionSnapshot.capture(session), T0);
		return snapshot.getLootEntries();
	}

	private static SessionAggregates.LootItemAggregate item(int itemId, String itemName, long quantity)
	{
		SessionAggregates.LootItemAggregate aggregate = new SessionAggregates.LootItemAggregate();
		aggregate.setItemId(itemId);
		aggregate.setItemName(itemName);
		aggregate.setQuantity(quantity);
		return aggregate;
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.CurrentSessionSectionOrder;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import java.awt.Component;
import java.awt.Container;
import java.util.Arrays;
import javax.swing.JLabel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import org.junit.Test;

/**
 * Current Session UI/config regressions: the empty-state text clipping fix
 * (real, headless Swing layout -- no RuneLite client needed, since the empty
 * state touches no ItemManager/SkillIconManager) and the XP / Loot order
 * setting.
 */
public class CurrentSessionViewTest
{
	private static final String EMPTY_TEXT = "Start playing normally and activity will appear here.";

	private static final OsrsTelemetryConfig DEFAULT_CONFIG = new OsrsTelemetryConfig()
	{
	};

	// ------------------------------------------------------------------
	// XP / Loot order
	// ------------------------------------------------------------------

	@Test
	public void sectionOrder_configDefault_isXpFirst_theExistingProductionOrder()
	{
		assertEquals(CurrentSessionSectionOrder.XP_FIRST, DEFAULT_CONFIG.currentSessionSectionOrder());
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(DEFAULT_CONFIG.currentSessionSectionOrder()));
	}

	@Test
	public void sectionOrder_xpFirst_placesXpBeforeLoot()
	{
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(CurrentSessionSectionOrder.XP_FIRST));
	}

	@Test
	public void sectionOrder_lootFirst_placesLootBeforeXp()
	{
		assertEquals(Arrays.asList(CurrentSessionView.Section.LOOT, CurrentSessionView.Section.XP),
			CurrentSessionView.orderedSections(CurrentSessionSectionOrder.LOOT_FIRST));
	}

	@Test
	public void sectionOrder_eachSectionRenderedExactlyOnce_nullFallsBackToProductionOrder()
	{
		for (CurrentSessionSectionOrder order : CurrentSessionSectionOrder.values())
		{
			assertEquals("both sections, each exactly once, for " + order, 2,
				CurrentSessionView.orderedSections(order).stream().distinct().count());
		}
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(null));
	}

	private static java.util.List<String> plan(CurrentSessionSectionOrder order, boolean hasXp, boolean hasLoot)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		CurrentSessionView.renderSections(CurrentSessionView.orderedSections(order),
			section -> section == CurrentSessionView.Section.XP ? hasXp : hasLoot,
			section -> out.add(section.name()),
			() -> out.add("GAP"));
		return out;
	}

	@Test
	public void sectionGap_exactlyOneBetweenSections_inBothOrders()
	{
		assertEquals(Arrays.asList("XP", "GAP", "LOOT"), plan(CurrentSessionSectionOrder.XP_FIRST, true, true));
		assertEquals(Arrays.asList("LOOT", "GAP", "XP"), plan(CurrentSessionSectionOrder.LOOT_FIRST, true, true));
		assertEquals(6, CurrentSessionView.SECTION_GAP);
	}

	@Test
	public void sectionGap_neverAddedWhenOnlyOneOrNoSectionRenders()
	{
		for (CurrentSessionSectionOrder order : CurrentSessionSectionOrder.values())
		{
			assertEquals(Arrays.asList("XP"), plan(order, true, false));
			assertEquals(Arrays.asList("LOOT"), plan(order, false, true));
			assertEquals(java.util.Collections.emptyList(), plan(order, false, false));
		}
	}

	@Test
	public void currentSessionLoot_stillUsesTheShared5ColumnGrid()
	{
		assertEquals(LootGridCell.GRID_COLUMNS, CurrentSessionView.LOOT_ITEMS_PER_ROW);
		assertEquals(5, LootGridCell.GRID_COLUMNS);
	}

	// ------------------------------------------------------------------
	// Empty-state clipping
	// ------------------------------------------------------------------

	/** Documents the root cause: Swing HTML scales CSS px by 1.3, so the old 180px div was ~233px wide. */
	@Test
	public void rootCause_oldFixedCssWidthLabel_isWiderThanTheSidebarContent()
	{
		JLabel old = new JLabel("<html><div style='text-align:center;width:180px;'>" + EMPTY_TEXT + "</div></html>");
		assertTrue("old label preferred width " + old.getPreferredSize().width + " exceeds the ~201px sidebar content width",
			old.getPreferredSize().width > 201);
	}

	private static WrappingHtmlLabel find(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof WrappingHtmlLabel)
			{
				return (WrappingHtmlLabel) c;
			}
			if (c instanceof Container)
			{
				WrappingHtmlLabel nested = find((Container) c);
				if (nested != null)
				{
					return nested;
				}
			}
		}
		return null;
	}

	private static void layoutTree(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layoutTree((Container) child);
			}
		}
	}

	@Test
	public void emptyState_textStaysInsideTheCardAndWraps_atRepresentativeSidebarWidths()
	{
		// 213 = RuneLite PluginPanel width (225) minus its 6px+6px padding;
		// plus narrower/wider cases -- behavior depends only on component width.
		for (int width : new int[] {150, 180, 213, 260})
		{
			CurrentSessionView view = new CurrentSessionView(null, null, null, DEFAULT_CONFIG, null);
			view.setSize(width, 600);
			layoutTree(view);
			layoutTree(view); // second pass: label height recomputed at the now-known width

			WrappingHtmlLabel label = find(view);
			assertNotNull("empty state must use the width-tracking label", label);
			Container content = label.getParent();
			int innerLeft = content.getInsets().left;
			int innerRight = content.getWidth() - content.getInsets().right;

			assertTrue("label must start inside the card at width " + width, label.getX() >= innerLeft);
			assertTrue("label must end inside the card at width " + width + " (x=" + label.getX()
				+ ", w=" + label.getWidth() + ", inner right=" + innerRight + ")", label.getX() + label.getWidth() <= innerRight);

			View html = (View) label.getClientProperty(BasicHTML.propertyKey);
			html.setSize(label.getWidth(), 0);
			assertTrue("wrapped text must fit the label's width at " + width,
				html.getMinimumSpan(View.X_AXIS) <= label.getWidth());
			assertTrue("label height must hold the wrapped text at " + width,
				label.getHeight() >= (int) html.getPreferredSpan(View.Y_AXIS));
		}
	}

	@Test
	public void emptyState_wrapsOntoMultipleLines_whenNarrow()
	{
		CurrentSessionView view = new CurrentSessionView(null, null, null, DEFAULT_CONFIG, null);
		view.setSize(150, 600);
		layoutTree(view);
		layoutTree(view);
		WrappingHtmlLabel label = find(view);
		JLabel oneLine = new JLabel(EMPTY_TEXT);
		oneLine.setFont(label.getFont());
		assertTrue("at 150px the message must wrap rather than overflow",
			label.getHeight() > oneLine.getPreferredSize().height);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import java.awt.Component;
import java.awt.Container;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import org.junit.Test;

/**
 * The remaining sidebar empty/help-state labels (History, Loot tab, Recent
 * Activity) use the shared WrappingHtmlLabel instead of the old fixed CSS
 * width:180px HTML (really ~233px in Swing, which clipped). Real headless
 * Swing layout -- same approach as CurrentSessionViewTest.
 */
public class EmptyStateWrappingTest
{
	private static final int[] WIDTHS = {150, 180, 213, 260};

	private static final OsrsTelemetryConfig DEFAULT_CONFIG = new OsrsTelemetryConfig()
	{
	};

	private static WrappingHtmlLabel find(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof WrappingHtmlLabel)
			{
				return (WrappingHtmlLabel) c;
			}
			if (c instanceof Container)
			{
				WrappingHtmlLabel nested = find((Container) c);
				if (nested != null)
				{
					return nested;
				}
			}
		}
		return null;
	}

	private static void layoutTree(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layoutTree((Container) child);
			}
		}
	}

	/** Lays the view out at `width` (twice: second pass sees the real parent width) and returns its wrapping label. */
	private static WrappingHtmlLabel layOut(Container view, int width)
	{
		view.setSize(width, 800);
		layoutTree(view);
		layoutTree(view);
		WrappingHtmlLabel label = find(view);
		assertNotNull("empty state must use the shared WrappingHtmlLabel", label);
		return label;
	}

	private static void assertFitsInsideParent(String what, WrappingHtmlLabel label, int width)
	{
		Container parent = label.getParent();
		int innerLeft = parent.getInsets().left;
		int innerRight = parent.getWidth() - parent.getInsets().right;
		assertTrue(what + ": label must start inside its container at " + width, label.getX() >= innerLeft);
		assertTrue(what + ": label must end inside its container at " + width + " (x=" + label.getX()
			+ ", w=" + label.getWidth() + ", inner right=" + innerRight + ")", label.getX() + label.getWidth() <= innerRight);

		View html = (View) label.getClientProperty(BasicHTML.propertyKey);
		html.setSize(label.getWidth(), 0);
		assertTrue(what + ": wrapped text must fit the label width at " + width,
			html.getMinimumSpan(View.X_AXIS) <= label.getWidth());
		assertTrue(what + ": label height must hold the wrapped text at " + width,
			label.getHeight() >= (int) html.getPreferredSpan(View.Y_AXIS));
		assertFalse(what + ": no fixed CSS width may remain in the label HTML", label.getText().contains("width:"));
	}

	private static void assertWrapsWhenNarrow(String what, Supplier<Container> viewFactory, int narrowWidth)
	{
		WrappingHtmlLabel label = layOut(viewFactory.get(), narrowWidth);
		JLabel oneLine = new JLabel("x");
		oneLine.setFont(label.getFont());
		assertTrue(what + ": text must wrap onto more lines (taller) at " + narrowWidth + "px",
			label.getHeight() > oneLine.getPreferredSize().height + label.getInsets().top + label.getInsets().bottom);
	}

	// ------------------------------------------------------------------ History

	private static Container historyEmpty()
	{
		return new HistoryView(null, null, null, DEFAULT_CONFIG, id -> { });
	}

	@Test
	public void historyEmptyState_staysInsideSidebar_atRepresentativeWidths()
	{
		for (int width : WIDTHS)
		{
			assertFitsInsideParent("History", layOut(historyEmpty(), width), width);
		}
	}

	@Test
	public void historyEmptyState_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("History", EmptyStateWrappingTest::historyEmpty, 150);
	}

	// ------------------------------------------------------------------ Loot tab

	/** Hosts the Loot tab's real empty-state label exactly the way render() does: in `content` (BoxLayout Y, 6px border). */
	private static Container lootEmpty(String message)
	{
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		content.add(LootTrackerView.emptyStateLabel(message));
		return content;
	}

	@Test
	public void lootTabEmptyStates_stayInsideSidebar_atRepresentativeWidths()
	{
		for (String message : new String[] {"No loot recorded yet.", "No favorited sources yet.", "No items match your search."})
		{
			for (int width : WIDTHS)
			{
				WrappingHtmlLabel label = layOut(lootEmpty(message), width);
				assertFitsInsideParent("Loot tab '" + message + "'", label, width);
				assertTrue("Loot tab keeps its 16px top padding", label.getInsets().top == 16);
			}
		}
	}

	@Test
	public void lootTabEmptyState_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("Loot tab", () -> lootEmpty("No items match your search."), 100);
	}

	// ------------------------------------------------------------------ Recent Activity

	@Test
	public void recentActivityPlaceholder_staysInsideSidebar_atRepresentativeWidths()
	{
		for (int width : WIDTHS)
		{
			assertFitsInsideParent("Recent Activity", layOut(new RecentActivityView(), width), width);
		}
	}

	@Test
	public void recentActivityPlaceholder_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("Recent Activity", RecentActivityView::new, 100);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.LoadoutProvenance;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionAggregates;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.time.Instant;
import java.util.Collections;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Covers
 * {@link HistoryDetailModel#from} -- the pure, Swing-free transform
 * {@link HistoryDetailView} renders -- without constructing any Swing
 * component, same convention {@code LootTrackerViewTest}/
 * {@code HistoryEntryTest} already establish for this codebase (this
 * project has no Mockito dependency, so RuneLite-injected types like
 * ItemManager/ClientThread are never faked; only pure, Swing-free logic
 * is unit tested directly).
 */
public class HistoryDetailModelTest
{
	private static final long TEST_ACCOUNT_HASH = 424_242_888L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");
	private static final Gson TEST_GSON = new Gson();

	@Before
	public void setUp()
	{
		deleteAccountDir();
	}

	@After
	public void tearDown()
	{
		deleteAccountDir();
	}

	private static void deleteAccountDir()
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static Session buildFinalizedSession()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		return engine.advanceTime(expiry).getFinalized();
	}

	@Test
	public void from_nullSession_returnsNull()
	{
		assertNull(HistoryDetailModel.from(null));
	}

	@Test
	public void from_validSession_carriesIdentityAndTiming()
	{
		Session session = buildFinalizedSession();

		HistoryDetailModel model = HistoryDetailModel.from(session);

		assertNotNull(model);
		assertEquals(session.getSessionId(), model.getSessionId());
		assertEquals(GARGOYLES, model.getActivityIdentity());
		assertEquals(session.getFinalizedAt(), model.getFinalizedAt());
		assertEquals(session.getAccumulatedActiveDurationMillis(), model.getAccumulatedActiveDurationMillis());
	}

	@Test
	public void from_xpRows_sortedDescendingByXpGained_zeroEntriesExcluded()
	{
		Session session = buildFinalizedSession();
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 500L);
		session.getAggregates().getXpGainedBySkill().put("STRENGTH", 1200L);
		session.getAggregates().getXpGainedBySkill().put("HITPOINTS", 0L);

		HistoryDetailModel model = HistoryDetailModel.from(session);

		assertEquals(2, model.getXpRows().size());
		assertEquals("STRENGTH", model.getXpRows().get(0).getSkill());
		assertEquals("SLAYER", model.getXpRows().get(1).getSkill());
		assertEquals(1700L, model.getTotalXpGained());
	}

	@Test
	public void from_lootDrops_summedAcrossGroupsByItemId()
	{
		Session session = buildFinalizedSession();
		SessionAggregates.LootDropGroup group1 = new SessionAggregates.LootDropGroup();
		group1.getItems().add(lootItem(526, "Bones", 1));
		SessionAggregates.LootDropGroup group2 = new SessionAggregates.LootDropGroup();
		group2.getItems().add(lootItem(526, "Bones", 2));
		group2.getItems().add(lootItem(995, "Coins", 40));
		session.getAggregates().getLootDrops().add(group1);
		session.getAggregates().getLootDrops().add(group2);

		HistoryDetailModel model = HistoryDetailModel.from(session);

		assertEquals("two drop GROUPS were observed, even though only two distinct item ids resulted", 2, model.getLootDropCount());
		assertEquals(2, model.getLootRows().size());
		long bonesQuantity = model.getLootRows().stream()
			.filter(row -> row.getItemId() == 526)
			.mapToLong(HistoryDetailModel.LootRow::getQuantity)
			.sum();
		assertEquals("bones from both groups must be summed into one row", 3L, bonesQuantity);
	}

	@Test
	public void from_noLoadoutAttached_bothLoadoutsUnavailable_neverNull()
	{
		Session session = buildFinalizedSession();

		HistoryDetailModel model = HistoryDetailModel.from(session);

		assertNotNull(model.getStartingLoadout());
		assertNotNull(model.getEndingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, model.getStartingLoadout().getProvenance());
		assertEquals(LoadoutProvenance.UNAVAILABLE, model.getEndingLoadout().getProvenance());
	}

	@Test
	public void from_loadoutPresent_passedThroughFromRealFinalizedSession() throws Exception
	{
		// Uses the real production persistence path (matches
		// SessionPersistenceLoadoutResolutionTest's own established
		// pattern) rather than Session's package-private setter, which
		// this ui-package test has no access to -- see Session's own
		// javadoc on why mutation is deliberately package-private.
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();
		try
		{
			// Recorded at -45s so it lands at-or-before the resolver's
			// target instant (T0 - 30s -- see
			// LoadoutResolver.STARTING_LOADOUT_TARGET_OFFSET), not merely
			// before T0 itself.
			LoadoutArchive archive = new LoadoutArchive();
			archive.record(T0.minusSeconds(45),
				Collections.singletonList(new StorageState.StorageItem(0, 995, "Coins", 500, null)),
				Collections.emptyList());
			SessionPersistence persistence = new SessionPersistence(store, archive);

			SessionLifecycleEngine engine = new SessionLifecycleEngine();
			engine.onQualifyingActivity(GARGOYLES, T0);
			Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
			engine.advanceTime(suspendedAt);
			Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
			Session finalized = engine.advanceTime(expiry).getFinalized();

			persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
			Thread.sleep(300);

			Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, finalized.getSessionId());
			HistoryDetailModel model = HistoryDetailModel.from(reloaded);

			assertNotNull(model.getStartingLoadout());
			assertEquals(LoadoutProvenance.PRE_START, model.getStartingLoadout().getProvenance());
			assertEquals(995, model.getStartingLoadout().getInventory().get(0).getItemId());
		}
		finally
		{
			store.shutdown();
		}
	}

	private static SessionAggregates.LootItemAggregate lootItem(int itemId, String name, long quantity)
	{
		SessionAggregates.LootItemAggregate item = new SessionAggregates.LootItemAggregate();
		item.setItemId(itemId);
		item.setItemName(name);
		item.setQuantity(quantity);
		return item;
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.time.Instant;
import java.util.Arrays;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Exercises
 * {@link LootTrackerPersistence#rebuild} against a REAL events.jsonl
 * file, written by the real {@link EventLedger} -- the same
 * "real file I/O, real executor" integration-style coverage
 * EventLedgerTest already established for this project's telemetry
 * ledger, extended here to the read-back/rebuild side nothing
 * previously exercised. Confirms: only SERVER_NPC_LOOT lines are
 * picked up (every other event type in the same file is correctly
 * ignored), eventId-based dedup survives a real rebuild, and the
 * retention cutoff excludes lines observed before it.
 */
public class LootTrackerPersistenceTest
{
	private static final long TEST_ACCOUNT_HASH = 999_222_444L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;
	private final LootTrackerPersistence persistence = new LootTrackerPersistence(TEST_GSON);

	@Before
	public void setUp() throws Exception
	{
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	private static EventPayloads.ServerNpcLoot loot(String sourceName, Integer sourceId, int itemId, String itemName, int qty)
	{
		return new EventPayloads.ServerNpcLoot(sourceName, sourceId,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(itemId, itemName, qty)));
	}

	@Test
	public void rebuild_onlyPicksUpServerNpcLootLines_ignoringEveryOtherEventType() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "QUEST_A", "Quest A"), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(1, applied);
		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(1, sources.size());
		assertEquals("Zulrah", sources.get(0).getSourceName());
	}

	@Test
	public void rebuild_missingEventsFile_yieldsEmptyIndex_noException()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(0, applied);
		assertTrue(index.snapshotSources().isEmpty());
	}

	@Test
	public void rebuild_preservesMultipleRecordsForTheSameSource_asDistinctAtomicEvents() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Gargoyle", 412, 561, "Nature rune", 5), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Gargoyle", 412, 561, "Nature rune", 3), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(2, applied);
		LootTrackerSource source = index.snapshotSources().get(0);
		assertEquals(2, source.getKillCount());
		assertEquals(8L, source.getItemTotals().get(0).getQuantity());
	}

	@Test
	public void rebuild_runTwiceAgainstTheSameIndex_isIdempotentViaEventIdDedup() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Vorkath", 8061, 1, "Dragonbone", 1), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int firstRun = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);
		int secondRun = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(1, firstRun);
		assertEquals(0, secondRun);
		assertEquals(1, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void rebuild_retentionCutoff_excludesRecordsObservedBeforeIt() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);

		// A cutoff strictly in the future excludes everything ever
		// appended so far -- confirms the retention bound actually
		// takes effect, without a fragile real-clock timing assumption.
		Instant farFuture = Instant.now().plusSeconds(3600);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, farFuture);

		assertEquals(0, applied);
		assertTrue(index.snapshotSources().isEmpty());
	}

	@Test
	public void rebuild_retentionCutoff_includesRecordsObservedAtOrAfterIt() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);

		Instant longAgo = Instant.now().minusSeconds(3600);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, longAgo);

		assertEquals(1, applied);
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Swing-independent coverage of {@link LootTrackerIndex} --
 * dedup, stable source identity (never merged), honest kill-count
 * semantics, and atomic per-record item-stack preservation. Plain
 * JUnit, no Mockito, matching this project's established test style.
 */
public class LootTrackerIndexTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");

	private static LootTrackerRecord record(String eventId, String sourceName, Integer sourceId, Instant at, LootTrackerItem... items)
	{
		return new LootTrackerRecord(eventId, sourceName, sourceId, at, Arrays.asList(items));
	}

	@Test
	public void apply_newRecord_createsSourceWithOneRecord()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		boolean applied = index.apply(record("e1", "Zulrah", 2042, T0,
			new LootTrackerItem(2444, "Zulrah's scales", 100)));

		assertTrue(applied);
		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(1, sources.size());
		assertEquals("Zulrah", sources.get(0).getSourceName());
		assertEquals(Integer.valueOf(2042), sources.get(0).getSourceId());
		assertEquals(1, sources.get(0).getKillCount());
	}

	@Test
	public void apply_duplicateEventId_dedupedAndSkipped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		LootTrackerRecord first = record("dup-1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 100));
		LootTrackerRecord duplicate = record("dup-1", "Zulrah", 2042, T0.plusSeconds(5), new LootTrackerItem(2444, "Zulrah's scales", 999));

		assertTrue(index.apply(first));
		assertFalse(index.apply(duplicate));

		LootTrackerSource source = index.snapshotSources().get(0);
		assertEquals(1, source.getKillCount());
		assertEquals(100L, source.getItemTotals().get(0).getQuantity());
	}

	@Test
	public void apply_nullEventId_neverDedupSkipped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		LootTrackerRecord a = record(null, "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 50));
		LootTrackerRecord b = record(null, "Zulrah", 2042, T0.plusSeconds(1), new LootTrackerItem(2444, "Zulrah's scales", 50));

		assertTrue(index.apply(a));
		assertTrue(index.apply(b));

		assertEquals(2, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void differentSourceIds_sameName_neverMerged()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Cave krystilia", 100, T0, new LootTrackerItem(1, "Bones", 1)));
		index.apply(record("e2", "Cave krystilia", 200, T0, new LootTrackerItem(1, "Bones", 1)));

		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(2, sources.size());
		assertFalse(sources.get(0).getSourceKey().equals(sources.get(1).getSourceKey()));
	}

	@Test
	public void nullSourceId_isItsOwnStableIdentity_distinctFromAnyRealId()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Goblin", null, T0, new LootTrackerItem(1, "Bones", 1)));
		index.apply(record("e2", "Goblin", 42, T0, new LootTrackerItem(1, "Bones", 1)));

		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(2, sources.size());
	}

	@Test
	public void sameSourceIdentity_recordsAccumulateAcrossMultipleApplyCalls()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Gargoyle", 412, T0, new LootTrackerItem(561, "Nature rune", 5)));
		index.apply(record("e2", "Gargoyle", 412, T0.plusSeconds(60), new LootTrackerItem(561, "Nature rune", 3)));
		index.apply(record("e3", "Gargoyle", 412, T0.plusSeconds(120), new LootTrackerItem(9, "Granite dust", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		// Honest kill count -- one per atomic SERVER_NPC_LOOT record, exactly RuneLite's own Loot Tracker semantics.
		assertEquals(3, source.getKillCount());
		// Individual-drop view preserves the exact atomic event boundaries, in observation order.
		assertEquals(3, source.getRecords().size());
		assertEquals(1, source.getRecords().get(0).getItems().size());

		// Grouped view sums quantities across records for the same item.
		List<LootTrackerItem> totals = source.getItemTotals();
		assertEquals(2, totals.size());
		LootTrackerItem natureRuneTotal = totals.get(0);
		assertEquals("Nature rune", natureRuneTotal.getItemName());
		assertEquals(8L, natureRuneTotal.getQuantity());
	}

	@Test
	public void snapshotSource_byKey_returnsNullWhenUnknown()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		assertNull(index.snapshotSource("nothing here"));
	}

	@Test
	public void snapshotSource_byKey_matchesSnapshotSourcesEntry()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Vorkath", 8061, T0, new LootTrackerItem(1, "Dragonbone", 1)));

		String key = index.snapshotSources().get(0).getSourceKey();
		LootTrackerSource bySingleLookup = index.snapshotSource(key);
		assertEquals("Vorkath", bySingleLookup.getSourceName());
		assertEquals(1, bySingleLookup.getKillCount());
	}

	@Test
	public void snapshotSources_isAFreshImmutableCopy_neverAffectedByLaterApply()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 100)));

		List<LootTrackerSource> before = index.snapshotSources();
		index.apply(record("e2", "Zulrah", 2042, T0.plusSeconds(1), new LootTrackerItem(2444, "Zulrah's scales", 50)));

		assertEquals(1, before.get(0).getKillCount());
		assertEquals(2, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void filteredAfter_null_returnsSameUnfilteredContent()
	{
		LootTrackerSource source = new LootTrackerSource("k", "Zulrah", 2042,
			Collections.singletonList(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(1, "x", 1))));
		LootTrackerSource same = source.filteredAfter(null);
		assertEquals(1, same.getKillCount());
	}

	@Test
	public void filteredAfter_excludesRecordsAtOrBeforeWatermark()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(1, "x", 1)));
		index.apply(record("e2", "Zulrah", 2042, T0.plusSeconds(30), new LootTrackerItem(1, "x", 1)));
		index.apply(record("e3", "Zulrah", 2042, T0.plusSeconds(90), new LootTrackerItem(1, "x", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		LootTrackerSource filtered = source.filteredAfter(T0.plusSeconds(30));

		// e1 (at T0) and e2 (exactly at the watermark) are both excluded; only e3 remains.
		assertEquals(1, filtered.getKillCount());
	}

	@Test
	public void filteredAfter_recordWithNullObservedAt_isNeverDropped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, null, new LootTrackerItem(1, "x", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		LootTrackerSource filtered = source.filteredAfter(T0.plusSeconds(90));

		assertEquals(1, filtered.getKillCount());
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Real-file
 * coverage of HistoryIndex.refresh() -- discovery, the ~10 day display
 * window filter, newest-first ordering, never-re-parse-once-indexed,
 * and fail-open skipping of a malformed file.
 * Matches SessionPersistenceTest/SessionLoadoutBackwardCompatibilityTest's
 * own established real-file, no-Client style.
 */
public class HistoryIndexTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_222L;
	private static final Instant NOW = Instant.parse("2026-01-15T12:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");
	private static final Gson TEST_GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	@Before
	public void setUp()
	{
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(TEST_GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown()
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	/** Writes a real finalized session file directly (bypassing the async store) so tests don't need to wait on it. */
	private static void writeSessionFileDirect(long accountHash, String sessionId, String finalizedAt) throws Exception
	{
		String json = "{"
			+ "\"sessionId\":\"" + sessionId + "\","
			+ "\"activityIdentity\":{\"activityType\":\"SLAYER\",\"activityKey\":\"gargoyles:catacombs\",\"displayName\":\"Gargoyles\"},"
			+ "\"state\":\"FINALIZED\","
			+ "\"startedAt\":\"2026-01-01T10:00:00Z\","
			+ "\"finalizedAt\":\"" + finalizedAt + "\","
			+ "\"accumulatedActiveDurationMillis\":60000,"
			+ "\"aggregates\":{\"xpGainedBySkill\":{},\"lootDrops\":[]}"
			+ "}";
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(accountHash, sessionId)), json.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void refresh_discoversRealFinalizedSession() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-1", "2026-01-15T11:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(1, result.size());
		assertEquals("session-1", result.get(0).getSessionId());
	}

	@Test
	public void refresh_emptyDirectory_returnsEmptyList()
	{
		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertTrue(result.isEmpty());
	}

	@Test
	public void refresh_ordersNewestFirst() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-old", "2026-01-10T10:00:00Z");
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-new", "2026-01-15T10:00:00Z");
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-mid", "2026-01-12T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(3, result.size());
		assertEquals("session-new", result.get(0).getSessionId());
		assertEquals("session-mid", result.get(1).getSessionId());
		assertEquals("session-old", result.get(2).getSessionId());
	}

	@Test
	public void refresh_excludesSessionsOutsideDisplayWindow_butKeepsThemIndexedForCount() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-recent", "2026-01-14T10:00:00Z");
		// 20 days before NOW -- outside a 10-day window.
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-ancient", "2025-12-26T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(1, result.size());
		assertEquals("session-recent", result.get(0).getSessionId());
		// The old file was never deleted, and IS still tracked internally
		// (display-only retention: old files are never deleted) --
		// it is simply excluded from the returned display snapshot.
		assertEquals(2, index.indexedCount());
		assertTrue(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-ancient").exists());
	}

	@Test
	public void refresh_malformedFile_skippedWithoutCrashingOtherEntries() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-good", "2026-01-15T10:00:00Z");
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-corrupt")),
			"{ not valid json at all".getBytes(StandardCharsets.UTF_8));

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("a malformed session file must be skipped, never crash the whole refresh",
			1, result.size());
		assertEquals("session-good", result.get(0).getSessionId());
	}

	@Test
	public void refresh_calledTwice_doesNotReParseAlreadyIndexedFiles() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-1", "2026-01-15T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);
		assertEquals(1, index.indexedCount());

		// Corrupt the already-indexed file on disk -- if refresh() were
		// re-parsing it, this second call would now fail to find it (or
		// throw); since it must never re-read an already-indexed file,
		// the cached entry is untouched and still present.
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-1")),
			"{ corrupted after first index".getBytes(StandardCharsets.UTF_8));

		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("an already-indexed session must never be re-parsed from disk",
			1, result.size());
		assertEquals("session-1", result.get(0).getSessionId());
	}

	@Test
	public void refresh_realSessionPersistenceWrite_discoveredCorrectly() throws Exception
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, NOW.minusSeconds(3600));
		Instant suspendedAt = NOW.minusSeconds(3600).plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), expiry.plusSeconds(60));

		assertEquals(1, result.size());
		assertEquals(finalized.getSessionId(), result.get(0).getSessionId());
	}

	@Test
	public void refresh_differentAccounts_neverCrossContaminate() throws Exception
	{
		long otherAccountHash = 888_777_111L;
		deleteAccountDir(otherAccountHash);
		try
		{
			writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-a", "2026-01-15T10:00:00Z");
			writeSessionFileDirect(otherAccountHash, "session-b", "2026-01-15T10:00:00Z");

			HistoryIndex index = new HistoryIndex();
			List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

			assertEquals(1, result.size());
			assertEquals("session-a", result.get(0).getSessionId());
		}
		finally
		{
			deleteAccountDir(otherAccountHash);
		}
	}

	@Test
	public void refresh_skippedMalformedFile_retriedOnNextRefresh() throws Exception
	{
		File corruptFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-fixable"));
		Files.write(corruptFile.toPath(), "{ not valid json".getBytes(StandardCharsets.UTF_8));

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> first = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);
		assertTrue(first.isEmpty());

		// The file "heals" (e.g. a retried write completes) between polls.
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-fixable", "2026-01-15T10:00:00Z");

		List<HistoryEntry> second = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("a file that was skipped for being malformed must be retried, not permanently blacklisted",
			1, second.size());
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import java.time.Instant;
import org.junit.Test;

/**
 * Pure
 * coverage of HistoryEntry.from()'s summary-building and its
 * fail-open null-return contract. Uses only PUBLIC
 * session-package API (SessionLifecycleEngine, Session's getters,
 * SessionAggregates' live map) -- this test class deliberately lives
 * in the history package, the same package HistoryEntry/HistoryIndex/
 * HistoryCoordinator live in, and never needs Session's
 * package-private setters.
 */
public class HistoryEntryTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static Session buildFinalizedSession()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		return engine.advanceTime(expiry).getFinalized();
	}

	@Test
	public void from_validFinalizedSession_buildsSummary()
	{
		Session session = buildFinalizedSession();

		HistoryEntry entry = HistoryEntry.from(session);

		assertNotNull(entry);
		assertEquals(session.getSessionId(), entry.getSessionId());
		assertEquals(GARGOYLES, entry.getActivityIdentity());
		assertEquals(session.getFinalizedAt(), entry.getFinalizedAt());
		assertEquals(session.getStartedAt(), entry.getStartedAt());
		assertEquals(session.getAccumulatedActiveDurationMillis(), entry.getAccumulatedActiveDurationMillis());
		assertFalse("no loadout was ever attached to this session", entry.isHasStartingLoadout());
		assertFalse(entry.isHasEndingLoadout());
	}

	@Test
	public void from_nullSession_returnsNull()
	{
		assertNull(HistoryEntry.from(null));
	}

	@Test
	public void from_sessionMissingFinalizedAt_returnsNull()
	{
		// An ACTIVE session -- finalizedAt is null. HistoryEntry.from()
		// must refuse it rather than fabricate a "finalized" summary.
		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();

		assertNull(HistoryEntry.from(session));
	}

	@Test
	public void from_sumsXpAcrossAllSkills()
	{
		Session session = buildFinalizedSession();
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 500L);
		session.getAggregates().getXpGainedBySkill().put("STRENGTH", 120L);

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(620L, entry.getTotalXpGained());
	}

	@Test
	public void from_countsLootDropGroups()
	{
		Session session = buildFinalizedSession();
		session.getAggregates().getLootDrops().add(new com.osrstelemetry.plugin.session.SessionAggregates.LootDropGroup());
		session.getAggregates().getLootDrops().add(new com.osrstelemetry.plugin.session.SessionAggregates.LootDropGroup());

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(2, entry.getLootDropCount());
	}

	@Test
	public void from_emptyAggregates_totalXpZero_noException()
	{
		Session session = buildFinalizedSession();

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(0L, entry.getTotalXpGained());
		assertEquals(0, entry.getLootDropCount());
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere (see
 * plugin/README.md / other test files' identical notes).
 *
 * Targets OsrsTelemetryPlugin.StartupHydrationGate directly — the
 * Client/ClientThread-independent piece extracted from the
 * client-thread lifecycle audit (see startUp()/onGameStateChanged()).
 * This project has no Mockito dependency and never mocks RuneLite's
 * Client or ClientThread anywhere (see e.g. QuestCollectorTest's own
 * note) — both are real RuneLite classes whose exact internal
 * threading behavior can't be faithfully faked here, so this test
 * covers exactly what IS safely testable without them: the pure
 * duplicate-initialization guard requirements 2 and 5 asked for.
 *
 * What this does NOT cover (verified instead by source inspection):
 * that startUp()
 * actually calls clientThread.invokeLater() rather than calling
 * handleLogin() directly, and that onConfigChanged()'s entire switch
 * runs inside clientThread.invokeLater(). Those are structural
 * properties of the production code, not decisions this gate makes.
 */
public class OsrsTelemetryPluginLifecycleTest
{
	@Test
	public void consumeWithoutArmingReturnsFalse()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		assertFalse("nothing was armed; the deferred callback must not run handleLogin()", gate.consumeIfPending());
	}

	@Test
	public void armThenConsumeReturnsTrueExactlyOnce()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.arm();
		assertTrue("first consume after arm() must run the deferred hydration", gate.consumeIfPending());
		assertFalse("a second consume for the same arm() must not run hydration again", gate.consumeIfPending());
	}

	@Test
	public void realLoginSupersedesStillPendingDeferredHydration()
	{
		// Models: startUp() runs on AWT while already logged in and
		// arms the gate, but a genuine GameStateChanged(LOGGED_IN)
		// (e.g. a fast relog) reaches onGameStateChanged() and calls
		// supersede() BEFORE the deferred ClientThread callback from
		// startUp() gets a chance to run.
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.arm();
		gate.supersede();

		assertFalse(
			"a real login event must make the deferred startup hydration a no-op, "
				+ "since onGameStateChanged()'s own handleLogin() call already covers it",
			gate.consumeIfPending()
		);
	}

	@Test
	public void supersedeBeforeArmIsSafeAndDoesNotArmAnything()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.supersede();
		assertFalse(gate.consumeIfPending());
	}

	@Test
	public void arm_consume_armAgain_consumeAgain_eachEnableGetsExactlyOneHydration()
	{
		// Models plugin disable -> re-enable -> disable -> re-enable:
		// each enable that reaches startUp() while already logged in
		// must independently produce exactly one hydration.
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();

		gate.arm();
		assertTrue(gate.consumeIfPending());
		assertFalse(gate.consumeIfPending());

		gate.arm();
		assertTrue(gate.consumeIfPending());
		assertFalse(gate.consumeIfPending());
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere (see
 * plugin/README.md / other test files' identical notes).
 *
 * Targets AccountContext directly — this is the exact decision logic
 * that gates OsrsTelemetryPlugin.handleLogin()'s account-switch reset
 * dispatch block (skillsCollector/questCollector/containerCollector/
 * activityKillCountCollector/serverNpcLootCollector/knownBossRegistry/
 * bossActivityContextCollector.resetForAccountSwitch(...) plus
 * eventLedger.startNewSession()): that whole block only runs when
 * accountContext.isRealSwitch(previousAccountHash, newAccountHash) is
 * true, and previousAccountHash always comes from
 * accountContext.update(newAccountHash) — so this class alone decides
 * "first login vs. real switch vs. same-account relog/world hop" for
 * every collector on that list.
 *
 * handleLogin() itself is deliberately NOT targeted here: it also
 * touches client.getAccountHash(), sessionRuntimeCoordinator, and ~10
 * concrete collector fields, all @Inject-wired to real RuneLite types
 * (Client, ClientThread, EventBus) with no interfaces to substitute —
 * this project has no Mockito dependency and never mocks RuneLite's
 * Client anywhere (see e.g. QuestCollectorTest's/
 * OsrsTelemetryPluginLifecycleTest's own identical notes), so
 * constructing a real OsrsTelemetryPlugin here would require either a
 * live RuneLite client or invasive production refactoring (extracting
 * an interface layer over every collector) neither of which is in
 * scope here. This test covers exactly what IS safely
 * testable without them: AccountContext's own pure switch-detection
 * decision, in isolation.
 */
public class AccountContextTest
{
	private static final long ACCOUNT_A = 111L;
	private static final long ACCOUNT_B = 222L;

	@Test
	public void firstObservationIsNotARealSwitch()
	{
		// Property A: first account initialization must not trigger the
		// destructive reset-dispatch block in handleLogin() — update()'s
		// sentinel "no account observed yet" (-1) previous value must
		// make isRealSwitch() return false.
		AccountContext context = new AccountContext();

		long previous = context.update(ACCOUNT_A);

		assertFalse(
			"the very first accountHash observed must be treated as a seed, not a switch",
			context.isRealSwitch(previous, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_A, context.getCurrentAccountHash());
	}

	@Test
	public void switchingToADifferentAccountIsARealSwitch()
	{
		// Property B: account A -> account B must be detected as a real
		// switch, so handleLogin() invokes every collector's
		// resetForAccountSwitch(...) exactly once for this transition.
		AccountContext context = new AccountContext();
		long firstPrevious = context.update(ACCOUNT_A);
		context.isRealSwitch(firstPrevious, ACCOUNT_A); // seed, as above

		long secondPrevious = context.update(ACCOUNT_B);

		assertTrue(
			"a genuinely different accountHash must be treated as a real switch",
			context.isRealSwitch(secondPrevious, ACCOUNT_B)
		);
		assertEquals(ACCOUNT_A, secondPrevious);
		assertEquals(ACCOUNT_B, context.getCurrentAccountHash());
	}

	@Test
	public void sameAccountReloginIsNotARealSwitch()
	{
		// Property C: a same-account relog/world hop (accountHash
		// unchanged) must NOT be treated as a real switch, so the
		// per-account collector state above is never falsely cleared —
		// only slayerCollector/tick-counter resets run unconditionally
		// in handleLogin(), by design (see its own comments), and that
		// unconditional-vs-real-switch-gated split is exactly what this
		// method decides.
		AccountContext context = new AccountContext();
		long firstPrevious = context.update(ACCOUNT_A);
		context.isRealSwitch(firstPrevious, ACCOUNT_A); // seed

		long secondPrevious = context.update(ACCOUNT_A);

		assertFalse(
			"re-observing the same accountHash (relog/world hop) must not be a real switch",
			context.isRealSwitch(secondPrevious, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_A, secondPrevious);
	}

	@Test
	public void switchAwayThenBackToAnEarlierAccountIsStillARealSwitch()
	{
		// A -> B -> A: the second transition back to A must be detected
		// as a real switch too — B's leftovers must never be diffed
		// against, or leak into, A's telemetry.
		AccountContext context = new AccountContext();
		context.update(ACCOUNT_A);
		long previousAtB = context.update(ACCOUNT_B);
		context.isRealSwitch(previousAtB, ACCOUNT_B);

		long previousBackAtA = context.update(ACCOUNT_A);

		assertTrue(
			"switching back to a previously-seen account is still a real switch",
			context.isRealSwitch(previousBackAtA, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_B, previousBackAtA);
	}

	@Test
	public void getCurrentAccountHashReflectsMostRecentUpdate()
	{
		AccountContext context = new AccountContext();
		context.update(ACCOUNT_A);
		assertEquals(ACCOUNT_A, context.getCurrentAccountHash());

		context.update(ACCOUNT_B);
		assertEquals(ACCOUNT_B, context.getCurrentAccountHash());
	}
}

