	// ----------------------------------------------------------------
	// HARD SLAYER RULE regression. A currently assigned
	// Slayer task is CONTEXT ONLY. Reproduces the exact live bug --
	// task "Gargoyles" assigned at login, fighting Desert Wolf then Goat
	// (both correctly named generic COMBAT), with NO
	// SLAYER_TASK_PROGRESS ever occurring -- and proves the session
	// never gets silently promoted to SLAYER/Gargoyles. Also proves
	// NPC_DEATH/SERVER_NPC_LOOT stay observational/ownership-only, and
	// that genuine SLAYER_TASK_PROGRESS evidence still correctly
	// upgrades the session via the existing SPECIFIC path, after which
	// it resists downgrade from further weak generic combat evidence.
	// ----------------------------------------------------------------

	@Test
	public void pipeline_hardSlayerRule_assignedTaskContextNeverPromotesOrdinaryCombatToSlayer()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_NPC_TEST);

		// 1: seed an active assigned Slayer task -- Gargoyles, amount 27
		// -- exactly like the live SLAYER_TASK_ASSIGNED at login. This
		// is CONTEXT ONLY; it must never by itself produce a SLAYER
		// identity.
		coordinator.testEnqueueSignal(
			SessionSignal.slayerTaskAssigned(T0, "Gargoyles", "Catacombs of Kourend", 27).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);

		// 2 & 3: interact with Desert Wolf, then genuine raw combat XP
		// establishes named generic COMBAT/Desert Wolf -- correct, as
		// live-observed.
		coordinator.testEnqueueSignal(
			SessionSignal.npcInteractionTarget(T0.plusSeconds(1), 601, "Desert Wolf").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusSeconds(1));
		coordinator.testEnqueueSignal(
			SessionSignal.rawCombatXpObserved(T0.plusMillis(1600), "Strength").withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusMillis(1600));

		Session afterWolf = coordinator.testCurrentSession();
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Desert Wolf"), afterWolf.getActivityIdentity());

		// 4 & 5: interact with Goat, then repeated raw combat XP
		// establishes/confirms named generic COMBAT/Goat -- correct, as
		// live-observed. Switching between two named generic-combat
		// identities goes through the existing ACTIVE ORDINARY-evidence
		// candidate gate (arm on the first blip, confirm on the second).
		coordinator.testEnqueueSignal(
			SessionSignal.npcInteractionTarget(T0.plusSeconds(2), 602, "Goat").withGameTick(4L));
		coordinator.testProcessTick(5L, T0.plusSeconds(2));

		coordinator.testEnqueueSignal(
			SessionSignal.rawCombatXpObserved(T0.plusMillis(2600), "Strength").withGameTick(5L));
		coordinator.testProcessTick(6L, T0.plusMillis(2600));
		// First blip only ARMS a candidate -- Desert Wolf is untouched.
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Desert Wolf"), coordinator.testCurrentSession().getActivityIdentity());

		coordinator.testEnqueueSignal(
			SessionSignal.rawCombatXpObserved(T0.plusMillis(3600), "Strength").withGameTick(6L));
		coordinator.testProcessTick(7L, T0.plusMillis(3600));
		// Second coherent blip CONFIRMS the switch to Goat.
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), coordinator.testCurrentSession().getActivityIdentity());

		// 6: continue repeated Goat combat evidence -- both the fast raw
		// path AND the slow, aggregated XP_CHANGE path (the exact live
		// bug's own mechanism -- classifyXpChange()'s combat branch).
		// Expected: session remains COMBAT/Goat. SLAYER/Gargoyles must
		// NOT appear merely because Gargoyles is assigned.
		coordinator.testEnqueueSignal(
			SessionSignal.rawCombatXpObserved(T0.plusMillis(4600), "Strength").withGameTick(7L));
		coordinator.testProcessTick(8L, T0.plusMillis(4600));
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), coordinator.testCurrentSession().getActivityIdentity());

		coordinator.testEnqueueSignal(
			SessionSignal.xpChange(T0.plusMillis(5600), "Strength", 40).withGameTick(8L));
		coordinator.testProcessTick(9L, T0.plusMillis(5600));
		Session afterOrdinaryCombatXp = coordinator.testCurrentSession();
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), afterOrdinaryCombatXp.getActivityIdentity());
		assertNotEquals(ActivitySignalClassifier.slayerIdentity("Gargoyles", "Catacombs of Kourend"), afterOrdinaryCombatXp.getActivityIdentity());

		// 7: NPC_DEATH is observational/corroborating ONLY -- never
		// player kill credit, never Slayer progress, never authority
		// over the current session's identity, regardless of any
		// activeSlayerTaskName the live collector layer separately
		// annotates its own payload with (that annotation never reaches
		// this classifier -- see SessionSignal.npcDeath()'s own
		// parameterless factory and ActivitySignalClassifier's
		// NPC_DEATH case, which is an unconditional ignore()).
		coordinator.testEnqueueSignal(SessionSignal.npcDeath(T0.plusSeconds(6)).withGameTick(9L));
		coordinator.testProcessTick(10L, T0.plusSeconds(6));
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), coordinator.testCurrentSession().getActivityIdentity());

		// 8: SERVER_NPC_LOOT/Goat remains associated with the current
		// generic combat session per existing ownership semantics --
		// metric-only, no identity change.
		coordinator.testEnqueueSignal(SessionSignal.serverNpcLoot(T0.plusMillis(6100), "Goat",
			Collections.singletonList(new SessionSignal.LootDrop(526, "Bones", 1))).withGameTick(10L));
		coordinator.testProcessTick(11L, T0.plusMillis(6100));
		Session afterLoot = coordinator.testCurrentSession();
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), afterLoot.getActivityIdentity());
		assertEquals(1, afterLoot.getAggregates().getLootDrops().size());
		assertEquals("Goat", afterLoot.getAggregates().getLootDrops().get(0).getSourceName());

		// 9: genuine SLAYER_TASK_PROGRESS/Gargoyles now arrives -- THIS
		// is the existing, authoritative, SPECIFIC-evidence path that is
		// actually allowed to establish SLAYER/Gargoyles.
		coordinator.testEnqueueSignal(
			SessionSignal.slayerTaskProgress(T0.plusSeconds(7), "Gargoyles", "Catacombs of Kourend", 1, 26).withGameTick(11L));
		coordinator.testProcessTick(12L, T0.plusSeconds(7));
		Session afterProgress = coordinator.testCurrentSession();
		assertEquals(ActivitySignalClassifier.slayerIdentity("Gargoyles", "Catacombs of Kourend"), afterProgress.getActivityIdentity());

		// 10: once genuinely established, weaker generic combat evidence
		// (another raw pulse against the same recent Goat target) must
		// NOT downgrade the established SLAYER/Gargoyles session.
		coordinator.testEnqueueSignal(
			SessionSignal.rawCombatXpObserved(T0.plusMillis(7600), "Strength").withGameTick(12L));
		coordinator.testProcessTick(13L, T0.plusMillis(7600));
		assertEquals(ActivitySignalClassifier.slayerIdentity("Gargoyles", "Catacombs of Kourend"), coordinator.testCurrentSession().getActivityIdentity());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Small, representative
 * registry-level tests -- deliberately NOT one test per cataloged task
 * alias (per explicit instruction: "do not add dozens of combinatorial
 * tests for every task alias"). Behavioral pipeline coverage (how
 * membership actually participates in session classification) lives in
 * ActivitySignalClassifierTest and SessionRuntimeCoordinatorTest.
 */
public class SlayerTaskFamilyRegistryTest
{
	// Test 1: the worked example from the task spec itself.
	@Test
	public void pyrefiendBelongsToPyrefiendsFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Pyrefiend"));
	}

	// Test 2: the boss-alternative-name example from the task spec.
	@Test
	public void flamingPyrelordBelongsToPyrefiendsFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Flaming pyrelord"));
	}

	// Test 3: a genuinely unrelated NPC is never hand-waved in.
	@Test
	public void unrelatedNpcDoesNotBelongToPyrefiendsFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Goat"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Cow"));
	}

	// Case normalization / whitespace: matching must not be case- or
	// whitespace-sensitive.
	@Test
	public void membershipIsCaseAndWhitespaceInsensitive()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("  PYREFIENDS  ", "flaming PYRELORD"));
	}

	// Multi-NPC task family (Gargoyles/Dawn/Dusk) -- the exact data the
	// boss-precedence regression test relies on NOT flattening
	// Grotesque Guardians (see ActivitySignalClassifierTest).
	@Test
	public void gargoylesFamilyIncludesDawnAndDusk()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Dawn"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Dusk"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Gargoyle"));
	}

	// Boss-alternative-target example named directly in the task spec.
	@Test
	public void blueDragonsFamilyIncludesVorkathBossAlternative()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Blue dragons", "Vorkath"));
	}

	// An uncatalogued task (not in the static table at all) falls back
	// ONLY to the exact same deterministic trailing-"s" strip RuneLite's
	// own SlayerPlugin unconditionally applies -- never a fuzzy/
	// approximate match, and never hand-waving an unrelated NPC in.
	@Test
	public void uncataloguedTaskFallsBackToSingularStripOnly()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Totally new task creatures", "Totally new task creature"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Totally new task creatures", "Some other monster"));
	}

	@Test
	public void nullTaskOrNpcNameNeverMatches()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily(null, "Pyrefiend"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", null));
	}

	// ------------------------------------------------------------------
	// Superior-coverage note: RuneLite's own Task enum does not
	// (yet) list every currently-live Superior slayer monster as a
	// target-name alias -- confirmed by direct source inspection (see
	// this class's own SUPERIOR-COVERAGE SOURCE javadoc). Elder aquanite
	// is the gap this fills.
	// ------------------------------------------------------------------

	// An Elder aquanite kill must stay on-task for an assigned Aquanites
	// task rather than being proposed as an off-task candidate switch.
	@Test
	public void elderAquaniteBelongsToAquanitesFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "Elder aquanite"));
	}

	// A superior alias already present (Nechryael ->
	// Nechryarch) must remain covered -- this registry only ever ADDS
	// entries, never removes/reshapes an existing one.
	@Test
	public void nechryarchStillBelongsToNechryaelFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Nechryarch"));
	}

	// A genuinely unrelated NPC is never hand-waved into a family this
	// pass touched, even one superficially "boss-like" in name.
	@Test
	public void unrelatedNpcNeverBelongsToAquanitesFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "Goat"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "General Graardor"));
	}

	// Basilisk Knight is a stronger, still-Basilisks-task-assignable NPC
	// (confirmed via its own OSRS Wiki infobox category, not invented) --
	// it and its own superior (Basilisk sentinel) both belong on the
	// EXISTING Basilisks family, never a separate invented task.
	@Test
	public void basiliskKnightAndItsSuperiorBelongToBasilisksFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Basilisks", "Basilisk Knight"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Basilisks", "Basilisk sentinel"));
	}

	// Greater Nechryael is Nechryael's own confirmed OSRS-Wiki "Superior
	// slayer monster" -- a genuine coverage gap this pass closes (see the
	// registry's own "Nechryael" entry javadoc). This is the direct
	// regression test for the live-reported bug: a Greater Nechryael kill
	// during an active Nechryael task must be recognized as on-task-family,
	// exactly like its existing Nechryarch sibling above, never treated as
	// an unrelated NPC.
	@Test
	public void greaterNechryaelBelongsToNechryaelFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Greater Nechryael"));
	}

	// Negative control for the SAME live-reported bug: Death Spawn is a
	// combat encounter byproduct of fighting Nechryael-family NPCs, never
	// itself an assignable/on-task Nechryael-family member (no OSRS Wiki
	// "Superior slayer monster" or task-alias listing pairs it with
	// Nechryael) -- it must NOT be hand-waved into this family just
	// because it appears during the same encounter. Its protection against
	// prematurely stealing session ownership comes from a different,
	// generic mechanism (SessionLifecycleEngine's downranking-combat-
	// challenge hysteresis), not from this registry -- see
	// SessionRuntimeCoordinatorTest's Death Spawn coverage.
	@Test
	public void deathSpawnNeverBelongsToNechryaelFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Death Spawn"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project.
 *
 * Covers serialization round-trips, restart/rehydration semantics,
 * finalized-record persistence and write ordering, and account
 * isolation — all against the real
 * LocalStateStore/TelemetryPaths, matching BankSnapshotBaselineTest's
 * own G-J section's established pattern (real files, no Client, two
 * distinct account hashes for isolation checks).
 */
public class SessionPersistenceTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_555L;
	private static final long OTHER_ACCOUNT_HASH = 888_777_666L;

	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	@Before
	public void setUp() throws Exception
	{
		deleteAccountDir(TEST_ACCOUNT_HASH);
		deleteAccountDir(OTHER_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
		deleteAccountDir(OTHER_ACCOUNT_HASH);
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	// --- 21/22/23: serialization round-trips ---

	@Test
	public void serializationRoundTrip_active()
	{
		Session original = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.ACTIVE, roundTripped.getState());
		assertEquals(GARGOYLES, roundTripped.getActivityIdentity());
	}

	@Test
	public void serializationRoundTrip_suspended()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session original = engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)).getCurrent();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.SUSPENDED, roundTripped.getState());
		assertNotNull(roundTripped.getSuspendedAt());
		assertNotNull(roundTripped.getResumeWindowExpiresAt());
	}

	@Test
	public void serializationRoundTrip_finalizedRecord()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session original = engine.advanceTime(expiry).getFinalized();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.FINALIZED, roundTripped.getState());
		assertEquals(expiry.toString(), roundTripped.getFinalizedAt());
	}

	// --- 24/25/26: restart/rehydration semantics ---

	@Test
	public void rehydrate_persistedActive_convertsConservativelyWithoutCountingOfflineTime()
	{
		Session persisted = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		long durationBeforeRehydration = persisted.getAccumulatedActiveDurationMillis();

		// RuneLite was closed for a full day; rehydration happens far later.
		Instant rehydratedAt = T0.plus(java.time.Duration.ofDays(1));
		SessionLifecycleEngine.RehydrationResult result = SessionLifecycleEngine.rehydrate(persisted, rehydratedAt);

		// The offline gap vastly exceeds the 30-minute resume window, so
		// the conservative SUSPENDED reconstruction immediately finalizes.
		assertNotNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.FINALIZED, result.getFinalizedDuringRehydration().getState());
		assertEquals("no offline time may ever be added to active duration",
			durationBeforeRehydration, result.getFinalizedDuringRehydration().getAccumulatedActiveDurationMillis());
		assertNull(result.getEngine().getCurrentSession());
	}

	@Test
	public void rehydrate_persistedSuspendedInsideWindow_remainsResumable()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		Session persisted = engine.advanceTime(suspendedAt).getCurrent();

		// Rehydrated 10 minutes into the 30-minute window.
		SessionLifecycleEngine.RehydrationResult result =
			SessionLifecycleEngine.rehydrate(persisted, suspendedAt.plus(java.time.Duration.ofMinutes(10)));

		assertNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.SUSPENDED, result.getEngine().getCurrentSession().getState());

		// And it genuinely still resumes on a matching heartbeat.
		LifecycleResult resumed = result.getEngine().onQualifyingActivity(
			GARGOYLES, suspendedAt.plus(java.time.Duration.ofMinutes(11)));
		assertEquals(SessionState.ACTIVE, resumed.getCurrent().getState());
	}

	@Test
	public void rehydrate_persistedSuspendedOutsideWindow_finalizes()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		Session persisted = engine.advanceTime(suspendedAt).getCurrent();
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);

		SessionLifecycleEngine.RehydrationResult result =
			SessionLifecycleEngine.rehydrate(persisted, expiry.plus(java.time.Duration.ofMinutes(1)));

		assertNotNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.FINALIZED, result.getFinalizedDuringRehydration().getState());
		assertEquals("timeout-driven finalization must use the deterministic expiry, not the rehydration wall time",
			expiry.toString(), result.getFinalizedDuringRehydration().getFinalizedAt());
		assertNull(result.getEngine().getCurrentSession());
	}

	// --- 27: finalized session writes to correct sessions path ---

	/**
	 * NOTE ON WAITING FOR THE ASYNC CHAIN: persistFinalized() chains a
	 * second write() call from inside the first write's onWritten
	 * callback (see SessionPersistence javadoc), both submitted to
	 * LocalStateStore's single-thread executor. Calling shutdown()
	 * immediately after persistFinalized() returns is NOT safe here the
	 * way it is for a single, non-chained write (see
	 * LocalStateStoreTest's "no sleep — shutdown() itself waits"
	 * comment): shutdown() can flip the executor to SHUTDOWN before the
	 * first task's onWritten callback gets a chance to submit the
	 * second task, causing that nested submit() to be silently
	 * rejected. This mirrors LocalStateStore's own javadoc reasoning for
	 * why real shutdown-time chaining uses the blocking writeAndWait()
	 * instead — ordinary runtime chaining (the case here)
	 * does not go through shutdown() at all, so a short sleep here
	 * (not shutdown()) is what correctly waits for both queued tasks to
	 * finish without introducing a race the production code path never
	 * has.
	 */
	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	@Test
	public void persistFinalized_writesToCorrectSessionsPath() throws Exception
	{
		Session finalized = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		finalized.setState(SessionState.FINALIZED);
		finalized.setFinalizedAt(T0.plusSeconds(10).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		File expected = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, finalized.getSessionId()));
		assertTrue("finalized record must exist at sessions/{sessionId}.json", expected.exists());

		Session reloaded = store.readIfExists(TestFilepaths.fromFile(expected), Session.class);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertEquals(finalized.getSessionId(), reloaded.getSessionId());
	}

	@Test
	public void persistFinalized_clearsSessionStateOnlyAfterSuccess() throws Exception
	{
		Session finalized = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		finalized.setState(SessionState.FINALIZED);
		finalized.setFinalizedAt(T0.plusSeconds(10).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session currentAfter = store.readIfExists(
			TelemetryPaths.sessionStateFile(TEST_ACCOUNT_HASH), Session.class);
		assertNull("session_state.json must no longer represent the finalized session as current",
			currentAfter);
	}

	// --- 28: account isolation ---

	@Test
	public void accountDirectoriesRemainIsolated() throws Exception
	{
		Session accountASession = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, accountASession);
		store.shutdown(); // single, non-chained write — safe to drain via shutdown(), see LocalStateStoreTest's own convention

		Session loadedForOther = persistence.loadCurrent(OTHER_ACCOUNT_HASH);
		Session loadedForTest = persistence.loadCurrent(TEST_ACCOUNT_HASH);

		assertNull("account B must never see account A's current session", loadedForOther);
		assertNotNull(loadedForTest);
		assertEquals(accountASession.getSessionId(), loadedForTest.getSessionId());
		assertFalse("session directories themselves must be different paths",
			TelemetryPaths.accountDir(TEST_ACCOUNT_HASH).equals(TelemetryPaths.accountDir(OTHER_ACCOUNT_HASH)));
	}

	// --- 29: persistence failure does not silently discard the only current session copy ---

	@Test
	public void persistFinalizedFailure_doesNotClearSessionState() throws Exception
	{
		// Seed session_state.json with a known-good SUSPENDED session first,
		// as if it were the last successfully persisted current state.
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session suspended = engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, suspended);
		store.shutdown(); // single, non-chained write — safe to drain via shutdown()
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);

		// Simulate the finalized-record write itself failing: same technique
		// LocalStateStoreTest uses for its own failure test (a parent
		// directory that cannot be created because a same-named file
		// already occupies that path).
		File accountDir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		File sessionsDirBlocker = new File(accountDir, "sessions");
		deleteRecursively(sessionsDirBlocker);
		sessionsDirBlocker.delete();
		java.nio.file.Files.write(sessionsDirBlocker.toPath(), "not a directory".getBytes());

		Session toFinalize = suspended;
		toFinalize.setState(SessionState.FINALIZED);
		toFinalize.setFinalizedAt(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plus(SessionLifecycleEngine.RESUME_WINDOW).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, toFinalize, null);
		store.shutdown();

		store = new LocalStateStore(GSON);
		store.start();
		Session stillCurrent = store.readIfExists(TelemetryPaths.sessionStateFile(TEST_ACCOUNT_HASH), Session.class);
		assertNotNull("a failed finalized-record write must never clear the only surviving copy of the session",
			stillCurrent);
		assertEquals(SessionState.SUSPENDED, stillCurrent.getState());

		sessionsDirBlocker.delete();
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

import java.time.Instant;
import org.junit.Test;

/**
 * Pure,
 * deterministic tests for SessionLifecycleEngine.refineIdentity() --
 * its invariants (sessionId/startedAt/duration/aggregates
 * preservation, never finalizing, ActivityIdentity immutability) and
 * its exact-boundary runtime-ordering contract. Does not weaken
 * or duplicate the existing SessionLifecycleEngineTest.java coverage
 * of the base ACTIVE/SUSPENDED/FINALIZED machinery.
 */
public class SessionLifecycleEngineRefinementTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T00:00:00Z");
	private static final ActivityIdentity GENERIC_COMBAT = ActivitySignalClassifier.genericCombatIdentity();
	private static final ActivityIdentity SLAYER_GARGOYLES = ActivitySignalClassifier.slayerIdentity("Gargoyles", "Catacombs of Kourend");
	private static final ActivityIdentity BOSSING_ZULRAH = ActivitySignalClassifier.bossIdentity("Zulrah");

	// Test 1: refineIdentity preserves sessionId.
	@Test
	public void refinePreservesSessionId()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		String sessionId = engine.getCurrentSession().getSessionId();
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertEquals(sessionId, engine.getCurrentSession().getSessionId());
	}

	// Test 2: refineIdentity preserves startedAt.
	@Test
	public void refinePreservesStartedAt()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		String startedAt = engine.getCurrentSession().getStartedAt();
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertEquals(startedAt, engine.getCurrentSession().getStartedAt());
	}

	// Test 3: refineIdentity accumulates duration exactly like an ordinary heartbeat -- never resets it.
	@Test
	public void refineAccumulatesDurationLikeAHeartbeat()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.onQualifyingActivity(GENERIC_COMBAT, T0.plusSeconds(30));
		assertEquals(30_000L, engine.getCurrentSession().getAccumulatedActiveDurationMillis());

		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(50));
		assertEquals(50_000L, engine.getCurrentSession().getAccumulatedActiveDurationMillis());
	}

	// Test 4: refineIdentity preserves the same SessionAggregates instance (never replaced).
	@Test
	public void refinePreservesAggregatesInstance()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		SessionAggregates aggregates = engine.getCurrentSession().getAggregates();
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertSame(aggregates, engine.getCurrentSession().getAggregates());
	}

	// Test 5: refineIdentity actually changes the session's ActivityIdentity.
	@Test
	public void refineChangesActivityIdentity()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertEquals(BOSSING_ZULRAH, engine.getCurrentSession().getActivityIdentity());
	}

	// Test 6: refineIdentity never finalizes the session.
	@Test
	public void refineNeverFinalizes()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertNull(result.getFinalized());
		assertEquals(SessionState.ACTIVE, engine.getCurrentSession().getState());
	}

	// Test 7: refineIdentity with an out-of-order observedAt is rejected -- no mutation at all.
	@Test
	public void refineRejectsOutOfOrderTimestamp()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0.plusSeconds(30));
		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, T0);
		assertEquals(GENERIC_COMBAT, result.getCurrent().getActivityIdentity());
		assertEquals(GENERIC_COMBAT, engine.getCurrentSession().getActivityIdentity());
	}

	// Test 8: refineIdentity on an engine with no current session is a safe no-op.
	@Test
	public void refineOnEmptyEngineIsNoOp()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, T0);
		assertNull(result.getCurrent());
		assertNull(engine.getCurrentSession());
	}

	// Test 9: after a refinement, ordinary heartbeats against the new identity continue the same session normally.
	@Test
	public void heartbeatsAfterRefineContinueNormally()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		LifecycleResult result = engine.onQualifyingActivity(BOSSING_ZULRAH, T0.plusSeconds(20));
		assertNull(result.getFinalized());
		assertEquals(20_000L, engine.getCurrentSession().getAccumulatedActiveDurationMillis());
	}

	// Test 10: refineIdentity suspends the session (keeping the new identity) if observedAt has itself reached the 5-minute threshold.
	@Test
	public void refineSuspendsAtDeterministicThresholdWhenDue()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		Instant refineAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(1);
		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, refineAt);
		assertEquals(SessionState.SUSPENDED, result.getCurrent().getState());
		assertEquals(BOSSING_ZULRAH, result.getCurrent().getActivityIdentity());
		assertEquals(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).toString(), result.getCurrent().getSuspendedAt());
	}

	// Test 11: refineIdentity resumes a SUSPENDED session at or before its resume window, preserving sessionId/duration.
	@Test
	public void refineResumesSuspendedSessionWithinWindow()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT));
		String sessionId = engine.getCurrentSession().getSessionId();
		long durationBefore = engine.getCurrentSession().getAccumulatedActiveDurationMillis();

		Instant resumeAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plus(SessionLifecycleEngine.RESUME_WINDOW).minusSeconds(1);
		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, resumeAt);
		assertEquals(SessionState.ACTIVE, result.getCurrent().getState());
		assertEquals(sessionId, result.getCurrent().getSessionId());
		assertEquals(durationBefore, result.getCurrent().getAccumulatedActiveDurationMillis());
		assertEquals(BOSSING_ZULRAH, result.getCurrent().getActivityIdentity());
		assertNull(result.getCurrent().getSuspendedAt());
	}

	// Test 12: refineIdentity resumes exactly AT the resume-window boundary (boundary-inclusive).
	@Test
	public void refineResumesExactlyAtResumeWindowBoundary()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT));
		Instant expiry = engine.getCurrentSession().resumeWindowExpiresAtInstant();

		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, expiry);
		assertEquals(SessionState.ACTIVE, result.getCurrent().getState());
		assertEquals(BOSSING_ZULRAH, result.getCurrent().getActivityIdentity());
	}

	// Test 13: refineIdentity strictly after the resume window is a no-op -- it must never resurrect an expired session.
	@Test
	public void refineDoesNotResurrectExpiredSuspendedSession()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(SLAYER_GARGOYLES, T0);
		engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT));
		Instant expiry = engine.getCurrentSession().resumeWindowExpiresAtInstant();

		LifecycleResult result = engine.refineIdentity(BOSSING_ZULRAH, expiry.plusSeconds(1));
		assertEquals(SessionState.SUSPENDED, result.getCurrent().getState());
		assertEquals(SLAYER_GARGOYLES, result.getCurrent().getActivityIdentity());
	}

	// Test 14: refining does not mutate the original ActivityIdentity object -- ActivityIdentity stays immutable.
	@Test
	public void refineDoesNotMutateOriginalIdentityObject()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(10));
		assertEquals(ActivityType.COMBAT, GENERIC_COMBAT.getActivityType());
		assertEquals("combat", GENERIC_COMBAT.getActivityKey());
	}

	// Test 15: the engine itself trusts its caller and permits a second refinement in sequence -- sessionId/startedAt still preserved.
	@Test
	public void sequentialRefinementsStillPreserveIdentityInvariants()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0);
		String sessionId = engine.getCurrentSession().getSessionId();
		String startedAt = engine.getCurrentSession().getStartedAt();

		engine.refineIdentity(SLAYER_GARGOYLES, T0.plusSeconds(10));
		engine.refineIdentity(BOSSING_ZULRAH, T0.plusSeconds(20));

		assertEquals(sessionId, engine.getCurrentSession().getSessionId());
		assertEquals(startedAt, engine.getCurrentSession().getStartedAt());
		assertEquals(BOSSING_ZULRAH, engine.getCurrentSession().getActivityIdentity());
	}

	// Test 16: an out-of-order refineIdentity call never moves lastActiveAt backwards.
	@Test
	public void refineOutOfOrderDoesNotMoveLastActiveAt()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GENERIC_COMBAT, T0.plusSeconds(30));
		String lastActiveBefore = engine.getCurrentSession().getLastActiveAt();
		engine.refineIdentity(BOSSING_ZULRAH, T0);
		assertEquals(lastActiveBefore, engine.getCurrentSession().getLastActiveAt());
	}

	// Test 17: the runtime-ordering contract -- processing a genuine same-identity/refinement event AT the
	// resume-window boundary before any timeout advancement resumes the session; advancing time to that same
	// instant FIRST, with no event, finalizes it instead. A future coordinator must always process pending events
	// for instant T before applying timeout advancement for T.
	@Test
	public void eventBeforeTimeoutAdvancementResumesWhileTimeoutAloneFinalizes()
	{
		SessionLifecycleEngine eventFirstEngine = new SessionLifecycleEngine();
		eventFirstEngine.onQualifyingActivity(SLAYER_GARGOYLES, T0);
		eventFirstEngine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT));
		Instant expiry = eventFirstEngine.getCurrentSession().resumeWindowExpiresAtInstant();
		eventFirstEngine.refineIdentity(BOSSING_ZULRAH, expiry);
		assertEquals(SessionState.ACTIVE, eventFirstEngine.getCurrentSession().getState());

		SessionLifecycleEngine timeoutFirstEngine = new SessionLifecycleEngine();
		timeoutFirstEngine.onQualifyingActivity(SLAYER_GARGOYLES, T0);
		timeoutFirstEngine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT));
		Instant sameExpiry = timeoutFirstEngine.getCurrentSession().resumeWindowExpiresAtInstant();
		LifecycleResult timeoutResult = timeoutFirstEngine.advanceTime(sameExpiry);
		assertNull(timeoutFirstEngine.getCurrentSession());
		assertEquals(SessionState.FINALIZED, timeoutResult.getFinalized().getState());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Proves
 * schema backward-compatibility ("extend finalized-session schema
 * conservatively/backward-compatibly") end to end:
 *   1. an OLD sessions/{id}.json (no
 *      startingLoadout/endingLoadout field at all) still deserializes
 *      cleanly, with every pre-existing field intact and both loadout
 *      fields simply null -- never a parse failure, never a
 *      fabricated/default loadout;
 *   2. a NEW session with a real starting+ending loadout attached
 *      round-trips losslessly, both via plain Gson and via the real
 *      SessionPersistence.persistFinalized()/loadFinalized() path
 *      against the real LocalStateStore/TelemetryPaths (matching
 *      SessionPersistenceTest's own established real-file, no-Client,
 *      two-account style);
 *   3. loadFinalized() fails open (returns null, never throws) on a
 *      malformed/partial file, the same contract loadCurrent() already
 *      has, applied to the one new read method here.
 *
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project (see SessionPersistenceTest).
 */
public class SessionLoadoutBackwardCompatibilityTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_444L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	@Before
	public void setUp()
	{
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown()
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	// --- 1: old-shape file (no loadout fields at all) ---

	/**
	 * Hand-authored, exactly matching the old field set --
	 * deliberately does NOT include startingLoadout/endingLoadout, the
	 * two fields added here. This is what every
	 * sessions/{id}.json written by the plugin previously
	 * actually looks like on disk today.
	 */
	private static final String OLD_SHAPE_FINALIZED_JSON = "{"
		+ "\"sessionId\":\"old-session-1\","
		+ "\"activityIdentity\":{\"activityType\":\"SLAYER\",\"activityKey\":\"gargoyles:catacombs\",\"displayName\":\"Gargoyles\"},"
		+ "\"state\":\"FINALIZED\","
		+ "\"startedAt\":\"2026-01-01T10:00:00Z\","
		+ "\"lastActiveAt\":\"2026-01-01T10:09:00Z\","
		+ "\"finalizedAt\":\"2026-01-01T10:39:00Z\","
		+ "\"accumulatedActiveDurationMillis\":540000,"
		+ "\"aggregates\":{\"xpGainedBySkill\":{\"SLAYER\":812},\"lootDrops\":[],\"slayerProgressDelta\":6}"
		+ "}";

	@Test
	public void oldShapeJson_deserializesCleanly_loadoutFieldsNullEverythingElseIntact()
	{
		Session reloaded = GSON.fromJson(OLD_SHAPE_FINALIZED_JSON, Session.class);

		assertNotNull(reloaded);
		assertEquals("old-session-1", reloaded.getSessionId());
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertEquals(GARGOYLES, reloaded.getActivityIdentity());
		assertEquals("2026-01-01T10:00:00Z", reloaded.getStartedAt());
		assertEquals("2026-01-01T10:39:00Z", reloaded.getFinalizedAt());
		assertEquals(540000L, reloaded.getAccumulatedActiveDurationMillis());
		assertEquals(Long.valueOf(812L), reloaded.getAggregates().getXpGainedBySkill().get("SLAYER"));
		assertEquals(Integer.valueOf(6), reloaded.getAggregates().getSlayerProgressDelta());

		assertNull("an old session file has no starting loadout -- must deserialize as null, never a fabricated/default snapshot",
			reloaded.getStartingLoadout());
		assertNull("an old session file has no ending loadout -- must deserialize as null, never a fabricated/default snapshot",
			reloaded.getEndingLoadout());
	}

	@Test
	public void oldShapeFile_onRealDisk_loadsThroughSessionPersistence() throws Exception
	{
		File sessionFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "old-session-1"));
		Files.write(sessionFile.toPath(), OLD_SHAPE_FINALIZED_JSON.getBytes(StandardCharsets.UTF_8));

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, "old-session-1");

		assertNotNull("a real pre-Checkpoint-1 file on disk must still load through the new loadFinalized() method", reloaded);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertNull(reloaded.getStartingLoadout());
		assertNull(reloaded.getEndingLoadout());
	}

	// --- 2: new session with a real loadout round-trips losslessly ---

	private static List<StorageState.StorageItem> sampleInventory()
	{
		List<StorageState.StorageItem> items = new ArrayList<>(LoadoutSnapshot.INVENTORY_SIZE);
		items.add(new StorageState.StorageItem(0, 995, "Coins", 12_345, null));
		items.add(new StorageState.StorageItem(1, 1359, "Swordfish", 5, null));
		for (int slot = 2; slot < LoadoutSnapshot.INVENTORY_SIZE; slot++)
		{
			items.add(new StorageState.StorageItem(slot, -1, null, 0, null));
		}
		return items;
	}

	private static List<StorageState.StorageItem> sampleEquipment()
	{
		return Arrays.asList(
			new StorageState.StorageItem(0, 1163, "Bronze full helm", 1, "HEAD"),
			new StorageState.StorageItem(3, -1, null, 0, "WEAPON"),
			new StorageState.StorageItem(4, 1129, "Bronze platebody", 1, "BODY")
		);
	}

	private Session buildFinalizedSessionWithLoadout()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		LoadoutSnapshot starting = new LoadoutSnapshot(
			sampleInventory(), sampleEquipment(), T0.minusSeconds(30).toString(), LoadoutProvenance.PRE_START);
		LoadoutSnapshot ending = new LoadoutSnapshot(
			sampleInventory(), sampleEquipment(), expiry.plusSeconds(5).toString(), LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);

		finalized.setStartingLoadout(starting);
		finalized.setEndingLoadout(ending);
		return finalized;
	}

	@Test
	public void newSessionWithLoadout_plainGsonRoundTrip_preservesEverything()
	{
		Session original = buildFinalizedSessionWithLoadout();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertNotNull(roundTripped.getStartingLoadout());
		assertNotNull(roundTripped.getEndingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, roundTripped.getStartingLoadout().getProvenance());
		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, roundTripped.getEndingLoadout().getProvenance());
		assertEquals(28, roundTripped.getStartingLoadout().getInventory().size());
		assertEquals(995, roundTripped.getStartingLoadout().getInventory().get(0).getItemId());
		assertEquals(-1, roundTripped.getStartingLoadout().getInventory().get(2).getItemId());
		assertEquals(3, roundTripped.getStartingLoadout().getEquipment().size());
		assertEquals("HEAD", roundTripped.getStartingLoadout().getEquipment().get(0).getEquipmentSlot());
	}

	@Test
	public void newSessionWithLoadout_realPersistFinalizedThenLoadFinalized_preservesLoadout() throws Exception
	{
		Session original = buildFinalizedSessionWithLoadout();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, original, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, original.getSessionId());

		assertNotNull(reloaded);
		assertEquals(original.getSessionId(), reloaded.getSessionId());
		assertNotNull("starting loadout must survive a real write-then-read cycle", reloaded.getStartingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, reloaded.getStartingLoadout().getProvenance());
		assertEquals(28, reloaded.getStartingLoadout().getInventory().size());
		assertEquals(1359, reloaded.getStartingLoadout().getInventory().get(1).getItemId());
		assertNotNull("ending loadout must survive a real write-then-read cycle", reloaded.getEndingLoadout());
		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, reloaded.getEndingLoadout().getProvenance());
	}

	@Test
	public void sessionWithUnavailableLoadout_roundTripsAsExplicitUnavailable_neverNullAfterBeingSet()
	{
		Session original = buildFinalizedSessionWithLoadout();
		original.setEndingLoadout(LoadoutSnapshot.unavailable());

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertNotNull("an explicitly-set unavailable() loadout is a real value, not the same as an old file's null",
			roundTripped.getEndingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, roundTripped.getEndingLoadout().getProvenance());
		assertTrue(roundTripped.getEndingLoadout().getInventory().isEmpty());
		assertTrue(roundTripped.getEndingLoadout().getEquipment().isEmpty());
	}

	// --- 3: loadFinalized() fails open on a malformed/partial file ---

	@Test
	public void loadFinalized_malformedFile_returnsNullRatherThanThrowing() throws Exception
	{
		File sessionFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "corrupt-session"));
		Files.write(sessionFile.toPath(), "{ this is not valid json".getBytes(StandardCharsets.UTF_8));

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, "corrupt-session");

		assertNull("a malformed session file must fail open (null), never throw and never crash a caller iterating many sessions",
			reloaded);
	}

	@Test
	public void loadFinalized_missingFile_returnsNull()
	{
		assertNull(persistence.loadFinalized(TEST_ACCOUNT_HASH, "does-not-exist"));
	}

	@Test
	public void differentAccounts_neverSeeEachOthersLoadoutData() throws Exception
	{
		long otherAccountHash = 888_777_555L;
		deleteAccountDir(otherAccountHash);
		try
		{
			Session original = buildFinalizedSessionWithLoadout();
			persistence.persistFinalized(TEST_ACCOUNT_HASH, original, null);
			awaitAsyncChain();

			Session crossAccountRead = persistence.loadFinalized(otherAccountHash, original.getSessionId());
			assertNull("a finalized session (and its loadout) must never be visible under a different account's hash",
				crossAccountRead);
		}
		finally
		{
			deleteAccountDir(otherAccountHash);
		}
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Slayer task-unit/physical-kill semantics regression coverage (see
 * SessionAggregates#getSlayerProgressDelta()'s own javadoc and
 * MetricUpdate#slayerProgress()'s own javadoc): every
 * MetricUpdate.slayerProgress() call carries ONE event's own
 * taskUnitsConsumed — the observed decrease in the assignment's
 * authoritative remaining-count value — which is a TASK-UNIT delta,
 * never a physical NPC-kill count, and must be SUMMED, never
 * overwritten, into SessionAggregates.slayerProgressDelta. Directly
 * against the real, pure, production SessionAggregateUpdater.apply() —
 * no mocking.
 */
public class SessionAggregateUpdaterTest
{
	@Test
	public void slayerProgress_singleEventOfTwoUnits_accumulatesExactlyTwoTaskUnits()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));

		assertEquals("taskUnitsConsumed=2 for one event (e.g. an expeditious-bracelet-style proc on a "
			+ "single physical kill) must accumulate to exactly 2 task units, never 1",
			Integer.valueOf(2), aggregates.getSlayerProgressDelta());
		assertEquals("the honestly-named accessor must return the same value as the raw getter",
			Integer.valueOf(2), aggregates.getSlayerTaskUnitsConsumed());
	}

	@Test
	public void slayerProgress_multipleEvents_sumsTaskUnitsAcrossTheWholeSession()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(1, 39));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 37));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(0, 37));

		// 1 + 2 + 0 = 3 task units total. The zero-unit event (e.g. a
		// bracelet-of-slaughter-style save, a physical kill that
		// consumed no task unit at all) contributes nothing -- it must
		// never subtract from, or reset, the running total.
		assertEquals(Integer.valueOf(3), aggregates.getSlayerProgressDelta());
	}

	@Test
	public void slayerProgress_currentRemainingIsOverwrittenNeverSummed_independentOfTaskUnitTotal()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(1, 37));

		assertEquals("slayerProgressDelta accumulates (2 + 1 = 3 task units)",
			Integer.valueOf(3), aggregates.getSlayerProgressDelta());
		assertEquals("latestSlayerCurrentRemaining is the LATEST authoritative absolute value only, "
			+ "never summed/accumulated -- the authoritative task-remaining figure this project must "
			+ "keep exactly as-is",
			Integer.valueOf(37), aggregates.getLatestSlayerCurrentRemaining());
	}

	@Test
	public void slayerProgress_neverPopulatesReliableCount_taskUnitsAreNotAPhysicalKillSignal()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));

		assertNull("Slayer task-unit progress must never populate reliableCount -- that field is "
			+ "reserved for a genuinely authoritative physical-kill/completion signal (e.g. BOSS_KILL), "
			+ "and this pathway must never manufacture one from task units",
			aggregates.getReliableCount());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Dedicated full-stack (SessionRuntimeCoordinator + SessionPersistence +
 * LocalStateStore + real disk I/O) coverage for the INTERRUPTED-ACTIVITY
 * RESUME (A -> brief B -> A) feature's PERSISTENCE contract: restart
 * safety, the account-switch/orderly-shutdown boundaries ("no candidate
 * may disappear silently"), and the manual "Re-evaluate Session" path's
 * preserved corrective semantics (it must never manufacture a hidden
 * resumable prior session). See InterruptedActivityResumeEngineTest for
 * the pure engine-level lifecycle/metric-ownership/boundary coverage
 * this file deliberately does not re-prove.
 */
public class InterruptedActivityResumeCoordinatorTest
{
	private static final long ACCOUNT_A = 810_200_300L;
	private static final long ACCOUNT_B = 810_200_400L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionRuntimeCoordinator coordinator;
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("interrupted-activity-resume-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));

		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
	}

	@After
	public void tearDown() throws Exception
	{
		if (store != null)
		{
			store.shutdown();
		}
		if (testRoot != null)
		{
			TestFilepaths.rooted(testRoot).deleteRecursively();
		}
	}

	private Session readFinalizedFile(String sessionId) throws Exception
	{
		return store.readIfExists(TelemetryPaths.sessionFile(ACCOUNT_A, sessionId), Session.class);
	}

	// A genuine, confirmed ACTIVE Slayer(Gargoyles) -> Agility switch, via
	// the SAME real, two-observation-confirmed hysteresis path already
	// exhaustively proved elsewhere (see SessionRuntimeCoordinatorTest's
	// own liveBug_incidentalAgilityXpWhileActiveGargoyles... test, which
	// this mirrors) -- exists purely to set up "A parked, B current"
	// state with the minimum ceremony, not to re-prove that decision
	// itself.
	private String establishActiveGargoylesThenSwitchToAgility(Instant confirmingAt) throws Exception
	{
		coordinator.ensureAccountLoaded(ACCOUNT_A);
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(T0, "Gargoyles", "Catacombs", 1).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		String gargoylesSessionId = coordinator.testCurrentSession().getSessionId();

		Instant firstAgility = T0.plusSeconds(34);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(firstAgility, "AGILITY", 6L).withGameTick(2L));
		coordinator.testProcessTick(3L, firstAgility);

		coordinator.testEnqueueSignal(SessionSignal.xpChange(confirmingAt, "AGILITY", 4L).withGameTick(3L));
		coordinator.testProcessTick(4L, confirmingAt);

		return gargoylesSessionId;
	}

	// =====================================================================
	// REQUIRED TEST 12: restart AFTER the candidate has already expired
	// -- A finalizes exactly once, at T1, and no resumability remains.
	// T0 is a fixed point far in the past relative to whenever this test
	// actually executes, so ensureAccountLoaded()'s own real
	// Instant.now() is guaranteed to already be long past the
	// candidate's 5-minute window -- a completely realistic "restarted
	// the client long afterward" scenario, deterministic by construction
	// without needing to inject a fake clock.
	// =====================================================================
	@Test
	public void restartAfterCandidateExpiry_aFinalizesExactlyOnceAtT1_noResumabilityRemains() throws Exception
	{
		Instant confirmingAt = T0.plusSeconds(70);
		String gargoylesSessionId = establishActiveGargoylesThenSwitchToAgility(confirmingAt);
		Thread.sleep(300);

		InterruptedCandidateRecord beforeRestart = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull("the parked Gargoyles candidate must be durably persisted before restart", beforeRestart);
		assertNull("A must not yet be finalized anywhere before restart", readFinalizedFile(gargoylesSessionId));

		// Simulate a client restart: a brand-new coordinator against the
		// SAME on-disk store/account.
		SessionRuntimeCoordinator restarted = new SessionRuntimeCoordinator(store);
		restarted.ensureAccountLoaded(ACCOUNT_A);

		Thread.sleep(300);
		Session finalizedA = readFinalizedFile(gargoylesSessionId);
		assertNotNull("A must finalize exactly once, durably, during rehydration", finalizedA);
		assertEquals(SessionState.FINALIZED, finalizedA.getState());
		assertEquals("A must finalize AT ITS OWN ORIGINAL interruption instant, never at restart time",
			confirmingAt.toString(), finalizedA.getFinalizedAt());

		InterruptedCandidateRecord afterRestart = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNull("no resumability may remain once the candidate has finalized", afterRestart);
	}

	// =====================================================================
	// REQUIRED TEST 13: account switch -- the parked candidate finalizes
	// under the OLD account only, never leaking into the new account.
	// =====================================================================
	@Test
	public void accountSwitchWithParkedCandidate_flushesUnderOldAccountOnly_neverLeaksToNewAccount() throws Exception
	{
		Instant confirmingAt = T0.plusSeconds(70);
		String gargoylesSessionId = establishActiveGargoylesThenSwitchToAgility(confirmingAt);
		Thread.sleep(300);

		InterruptedCandidateRecord beforeSwitch = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull(beforeSwitch);

		coordinator.ensureAccountLoaded(ACCOUNT_B);
		Thread.sleep(300);

		Session finalizedUnderA = readFinalizedFile(gargoylesSessionId);
		assertNotNull("A must be flushed/finalized under the OLD account exactly", finalizedUnderA);
		assertEquals(SessionState.FINALIZED, finalizedUnderA.getState());
		assertEquals("finalized AT ITS OWN interruption instant, never at switch time",
			confirmingAt.toString(), finalizedUnderA.getFinalizedAt());

		InterruptedCandidateRecord afterSwitchOldAccount = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNull("the old account's candidate record must be cleared once flushed", afterSwitchOldAccount);

		InterruptedCandidateRecord newAccountCandidate = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_B);
		assertNull("the new account must never inherit the old account's interrupted candidate",
			newAccountCandidate);
		assertNull("account B must start from a clean hydration, never an invented transition",
			coordinator.testCurrentSession());
	}

	// =====================================================================
	// REQUIRED TEST 14: orderly plugin shutdown -- the parked candidate
	// is never lost, and finalizes exactly once, at T1.
	// =====================================================================
	@Test
	public void orderlyShutdown_parkedCandidateNotLost_finalizesOnceAtT1() throws Exception
	{
		Instant confirmingAt = T0.plusSeconds(70);
		String gargoylesSessionId = establishActiveGargoylesThenSwitchToAgility(confirmingAt);

		coordinator.flushPendingAndShutdown();

		Thread.sleep(300);
		Session finalizedA = readFinalizedFile(gargoylesSessionId);
		assertNotNull("the parked candidate must never disappear silently on orderly shutdown", finalizedA);
		assertEquals(SessionState.FINALIZED, finalizedA.getState());
		assertEquals(confirmingAt.toString(), finalizedA.getFinalizedAt());

		InterruptedCandidateRecord afterShutdown = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNull(afterShutdown);
	}

	// =====================================================================
	// LIVE REGRESSION: Crafting A -> Cooking B -> close RuneLite ->
	// restart -> return to Crafting inside A's window. Drives the REAL
	// production shutdown path of the OLD process (the exact coordinator
	// method RuneLite's ClientShutdown / Plugin.shutDown() invoke,
	// followed by the store drain OsrsTelemetryPlugin.shutDown() does),
	// then constructs FRESH LocalStateStore + SessionRuntimeCoordinator
	// objects exactly as a new client process does and loads the same
	// account via ensureAccountLoaded() (what handleLogin() calls). The
	// pre-existing restart coverage skipped the old process's shutdown
	// path entirely (engine tests hand the in-memory candidate straight
	// to rehydrate()), which is precisely where the candidate was being
	// destroyed. Timestamps are anchored to the real clock because
	// ensureAccountLoaded() rehydrates against Instant.now().
	// =====================================================================
	@Test
	public void liveRestart_clientShutdownOnly_craftingAResumesWithSameSessionId() throws Exception
	{
		assertRealRestartResumesCraftingA(false);
	}

	// Real RuneLite close where Plugin.shutDown() ALSO runs after
	// ClientShutdown: the later shutDown must not destroy the candidate
	// ClientShutdown just preserved.
	@Test
	public void liveRestart_clientShutdownThenPluginShutDown_candidateSurvives_craftingAResumes() throws Exception
	{
		assertRealRestartResumesCraftingA(true);
	}

	// MANUAL plugin disable (no ClientShutdown): Spyglass could not
	// observe gameplay while disabled, so A must finalize exactly once at
	// its ORIGINAL interruption instant, the record must be cleared, and a
	// later fresh runtime must never resume A -- even inside the
	// original 5-minute wall-clock window.
	@Test
	public void manualPluginDisable_craftingAFinalizesAtT1_cleared_freshRuntimeCannotResumeA() throws Exception
	{
		String[] ids = establishCraftingAThenCookingB();
		String aSessionId = ids[0];
		String bSessionId = ids[1];
		Instant t1 = Instant.parse(ids[2]);

		coordinator.flushPendingAndShutdown();
		store.shutdown();

		Session finalizedA = readFinalizedFile(aSessionId);
		assertNotNull("A must finalize on a manual disable", finalizedA);
		assertEquals(SessionState.FINALIZED, finalizedA.getState());
		assertEquals("A must finalize at its ORIGINAL interruption instant", t1.toString(), finalizedA.getFinalizedAt());
		assertNull("the candidate record must be cleared on a manual disable",
			new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A));

		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
		coordinator.ensureAccountLoaded(ACCOUNT_A);
		assertNull("a fresh runtime must have no resumable candidate", coordinator.testInterruptedCandidate());
		assertEquals(bSessionId, coordinator.testCurrentSession().getSessionId());

		Instant firstReturn = Instant.now().plusSeconds(5);
		Instant secondReturn = firstReturn.plusSeconds(30);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(firstReturn, "CRAFTING", 280L).withGameTick(100L));
		coordinator.testProcessTick(101L, firstReturn);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(secondReturn, "CRAFTING", 630L).withGameTick(101L));
		coordinator.testProcessTick(102L, secondReturn);

		Session current = coordinator.testCurrentSession();
		assertEquals("crafting", current.getActivityIdentity().getActivityKey());
		assertFalse("returning Crafting must be a NEW session, never resurrected A",
			aSessionId.equals(current.getSessionId()));
		Thread.sleep(300);
		Session aAgain = readFinalizedFile(aSessionId);
		assertEquals("A must have finalized exactly once, untouched afterward", t1.toString(), aAgain.getFinalizedAt());
	}

	// Crafting A (active) -> genuine Cooking B switch through the real
	// coordinator path, anchored to the real clock (ensureAccountLoaded()
	// rehydrates against Instant.now()). Returns {aSessionId, bSessionId,
	// aInterruptedAt, aStartedAt}.
	private String[] establishCraftingAThenCookingB() throws Exception
	{
		Instant base = Instant.now().minusSeconds(150);
		long tick = 1L;

		coordinator.ensureAccountLoaded(ACCOUNT_A);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(base, "CRAFTING", 140L).withGameTick(tick));
		coordinator.testProcessTick(++tick, base);
		Instant craftingAgain = base.plusSeconds(30);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(craftingAgain, "CRAFTING", 980L).withGameTick(tick));
		coordinator.testProcessTick(++tick, craftingAgain);
		Session a = coordinator.testCurrentSession();
		assertEquals("crafting", a.getActivityIdentity().getActivityKey());

		Instant cookingAt = craftingAgain;
		for (int i = 0; i < 6 && coordinator.testInterruptedCandidate() == null; i++)
		{
			cookingAt = cookingAt.plusSeconds(20);
			coordinator.testEnqueueSignal(SessionSignal.xpChange(cookingAt, "COOKING", 2100L).withGameTick(tick));
			coordinator.testProcessTick(++tick, cookingAt);
		}
		assertNotNull("setup: A must be parked by a genuine Cooking switch", coordinator.testInterruptedCandidate());
		assertEquals(a.getSessionId(), coordinator.testInterruptedCandidate().getSessionId());
		Session b = coordinator.testCurrentSession();
		assertEquals("cooking", b.getActivityIdentity().getActivityKey());
		Thread.sleep(300);
		InterruptedCandidateRecord parked = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull(parked);
		return new String[] {a.getSessionId(), b.getSessionId(), parked.getInterruptedAt(), a.getStartedAt()};
	}

	private void assertRealRestartResumesCraftingA(boolean pluginShutDownFollows) throws Exception
	{
		String[] ids = establishCraftingAThenCookingB();
		String aSessionId = ids[0];
		String bSessionId = ids[1];
		String aStartedAt = ids[3];

		// 3./4. Real shutdown of the OLD process -- the exact entry point
		// onClientShutdown() drives (beginClientShutdownFinalization()
		// marks client shutdown synchronously, then runs the blocking
		// finalization on scheduledExecutor -- called directly here since
		// that injected executor does not exist in tests) -- optionally followed by
		// the Plugin.shutDown() sequence, then the store drain.
		coordinator.markClientShutdownBegun();
		coordinator.finalizeForClientShutdownBlocking();
		if (pluginShutDownFollows)
		{
			coordinator.flushPendingAndShutdown();
		}
		store.shutdown();

		InterruptedCandidateRecord persistedBefore = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull("the candidate record must survive the old process's shutdown path", persistedBefore);
		assertNull("shutdown must not finalize A", readFinalizedFile(aSessionId));

		// 5./6. FRESH runtime objects, as real plugin startup builds them,
		// then the same account logs in.
		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
		coordinator.ensureAccountLoaded(ACCOUNT_A);

		// 7.
		Session current = coordinator.testCurrentSession();
		assertEquals(bSessionId, current.getSessionId());
		assertEquals("cooking", current.getActivityIdentity().getActivityKey());
		assertEquals(SessionState.SUSPENDED, current.getState());
		Session candidate = coordinator.testInterruptedCandidate();
		assertNotNull("the interrupted candidate must be restored into the fresh engine", candidate);
		assertEquals(aSessionId, candidate.getSessionId());
		assertEquals("crafting", candidate.getActivityIdentity().getActivityKey());
		Thread.sleep(300);
		InterruptedCandidateRecord persistedAfter = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull(persistedAfter);
		assertEquals(persistedBefore.getInterruptedAt(), persistedAfter.getInterruptedAt());
		assertEquals(persistedBefore.getExpiresAt(), persistedAfter.getExpiresAt());
		assertEquals(persistedBefore.getSession().getSessionId(), persistedAfter.getSession().getSessionId());
		Instant expiresAt = persistedAfter.expiresAtInstant();

		// 8. Ordinary Crafting evidence through the real coordinator path.
		Instant firstReturn = Instant.now().plusSeconds(5);
		Instant secondReturn = firstReturn.plusSeconds(30);
		assertFalse("setup: the return must be inside A's window", secondReturn.isAfter(expiresAt));
		coordinator.testEnqueueSignal(SessionSignal.xpChange(firstReturn, "CRAFTING", 280L).withGameTick(100L));
		coordinator.testProcessTick(101L, firstReturn);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(secondReturn, "CRAFTING", 630L).withGameTick(101L));
		coordinator.testProcessTick(102L, secondReturn);

		// 9.
		Session resumed = coordinator.testCurrentSession();
		assertEquals("original A must resume -- never a fresh Crafting session", aSessionId, resumed.getSessionId());
		assertEquals(aStartedAt, resumed.getStartedAt());
		assertEquals(SessionState.ACTIVE, resumed.getState());
		assertNull(coordinator.testInterruptedCandidate());

		Thread.sleep(300);
		Session finalizedB = readFinalizedFile(bSessionId);
		assertNotNull("B must finalize separately", finalizedB);
		assertEquals(SessionState.FINALIZED, finalizedB.getState());
		assertNull("A must not have been finalized anywhere", readFinalizedFile(aSessionId));
		assertNull("no candidate record may linger once A resumed",
			new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A));
		try (java.util.stream.Stream<Path> files = Files.list(testRoot.resolve(String.valueOf(ACCOUNT_A)).resolve("sessions")))
		{
			assertEquals("exactly one finalized session file (B) -- no fresh Crafting session minted",
				1L, files.count());
		}
	}

	// =====================================================================
	// REQUIRED TEST 20: manual "Re-evaluate Session" regression -- it
	// must never manufacture a hidden resumable prior session/History
	// entry, even in a scenario the AUTOMATIC pipeline would genuinely
	// park (allowInterruptedResume=false is threaded through
	// specifically to guarantee this -- see reEvaluateCurrentSession()'s
	// own wiring). The outgoing session must finalize IMMEDIATELY and
	// DURABLY, exactly as manual re-evaluation always has, before this
	// feature existed.
	// =====================================================================
	@Test
	public void manualReEvaluation_neverParksOutgoingSession_evenInAScenarioTheAutomaticPathWouldHaveParked() throws Exception
	{
		coordinator.ensureAccountLoaded(ACCOUNT_A);

		// Establish a plain generic COMBAT session (no recent NPC target
		// tracked) -- the exact same setup already proven elsewhere to
		// switch immediately via the manual button
		// (manualReEvaluation_freshEvidence_switchesImmediately_withoutWaitingForNormalCandidateThreshold
		// in SessionRuntimeCoordinatorTest), which this test extends to
		// also verify the interrupted-candidate persistence contract that
		// one does not check.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0, "STRENGTH", 50L).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		Session established = coordinator.testCurrentSession();
		String establishedSessionId = established.getSessionId();

		coordinator.reEvaluateCurrentSession("Giant rat", 55, T0.plusSeconds(5));

		Session afterManualCall = coordinator.testCurrentSession();
		assertFalse("a real activity switch must start a brand-new session",
			establishedSessionId.equals(afterManualCall.getSessionId()));

		Thread.sleep(300);
		Session finalizedOld = readFinalizedFile(establishedSessionId);
		assertNotNull("manual re-evaluation must finalize the outgoing session IMMEDIATELY and DURABLY -- "
			+ "never park it", finalizedOld);
		assertEquals(SessionState.FINALIZED, finalizedOld.getState());
		assertEquals(T0.plusSeconds(5).toString(), finalizedOld.getFinalizedAt());

		InterruptedCandidateRecord candidateRecord = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNull("manual re-evaluation must never manufacture a hidden resumable prior session",
			candidateRecord);
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import org.junit.Test;

/**
 * Proves {@link SessionSnapshot#capture(Session)} does exactly
 * what its own javadoc claims: every collection/nested value object it
 * returns is a fresh, independent copy that shares no reference with
 * the {@link Session}/{@link SessionAggregates} it was built from, so
 * mutating the source AFTER capture never changes an already-returned
 * snapshot (items B/C/D/E). Also proves
 * (item A) that {@link SessionRuntimeCoordinator#getCurrentSessionSnapshot()}'s
 * return type can never hand a caller a live {@link Session} reference,
 * and (item F) that one captured snapshot is a coherent identity/state/
 * aggregate combination -- true "by construction" here since capture()
 * is a single synchronous method with no partial-write window, the same
 * argument the production call site relies on under
 * SessionRuntimeCoordinator's monitor (see that method's own javadoc);
 * a single-threaded JUnit test cannot itself exercise concurrent
 * mutation, so this test demonstrates correctness-by-construction of
 * the copying code, not a live race.
 *
 * Builds every fixture via the real, public {@link SessionLifecycleEngine}
 * (onQualifyingActivity()), exactly like SessionLifecycleEngineTest and
 * CurrentSessionSnapshotTest -- Session's mutation surface is
 * intentionally package-private (see its own javadoc), so driving the
 * real engine is the production-faithful way to get an ACTIVE Session.
 * This test class itself lives in the session package (like
 * SessionRuntimeCoordinatorTest), so it may also mutate
 * Session#getAggregates()' public @Data fields directly to simulate
 * "the runtime kept mutating after the snapshot was taken" -- exactly
 * what a concurrent client-thread/scheduledExecutor mutation would do
 * in production.
 */
public class SessionSnapshotTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");

	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	// ------------------------------------------------------------------
	// A. absent()/capture(null) never exposes a live Session -- and
	// capture()'s return type is SessionSnapshot, never Session, so no
	// caller of it can ever obtain a live Session reference through it.
	// ------------------------------------------------------------------
	@Test
	public void captureNull_returnsAbsent()
	{
		SessionSnapshot snapshot = SessionSnapshot.capture(null);

		assertSame(SessionSnapshot.absent(), snapshot);
		assertFalse(snapshot.isPresent());
	}

	@Test
	public void absent_hasNoIdentityOrAggregateData()
	{
		SessionSnapshot snapshot = SessionSnapshot.absent();

		assertFalse(snapshot.isPresent());
		assertNull(snapshot.getSessionId());
		assertNull(snapshot.getActivityType());
		assertNull(snapshot.getState());
		assertTrue(snapshot.getXpGainedBySkill().isEmpty());
		assertNull(snapshot.getReliableCount());
		assertNull(snapshot.getSlayerProgressDelta());
		assertTrue(snapshot.getLootDrops().isEmpty());
		assertNull(snapshot.getLatestSlayerCurrentRemaining());
	}

	// ------------------------------------------------------------------
	// B. XP map independence: mutating the live Session's XP map AFTER
	// capture never changes the already-returned snapshot.
	// ------------------------------------------------------------------
	@Test
	public void xpMap_isIndependentOfLaterSessionMutation()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 100L);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertEquals(Long.valueOf(100L), snapshot.getXpGainedBySkill().get("SLAYER"));
		assertNotSame(session.getAggregates().getXpGainedBySkill(), snapshot.getXpGainedBySkill());

		// Simulates a concurrent runtime mutation arriving after this
		// snapshot was already handed to a reader.
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 999L);
		session.getAggregates().getXpGainedBySkill().put("ATTACK", 50L);

		assertEquals(Long.valueOf(100L), snapshot.getXpGainedBySkill().get("SLAYER"));
		assertFalse(snapshot.getXpGainedBySkill().containsKey("ATTACK"));
	}

	@Test(expected = UnsupportedOperationException.class)
	public void xpMap_isUnmodifiable()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 100L);

		SessionSnapshot.capture(session).getXpGainedBySkill().put("ATTACK", 1L);
	}

	// ------------------------------------------------------------------
	// C. Loot independence: mutating the live Session's loot groups/
	// items AFTER capture never changes the already-returned snapshot.
	// ------------------------------------------------------------------
	@Test
	public void lootDrops_areIndependentOfLaterSessionMutation()
	{
		Session session = activeSessionAt(T0);

		SessionAggregates.LootDropGroup group = new SessionAggregates.LootDropGroup();
		group.setSourceName("Gargoyle");
		group.setObservedAt(T0.toString());
		SessionAggregates.LootItemAggregate item = new SessionAggregates.LootItemAggregate();
		item.setItemId(561);
		item.setItemName("Nature rune");
		item.setQuantity(10L);
		group.setItems(new java.util.ArrayList<>(Collections.singletonList(item)));
		session.getAggregates().getLootDrops().add(group);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertEquals(1, snapshot.getLootDrops().size());
		assertEquals(10L, snapshot.getLootDrops().get(0).getItems().get(0).getQuantity());

		// Simulates a concurrent runtime mutation arriving after this
		// snapshot was already handed to a reader: the quantity on the
		// SAME live item object changes, and a second group is added.
		item.setQuantity(999L);
		SessionAggregates.LootDropGroup secondGroup = new SessionAggregates.LootDropGroup();
		secondGroup.setSourceName("Gargoyle");
		session.getAggregates().getLootDrops().add(secondGroup);

		assertEquals(1, snapshot.getLootDrops().size());
		assertEquals(10L, snapshot.getLootDrops().get(0).getItems().get(0).getQuantity());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void lootDrops_outerListIsUnmodifiable()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().getLootDrops().add(new SessionAggregates.LootDropGroup());

		SessionSnapshot.capture(session).getLootDrops().add(new SessionAggregates.LootDropGroup());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void lootDrops_innerItemListIsUnmodifiable()
	{
		Session session = activeSessionAt(T0);
		SessionAggregates.LootDropGroup group = new SessionAggregates.LootDropGroup();
		SessionAggregates.LootItemAggregate item = new SessionAggregates.LootItemAggregate();
		item.setItemName("Nature rune");
		group.setItems(Collections.singletonList(item));
		session.getAggregates().getLootDrops().add(group);

		SessionSnapshot.capture(session).getLootDrops().get(0).getItems()
			.add(new SessionAggregates.LootItemAggregate());
	}

	// ------------------------------------------------------------------
	// D. ReliableCount independence: it is a mutable object
	// (SessionAggregates.ReliableCount, a @Data class with setters), so
	// capture() must copy its fields into a NEW instance -- mutating the
	// live source object afterward must never change the snapshot's copy.
	// ------------------------------------------------------------------
	@Test
	public void reliableCount_isIndependentOfLaterSessionMutation()
	{
		Session session = activeSessionAt(T0);
		SessionAggregates.ReliableCount rc = new SessionAggregates.ReliableCount();
		rc.setKind(SessionAggregates.ReliableCountKind.KILLS);
		rc.setSourceKey("gargoyles:catacombs");
		rc.setSessionOccurrences(3);
		rc.setAuthoritativeCurrentValue(500);
		session.getAggregates().setReliableCount(rc);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertNotSame(rc, snapshot.getReliableCount());
		assertEquals(3, snapshot.getReliableCount().getSessionOccurrences());

		// Simulates a concurrent runtime mutation of the SAME live
		// ReliableCount object arriving after this snapshot was already
		// handed to a reader.
		rc.setSessionOccurrences(4);
		rc.setAuthoritativeCurrentValue(501);

		assertEquals(3, snapshot.getReliableCount().getSessionOccurrences());
		assertEquals(Integer.valueOf(500), snapshot.getReliableCount().getAuthoritativeCurrentValue());
	}

	@Test
	public void reliableCount_absentStaysNull()
	{
		Session session = activeSessionAt(T0);
		assertNull(session.getAggregates().getReliableCount());

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertNull(snapshot.getReliableCount());
	}

	// ------------------------------------------------------------------
	// E. slayerProgressDelta: a boxed Integer is already an immutable
	// value once assigned -- capture() just needs to carry the correct
	// value through (no shared mutable wrapper is possible for a boxed
	// primitive), confirmed here by simple value equality plus a later
	// mutation of the SOURCE FIELD (not the value itself, which can't
	// be mutated) having no effect on the already-captured snapshot.
	// ------------------------------------------------------------------
	@Test
	public void slayerProgressDelta_copiedAsPlainValue()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().setSlayerProgressDelta(7);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertEquals(Integer.valueOf(7), snapshot.getSlayerProgressDelta());

		// Simulates a concurrent runtime mutation replacing the field's
		// value entirely after this snapshot was already captured.
		session.getAggregates().setSlayerProgressDelta(20);

		assertEquals(Integer.valueOf(7), snapshot.getSlayerProgressDelta());
	}

	// ------------------------------------------------------------------
	// K. latestSlayerCurrentRemaining: a boxed
	// Integer, copied verbatim exactly like slayerProgressDelta above
	// (test E), but tracking a DIFFERENT aggregate with OVERWRITE
	// semantics rather than SUM semantics -- SessionSnapshot must carry
	// it through defensively (correctly, since it is a plain immutable
	// boxed value) so CurrentSessionSnapshot (ui.model) can surface it
	// without ever reaching back into SessionAggregates/SlayerCollector.
	// ------------------------------------------------------------------
	@Test
	public void latestSlayerCurrentRemaining_copiedAsPlainValue()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().setLatestSlayerCurrentRemaining(98);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertEquals(Integer.valueOf(98), snapshot.getLatestSlayerCurrentRemaining());

		// Simulates a concurrent runtime mutation (the next Gargoyle kill's
		// SLAYER_TASK_PROGRESS overwriting the field) after this snapshot
		// was already captured.
		session.getAggregates().setLatestSlayerCurrentRemaining(97);

		assertEquals(Integer.valueOf(98), snapshot.getLatestSlayerCurrentRemaining());
	}

	// ------------------------------------------------------------------
	// F. One captured snapshot is a coherent identity/state/aggregate
	// combination -- every field reflects the SAME point-in-time state,
	// never a mix of pre- and post-transition values. Correct-by-
	// construction: capture() is one synchronous method with no partial
	// -write window, so this test demonstrates the invariant holds for
	// a specific, non-trivial state (mid-SUSPENDED, with XP/loot/reliable
	// -count/slayer data already attached) rather than proving cross-
	// thread atomicity, which a single-threaded JUnit test cannot do --
	// see class javadoc.
	// ------------------------------------------------------------------
	@Test
	public void capturedSnapshot_isCoherentForItsExactState()
	{
		Session session = activeSessionAt(T0);
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 5000L);
		SessionAggregates.ReliableCount rc = new SessionAggregates.ReliableCount();
		rc.setKind(SessionAggregates.ReliableCountKind.KILLS);
		rc.setSessionOccurrences(2);
		session.getAggregates().setReliableCount(rc);
		session.getAggregates().setSlayerProgressDelta(9);

		SessionSnapshot snapshot = SessionSnapshot.capture(session);

		// Every field on this ONE snapshot object reflects the exact
		// same moment: the pre-transition identity/session id together
		// with the aggregates attached to that same Session instance at
		// capture time.
		assertTrue(snapshot.isPresent());
		assertEquals(session.getSessionId(), snapshot.getSessionId());
		assertEquals(SessionState.ACTIVE, snapshot.getState());
		assertEquals(ActivityType.SLAYER, snapshot.getActivityType());
		assertEquals("Gargoyles", snapshot.getActivityDisplayName());
		assertEquals(Long.valueOf(5000L), snapshot.getXpGainedBySkill().get("SLAYER"));
		assertEquals(2, snapshot.getReliableCount().getSessionOccurrences());
		assertEquals(Integer.valueOf(9), snapshot.getSlayerProgressDelta());
		assertEquals(session.getAccumulatedActiveDurationMillis(), snapshot.getAccumulatedActiveDurationMillis());
		assertEquals(session.getLastActiveAt(), snapshot.getLastActiveAt());
	}

	@Test
	public void capturedSnapshot_suspendedState_isCoherent()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant t1 = T0.plus(Duration.ofMinutes(2));
		engine.onQualifyingActivity(GARGOYLES, t1);
		engine.advanceTime(t1.plus(Duration.ofMinutes(10)));

		Session session = engine.getCurrentSession();
		assertEquals(SessionState.SUSPENDED, session.getState());

		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertEquals(SessionState.SUSPENDED, snapshot.getState());
		assertEquals(Duration.ofMinutes(2).toMillis(), snapshot.getAccumulatedActiveDurationMillis());
		assertEquals(session.getSessionId(), snapshot.getSessionId());
	}

	private static Session activeSessionAt(Instant at)
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, at);
		return engine.getCurrentSession();
	}

	// ------------------------------------------------------------------
	// Immediate Current Session XP display:
	// the live-XP-aware capture(Session, Map) overload.
	// ------------------------------------------------------------------

	@Test
	public void legacyCapture_alwaysReturnsEmptyLivePendingXp()
	{
		Session session = activeSessionAt(T0);
		SessionSnapshot snapshot = SessionSnapshot.capture(session);
		assertTrue(snapshot.getLivePendingXpBySkill().isEmpty());
	}

	@Test
	public void captureWithLiveXp_carriesTheGivenMapVerbatim()
	{
		Session session = activeSessionAt(T0);
		java.util.Map<String, Long> live = new java.util.HashMap<>();
		live.put("Woodcutting", 40L);

		SessionSnapshot snapshot = SessionSnapshot.capture(session, live);

		assertEquals(Long.valueOf(40L), snapshot.getLivePendingXpBySkill().get("Woodcutting"));
	}

	@Test
	public void captureWithLiveXp_defensivelyCopies_neverALiveViewOfTheInputMap()
	{
		Session session = activeSessionAt(T0);
		java.util.Map<String, Long> live = new java.util.HashMap<>();
		live.put("Agility", 15L);

		SessionSnapshot snapshot = SessionSnapshot.capture(session, live);
		live.put("Agility", 999L);
		live.put("Fishing", 5L);

		assertEquals(Long.valueOf(15L), snapshot.getLivePendingXpBySkill().get("Agility"));
		assertFalse(snapshot.getLivePendingXpBySkill().containsKey("Fishing"));
	}

	@Test
	public void captureWithLiveXp_nullSession_stillReturnsAbsent()
	{
		java.util.Map<String, Long> live = new java.util.HashMap<>();
		live.put("Attack", 10L);
		SessionSnapshot snapshot = SessionSnapshot.capture(null, live);
		assertFalse(snapshot.isPresent());
	}

	@Test
	public void captureWithLiveXp_nullMap_treatedAsEmpty()
	{
		Session session = activeSessionAt(T0);
		SessionSnapshot snapshot = SessionSnapshot.capture(session, null);
		assertTrue(snapshot.getLivePendingXpBySkill().isEmpty());
	}

	// ------------------------------------------------------------------
	// CURRENT SESSION XP LEVEL-PROGRESS PASS: the absolute-XP-aware
	// capture(Session, Map, Map) overload -- same defensive-copy
	// contract already proven above for livePendingXpBySkill, applied to
	// the new third map.
	// ------------------------------------------------------------------

	@Test
	public void legacyCaptureOverloads_alwaysReturnEmptyAbsoluteXp()
	{
		Session session = activeSessionAt(T0);
		assertTrue(SessionSnapshot.capture(session).getAbsoluteXpBySkill().isEmpty());
		assertTrue(SessionSnapshot.capture(session, Collections.<String, Long>emptyMap())
			.getAbsoluteXpBySkill().isEmpty());
	}

	@Test
	public void captureWithAbsoluteXp_carriesTheGivenMapVerbatim()
	{
		Session session = activeSessionAt(T0);
		java.util.Map<String, Long> absolute = new java.util.HashMap<>();
		absolute.put("STRENGTH", 13_034_431L);

		SessionSnapshot snapshot = SessionSnapshot.capture(session, Collections.<String, Long>emptyMap(), absolute);

		assertEquals(Long.valueOf(13_034_431L), snapshot.getAbsoluteXpBySkill().get("STRENGTH"));
	}

	@Test
	public void captureWithAbsoluteXp_defensivelyCopies_neverALiveViewOfTheInputMap()
	{
		Session session = activeSessionAt(T0);
		java.util.Map<String, Long> absolute = new java.util.HashMap<>();
		absolute.put("MINING", 500L);

		SessionSnapshot snapshot = SessionSnapshot.capture(session, Collections.<String, Long>emptyMap(), absolute);
		absolute.put("MINING", 999_999L);
		absolute.put("FISHING", 5L);

		assertEquals(Long.valueOf(500L), snapshot.getAbsoluteXpBySkill().get("MINING"));
		assertFalse(snapshot.getAbsoluteXpBySkill().containsKey("FISHING"));
	}

	@Test
	public void captureWithAbsoluteXp_nullSession_stillReturnsAbsent()
	{
		java.util.Map<String, Long> absolute = new java.util.HashMap<>();
		absolute.put("ATTACK", 10L);
		SessionSnapshot snapshot = SessionSnapshot.capture(null, Collections.<String, Long>emptyMap(), absolute);
		assertFalse(snapshot.isPresent());
	}

	@Test
	public void captureWithAbsoluteXp_nullMap_treatedAsEmpty()
	{
		Session session = activeSessionAt(T0);
		SessionSnapshot snapshot = SessionSnapshot.capture(session, Collections.<String, Long>emptyMap(), null);
		assertTrue(snapshot.getAbsoluteXpBySkill().isEmpty());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.time.Instant;
import java.util.Collections;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * End-to-
 * end coverage of the REAL production wiring path -- the two-arg
 * SessionPersistence(store, loadoutArchive) constructor
 * SessionRuntimeCoordinator now uses -- as opposed to
 * LoadoutResolverTest (the resolution ladder in isolation) or
 * SessionLoadoutBackwardCompatibilityTest (an explicitly
 * pre-attached loadout with a null/no-op archive). Proves:
 *   1. a brand-new session's FIRST persistCurrent() call resolves and
 *      attaches a real starting loadout from live archive data;
 *   2. a second persistCurrent() call for the SAME session object does
 *      NOT re-resolve (identity refinement/repeated
 *      persistence must never replace an already-attached starting
 *      loadout);
 *   3. persistFinalized() resolves and attaches an ending loadout;
 *   4. an account with no archive data at all still finalizes cleanly
 *      with an explicit UNAVAILABLE loadout, never blocking
 *      persistence.
 *
 * Real LocalStateStore/TelemetryPaths, matching
 * SessionPersistenceTest/SessionLoadoutBackwardCompatibilityTest's own
 * established real-file style.
 *
 * Archive
 * observations that exercise a PRE_START starting-loadout resolution
 * are recorded far enough before T0 to land at-or-before the
 * resolver's target instant (T0 - 30s -- see
 * LoadoutResolver.STARTING_LOADOUT_TARGET_OFFSET), not merely before
 * T0 itself.
 */
public class SessionPersistenceLoadoutResolutionTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_333L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private LoadoutArchive archive;
	private SessionPersistence persistence;

	@Before
	public void setUp()
	{
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		archive = new LoadoutArchive();
		persistence = new SessionPersistence(store, archive);
	}

	@After
	public void tearDown()
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	@Test
	public void firstPersistCurrent_resolvesAndAttachesRealStartingLoadout()
	{
		archive.record(T0.minusSeconds(45),
			Collections.singletonList(new StorageState.StorageItem(0, 995, "Coins", 500, null)),
			Collections.emptyList());

		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		assertNull("a freshly-created session must not already have a loadout", session.getStartingLoadout());

		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);

		assertNotNull("persistCurrent() must resolve and attach a starting loadout for a brand-new session",
			session.getStartingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, session.getStartingLoadout().getProvenance());
		assertEquals(995, session.getStartingLoadout().getInventory().get(0).getItemId());
	}

	@Test
	public void secondPersistCurrent_neverReplacesAlreadyAttachedStartingLoadout()
	{
		archive.record(T0.minusSeconds(45),
			Collections.singletonList(new StorageState.StorageItem(0, 995, "Coins", 500, null)),
			Collections.emptyList());

		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);
		LoadoutSnapshot firstResolved = session.getStartingLoadout();

		// Simulate a later observation arriving (e.g. the player picked
		// something up) that must NOT retroactively become this
		// session's "starting" loadout.
		archive.record(T0.plusSeconds(5),
			Collections.singletonList(new StorageState.StorageItem(0, 1234, "Different item", 1, null)),
			Collections.emptyList());
		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);

		assertEquals("a second persistCurrent() call for the same session object must not re-resolve the starting loadout",
			firstResolved, session.getStartingLoadout());
	}

	@Test
	public void persistFinalized_resolvesAndAttachesEndingLoadout() throws Exception
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		archive.record(expiry.minusSeconds(5),
			Collections.singletonList(new StorageState.StorageItem(0, 1359, "Swordfish", 3, null)),
			Collections.emptyList());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, finalized.getSessionId());
		assertNotNull(reloaded);
		assertNotNull("persistFinalized() must resolve and attach an ending loadout", reloaded.getEndingLoadout());
		assertEquals(1359, reloaded.getEndingLoadout().getInventory().get(0).getItemId());
	}

	@Test
	public void noArchiveData_finalizesCleanlyWithExplicitUnavailableLoadout_neverBlocks() throws Exception
	{
		// archive is real but has never recorded anything for this account.
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, finalized.getSessionId());
		assertNotNull("finalization must succeed even with zero archive data", reloaded);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertNotNull(reloaded.getStartingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, reloaded.getStartingLoadout().getProvenance());
		assertNotNull(reloaded.getEndingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, reloaded.getEndingLoadout().getProvenance());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Direct, isolated coverage of {@link LiveXpTracker}'s own
 * ownership/reconciliation contract -- independent of
 * SessionRuntimeCoordinator/SkillsCollector's own wiring (covered
 * separately by SessionRuntimeCoordinatorTest/GenericNpcCombatRecognitionTest-
 * style full-pipeline tests and SkillsCollectorTest's pure
 * evaluateLiveXpDelta() tests).
 */
public class LiveXpTrackerTest
{
	// 1: a recorded delta is immediately visible via getPending()/getPendingForSession().
	@Test
	public void recordDelta_isImmediatelyVisible()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		assertEquals(40L, tracker.getPending("session-1", "Strength"));
		assertEquals(Long.valueOf(40L), tracker.getPendingForSession("session-1").get("Strength"));
	}

	// 2: multiple deltas for the same (session, skill) accumulate.
	@Test
	public void recordDelta_accumulatesAcrossMultipleCalls()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Strength", 15L);
		assertEquals(55L, tracker.getPending("session-1", "Strength"));
	}

	// delta <= 0 is always ignored -- never fabricates positive live XP.
	@Test
	public void recordDelta_ignoresZeroOrNegativeDeltas()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 0L);
		tracker.recordDelta("session-1", "Strength", -5L);
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
	}

	// null sessionId/skill is always ignored -- no honest owner to attach to.
	@Test
	public void recordDelta_ignoresNullSessionOrSkill()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta(null, "Strength", 40L);
		tracker.recordDelta("session-1", null, 40L);
		assertTrue(tracker.getPendingForSession("session-1").isEmpty());
	}

	// 6: a session switch (a delta for a DIFFERENT sessionId) discards
	// every previously-tracked amount -- the old session's pending XP
	// must never leak into the new one's display.
	@Test
	public void recordDelta_sessionSwitch_discardsThePreviousOwnersPendingXp()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("woodcutting-session", "Woodcutting", 100L);
		assertEquals(100L, tracker.getPending("woodcutting-session", "Woodcutting"));

		tracker.recordDelta("combat-session", "Strength", 10L);

		assertEquals(0L, tracker.getPending("woodcutting-session", "Woodcutting"));
		assertTrue(tracker.getPendingForSession("woodcutting-session").isEmpty());
		assertEquals(10L, tracker.getPending("combat-session", "Strength"));
	}

	// 3: reconcile() (a real XP_CHANGE flush landing) resets the live
	// pending amount for that (session, skill) to zero -- this is what
	// guarantees the exact-once display total (canonical + live never
	// double-counts once XP_CHANGE catches up).
	@Test
	public void reconcile_resetsPendingForThatSkillToZero()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.reconcile("session-1", "Strength");
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
	}

	// reconcile() only clears the skill it names -- an unrelated skill's
	// own pending amount is untouched.
	@Test
	public void reconcile_onlyClearsTheNamedSkill()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Attack", 25L);
		tracker.reconcile("session-1", "Strength");
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
		assertEquals(25L, tracker.getPending("session-1", "Attack"));
	}

	// 7: reconcile() for a sessionId that is NOT the current owner is a
	// no-op -- a delayed XP_CHANGE for an abandoned/finalized session
	// arriving after a real switch must never disturb the NEW current
	// owner's own live view.
	@Test
	public void reconcile_forAnAbandonedSessionAfterASwitch_isANoOp()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("woodcutting-session", "Woodcutting", 100L);
		tracker.recordDelta("combat-session", "Strength", 10L);

		// Delayed XP_CHANGE for the OLD (abandoned) session finally lands.
		tracker.reconcile("woodcutting-session", "Woodcutting");

		// The new current owner's own live pending XP is completely unaffected.
		assertEquals(10L, tracker.getPending("combat-session", "Strength"));
	}

	// getPending()/getPendingForSession() for a sessionId that has never
	// been recorded against (or is not the current owner) return 0/empty.
	@Test
	public void getPending_forUnknownOrStaleSession_returnsZeroOrEmpty()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);

		assertEquals(0L, tracker.getPending("session-2", "Strength"));
		assertTrue(tracker.getPendingForSession("session-2").isEmpty());
		assertEquals(0L, tracker.getPending(null, "Strength"));
	}

	// getPendingForSession() returns a defensive copy -- mutating it
	// never affects the tracker's own internal state.
	@Test
	public void getPendingForSession_returnsADefensiveCopy()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);

		java.util.Map<String, Long> copy = tracker.getPendingForSession("session-1");
		try
		{
			copy.put("Strength", 999L);
		}
		catch (UnsupportedOperationException expected)
		{
			// Also acceptable -- an unmodifiable view throwing on mutation.
		}

		assertEquals(40L, tracker.getPending("session-1", "Strength"));
	}

	// 9: reset() (account switch) clears every tracked owner/amount --
	// no fake live XP survives into the new account.
	@Test
	public void reset_clearsOwnerAndAllPendingAmounts()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.reset();

		assertEquals(0L, tracker.getPending("session-1", "Strength"));
		assertTrue(tracker.getPendingForSession("session-1").isEmpty());

		// A fresh account's own session can now become the owner cleanly.
		tracker.recordDelta("session-1", "Strength", 5L);
		assertEquals(5L, tracker.getPending("session-1", "Strength"));
	}

	// An ordinary suspend/resume (the SAME sessionId recorded again
	// later) is NOT treated as a switch -- pending XP survives across it.
	@Test
	public void recordDelta_sameSessionIdAgainLater_isNotTreatedAsASwitch()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Strength", 5L);
		assertEquals(45L, tracker.getPending("session-1", "Strength"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.osrstelemetry.plugin.model.StorageState;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Swing/Client-independent coverage of LoadoutSnapshot's
 * data-shape guarantees: defensive copying, unmodifiability, the
 * unavailable() factory, and the fixed inventory slot count. Plain
 * JUnit, no Mockito, matching this project's established test style
 * (see LootTrackerIndexTest).
 */
public class LoadoutSnapshotTest
{
	private static StorageState.StorageItem item(int slot, int itemId, String name, int quantity)
	{
		return new StorageState.StorageItem(slot, itemId, name, quantity, null);
	}

	private static StorageState.StorageItem emptySlot(int slot)
	{
		return new StorageState.StorageItem(slot, -1, null, 0, null);
	}

	private static List<StorageState.StorageItem> twentyEightEmptySlots()
	{
		List<StorageState.StorageItem> slots = new ArrayList<>(LoadoutSnapshot.INVENTORY_SIZE);
		for (int i = 0; i < LoadoutSnapshot.INVENTORY_SIZE; i++)
		{
			slots.add(emptySlot(i));
		}
		return slots;
	}

	@Test
	public void inventorySize_isTwentyEight()
	{
		assertEquals(28, LoadoutSnapshot.INVENTORY_SIZE);
	}

	@Test
	public void constructor_defensivelyCopiesInputLists_laterMutationOfSourceNotReflected()
	{
		List<StorageState.StorageItem> inventory = new ArrayList<>(twentyEightEmptySlots());
		List<StorageState.StorageItem> equipment = new ArrayList<>(Collections.singletonList(item(3, 1127, "Rune platebody", 1)));

		LoadoutSnapshot snapshot = new LoadoutSnapshot(inventory, equipment, "2026-01-01T10:00:00Z", LoadoutProvenance.PRE_START);

		// Mutate the caller's own lists after construction.
		inventory.clear();
		equipment.add(item(4, 1, "extra", 1));

		assertEquals("snapshot must be unaffected by later mutation of the source inventory list",
			28, snapshot.getInventory().size());
		assertEquals("snapshot must be unaffected by later mutation of the source equipment list",
			1, snapshot.getEquipment().size());
	}

	@Test
	public void getters_returnUnmodifiableLists()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot(
			twentyEightEmptySlots(), Collections.emptyList(), "2026-01-01T10:00:00Z", LoadoutProvenance.PRE_START);

		try
		{
			snapshot.getInventory().add(item(0, 1, "x", 1));
			fail("inventory list returned by getInventory() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}

		try
		{
			snapshot.getEquipment().add(item(0, 1, "x", 1));
			fail("equipment list returned by getEquipment() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	@Test
	public void unavailable_hasEmptyListsNeverNull_nullCapturedAt_unavailableProvenance()
	{
		LoadoutSnapshot snapshot = LoadoutSnapshot.unavailable();

		assertTrue(snapshot.getInventory().isEmpty());
		assertTrue(snapshot.getEquipment().isEmpty());
		assertNull(snapshot.getCapturedAt());
		assertEquals(LoadoutProvenance.UNAVAILABLE, snapshot.getProvenance());
	}

	@Test
	public void preservesSlotIndexAndEmptySlotConvention_itemIdNegativeOne()
	{
		List<StorageState.StorageItem> equipment = Arrays.asList(
			item(0, 1163, "Bronze full helm", 1),
			emptySlot(1),
			emptySlot(2)
		);

		LoadoutSnapshot snapshot = new LoadoutSnapshot(twentyEightEmptySlots(), equipment, "2026-01-01T10:00:00Z", LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);

		assertEquals(3, snapshot.getEquipment().size());
		assertEquals(-1, snapshot.getEquipment().get(1).getItemId());
		assertEquals(1163, snapshot.getEquipment().get(0).getItemId());
		assertEquals(0, snapshot.getEquipment().get(0).getSlot());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.model.StorageState;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Covers the
 * target-time (startedAt - 30s) redesign of resolveStarting(). Pure,
 * RuneLite/Client-independent coverage of LoadoutResolver's
 * PRE_START / FALLBACK_AT_OR_AFTER_START / UNAVAILABLE resolution
 * ladder, against a real (in-memory)
 * LoadoutArchive. Plain JUnit, no Mockito.
 */
public class LoadoutResolverTest
{
	private static final Instant STARTED_AT = Instant.parse("2026-01-01T10:00:00Z");

	private static List<StorageState.StorageItem> oneItem(int itemId)
	{
		return Collections.singletonList(new StorageState.StorageItem(0, itemId, "item-" + itemId, 1, null));
	}

	// --- null-safety (backward-compat constructor path) ---

	@Test
	public void nullArchive_resolveStarting_alwaysUnavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(null);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
		assertTrue(result.getInventory().isEmpty());
	}

	@Test
	public void nullArchive_resolveEnding_alwaysUnavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(null);

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
	}

	@Test
	public void nullReferenceInstant_alwaysUnavailable_evenWithRealArchive()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(30), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		assertEquals(LoadoutProvenance.UNAVAILABLE, resolver.resolveStarting(null).getProvenance());
		assertEquals(LoadoutProvenance.UNAVAILABLE, resolver.resolveEnding(null).getProvenance());
	}

	// --- resolveStarting: PRE_START ---

	@Test
	public void resolveStarting_observationExactlyAtTarget_producesPreStart()
	{
		// target = STARTED_AT - 30s (LoadoutResolver.STARTING_LOADOUT_TARGET_OFFSET).
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(30), oneItem(995), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(995, result.getInventory().get(0).getItemId());
		assertEquals(STARTED_AT.minusSeconds(30).toString(), result.getCapturedAt());
	}

	@Test
	public void resolveStarting_prefersLatestStateAtOrBeforeTarget_notAnEarlierOne()
	{
		// Both observations are at-or-before target (STARTED_AT - 30s):
		// the resolver must pick the LATER of the two (closest to
		// target), not the earliest.
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(120), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.minusSeconds(45), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(2, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_targetAnchoredNotStartedAtAnchored_observationAfterTargetButBeforeStartIsIgnoredForPreStart()
	{
		// A state change between target (STARTED_AT - 30s) and
		// startedAt itself must NOT be treated as the pre-target state
		// -- resolution is anchored to target, not startedAt. The
		// correct PRE_START pick is the state actually in effect AT
		// target (item 1, recorded at -60s), even though item 2 (at
		// -10s, after target but before startedAt) is "more recent."
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(60), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.minusSeconds(10), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals("the state in effect AT the -30s target (item 1), not a later in-session change (item 2)",
			1, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_stateHistory_oldButStillCurrentObservationCountsAsStartingLoadout()
	{
		// Worked example from spec section 3: gear equipped at T-2min,
		// nothing changes afterward, session begins at T (target =
		// T-30s). The T-2min observation is still the state in effect
		// at T-30s and must be used -- loadout snapshots are treated as
		// state history, not point samples; no observation needs to
		// land exactly on the target instant.
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minus(java.time.Duration.ofMinutes(2)), oneItem(1337), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(1337, result.getInventory().get(0).getItemId());
		assertEquals(STARTED_AT.minus(java.time.Duration.ofMinutes(2)).toString(), result.getCapturedAt());
	}

	@Test
	public void resolveStarting_preStartObservationOutsideLookback_fallsBackInstead()
	{
		// Well outside PRE_START_LOOKBACK of target (STARTED_AT - 30s).
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minus(LoadoutResolver.PRE_START_LOOKBACK).minusSeconds(60), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.plusSeconds(5), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals("a state older than the lookback window (relative to target) must not be trusted as PRE_START",
			LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals(2, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_observationExactlyAtLookbackBoundaryFromTarget_stillCountsAsPreStart()
	{
		// Boundary is relative to target (STARTED_AT - 30s), not
		// startedAt itself: this observation sits exactly
		// PRE_START_LOOKBACK before the TARGET instant.
		LoadoutArchive archive = new LoadoutArchive();
		Instant target = STARTED_AT.minusSeconds(30);
		archive.record(target.minus(LoadoutResolver.PRE_START_LOOKBACK), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
	}

	// --- resolveStarting: FALLBACK_AT_OR_AFTER_START ---

	@Test
	public void resolveStarting_noPreStartObservationAtAll_fallsBackToEarliestAtOrAfter()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT, oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.plusSeconds(30), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals("must pick the EARLIEST at-or-after observation, not a later one",
			1, result.getInventory().get(0).getItemId());
	}

	// --- resolveStarting: UNAVAILABLE ---

	@Test
	public void resolveStarting_emptyArchive_unavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(new LoadoutArchive());

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
		assertNull(result.getCapturedAt());
		assertTrue(result.getInventory().isEmpty());
		assertTrue(result.getEquipment().isEmpty());
	}

	// --- resolveEnding ---

	@Test
	public void resolveEnding_observationAtOrBeforeReference_used()
	{
		LoadoutArchive archive = new LoadoutArchive();
		Instant finalizedAt = STARTED_AT.plusSeconds(600);
		archive.record(finalizedAt.minusSeconds(20), oneItem(4151), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveEnding(finalizedAt);

		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals(4151, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveEnding_noObservationAtAll_unavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(new LoadoutArchive());

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
	}

	@Test
	public void resolveEnding_neverProducesPreStart()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(10), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals("ending-loadout resolution must never claim PRE_START -- see LoadoutProvenance's own javadoc",
			LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
	}
}

