		Instant t1 = T0.plusSeconds(10);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(t1, "SLAYER", 113L).withGameTick(2L));
		coordinator.testEnqueueSignal(SessionSignal.bossKill(t1, "Vorkath", 1).withGameTick(2L));
