 *  - "Producing NPC_LOOT_ATTRIBUTED has no dependency on an
 *    NPC_DEATH event": enforced by construction — LootCollector's
 *    only import from another collector's package is none at all; it
 *    has no reference to NpcDeathCollector, EventType.NPC_DEATH, or
 *    ActorDeath anywhere in its source, and its only @Subscribe
 *    handler is onNpcLootReceived(NpcLootReceived).
 *  - "Producing NPC_LOOT_ATTRIBUTED has no dependency on a
 *    SLAYER_TASK_PROGRESS event": enforced by construction — same
 *    reasoning; LootCollector has no reference to SlayerCollector,
 *    EventType.SLAYER_TASK_PROGRESS, SlayerPluginService, or
 *    VarbitChanged anywhere in its source.
 */
public class LootCollectorTest
{
	private static final Gson GSON = new Gson();

	// --- 1. serializable through an isolated equivalent of the project's actual serialization path ---

	@Test
	public void payload_roundTripsThroughGson_sameSerializerEventLedgerUses()
	{
		// EventLedger.append() serializes the payload with a plain
		// `new Gson()` (see EventLedger.java) — this test uses the same
		// mechanism directly on the payload object, isolated from
		// Client/EventBus/file I/O, rather than duplicating
		// EventLedger's own tested append()/appendNow() logic.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		String json = GSON.toJson(payload);
		EventPayloads.NpcLootAttributed roundTripped = GSON.fromJson(json, EventPayloads.NpcLootAttributed.class);

		assertEquals(payload, roundTripped);
		assertTrue("serialized JSON should carry the item name", json.contains("Abyssal whip"));
	}

	// --- 2. NPC/source identity preserved ---

	@Test
	public void buildPayload_preservesSourceIdentity()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		assertEquals("NPC", payload.getSourceType());
		assertEquals("Gargoyle", payload.getSourceName());
		assertEquals(111, payload.getSourceId());
	}

	// --- 3. item identity preserved ---

	@Test
	public void buildPayload_preservesItemIdentity()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		assertEquals(4151, payload.getItemId());
		assertEquals("Abyssal whip", payload.getItemName());
		assertEquals(1, payload.getQuantity());
	}

	@Test
	public void buildPayload_preservesQuantityGreaterThanOne()
	{
		// Stacked items (e.g. runes, coins) are a routine case — confirm
		// quantity is passed through unmodified, not clamped/assumed 1.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Chicken", 41, 995, "Coins", 42);

		assertEquals(42, payload.getQuantity());
	}

	// --- 4/5/6. no ownership, kill-attribution, or Slayer-attribution field exists ---

	@Test
	public void payload_declaresOnlyTheSixExpectedFields_noAttributionOrOwnershipField()
	{
		// Structural check on EventPayloads.NpcLootAttributed itself
		// (not on a specific instance) — the actual contract this test
		// requirement is about is "no such field EXISTS", not "no such
		// field happens to be set." Reflection over the declared field
		// set is a real assertion on the payload's shape, not a
		// duplication of buildPayload()'s pass-through logic.
		Field[] fields = EventPayloads.NpcLootAttributed.class.getDeclaredFields();
		String[] fieldNames = Arrays.stream(fields)
			.map(Field::getName)
			.toArray(String[]::new);

		String[] expected = {"sourceType", "sourceName", "sourceId", "itemId", "itemName", "quantity"};
		String[] sortedActual = fieldNames.clone();
		String[] sortedExpected = expected.clone();
		Arrays.sort(sortedActual);
		Arrays.sort(sortedExpected);
		assertArrayEquals(sortedExpected, sortedActual);

		for (String name : fieldNames)
		{
			String lower = name.toLowerCase(Locale.ROOT);
			assertFalse("field " + name + " must not imply ownership", lower.contains("owner"));
			assertFalse("field " + name + " must not imply local-player ownership", lower.contains("mine") || lower.contains("belongsto"));
			assertFalse("field " + name + " must not imply kill attribution", lower.contains("kill"));
			assertFalse("field " + name + " must not imply Slayer attribution", lower.contains("slayer") || lower.contains("ontask"));
		}
	}

	// --- 9. unavailable metadata is not fabricated ---

	@Test
	public void buildPayload_nullSourceName_passedThroughNotFabricated()
	{
		// npc.getName() can legitimately return null for some NPCs
		// (RuneLite's own NPC/Actor accessors carry no guarantee
		// otherwise). buildPayload() must never substitute a placeholder
		// like "Unknown" — it's a pass-through, not a decision.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", null, 111, 4151, "Abyssal whip", 1);

		assertEquals(null, payload.getSourceName());
	}

	@Test
	public void buildPayload_nullItemName_passedThroughNotFabricated()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, null, 1);

		assertEquals(null, payload.getItemName());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere. Targets
 * QuestCollector.justFinished(), the pure Client-independent piece of
 * the collector, using two real Quest enum constants (Quest itself
 * has no Client dependency, so this compiles and runs without mocking
 * RuneLite's Client at all).
 */
public class QuestCollectorTest
{
	@Test
	public void firstObservationNeverReportsAnythingAsJustFinished()
	{
		// This is the account-switch/first-login safety property:
		// a null "previous" snapshot (freshly reset,
		// or never seen before) must not cause every already-finished
		// quest to be reported as newly completed.
		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		current.put(Quest.DEMON_SLAYER, QuestState.FINISHED);

		List<Quest> result = QuestCollector.justFinished(null, current);

		assertTrue("first observation must report zero transitions", result.isEmpty());
	}

	@Test
	public void reportsOnlyQuestsThatTransitionedIntoFinished()
	{
		Map<Quest, QuestState> previous = new HashMap<>();
		previous.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		previous.put(Quest.DEMON_SLAYER, QuestState.IN_PROGRESS);

		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // unchanged
		current.put(Quest.DEMON_SLAYER, QuestState.FINISHED); // just finished

		List<Quest> result = QuestCollector.justFinished(previous, current);

		assertEquals(1, result.size());
		assertEquals(Quest.DEMON_SLAYER, result.get(0));
	}

	@Test
	public void reportsNothingWhenNoQuestChangedState()
	{
		Map<Quest, QuestState> previous = new HashMap<>();
		previous.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);

		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);

		assertTrue(QuestCollector.justFinished(previous, current).isEmpty());
	}

	@Test
	public void accountSwitchSimulation_doesNotFabricateCompletionsFromDifferentAccount()
	{
		// Account A's snapshot before switching away.
		Map<Quest, QuestState> accountASnapshot = new HashMap<>();
		accountASnapshot.put(Quest.COOKS_ASSISTANT, QuestState.NOT_STARTED);

		// resetForAccountSwitch() sets lastKnown = null — simulated
		// directly here since this test targets justFinished(), not
		// the collector's field mutation.
		Map<Quest, QuestState> afterReset = null;

		// Account B's actual (very different) quest list.
		Map<Quest, QuestState> accountBSnapshot = new HashMap<>();
		accountBSnapshot.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		accountBSnapshot.put(Quest.DEMON_SLAYER, QuestState.FINISHED);

		List<Quest> result = QuestCollector.justFinished(afterReset, accountBSnapshot);

		assertTrue(
			"account B's pre-existing completions must never be reported as new just because account A's leftover state was different",
			result.isEmpty()
		);
	}

	// =====================================================================
	// Quest config re-enable regression (client-thread lifecycle audit,
	// letter C) -- added after a CONFIRMED live crash: onConfigChanged()'s
	// "collectQuests" case used to run resetForAccountSwitch() then
	// checkAndFlush() directly from the AWT thread, and checkAndFlush()
	// itself both (a) diffs the fresh read against lastKnown AND (b)
	// unconditionally sets lastKnown = current as a side effect. The fix
	// swaps that call to captureInitialStateWithoutBaseline() (marshalled
	// onto ClientThread from OsrsTelemetryPlugin.onConfigChanged() --
	// see that class), which deliberately never touches lastKnown at
	// all. These tests model that exact contract purely against
	// justFinished(), the same Client-independent core the collector's
	// own checkAndFlush()/captureInitialStateWithoutBaseline() both
	// ultimately rely on for their no-fabrication guarantee.
	// =====================================================================

	@Test
	public void reenableAfterBeingDisabled_questFinishedWhileDisabled_isNeverReportedAsJustFinished()
	{
		// Before disable: some in-progress quest.
		Map<Quest, QuestState> beforeDisable = new HashMap<>();
		beforeDisable.put(Quest.COOKS_ASSISTANT, QuestState.IN_PROGRESS);

		// While disabled, the category stops collecting -- baselines are
		// left stale (see OsrsTelemetryPlugin.onConfigChanged()'s
		// "disabling needs no extra work" comment) -- but the player
		// actually finishes the quest during that window.
		//
		// resetForAccountSwitch() (called immediately before the silent
		// hydration on re-enable) sets lastKnown to null -- simulated
		// directly here, since this test targets justFinished(), not
		// the collector's field mutation (mirrors
		// accountSwitchSimulation_... above).
		Map<Quest, QuestState> afterReset = null;

		// Re-enable's fresh read: the quest is now FINISHED, having
		// completed entirely while collection was off.
		Map<Quest, QuestState> onReenable = new HashMap<>();
		onReenable.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);

		List<Quest> result = QuestCollector.justFinished(afterReset, onReenable);

		assertTrue(
			"a quest finished entirely while collection was disabled must be silently hydrated on re-enable, "
				+ "never reported as a retroactive QUEST_COMPLETED the instant collection resumes",
			result.isEmpty()
		);
	}

	@Test
	public void reenableThenNextPeriodicCheck_onlyReportsQuestsFinishedAfterReenable()
	{
		// Re-enable silently hydrates (previous == null, per the test
		// above) -- captureInitialStateWithoutBaseline() deliberately
		// leaves lastKnown null afterward (see its own javadoc), so the
		// PLUGIN'S NEXT periodic checkAndFlush() also starts from
		// previous == null and silently reseeds a second time...
		Map<Quest, QuestState> reenableRead = new HashMap<>();
		reenableRead.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // finished while disabled
		reenableRead.put(Quest.DEMON_SLAYER, QuestState.IN_PROGRESS);

		assertTrue(
			"captureInitialStateWithoutBaseline() must never establish lastKnown itself",
			QuestCollector.justFinished(null, reenableRead).isEmpty()
		);

		// ...and only a quest that transitions to FINISHED strictly
		// AFTER that silent reseed (i.e. once a real baseline exists)
		// is ever reported -- proving the silent-hydration contract
		// doesn't also suppress genuine future completions.
		Map<Quest, QuestState> genuineBaseline = reenableRead;
		Map<Quest, QuestState> nextCheck = new HashMap<>();
		nextCheck.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // unchanged
		nextCheck.put(Quest.DEMON_SLAYER, QuestState.FINISHED); // genuinely just finished

		List<Quest> result = QuestCollector.justFinished(genuineBaseline, nextCheck);
		assertEquals(1, result.size());
		assertEquals(Quest.DEMON_SLAYER, result.get(0));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as elsewhere in this
 * test module (see plugin/README.md). Targets
 * SkillsCollector.evaluateXpWindow(), the pure Client/EventLedger-
 * independent core of the "seed-once-then-diff" XP window decision —
 * factored out for the exact same reason QuestCollector.justFinished()
 * was: unit-testable without mocking RuneLite's Client.
 *
 * This covers the fix for the
 * startup XP_CHANGE flood (see
 * SkillsCollector's own javadoc for the full
 * root-cause trace) — every test below maps to one of the "BASELINE /
 * EVENT TESTS" scenarios for that fix.
 */
public class SkillsCollectorTest
{
	@Test
	public void firstObservationForASkillAlwaysSeedsNeverEmitsADelta()
	{
		// Scenario C/G: a session begins with no baseline for this
		// skill (fresh session, or just reset for an account switch) —
		// the null baseline must always mean "seed silently," never
		// "compare against zero," no matter how large currentXp is.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(null, 5_000_000);
		assertTrue("a null baseline must always seed", result.shouldSeed);
	}

	@Test
	public void firstObservationSeedsRegardlessOfMagnitude_neverFabricatesAHistoricalDelta()
	{
		// Scenario I: an account with a LOT of pre-existing XP (the
		// "initial/default/incomplete state followed by real state"
		// case) must not have that real, large XP value misread as a
		// gain the moment it's first observed — the null-baseline path
		// has no notion of "previous" to compare against at all, so it
		// cannot fabricate a delta regardless of the value's size.
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(null, xp);
			assertTrue("xp=" + xp + " must still seed, never emit a delta on first observation", result.shouldSeed);
		}
	}

	@Test
	public void secondIdenticalObservationComputesZeroDelta()
	{
		// Scenario D: once seeded, an unchanged read must compute a
		// zero delta (closeXpWindowsFor() only emits when delta > 0,
		// so this is what "emits nothing" reduces to at the pure-logic
		// level).
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(273_742, 273_742);
		assertFalse("an existing baseline must never re-seed", result.shouldSeed);
		assertEquals(0, result.delta);
	}

	@Test
	public void genuineIncreaseAfterSeedComputesTheCorrectPositiveDelta()
	{
		// Scenario F: a real XP gain after the baseline is established
		// must compute exactly the real delta.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(273_742, 300_000);
		assertFalse(result.shouldSeed);
		assertEquals(300_000 - 273_742, result.delta);
	}

	@Test
	public void decreaseAgainstBaselineIsNeverTreatedAsAGain()
	{
		// XP cannot genuinely decrease, but this pins the sign
		// convention explicitly: closeXpWindowsFor() only emits when
		// delta > 0, so a negative delta (which should never actually
		// occur) is still handled safely by the >0 guard at the call
		// site rather than this pure function needing to clamp it.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(300_000, 273_742);
		assertFalse(result.shouldSeed);
		assertEquals(273_742 - 300_000, result.delta);
	}

	// --- evaluateLevelTransition() ---
	//
	// Confirmed live-validation bug: LEVEL_UP fired for every skill
	// within milliseconds of login, all with previousLevel=0, because
	// the old comparison baseline (state.getSkills(), seeded by
	// captureInitialState()'s own unsynced login-time read) could hold
	// a wrong 0 the moment the first genuine, correctly-synced
	// StatChanged arrived. evaluateLevelTransition() is the pure core
	// of the fix: a null baseline must ALWAYS mean "seed silently,"
	// regardless of the observed level's value, exactly mirroring
	// evaluateXpWindow()'s contract. These five tests map directly to
	// the requested regression scenarios A-E.

	@Test
	public void scenarioA_firstLevelObservationSilentlySeeds_neverEmitsLevelUp()
	{
		// A. first level observation 0/unset -> 87 silently seeds, NO
		// LEVEL_UP — an existing level 87 must never be reported as a
		// fabricated 0 -> 87 transition just because it's the first
		// time this skill has been observed this session.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(null, 87);
		assertFalse("a null baseline must never emit LEVEL_UP", result.shouldEmit);
	}

	@Test
	public void scenarioB_secondIdenticalObservationEmitsNothing()
	{
		// B. second observation 87 -> 87 emits nothing.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(87, 87);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void scenarioC_realIncreaseEmitsExactlyOneLevelUp()
	{
		// C. real 87 -> 88 emits exactly one LEVEL_UP (shouldEmit=true;
		// the call site emits at most once per StatChanged, so "exactly
		// one" reduces to "shouldEmit is true here and nowhere else").
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(87, 88);
		assertTrue(result.shouldEmit);
	}

	@Test
	public void scenarioD_resetProducesANewSilentSeed()
	{
		// D. reset/session change (SkillsCollector.resetForAccountSwitch()
		// clears lastKnownLevel, which is exactly the null-baseline
		// input this pure function receives afterward) causes a new
		// silent seed, not a diff against the old account's level —
		// same null-in/no-emit behavior as scenario A, applied after a
		// reset instead of a fresh session.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(null, 42);
		assertFalse("post-reset baseline is null, so this must reseed silently, not diff", result.shouldEmit);
	}

	@Test
	public void scenarioE_accountABaselineCannotLeakIntoAccountB()
	{
		// E. account A's level baseline cannot leak into account B.
		// resetForAccountSwitch() clears lastKnownLevel per-skill (see
		// SkillsCollector), so by the time account B is observed, the
		// call site always passes null here regardless of what account
		// A's level was — pinned directly: a high account-A baseline
		// must never suppress or distort account B's own first
		// observation.
		SkillsCollector.LevelTransitionResult accountALeftover = SkillsCollector.evaluateLevelTransition(99, 99);
		assertFalse(accountALeftover.shouldEmit);

		SkillsCollector.LevelTransitionResult accountBFirstObservation = SkillsCollector.evaluateLevelTransition(null, 3);
		assertFalse("account B's first observation must seed silently regardless of account A's leftover level",
			accountBFirstObservation.shouldEmit);
	}

	@Test
	public void decreaseInLevelIsNeverTreatedAsALevelUp()
	{
		// A real level cannot genuinely decrease outside an account
		// switch (which resets the baseline to null first, covered by
		// scenario E), but this pins the strict-greater-than convention
		// explicitly, mirroring decreaseAgainstBaselineIsNeverTreatedAsAGain()
		// above.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(88, 87);
		assertFalse(result.shouldEmit);
	}

	// --- evaluateRawCombatXpPulse() -- universal generic NPC
	// recognition, temporal-design follow-up fix ---
	//
	// The pure core of the IMMEDIATE (per-StatChanged, not aggregated)
	// raw-combat-XP-pulse decision that backs EventType.RAW_COMBAT_XP_OBSERVED
	// -- see that constant's own javadoc for why this exists (closing
	// the gap between a fresh NPC interaction and XP_CHANGE's slow,
	// ~30s-aggregated flush cadence). Mirrors evaluateLevelTransition()'s
	// exact seed-once-then-diff contract, on its own SEPARATE baseline
	// map (lastKnownXpForRawPulse) so this new code path can never alter
	// XP_CHANGE's own accounting (windowBaselineXp is untouched by any
	// of this).

	@Test
	public void firstRawObservationForASkillAlwaysSeedsNeverEmitsAPulse()
	{
		// A session begins with no raw-pulse baseline for this skill
		// (fresh session, account switch, or a Skills re-enable) -- the
		// null baseline must always mean "seed silently," never "compare
		// against zero," no matter how large currentXp is (an existing
		// account's real XP total must never be misread as an
		// instantaneous gain the moment it is first observed).
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, 5_000_000);
		assertFalse("a null baseline must always seed, never emit", result.shouldEmit);
	}

	@Test
	public void firstRawObservationSeedsRegardlessOfMagnitude()
	{
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, xp);
			assertFalse("xp=" + xp + " must still seed, never emit on first observation", result.shouldEmit);
		}
	}

	@Test
	public void secondIdenticalRawObservationEmitsNoPulse()
	{
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(273_742, 273_742);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void genuineIncreaseAfterSeedEmitsExactlyOnePulse()
	{
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(273_742, 273_780);
		assertTrue(result.shouldEmit);
	}

	@Test
	public void decreaseAgainstRawBaselineIsNeverTreatedAsAPulse()
	{
		// XP cannot genuinely decrease, but pins the sign convention
		// explicitly, mirroring decreaseAgainstBaselineIsNeverTreatedAsAGain()
		// above.
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(300_000, 273_742);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void resetProducesANewSilentRawSeed()
	{
		// resetForAccountSwitch()/reseedTransitionBaselinesSilently()
		// both clear lastKnownXpForRawPulse, which is exactly the
		// null-baseline input this pure function receives afterward --
		// a new silent seed, never a diff against a stale account's XP.
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, 42);
		assertFalse("post-reset baseline is null, so this must reseed silently, not diff", result.shouldEmit);
	}

	@Test
	public void accountARawBaselineCannotLeakIntoAccountB()
	{
		SkillsCollector.RawCombatXpPulseResult accountALeftover = SkillsCollector.evaluateRawCombatXpPulse(99_999, 99_999);
		assertFalse(accountALeftover.shouldEmit);

		SkillsCollector.RawCombatXpPulseResult accountBFirstObservation = SkillsCollector.evaluateRawCombatXpPulse(null, 3);
		assertFalse("account B's first observation must seed silently regardless of account A's leftover baseline",
			accountBFirstObservation.shouldEmit);
	}

	// ------------------------------------------------------------------
	// evaluateLiveXpDelta() -- immediate
	// Current Session XP display. Same seed-once-then-diff, positive-
	// only discipline as evaluateRawCombatXpPulse() above, but
	// deliberately generic across every skill (not just
	// RAW_COMBAT_SKILLS) -- these tests deliberately use both combat
	// (Strength) and non-combat (Woodcutting) skill names to pin that
	// genericity, even though the pure function itself takes no skill
	// name at all (SkillsCollector.onStatChanged() is what makes it
	// generic, by calling this for every skill unconditionally).
	// ------------------------------------------------------------------

	@Test
	public void firstLiveObservationForASkillAlwaysSeedsReturnsZero()
	{
		// Test 1/9 (required list): a null baseline (fresh session,
		// account switch) must always mean "seed silently," never
		// "compare against zero" -- an existing large XP total must
		// never be misread as an instantaneous live gain the moment it
		// is first observed.
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(null, 5_000_000));
	}

	@Test
	public void firstLiveObservationSeedsRegardlessOfMagnitude()
	{
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			assertEquals("xp=" + xp + " must still seed (return 0), never emit a delta on first observation",
				0L, SkillsCollector.evaluateLiveXpDelta(null, xp));
		}
	}

	@Test
	public void noChangeInLiveXpProducesZeroDelta()
	{
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(273_742, 273_742));
	}

	@Test
	public void genuineIncreaseAfterSeedProducesExactPositiveDelta()
	{
		// Test 2/5 (required list): works for combat XP (Strength is a
		// stand-in here -- the function itself is skill-name-agnostic).
		assertEquals(38L, SkillsCollector.evaluateLiveXpDelta(273_742, 273_780));
	}

	@Test
	public void genuineIncreaseForANonCombatSkillProducesExactPositiveDeltaToo()
	{
		// Test 4 (required list): Woodcutting/Agility must work exactly
		// like a combat skill -- evaluateLiveXpDelta() takes no skill
		// name at all, proving there is no combat-only special-casing.
		assertEquals(120L, SkillsCollector.evaluateLiveXpDelta(4_500, 4_620));
	}

	@Test
	public void multipleSuccessiveIncreasesEachProduceTheirOwnCorrectDelta()
	{
		// Test 2 (required list): "multiple raw XP gains accumulate
		// correctly" -- accumulation itself is LiveXpTracker's own job
		// (see LiveXpTrackerTest), this pins that each individual
		// SkillsCollector-level reading against its own immediately-
		// prior baseline produces the correct incremental delta.
		assertEquals(50L, SkillsCollector.evaluateLiveXpDelta(1_000, 1_050));
		assertEquals(25L, SkillsCollector.evaluateLiveXpDelta(1_050, 1_075));
	}

	@Test
	public void decreaseAgainstLiveBaselineNeverProducesAPositiveDelta()
	{
		// XP decrease/reset/reseed must never fabricate positive live XP.
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(300_000, 273_742));
	}

	@Test
	public void resetProducesANewSilentLiveSeed()
	{
		// Test 9 (required list): resetForAccountSwitch() clears
		// lastKnownXpForLiveDelta, which is exactly the null-baseline
		// input this pure function receives afterward -- a new silent
		// seed, never a diff against a stale account's XP, so no fake
		// live XP is ever produced across an account switch.
		assertEquals("post-reset baseline is null, so this must reseed silently (return 0), not diff",
			0L, SkillsCollector.evaluateLiveXpDelta(null, 42));
	}

	@Test
	public void accountALiveBaselineCannotLeakIntoAccountB()
	{
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(99_999, 99_999));
		assertEquals("account B's first observation must seed silently (return 0) regardless of account A's leftover baseline",
			0L, SkillsCollector.evaluateLiveXpDelta(null, 3));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.osrstelemetry.plugin.events.EventPayloads;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as everywhere else
 * in this project's test module (see plugin/README.md).
 *
 * Renamed from NpcKillCollectorTest (event truth-semantics
 * correction) — targets NpcDeathCollector.buildPayload()/
 * formatWorldLocation(), unchanged from the prior NpcKillCollector
 * versions apart from the rename. This is the pure Client/EventLedger/
 * RuneLite-API-independent core of the NPC_DEATH payload decision —
 * factored out for the same reason as
 * SlayerCollector.evaluateSlayerTransition(): unit-testable without
 * mocking RuneLite's NPC/Client/SlayerPluginService (this project has
 * no Mockito dependency — see BankSnapshotBaselineTest's javadoc for
 * the same constraint noted before).
 *
 * The audit's minimum test list for NPC_DEATH is mostly architectural,
 * not unit-testable in isolation without mocking RuneLite's
 * EventBus/ActorDeath/NPC types this project deliberately avoids
 * depending on for tests; where that's the case, the guarantee and
 * where to see it enforced by construction is noted in a comment
 * instead of a fabricated test:
 *
 *  - "ActorDeath with NPC -> NPC_DEATH": enforced by onActorDeath()
 *    calling eventLedger.append(..., EventType.NPC_DEATH, ...) exactly
 *    once per invocation, unconditionally on a successful instanceof
 *    NPC check (see NpcDeathCollector.onActorDeath()).
 *  - "player ActorDeath -> no NPC_DEATH": enforced by the same method's
 *    `if (!(actor instanceof NPC)) { return; }` guard — a Player actor
 *    never reaches the append() call.
 *  - "active Slayer task context does not imply on-task attribution" /
 *    "no dependency on Slayer progress": tested directly below
 *    (scenarios 5-7) — buildPayload() never gates emission on
 *    slayerRemaining, only whether to attach contextual task-name/
 *    location fields, and never produces any onSlayerTask-style
 *    boolean.
 *  - "no dependency on loot": enforced by construction —
 *    NpcDeathCollector has no reference to LootCollector, NpcLootAttributed,
 *    or EventType.NPC_LOOT_ATTRIBUTED anywhere in its source.
 *  - "config gating still works": onActorDeath()'s first line is
 *    `if (!config.collectNpcDeaths()) { return; }` — architectural,
 *    same pattern as every other collector in this project (see
 *    OsrsTelemetryConfig javadoc: "read live by its collector on every
 *    relevant event").
 *  - "null/unavailable NPC metadata is not fabricated": tested directly
 *    below (scenarios 2-3).
 */
public class NpcDeathCollectorTest
{
	// --- formatWorldLocation ---

	@Test
	public void formatWorldLocation_buildsCommaSeparatedTriple()
	{
		assertEquals("3210,3424,0", NpcDeathCollector.formatWorldLocation(3210, 3424, 0));
	}

	// --- npcId / combatLevel nullability ("do not fabricate missing values") ---

	@Test
	public void buildPayload_positiveIdAndCombatLevel_areKept()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 89, "1,2,0", 0, null, null);

		assertEquals("Gargoyle", payload.getNpcName());
		assertEquals(Integer.valueOf(111), payload.getNpcId());
		assertEquals(Integer.valueOf(89), payload.getCombatLevel());
	}

	@Test
	public void buildPayload_negativeRawId_isNulledNotFabricated()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", -1, 89, "1,2,0", 0, null, null);

		assertNull(payload.getNpcId());
	}

	@Test
	public void buildPayload_nonPositiveCombatLevel_isNulledNotFabricated()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 0, "1,2,0", 0, null, null);

		assertNull(payload.getCombatLevel());
	}

	// --- Slayer correlation: contextual only, never a death-emission gate, never on-task attribution ---

	@Test
	public void buildPayload_noActiveTask_slayerFieldsNull()
	{
		// A non-task NPC death while no Slayer assignment exists at all.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Chicken", 41, 1, "1,2,0", 0, null, null);

		assertNull(payload.getActiveSlayerTaskName());
		assertNull(payload.getActiveSlayerTaskLocation());
	}

	@Test
	public void buildPayload_activeTask_attachesContextualTaskFieldsOnly()
	{
		// Normal on-task death: Gargoyles active, remaining > 0. Context
		// only — this test does not (and the payload cannot) assert any
		// "this death counted toward the task" claim, because no such
		// field exists.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 89, "1,2,0", 138, "Gargoyles", "Wilderness Slayer Cave");

		assertEquals("Gargoyles", payload.getActiveSlayerTaskName());
		assertEquals("Wilderness Slayer Cave", payload.getActiveSlayerTaskLocation());
	}

	@Test
	public void buildPayload_unrelatedNpcWhileTaskActive_stillAttachesTaskContextOnly()
	{
		// The audit's own worked example: a chicken dies while Gargoyles
		// is assigned. Task context is attached (it is genuinely active),
		// but nothing on this payload claims the chicken IS on-task —
		// there is no onSlayerTask field at all, and the dead NPC's own
		// identity (npcName) is completely independent of the attached
		// task fields.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Chicken", 2854, 1, "1,2,0", 138, "Gargoyles", "Wilderness Slayer Cave");

		assertEquals("Chicken", payload.getNpcName());
		assertEquals("Gargoyles", payload.getActiveSlayerTaskName());
	}

	@Test
	public void buildPayload_zeroRemaining_treatedAsNoActiveTask()
	{
		// Mirrors SlayerCollector.resolveCurrent()'s own "only set task
		// fields when remaining > 0" convention — a just-completed task
		// (remaining == 0) must not leak stale task name/location onto
		// an unrelated death.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Cow", 81, 2, "1,2,0", 0, "Gargoyles", "Wilderness Slayer Cave");

		assertNull(payload.getActiveSlayerTaskName());
		assertNull(payload.getActiveSlayerTaskLocation());
	}
}

