	// --- I. enable -> disable -> enable still works for the full bank finalization chain ---

	@Test
	public void i_enableDisableEnableCycle_bankFinalizationStillWorksEachTime() throws Exception
	{
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, oneItem("Dragon claws")));
		assertEquals(1, bankSnapshotEventLines().size());
		assertEquals(1, countSnapshotFiles());

		// Simulate plugin disable -> re-enable within the same client
		// process: both executors are torn down and restarted, exactly
		// as OsrsTelemetryPlugin's shutDown()/startUp() do.
		store.shutdown();
		eventLedger.shutdown();

		store.start();
		eventLedger.start();
		eventLedger.startNewSession();

		// A different item (dedup must not suppress this — different
		// content than the baseline recorded before the toggle).
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, oneItem("Twisted bow")));

		assertEquals(
			"both the pre- and post-restart finalizations must have durably produced a BANK_SNAPSHOT event",
			2, bankSnapshotEventLines().size());
		assertEquals(2, countSnapshotFiles());
	}

	// =====================================================================
	// Bank placeholder handling (letters A-G) -- guarding
	// against a bank placeholder left behind
	// after withdrawing the final copy of an item (e.g. real "Grubby
	// key" itemId 23499 -> placeholder "Grubby key" itemId 23501,
	// quantity still reported as 1) was persisted as an owned item.
	// buildBankItemsCore() is the exact pure core buildBankItems() (the
	// real production ItemContainer-facing method) delegates to -- see
	// its own javadoc -- exercised here with plain IntPredicate/
	// IntFunction fakes instead of a mocked ItemManager/ItemComposition
	// (this project has no Mockito dependency).
	// =====================================================================

	private static final IntPredicate NEVER_PLACEHOLDER = itemId -> false;

	private static IntFunction<String> nameLookup(Map<Integer, String> names)
	{
		return names::get;
	}

	// --- A. normal bank item is retained ---

	@Test
	public void placeholder_a_normalBankItem_isRetained()
	{
		Item[] raw = new Item[] { new Item(23499, 1) };
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, NEVER_PLACEHOLDER, nameLookup(names));

		assertEquals(1, items.size());
		StorageState.StorageItem item = items.get(0);
		assertEquals(0, item.getSlot());
		assertEquals(23499, item.getItemId());
		assertEquals("Grubby key", item.getName());
		assertEquals(1, item.getQuantity());
	}

	// --- B. placeholder item is excluded ---

	@Test
	public void placeholder_b_placeholderItem_isExcluded()
	{
		// Exactly the live-bug shape: placeholder itemId (23501),
		// reported quantity 1 -- must still be excluded.
		Item[] raw = new Item[] { new Item(23501, 1) };
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, isPlaceholder, nameLookup(names));

		assertTrue("a placeholder-only slot must produce no owned-item entry at all", items.isEmpty());
	}

	// --- C. real item -> placeholder transition produces an owned-state change ---

	@Test
	public void placeholder_c_realItemToPlaceholderTransition_isAnOwnedStateChange()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");
		IntPredicate isPlaceholder = itemId -> itemId == 23501;

		List<StorageState.StorageItem> before = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		List<StorageState.StorageItem> after = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));

		assertEquals(1, before.size());
		assertTrue("withdrawing the final copy (leaving a placeholder) must remove it from owned items", after.isEmpty());
		assertFalse("the before/after owned-item lists must be genuinely different", before.equals(after));
	}

	// --- D. placeholder-only bank slot is not serialized as ownership ---

	@Test
	public void placeholder_d_placeholderOnlySlot_isNeverSerializedAsOwnership()
	{
		// A slot RuneLite still reserves for the placeholder, alongside
		// unrelated real items in other slots -- only the placeholder
		// slot must be dropped.
		Item[] raw = new Item[] {
			new Item(23499, 1),
			new Item(13797, 5),
			new Item(23501, 1)
		};
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Blood moon chestplate");
		names.put(13797, "Onion seed");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, isPlaceholder, nameLookup(names));

		assertEquals("exactly the two real items must survive, never the placeholder slot", 2, items.size());
		for (StorageState.StorageItem item : items)
		{
			assertFalse("no serialized item may carry the placeholder itemId", item.getItemId() == 23501);
		}
	}

	// --- E. bank snapshot after removing the final copy does not contain the item ---

	@Test
	public void placeholder_e_bankSnapshotAfterRemovingFinalCopy_doesNotContainTheItem() throws Exception
	{
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> withKey = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, withKey));

		StorageState pointerBefore = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
		StorageState snapshotBefore = store.readIfExists(
			TelemetryPaths.bankSnapshotFile(accountHash, pointerBefore.getLatestSnapshotId()), StorageState.class);
		assertEquals(1, snapshotBefore.getItems().size());

		// The final copy is withdrawn, leaving only the placeholder --
		// buildBankItemsCore() (as production's buildBankItems() would)
		// excludes it entirely from the observed owned-item list.
		List<StorageState.StorageItem> withPlaceholderOnly = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, withPlaceholderOnly));

		StorageState pointerAfter = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
		StorageState snapshotAfter = store.readIfExists(
			TelemetryPaths.bankSnapshotFile(accountHash, pointerAfter.getLatestSnapshotId()), StorageState.class);

		assertTrue("the new immutable snapshot must contain no entry for the withdrawn item at all",
			snapshotAfter.getItems().isEmpty());
		for (StorageState.StorageItem item : snapshotAfter.getItems())
		{
			assertFalse(item.getItemId() == 23499 || item.getItemId() == 23501);
		}
	}

	// --- F. dedup logic sees real-item -> placeholder as changed contents ---

	@Test
	public void placeholder_f_dedupBaseline_seesRealItemToPlaceholderTransitionAsChanged()
	{
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> baselineItems = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		List<StorageState.StorageItem> candidateItems = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));

		Instant createdAt = Instant.now();
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(baselineItems, createdAt);

		assertTrue(
			"a real-item -> placeholder transition must be recognized as removal of the owned item, forcing a new snapshot",
			BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, candidateItems, createdAt.plusSeconds(1), java.time.Duration.ofMinutes(10)));
	}

	// --- G. inventory/equipment behavior is unchanged ---

	@Test
	public void placeholder_g_inventoryAndEquipment_behaviorUnchanged()
	{
		// buildSparseItems()/buildEquipmentItems() (inventory/equipment/
		// seed vault/group storage) are untouched by this fix -- they
		// never call buildBankItemsCore()/isPlaceholder at all, so an
		// itemId that WOULD be treated as a bank placeholder must still
		// be recorded normally everywhere else. This asserts the
		// negative: buildBankItemsCore() applied with a
		// no-op placeholder predicate (equivalent to what
		// buildSparseItems() effectively does -- no placeholder concept)
		// still returns every real, quantity>0 item, confirming the
		// filtering is additive and opt-in per container, not a global
		// itemId denylist that could ever leak into another container's
		// logic.
		Map<Integer, String> names = new HashMap<>();
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, NEVER_PLACEHOLDER, nameLookup(names));

		assertEquals(
			"without bank-specific placeholder classification (i.e. exactly how buildSparseItems()/"
				+ "buildEquipmentItems() treat every item id), the same raw item is retained normally",
			1, items.size());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.model.StorageState;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Client-independent coverage of LoadoutArchive: query
 * semantics (strictly-before / at-or-after / at-or-before), pruning
 * by age and by count, defensive copying, and account-switch reset.
 * Plain JUnit, no Mockito, matching this project's established test
 * style (see LootTrackerIndexTest).
 */
public class LoadoutArchiveTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");

	private static List<StorageState.StorageItem> oneItem(int itemId)
	{
		return Collections.singletonList(new StorageState.StorageItem(0, itemId, "item-" + itemId, 1, null));
	}

	@Test
	public void record_thenLatestStrictlyBefore_findsEntryStrictlyEarlier()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestStrictlyBefore(T0.plusSeconds(90));

		assertNotNull(found);
		assertEquals(T0.plusSeconds(60), found.getObservedAt());
		assertEquals(2, found.getInventory().get(0).getItemId());
	}

	@Test
	public void latestStrictlyBefore_excludesEntryExactlyAtInstant()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		assertNull("an entry observed exactly AT the query instant must not count as 'strictly before' it",
			archive.latestStrictlyBefore(T0));
	}

	@Test
	public void earliestAtOrAfter_includesEntryExactlyAtInstant()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());

		LoadoutArchive.Entry found = archive.earliestAtOrAfter(T0);

		assertNotNull(found);
		assertEquals(T0, found.getObservedAt());
		assertEquals(1, found.getInventory().get(0).getItemId());
	}

	@Test
	public void earliestAtOrAfter_picksEarliestQualifyingEntry_notLatest()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0.plusSeconds(30), oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());
		archive.record(T0.plusSeconds(90), oneItem(3), Collections.emptyList());

		LoadoutArchive.Entry found = archive.earliestAtOrAfter(T0.plusSeconds(10));

		assertEquals(T0.plusSeconds(30), found.getObservedAt());
	}

	@Test
	public void latestAtOrBefore_includesEntryExactlyAtInstant_picksMostRecentQualifying()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(30), oneItem(2), Collections.emptyList());
		archive.record(T0.plusSeconds(90), oneItem(3), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0.plusSeconds(30));

		assertNotNull(found);
		assertEquals(T0.plusSeconds(30), found.getObservedAt());
	}

	@Test
	public void queries_onEmptyArchive_returnNull()
	{
		LoadoutArchive archive = new LoadoutArchive();

		assertNull(archive.latestStrictlyBefore(T0));
		assertNull(archive.earliestAtOrAfter(T0));
		assertNull(archive.latestAtOrBefore(T0));
	}

	@Test
	public void record_defensivelyCopiesLists_laterMutationNotReflected()
	{
		LoadoutArchive archive = new LoadoutArchive();
		List<StorageState.StorageItem> inventory = new ArrayList<>(oneItem(1));

		archive.record(T0, inventory, Collections.emptyList());
		inventory.clear();

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0);
		assertEquals(1, found.getInventory().size());
	}

	@Test
	public void entryLists_areUnmodifiable()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0);
		try
		{
			found.getInventory().add(new StorageState.StorageItem(1, 2, "x", 1, null));
			org.junit.Assert.fail("Entry's inventory list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	@Test
	public void prune_dropsEntriesOlderThanMaxAge()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		// A later record() call prunes based on ITS OWN observedAt as "now".
		Instant wellPastMaxAge = T0.plus(LoadoutArchive.MAX_AGE).plusSeconds(1);
		archive.record(wellPastMaxAge, oneItem(2), Collections.emptyList());

		assertNull("the T0 entry must have aged out once MAX_AGE has elapsed -- a query that could ONLY match it must find nothing",
			archive.latestStrictlyBefore(T0.plusSeconds(1)));
		assertNotNull("the fresh entry must still be present",
			archive.latestAtOrBefore(wellPastMaxAge));
	}

	@Test
	public void prune_boundsEntryCountAtMaxEntries()
	{
		LoadoutArchive archive = new LoadoutArchive();
		for (int i = 0; i < LoadoutArchive.MAX_ENTRIES + 20; i++)
		{
			// One-second spacing keeps every entry well within MAX_AGE of
			// the last one recorded, so only the count bound is exercised.
			archive.record(T0.plusSeconds(i), oneItem(i), Collections.emptyList());
		}

		assertEquals(LoadoutArchive.MAX_ENTRIES, archive.size());
		// The oldest entries (0..19) must have been evicted in favor of the newest.
		assertNull(archive.latestAtOrBefore(T0.plusSeconds(5)));
	}

	@Test
	public void resetForAccountSwitch_clearsEverything()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		assertTrue(archive.size() > 0);

		archive.resetForAccountSwitch();

		assertEquals(0, archive.size());
		assertNull(archive.latestAtOrBefore(T0.plusSeconds(1000)));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import org.junit.Test;

/**
 * NOTE: written, not run in this file — same "written, not run" caveat
 * this project applies to every Java test (no JDK/RuneLite client jar
 * available in the cloud sandbox that authored this file; see plugin/
 * README.md and LootCollectorTest's identical note). The actual
 * `./gradlew test` run is Josh's to perform on his own machine.
 *
 * Targets ServerNpcLootCollector's pure, Client/EventLedger/RuneLite-
 * API-independent helpers (buildPayload(), isPickpocketMessage(),
 * shouldSuppress()) — this project has no Mockito dependency, so
 * NPCComposition/ItemStack/Client/ServerNpcLoot/ChatMessage are never
 * mocked, mirroring LootCollectorTest/NpcDeathCollectorTest's existing
 * pattern exactly.
 *
 * Guarantees that are architectural rather than
 * unit-testable in isolation without mocking RuneLite's EventBus (this
 * project deliberately avoids depending on that for tests), documented
 * here instead of faked as a test — see points 14/15 below.
 */
public class ServerNpcLootCollectorTest
{
	private static final Gson GSON = new Gson();

	private static EventPayloads.ServerNpcLootItem item(int itemId, String itemName, int quantity)
	{
		return new EventPayloads.ServerNpcLootItem(itemId, itemName, quantity);
	}

	// --- 1/8. one notification -> one payload containing all item stacks, original grouping preserved ---

	@Test
	public void buildPayload_oneNotification_preservesAllItemStacksTogether()
	{
		List<EventPayloads.ServerNpcLootItem> items = Arrays.asList(
			item(4151, "Abyssal whip", 1),
			item(995, "Coins", 42),
			item(1631, "Ensouled goblin head", 1)
		);

		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload("Gargoyle", 111, items);

		assertEquals(3, payload.getItems().size());
		assertEquals(items, payload.getItems());
	}

	// --- 2. source name preserved ---

	@Test
	public void buildPayload_preservesSourceName()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertEquals("Gargoyle", payload.getSourceName());
	}

	// --- 3. source id preserved when valid ---

	@Test
	public void buildPayload_preservesValidSourceId()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertEquals(Integer.valueOf(111), payload.getSourceId());
	}

	// --- 4. unavailable/invalid source id not fabricated ---

	@Test
	public void buildPayload_negativeSourceId_leftNullNotFabricated()
	{
		// NPCComposition#getId() carries no documented guarantee of
		// always returning a real value — mirroring NpcDeathCollector.
		// buildPayload()'s identical treatment of NPC#getId().
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", -1, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceId());
	}

	@Test
	public void buildPayload_zeroSourceId_leftNullNotFabricated()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 0, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceId());
	}

	// --- 5/6/7. item id/name/quantity preserved ---

	@Test
	public void buildPayload_preservesItemIdNameAndQuantity()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Chicken", 41, Collections.singletonList(item(995, "Coins", 42)));

		EventPayloads.ServerNpcLootItem only = payload.getItems().get(0);
		assertEquals(995, only.getItemId());
		assertEquals("Coins", only.getItemName());
		assertEquals(42, only.getQuantity());
	}

	@Test
	public void buildPayload_itemNameNull_passedThroughNotFabricated()
	{
		// An ItemManager lookup that fails to resolve a name must not be
		// papered over with a placeholder like "Unknown" — pass-through,
		// not a decision, same discipline as LootCollector.buildPayload().
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, null, 1)));

		assertNull(payload.getItems().get(0).getItemName());
	}

	// --- 9. empty/null-shaped input does not fabricate loot ---

	@Test
	public void buildPayload_emptyItemList_notFabricatedIntoNonEmptyLoot()
	{
		// A ServerNpcLoot notification with no items is not RuneLite
		// behavior this collector invented a workaround for — whatever
		// the notification actually carried (including nothing) is what
		// the payload carries; an empty items list must stay empty, not
		// be treated as "no event" (that decision belongs to the caller
		// deciding whether to call buildPayload() at all, not to this
		// pure function) and never padded with an invented item.
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.emptyList());

		assertTrue(payload.getItems().isEmpty());
	}

	@Test
	public void buildPayload_nullSourceName_passedThroughNotFabricated()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			null, 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceName());
	}

	// --- 10. serializes through the project's actual Gson mechanism ---

	@Test
	public void payload_roundTripsThroughGson_sameSerializerEventLedgerUses()
	{
		// EventLedger.append() serializes the payload with a plain
		// `new Gson()` (see EventLedger.java) — this test uses the same
		// mechanism directly on the payload object, isolated from
		// Client/EventBus/file I/O, mirroring LootCollectorTest's
		// identical pattern.
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Arrays.asList(item(4151, "Abyssal whip", 1), item(995, "Coins", 42)));

		String json = GSON.toJson(payload);
		EventPayloads.ServerNpcLoot roundTripped = GSON.fromJson(json, EventPayloads.ServerNpcLoot.class);

		assertEquals(payload, roundTripped);
		assertTrue("serialized JSON should carry the item name", json.contains("Abyssal whip"));
		assertTrue("serialized JSON should carry the source name", json.contains("Gargoyle"));
	}

	// --- helper: build an "armed" suppression state for a given tick/identity ---

	private static ServerNpcLootCollector.PickpocketSuppressionState armed(int tick, Integer npcId, String npcName)
	{
		return ServerNpcLootCollector.PickpocketSuppressionState.armed(tick, npcId, npcName);
	}

	private static ServerNpcLootCollector.PickpocketSuppressionState notArmed()
	{
		return ServerNpcLootCollector.PickpocketSuppressionState.notArmed();
	}

	// --- 11. same tick + SAME NPC identity (by id) => duplicate pickpocket-style loot stays suppressed ---

	@Test
	public void shouldSuppress_sameTickSameNpcIdById_suppressed()
	{
		// The pickpocket message was observed while interacting with NPC
		// id 41 ("Chicken"); the ServerNpcLoot notification on the same
		// tick is for the same id — this is the ordinary "avoid a
		// duplicate pickpocket-loot notification" case and must stay
		// suppressed exactly as RuneLite's own tick-only guard already
		// suppressed it.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(12345, 41, "Chicken");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 12345, "Chicken", 41));
	}

	@Test
	public void shouldSuppress_sameTickSameNpcNameOnly_suppressed_whenIdsUnavailable()
	{
		// Neither side has a resolvable positive id (e.g. getId()
		// returned an unresolved/non-positive value) — falls back to a
		// normalized name comparison and still suppresses the duplicate.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(500, null, "Man");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 500, "Man", 0));
	}

	// --- 12. same tick + DIFFERENT NPC/source kill loot => NOT suppressed (the actual fix) ---

	@Test
	public void shouldSuppress_sameTickDifferentNpcById_notSuppressed()
	{
		// This is the live defect being guarded against: an unrelated
		// pickpocket message (e.g. for a "Man") landing on the same
		// tick as a genuine, different NPC's ("Gargoyle") kill loot must
		// not silently discard that kill's ServerNpcLoot. Applies
		// uniformly to any NPC name — nothing Bandit-specific here.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(777, 41, "Man");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 777, "Gargoyle", 111));
	}

	@Test
	public void shouldSuppress_sameTickDifferentNpcByNameOnly_notSuppressed()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(900, null, "Man");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 900, "Gargoyle", 0));
	}

	@Test
	public void shouldSuppress_idsDiffer_evenWhenNamesHappenToMatch_notSuppressed()
	{
		// Id comparison takes precedence over name when both sides have
		// a resolvable id — two different-id sources sharing a display
		// name (a generic/common NPC name) must not be treated as the
		// same NPC merely because the names happen to match.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(42, 41, "Guard");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 42, "Guard", 99));
	}

	// --- 13. ordinary NPC kill with no pickpocket signal at all => SERVER_NPC_LOOT emitted (not suppressed) ---

	@Test
	public void shouldSuppress_noPickpocketSignalAtAll_ordinaryKillLootNotSuppressed()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = notArmed();
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 0, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 1, "Gargoyle", 111));
	}

	// --- 14. no identity captured at pickpocket time (interaction target unresolvable) => safe tick-only fallback ---

	@Test
	public void shouldSuppress_noIdentityCapturedAtArmTime_fallsBackToTickOnlySuppression()
	{
		// getInteracting() returned null/non-NPC at the exact moment the
		// pickpocket message was observed -- both npcId and npcName are
		// null on the armed state. The original "never allow duplicate
		// pickpocket loot" guarantee still holds in this narrow case: a
		// same-tick ServerNpcLoot for ANY source is suppressed, exactly
		// as the pre-fix tick-only guard behaved.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(2024, null, null);
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 2024, "Gargoyle", 111));
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 2024, "Chicken", 41));
	}

	// --- 15. tick rollover / stale suppression state cannot suppress a later unrelated kill ---

	@Test
	public void shouldSuppress_staleArmedStateFromEarlierTick_neverSuppressesLaterUnrelatedKill()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(100, 41, "Chicken");
		// Even for the SAME NPC identity, a different (later, or
		// wrapped-around) tick must never be treated as "still armed" --
		// the tick check is the first, unconditional gate.
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 101, "Chicken", 41));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, Integer.MAX_VALUE, "Chicken", 41));
	}

	// --- 16. multiple NPCs on the same tick do not contaminate each other's suppression state ---

	@Test
	public void shouldSuppress_multipleNpcsSameTick_noCrossContamination()
	{
		// Suppression state captured for one NPC ("Man") on a given tick
		// must resolve independently per candidate ServerNpcLoot source
		// checked against it: the matching NPC stays suppressed, every
		// other NPC checked on that same tick is not.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(55, 41, "Man");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 55, "Man", 41));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 55, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 55, "Chicken", 7));
	}

	@Test
	public void shouldSuppress_notArmedSentinel_neverEqualsRealTick()
	{
		// NOT_ARMED_TICK (-1) must never accidentally suppress a
		// legitimate tick-0 (or any other real, non-negative)
		// ServerNpcLoot — see ServerNpcLootCollector's NOT_ARMED_TICK
		// javadoc for why -1 (not RuneLite's own implicit-0 default) was
		// chosen.
		ServerNpcLootCollector.PickpocketSuppressionState state = notArmed();
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 0, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 1, "Gargoyle", 111));
	}

	@Test
	public void isPickpocketMessage_matchesRuneLitesOwnPattern()
	{
		// Exact same pattern/match-style as current LootTrackerPlugin's
		// PICKPOCKET_REGEX — see class javadoc's verbatim quote.
		assertTrue(ServerNpcLootCollector.isPickpocketMessage("You pick the Man's pocket."));
		assertTrue(ServerNpcLootCollector.isPickpocketMessage("You pick Hard hitter's pocket and get some coins."));
	}

	@Test
	public void isPickpocketMessage_ordinaryLootMessage_doesNotMatch()
	{
		assertFalse(ServerNpcLootCollector.isPickpocketMessage("Valuable drop: Abyssal whip"));
		assertFalse(ServerNpcLootCollector.isPickpocketMessage("You have a funny feeling like you're being followed."));
	}

	// --- 17. config gating enforced by construction (documented, see class javadoc) ---
	//
	// onChatMessage()/onServerNpcLoot() both check config.collectLoot()
	// as their very first statement (mirroring LootCollector's identical
	// pattern) — not independently unit-testable without mocking
	// RuneLite's Client/EventBus/OsrsTelemetryConfig, which this project
	// deliberately avoids for tests (see LootCollectorTest's identical
	// "architectural, not unit-testable in isolation" notes).

	// --- 18/19. no dependency on NPC_DEATH or NPC_LOOT_ATTRIBUTED ---
	//
	// Enforced by construction — ServerNpcLootCollector has no reference
	// to NpcDeathCollector, EventType.NPC_DEATH, ActorDeath,
	// LootCollector, EventType.NPC_LOOT_ATTRIBUTED, or NpcLootReceived
	// anywhere in its source; its only @Subscribe handlers are
	// onChatMessage(ChatMessage) and onServerNpcLoot(ServerNpcLoot).

	// --- 20. no Slayer/kill ownership field on the payload ---

	@Test
	public void payload_declaresOnlyTheThreeExpectedFields_noOwnershipKillOrSlayerField()
	{
		Field[] fields = EventPayloads.ServerNpcLoot.class.getDeclaredFields();
		String[] fieldNames = Arrays.stream(fields)
			.map(Field::getName)
			.toArray(String[]::new);

		String[] expected = {"sourceName", "sourceId", "items"};
		String[] sortedActual = fieldNames.clone();
		String[] sortedExpected = expected.clone();
		Arrays.sort(sortedActual);
		Arrays.sort(sortedExpected);
		assertArrayEquals(sortedExpected, sortedActual);

		assertNoOwnershipKillOrSlayerField(fieldNames);
		assertNoOwnershipKillOrSlayerField(
			Arrays.stream(EventPayloads.ServerNpcLootItem.class.getDeclaredFields())
				.map(Field::getName)
				.toArray(String[]::new));
	}

	private static void assertNoOwnershipKillOrSlayerField(String[] fieldNames)
	{
		for (String name : fieldNames)
		{
			String lower = name.toLowerCase(Locale.ROOT);
			assertFalse("field " + name + " must not imply ownership", lower.contains("owner"));
			assertFalse("field " + name + " must not imply local-player ownership", lower.contains("mine") || lower.contains("belongsto"));
			assertFalse("field " + name + " must not imply kill attribution", lower.contains("kill"));
			assertFalse("field " + name + " must not imply death attribution", lower.contains("death"));
			assertFalse("field " + name + " must not imply Slayer attribution", lower.contains("slayer") || lower.contains("ontask"));
		}
	}
}

package com.osrstelemetry.plugin.events;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.UUID;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Append-only, one JSON object per line, per account.
 *
 * Same two fixes as LocalStateStore, for the same reasons (see its
 * javadoc): the envelope (including the payload) is built and
 * serialized to a String synchronously in append(), before handing
 * off to the background executor — a payload object's fields are
 * final/immutable by construction (see EventPayloads), but building
 * the JSON string synchronously means there is never a window where a
 * caller could observe or mutate anything after the fact and get a
 * different result than what's on disk. start()/shutdown() are
 * explicit lifecycle methods rather than constructor/finalizer, so
 * enable -> disable -> enable within one client process gets a fresh
 * working executor every time instead of reusing a shut-down one.
 */
@Slf4j
@Singleton
public class EventLedger
{
	private final Gson gson;
	private ExecutorService executor;
	private volatile String sessionId = UUID.randomUUID().toString();

	@Inject
	public EventLedger(Gson gson)
	{
		this.gson = gson;
	}

	// See TelemetryEventListener's javadoc for the full contract.
	// CopyOnWriteArrayList: registration/
	// unregistration (plugin enable/disable) is rare, notification (every
	// append()) is frequent -- optimizing the common case for lock-free
	// reads, matching this project's existing preference for simple,
	// well-understood concurrency primitives over anything bespoke.
	private final List<TelemetryEventListener> listeners = new CopyOnWriteArrayList<>();

	/**
	 * Registration must be paired with removeListener() on plugin
	 * disable/shutDown() -- this list is NOT cleared by start()/
	 * shutdown() (those only manage the write executor), so a caller
	 * that adds itself again on every re-enable without ever removing
	 * itself would silently accumulate duplicate listeners and receive
	 * every event more than once. This is the exact same class of bug
	 * the client-thread lifecycle audit found and fixed for EventBus
	 * registration -- see OsrsTelemetryPlugin's own startUp()/shutDown()
	 * pairing for the established, already-correct pattern to mirror.
	 */
	public void addListener(TelemetryEventListener listener)
	{
		listeners.add(listener);
	}

	public void removeListener(TelemetryEventListener listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Synchronous, on the calling thread, by design -- see
	 * TelemetryEventListener's javadoc. Every listener is isolated from
	 * every other and from the durable write: an ordinary listener
	 * failure is logged and swallowed here, never allowed to prevent or
	 * corrupt the append this notification accompanies ("session routing
	 * failure must not corrupt/drop the durable telemetry event").
	 *
	 * FAILURE-ISOLATION CONTRACT: this is the ONLY boundary in
	 * this class that separates a telemetry COLLECTOR (the caller of
	 * append()/appendAndWait(), e.g. SkillsCollector, ContainerCollector)
	 * from a session-runtime LISTENER (e.g. SessionRuntimeCoordinator).
	 * A broken listener must not be able to unwind into an unrelated
	 * collector's own control flow -- that includes both RuntimeException
	 * AND AssertionError (a real, previously-observed failure mode in
	 * this project's RuneLite development, and NOT a RuntimeException),
	 * so both are caught and isolated below.
	 *
	 * This does NOT extend to genuine JVM-fatal conditions --
	 * VirtualMachineError (OutOfMemoryError, StackOverflowError, and
	 * their siblings) and ThreadDeath. An earlier pass caught
	 * `Throwable` unconditionally, which was too broad: silently
	 * swallowing a condition that means the JVM itself is dying (or a
	 * thread is being deliberately, cooperatively stopped via
	 * ThreadDeath) hides a failure this method has no ability to
	 * meaningfully isolate or recover from, and every other component
	 * sharing this same JVM is about to be affected by it regardless of
	 * what this catch block does. Those conditions are deliberately
	 * re-thrown -- allowed to propagate out of notifyListeners() and out
	 * of append()/appendAndWait() -- rather than logged and suppressed.
	 * This is the standard "catch broadly, but never swallow VM-fatal
	 * conditions" idiom: `catch (Throwable t)` combined with an explicit
	 * rethrow for the fatal subset, since Java's multi-catch syntax
	 * cannot express "Throwable except VirtualMachineError/ThreadDeath"
	 * directly.
	 *
	 * Rethrowing here does not put the already-durably-accepted write at
	 * risk: by the time notifyListeners() runs, the write has already
	 * been submitted to the single-writer executor (see append()'s/
	 * appendAndWait()'s own ordering comments) -- an Error propagating
	 * out of this method at that point can no longer cancel, prevent, or
	 * otherwise affect that already-submitted durable write; it only
	 * affects whether THIS method call returns normally to its caller.
	 */
	private void notifyListeners(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		for (TelemetryEventListener listener : listeners)
		{
			try
			{
				listener.onEvent(accountHash, type, payload, observedAt);
			}
			catch (VirtualMachineError | ThreadDeath fatal)
			{
				// Genuine JVM-fatal conditions are never swallowed --
				// see the class-level rationale above. Deliberately
				// rethrown before the broader catch below can absorb it.
				throw fatal;
			}
			catch (Throwable t)
			{
				// Everything else -- ordinary RuntimeExceptions AND
				// AssertionError -- is isolated here. This runs AFTER the
				// durable write has already been accepted (see append()/
				// appendAndWait()), so nothing caught here can still
				// reach back and prevent/cancel/corrupt that acceptance.
				log.warn("Telemetry event listener threw while handling {}; durable write is unaffected", type, t);
			}
		}
	}

	public synchronized void start()
	{
		if (executor != null && !executor.isShutdown())
		{
			return;
		}
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-event-ledger");
			t.setDaemon(true);
			return t;
		});
	}

	/**
	 * A "session" is one run of the client with this plugin active,
	 * not one game-account login — see plugin startUp(). Also called
	 * on an account switch (see AccountContext) so events from
	 * different accounts in the same client run never share a
	 * sessionId.
	 */
	public void startNewSession()
	{
		sessionId = UUID.randomUUID().toString();
	}

	public void append(long accountHash, EventType type, Object payload)
	{
		ExecutorService executor = this.executor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("append() called while EventLedger is not started; dropping event {}", type);
			return;
		}

		Instant observedAt = Instant.now();
		String json = buildEnvelopeJson(accountHash, type, payload, observedAt);

		// Durable acceptance FIRST, structurally -- see class-level
		// ordering note above. If this event isn't even accepted for a
		// durable write, listeners are never told about it either.
		try
		{
			executor.submit(() -> appendNow(accountHash, json));
		}
		catch (RejectedExecutionException e)
		{
			log.warn("append() rejected while EventLedger is shutting down; dropping event {}", type);
			return;
		}

		notifyListeners(accountHash, type, payload, observedAt);
	}

	/**
	 * Synchronous/waitable counterpart to append(), for shutdown-critical
	 * callers that must know an event actually reached disk before they
	 * can safely return -- e.g. ContainerCollector.finalizeBankSnapshotBlocking().
	 * The fire-and-forget append() above relies on shutdown()'s graceful
	 * drain, which is not guaranteed to complete an append still
	 * queued-but-not-yet-run when shutdown() tears the executor down --
	 * this method removes that reliance entirely for the one call site
	 * that cannot tolerate it.
	 *
	 * Builds and serializes the IDENTICAL TelemetryEvent envelope
	 * append() does -- same fresh random eventId, the ledger's current
	 * sessionId, same schema/payload shape, same Gson serializer -- and
	 * submits it through the SAME single-writer executor, so ordering
	 * relative to every other append()/appendAndWait() call is fully
	 * preserved (this is not a second, parallel write path). The only
	 * difference is that the calling thread then blocks (bounded by
	 * timeoutMs) until that specific submitted write has actually run
	 * and reports its own success/failure, instead of returning the
	 * instant the task is merely queued.
	 *
	 * This is deliberately NOT a replacement for append() in ordinary
	 * gameplay event handling -- it exists only for the narrow set of
	 * callers (currently: shutdown-time bank finalization) that cannot
	 * proceed without a durable answer.
	 *
	 * @return true only if this specific event was confirmed written to
	 * disk before timeoutMs elapsed. false covers every other outcome
	 * -- not started, rejected because shutdown is already underway,
	 * a genuine write failure, a timeout, or this thread being
	 * interrupted while waiting -- and callers must treat all of them
	 * identically: the event did not durably happen, full stop.
	 */
	public boolean appendAndWait(long accountHash, EventType type, Object payload, long timeoutMs)
	{
		ExecutorService executor = this.executor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("appendAndWait() called while EventLedger is not started; dropping event {}", type);
			return false;
		}

		Instant observedAt = Instant.now();
		String json = buildEnvelopeJson(accountHash, type, payload, observedAt);

		// EXACT ENFORCED ORDER: (1) submit the durable write --
		// durably ACCEPTED onto the single-writer executor; (2)
		// synchronous listener notification, on this calling thread,
		// isolated per-listener by notifyListeners()'s own Throwable
		// catch; (3) THEN, and only then, wait (bounded by timeoutMs) for
		// the durable future submitted in step (1) to actually complete.
		// The durable future's own success/failure was already decided
		// independently back in step (1) -- it does not depend on
		// listener success in any way -- but this method, being
		// synchronous, still executes all of step (2)'s listener work
		// before it ever reaches step (3)'s durability wait. A slow or
		// misbehaving listener therefore delays how soon THIS caller
		// observes the durability result, even though it can never change
		// what that result is.
		Future<Boolean> future;
		try
		{
			future = executor.submit(() -> appendNow(accountHash, json));
		}
		catch (RejectedExecutionException e)
		{
			log.warn("appendAndWait() rejected while EventLedger is shutting down; dropping event {}", type);
			return false;
		}

		notifyListeners(accountHash, type, payload, observedAt);

		try
		{
			return Boolean.TRUE.equals(future.get(timeoutMs, TimeUnit.MILLISECONDS));
		}
		catch (InterruptedException e)
		{
			log.warn("appendAndWait() interrupted while waiting to append {}; treating as not durably written", type);
			return false;
		}
		catch (ExecutionException | TimeoutException e)
		{
			log.warn("appendAndWait() failed or timed out appending {}", type, e);
			return false;
		}
	}

	/**
	 * Shared envelope construction for append()/appendAndWait() --
	 * factored out so the two entry points can never drift in
	 * sessionId/eventId/schema semantics from one another. Building
	 * and serializing here, synchronously on the calling thread before
	 * either method touches the executor, mirrors this class's
	 * existing documented discipline (see class javadoc).
	 */
	private String buildEnvelopeJson(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		TelemetryEvent event = new TelemetryEvent(
			UUID.randomUUID().toString(),
			Long.toString(accountHash),
			type,
			observedAt.toString(),
			sessionId,
			payload
		);
		return gson.toJson(event);
	}

	/** @return true if this event line was successfully and durably
	 * appended to disk. */
	private boolean appendNow(long accountHash, String json)
	{
		try
		{
			TelemetryPaths.eventsFile(accountHash).write(
				(json + System.lineSeparator()).getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.APPEND
			);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Failed appending telemetry event for account {}", accountHash, e);
			return false;
		}
	}

	/**
	 * Graceful drain — same reasoning as LocalStateStore.shutdown().
	 */
	public void shutdown()
	{
		ExecutorService executor = this.executor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("EventLedger writer did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the EventLedger writer; leaving it to keep draining in the background");
		}
	}
}

package com.osrstelemetry.plugin.events;

import lombok.Data;

/**
 * Bundled in one file (rather than one file per payload, unlike the
 * model/ package) because these are pure inert data shapes with no
 * behavior — splitting them wouldn't aid readability, just add file
 * count. Each mirrors a payload example from the telemetry schema.
 */
public final class EventPayloads
{
	private EventPayloads()
	{
	}

	@Data
	public static class XpChange
	{
		private final String skill;
		private final int previousXp;
		private final int newXp;
		private final int delta;
		private final String windowStart;
		private final String windowEnd;
	}

	@Data
	public static class LevelUp
	{
		private final String skill;
		private final int previousLevel;
		private final int newLevel;
		private final int xp;
	}

	@Data
	public static class QuestCompleted
	{
		private final int questId;
		private final String questKey;
		private final String questName;
	}

	@Data
	public static class CombatAchievementCompleted
	{
		private final String tier;
		private final String taskName;
	}

	/**
	 * itemId is null here — see CollectionLogCollector javadoc, the
	 * chat message this is built from doesn't carry an item ID and I'm
	 * not resolving name->ID by guessing. Fill this in once the
	 * full-page widget read (still unimplemented) provides a real
	 * source for it.
	 */
	@Data
	public static class CollectionLogNewItem
	{
		private final Integer itemId;
		private final String itemName;
	}

	/**
	 * Renamed from LootDrop/LOOT_DROP. Built from
	 * net.runelite.client.events.NpcLootReceived, produced by
	 * net.runelite.client.game.LootManager, which attributes an
	 * item stack to an NPC by pure tile + same-game-tick correlation to
	 * the NPC's despawn (LootManager.onItemSpawned() adds every
	 * ItemSpawned to a per-tile map unconditionally;
	 * getItemStacksFromAreas() then just reads whatever TileItem(s) are
	 * on the death tile(s), converting by id+quantity only —
	 * TileItem#getOwnership()/isPrivate() are never read anywhere in
	 * that file). This does NOT prove the item was awarded to or owned
	 * by the local player specifically — it can genuinely include
	 * another visible player's drop sharing the same tile in the same
	 * tick. Hence the field/class name change from "Drop" (which reads
	 * as "my loot") to "LootAttributed" (RuneLite's attribution of an
	 * observed stack to an NPC, nothing stronger). See
	 * NpcDeathCollector's own class javadoc for the full source-audit
	 * evidence, including why the newer, likely
	 * player-owned-loot-capable net.runelite.client.events.ServerNpcLoot
	 * was deliberately NOT switched to as this event's source.
	 *
	 * No field on this payload claims local-player ownership, kill
	 * attribution, or Slayer-task attribution — sourceType/sourceName/
	 * sourceId identify the NPC RuneLite attributed the stack to;
	 * itemId/itemName/quantity identify the item stack itself. Nothing
	 * here was renamed at the field level (no field ever claimed
	 * ownership) — only the class/event name, which previously implied
	 * more than the source proves.
	 */
	@Data
	public static class NpcLootAttributed
	{
		private final String sourceType;
		private final String sourceName;
		private final int sourceId;
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}

	@Data
	public static class BossKill
	{
		private final String activityId;
		private final String displayName;
		private final int killCount;
		private final String source;
	}

	/**
	 * Backs EventType.BOSS_ACTIVITY_CONTEXT -- see that constant's javadoc for
	 * the full source audit and the reason this is deliberately
	 * NON-authoritative. Intentionally a single-field payload:
	 * bossName is the canonical boss display name KnownBossRegistry
	 * resolved (already alias-mapped, e.g. "Dawn" -> "Grotesque
	 * Guardians" -- never the raw, un-resolved NPC name). No
	 * reliableCount/killCount field exists here, unlike BossKill --
	 * this payload structurally cannot carry kill-count authority.
	 */
	@Data
	public static class BossActivityContext
	{
		private final String bossName;
	}

	@Data
	public static class RaidCompletion
	{
		private final String activityId;
		private final String displayName;
		private final int completionCount;
		private final String source;
	}

	/**
	 * Everything that prints a "completion count" line but is NOT one
	 * of the three verified raids (see ActivityKillCountCollector's
	 * RAID_IDS) — Corrupted Gauntlet, minigames, and any other
	 * activity with a completion counter. Kept schema-identical to
	 * RaidCompletion deliberately (same fields) so downstream summary
	 * code can treat them uniformly if it wants to, while the event
	 * TYPE itself still keeps "raid" meaning something specific rather
	 * than "any repeatable content with a counter".
	 */
	@Data
	public static class ActivityCompletion
	{
		private final String activityId;
		private final String displayName;
		private final int completionCount;
		private final String source;
	}

	@Data
	public static class SlayerTaskAssigned
	{
		private final String monster;
		private final int amount;
		private final String location;
		private final int masterId;
	}

	@Data
	public static class SlayerTaskCompleted
	{
		private final String monster;
		private final int streak;
		private final String streakLabel;
		private final int points;
	}

	/**
	 * Task IDENTITY fields (taskName/taskLocation) are included for correlation only
	 * — this event never fires across an identity change (see
	 * SlayerCollector.evaluateSlayerTransition()); it always describes
	 * the SAME assignment's count changing. initialAmount/masterId are
	 * included only because they're already known/available on the
	 * current observation when this fires (the task has amountRemaining
	 * > 0 in both cases progress is computed from) — never fabricated
	 * for an observation where they wouldn't naturally be present.
	 *
	 * Deliberately NOT a kill count: remainingDelta/taskUnitsConsumed
	 * describe the observed change in the task's remaining-count field,
	 * not a verified NPC death count — see EventType.SLAYER_TASK_PROGRESS's
	 * javadoc for why those aren't provably equivalent.
	 */
	@Data
	public static class SlayerTaskProgress
	{
		private final String taskName;
		private final String taskLocation;
		private final int previousRemaining;
		private final int currentRemaining;
		private final int remainingDelta;
		private final int taskUnitsConsumed;
		private final int initialAmount;
		private final int masterId;
	}

	/**
	 * Built from net.runelite.api.events.ActorDeath filtered to actor
	 * instanceof NPC — see NpcDeathCollector's class javadoc for the full
	 * signal selection audit.
	 *
	 * Renamed NpcKill -> NpcDeath (matching EventType.NPC_KILL ->
	 * NPC_DEATH): ActorDeath proves only that RuneLite observed this NPC
	 * die, never that the local player caused the death, received kill
	 * credit, or that the NPC counted toward an active Slayer
	 * assignment — "Kill" read as a player-attribution claim the source
	 * signal cannot back up. Nothing about the field set changed; only
	 * the class/event name, which previously implied more than the
	 * source proves.
	 *
	 * npcName/npcId are the primary NPC identity, read directly off the
	 * NPC object at the moment of death — never fabricated/defaulted.
	 * npcId is nullable: NPC#getId() is documented to be able to return
	 * -1 for an NPC with no valid composition (e.g. a mid-transform
	 * frame); when that happens this field is left null rather than
	 * storing a sentinel that looks like a real ID. combatLevel is
	 * similarly nullable for the same reason (Actor#getCombatLevel()
	 * gives no documented guarantee it always reflects a real NPC
	 * combat level in every case) — see NpcDeathCollector for exactly
	 * when each is left null.
	 *
	 * worldLocation is the actor's server-side WorldPoint (per
	 * Actor#getWorldLocation()'s own javadoc: "not affected by things
	 * such as animations," i.e. authoritative, not a render-position
	 * guess), serialized as "x,y,plane".
	 *
	 * activeSlayerTaskName/activeSlayerTaskLocation are a LIVE read of
	 * whatever Slayer assignment (if any) is active at the moment of
	 * this death — contextual metadata only, not a claim that the dead
	 * NPC belongs to that assignment, and not a claim that the local
	 * player caused this death. There is deliberately NO onSlayerTask
	 * boolean on this payload: no defensible RuneLite/Jagex mechanism
	 * was found for mapping a specific dead NPC to
	 * a specific active Slayer assignment (e.g. a random rat dying while
	 * Gargoyles is active must not read as a Slayer kill just because a
	 * task happens to be active) — see NpcDeathCollector's javadoc for
	 * the full reasoning. Both fields are null when no task is active.
	 */
	@Data
	public static class NpcDeath
	{
		private final String npcName;
		private final Integer npcId;
		private final Integer combatLevel;
		private final String worldLocation;
		private final String activeSlayerTaskName;
		private final String activeSlayerTaskLocation;
	}

	/**
	 * Pointer only, per the spec — no per-item diff event. itemCount
	 * is a cheap sanity signal for downstream consumers; the actual
	 * delta calculation is a backend job against the
	 * corresponding bank.json snapshot, not something computed here.
	 */
	@Data
	public static class BankSnapshot
	{
		private final String storageId;
		private final String snapshotId;
		private final int itemCount;
	}

	/**
	 * See EventType.SEED_VAULT_SNAPSHOT's javadoc for the full audit. Pointer
	 * only — deliberately mirrors BankSnapshot's shape minus snapshotId
	 * (Seed Vault has no immutable per-observation snapshot file the way
	 * Bank does).
	 * The real itemId+quantity+name list lives in seed_vault.json, not
	 * here — same "pointer, not a per-item diff event" precedent
	 * BankSnapshot already established.
	 */
	@Data
	public static class SeedVaultSnapshot
	{
		private final String storageId;
		private final int itemCount;
	}

	/**
	 * Backs EventType.SERVER_NPC_LOOT — see that enum constant's javadoc for
	 * the full source audit and naming rationale. Built from
	 * net.runelite.client.events.ServerNpcLoot (composition + items),
	 * after ServerNpcLootCollector's pickpocket-tick filter has already
	 * rejected the notification (a suppressed notification never
	 * reaches buildPayload() at all — see that collector).
	 *
	 * sourceId is nullable: NPCComposition#getId() carries no documented
	 * guarantee of always returning a real, usable value (mirroring the
	 * same "do not fabricate missing values" treatment
	 * NpcDeathCollector.buildPayload() already applies to NPC#getId()) —
	 * any non-positive raw id is left null rather than stored as a
	 * misleading not-actually-real id.
	 *
	 * items is a small typed list (ServerNpcLootItem), not an
	 * unstructured map, and deliberately preserves every item stack from
	 * one ServerNpcLoot notification together in one payload — this is
	 * what lets a future aggregation layer reconstruct one individual-
	 * drop record, source-grouped totals, and item-grouped totals within
	 * a source, all from this one event. No NPC instance/world-location
	 * field exists on this payload: ServerNpcLoot does not provide one
	 * (only NPCComposition, not a live NPC instance — see the enum
	 * javadoc), and none is fabricated here.
	 *
	 * Deliberately absent from this payload, by design (see
	 * EventType.SERVER_NPC_LOOT's independence rationale and
	 * ServerNpcLootCollector's class javadoc): any kill/death reference,
	 * any Slayer-task field, any "ownedByLocalPlayer"-style boolean.
	 * This payload states only what RuneLite's ServerNpcLoot event
	 * itself carries, nothing this project inferred on top of it.
	 */
	@Data
	public static class ServerNpcLoot
	{
		private final String sourceName;
		private final Integer sourceId;
		private final java.util.List<ServerNpcLootItem> items;
	}

	/**
	 * One item stack within a ServerNpcLoot notification. A small typed
	 * shape (itemId/itemName/quantity) rather than an unstructured
	 * map/array-pair, matching how every other multi-field payload in
	 * this file is represented. itemName is resolved the same way
	 * LootCollector already resolves NPC_LOOT_ATTRIBUTED item names
	 * (ItemManager#getItemComposition(itemId).getName()) — never
	 * fabricated when the lookup can't resolve.
	 */
	@Data
	public static class ServerNpcLootItem
	{
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}

	/**
	 * Backs EventType.NPC_INTERACTION_TARGET — see that constant's javadoc for
	 * the full source audit. npcName is read directly off the NPC's own
	 * (transformed) NPCComposition at interaction time — never
	 * fabricated/guessed, never looked up in any hand-maintained table.
	 * npcId mirrors NpcDeath.npcId's own nullability precedent (NPC#getId()
	 * is documented to be able to return -1 for an NPC with no valid
	 * composition, e.g. a mid-transform frame — left null rather than
	 * stored as a misleading not-actually-real id). No reliableCount/
	 * killCount/combat-proof field exists here, unlike BossKill — this
	 * payload structurally cannot carry kill or damage-attribution
	 * authority (see NpcInteractionTargetCollector — it only ever builds
	 * this payload after confirming the target NPC's composition/actions
	 * genuinely include "Attack", so this is never emitted for a
	 * banker/shopkeeper/other merely-talked-to NPC in the first place).
	 */
	@Data
	public static class NpcInteractionTarget
	{
		private final Integer npcId;
		private final String npcName;
	}

	/**
	 * See EventType.RAW_COMBAT_XP_OBSERVED's own javadoc. skillName is
	 * the RuneLite Skill enum's own name() (matching
	 * XpChange.skillName's own convention exactly) -- deliberately NO
	 * xp/delta/level field of any kind, so this payload is structurally
	 * incapable of ever being mistaken for or merged into an XP metric.
	 */
	@Data
	public static class RawCombatXpObserved
	{
		private final String skillName;
	}
}

