package com.osrstelemetry.plugin.storage;

import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * All telemetry files live under this plugin's own RuneLite-managed
 * plugin-data directory, keyed by accountHash (not display name) so a
 * rename never orphans history:
 *
 *   .runelite/plugin-data/{internalName}/{accountHash}/
 *
 * MIGRATION (Plugin Hub maintainer review -- Filepath API): this used to
 * be a plain java.io.File tree rooted directly at
 * .runelite/osrs-telemetry/{accountHash}/ (built off RuneLite.RUNELITE_DIR).
 * RuneLite's Filepath model replaces that with a per-plugin root obtained
 * from Plugin.getPluginDirectory() -- see OsrsTelemetryPlugin.startUp(),
 * which calls init() below exactly once, before anything else touches
 * storage, with the Filepath that method returns.
 *
 * EXISTING USER DATA IS NOT LOST: @PluginDescriptor.legacyDataDirectory
 * on OsrsTelemetryPlugin is set to "osrs-telemetry" (the exact old root
 * directory name). RuneLite's own Plugin.getPluginDirectory() implementation
 * already contains a one-time automatic migration for exactly this
 * situation: the first time it is called after this update, if the NEW
 * plugin-data directory does not exist yet AND the OLD
 * .runelite/osrs-telemetry directory does exist, RuneLite itself moves
 * (renames) the entire old directory -- every accountHash subfolder and
 * everything under it -- into the new location before returning it. No
 * custom migration code was written here; this class and
 * OsrsTelemetryPlugin only need to point at the new root and declare the
 * old one's name for RuneLite's own core mechanism to find.
 *
 * ROOT LIFECYCLE: init() must be called exactly once (repeat calls with
 * the same value are harmless) before any other method on this class is
 * used -- from a real Plugin's startUp() in production, or from a
 * throwaway Filepath rooted at a JVM temp directory in tests (see
 * TestFilepaths). Every method below throws IllegalStateException if
 * called before init().
 */
@Slf4j
public final class TelemetryPaths
{
	private TelemetryPaths()
	{
	}

	private static volatile Filepath root;

	/**
	 * Called exactly once from OsrsTelemetryPlugin.startUp(), with the
	 * Filepath its own getPluginDirectory() returns -- never touched
	 * again for the lifetime of the client process. A plugin
	 * disable/re-enable cycle calls startUp() again, but
	 * getPluginDirectory() resolves to the exact same location every
	 * time (it depends only on RuneLite's own static PLUGIN_DATA
	 * directory and this plugin's fixed internalName), so re-calling
	 * init() on every startUp() is harmless and deliberately not
	 * guarded against.
	 */
	public static void init(Filepath pluginDirectory)
	{
		root = pluginDirectory;
	}

	private static Filepath root()
	{
		Filepath r = root;
		if (r == null)
		{
			throw new IllegalStateException("TelemetryPaths.init() must be called before any storage path is resolved.");
		}
		return r;
	}

	public static Filepath accountDir(long accountHash)
	{
		Filepath dir = root().joinSegment(Long.toString(accountHash));
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath stateFile(long accountHash, String category)
	{
		return accountDir(accountHash).joinSegment(category + ".json");
	}

	public static Filepath collectionLogDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("collection_log");
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath activitiesDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("activities");
		createDirectoriesQuietly(dir);
		return dir;
	}

	/**
	 * ADDED (Filepath migration audit): closes the one call site
	 * (ActivityKillCountCollector) that previously built this exact path
	 * itself via {@code activitiesDir(...).joinSegment(activityId + ".json")}
	 * instead of going through TelemetryPaths like every sibling file
	 * accessor here -- see the migration's file-I/O audit list.
	 */
	public static Filepath activityFile(long accountHash, String activityId)
	{
		return activitiesDir(accountHash).joinSegment(activityId + ".json");
	}

	/**
	 * Immutable historical bank snapshot -- never overwritten. The
	 * current-state bank.json (via stateFile) is a mutable pointer
	 * that references the latest snapshotId; this file, once written,
	 * is never touched again.
	 */
	public static Filepath bankSnapshotFile(long accountHash, String snapshotId)
	{
		return bankSnapshotsDir(accountHash).joinSegment(snapshotId + ".json");
	}

	/** The directory itself, for BankSnapshotRetention to list/prune. */
	public static Filepath bankSnapshotsDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("bank_snapshots");
		createDirectoriesQuietly(dir);
		return dir;
	}

	/**
	 * Single append-only file per account. Not split by day/session --
	 * at this data volume there is no need for log rotation.
	 */
	public static Filepath eventsFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("events.jsonl");
	}

	/**
	 * Mutable pointer to whatever session is currently in progress
	 * (ACTIVE or SUSPENDED) for this account. Overwritten on every
	 * lifecycle transition; never itself an append-only or historical
	 * record.
	 */
	public static Filepath sessionStateFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("session_state.json");
	}

	/**
	 * Directory of immutable, one-per-finalized-session records -- same
	 * role bank_snapshots/ plays for bank history.
	 */
	public static Filepath sessionsDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("sessions");
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath sessionFile(long accountHash, String sessionId)
	{
		return sessionsDir(accountHash).joinSegment(sessionId + ".json");
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A): the ONE
	 * additive, account-scoped persistence record for the interrupted/
	 * resumable prior session, if any -- see InterruptedCandidateRecord's
	 * own javadoc. Deliberately a small SEPARATE file rather than a
	 * change to session_state.json's own shape (a different plugin
	 * version, or an account that predates this feature, simply has no
	 * such file -- SessionPersistence treats that identically to "no
	 * candidate parked," never an error).
	 */
	public static Filepath interruptedCandidateFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("interrupted_candidate.json");
	}

	/**
	 * Mirrors the old File-based "mkdirs() if missing" convention --
	 * Filepath.createDirectories() is idempotent exactly like mkdirs()
	 * (a no-op success if the directory already exists), the one
	 * difference being that it can throw IOException where mkdirs()
	 * returned a boolean nobody checked. Logged and swallowed here
	 * rather than propagated: a directory that fails to create will
	 * surface anyway, immediately and more specifically, the moment a
	 * caller tries to write into it (see LocalStateStore's own warn
	 * logging on write failure) -- this is purely defensive, not a new
	 * failure mode.
	 */
	private static void createDirectoriesQuietly(Filepath dir)
	{
		try
		{
			dir.createDirectories();
		}
		catch (IOException e)
		{
			log.warn("Failed creating telemetry directory {}", dir, e);
		}
	}
}

package com.osrstelemetry.plugin.storage;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Writes state documents to disk.
 *
 * CORRECTNESS NOTE: write() serializes the document to a String synchronously,
 * on the calling thread, before returning. Only the cheap "write this
 * already-built String to a file" step happens on the background
 * executor. This guarantees the persisted document reflects exactly
 * the logical state at the moment write() was called, even if the
 * caller's collector goes on to mutate the same object afterward (e.g.
 * SkillsState.skills is a live map a collector keeps updating). Gson
 * serialization of these small documents is on the order of tens of
 * microseconds — cheap enough that doing it on the client thread is
 * the correct tradeoff (correctness over avoiding client-thread work),
 * per the project's own stated priority.
 *
 * LIFECYCLE NOTE: the executor is created in start() and torn down in
 * shutdown(), not in
 * the constructor — Guice creates this as a singleton once per client
 * process, but the plugin itself can be toggled on and off many times
 * within that process, and each toggle needs a live executor. Calling
 * write() before start() or after shutdown() is a caller bug, not a
 * state this class tries to paper over.
 *
 * SHUTDOWN IS NON-INTERRUPTING (Plugin Hub maintainer review): shutdown()
 * never forcibly terminates the executor or re-asserts this thread's own
 * interrupt status -- both are forms of thread interruption this
 * project's Plugin Hub review disallows outright. A write that is still
 * running when the graceful drain window elapses is left to finish on
 * its own, in the background, on its own (already-daemon) thread rather
 * than being forcibly interrupted -- see shutdown()'s own javadoc.
 */
@Slf4j
@Singleton
public class LocalStateStore
{
	private final Gson gson;
	private ExecutorService writeExecutor;

	/**
	 * @param injectedGson RuneLite's shared, DI-managed Gson. Derived
	 * (never replaced) via {@link Gson#newBuilder()} to add pretty-
	 * printing for these on-disk documents, per the terminal-API rule
	 * against ever constructing a fresh {@code Gson}/{@code GsonBuilder}
	 * of this class's own.
	 */
	@Inject
	public LocalStateStore(Gson injectedGson)
	{
		this.gson = injectedGson.newBuilder().setPrettyPrinting().create();
	}

	public synchronized void start()
	{
		if (writeExecutor != null && !writeExecutor.isShutdown())
		{
			return;
		}
		writeExecutor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-writer");
			t.setDaemon(true);
			return t;
		});
	}

	public void write(Filepath target, Object document)
	{
		write(target, document, () -> { });
	}

	/**
	 * onWritten only runs if the write actually succeeded — see
	 * writeNow()'s boolean return. This matters because a dependent
	 * write (e.g. a BANK_SNAPSHOT event) must never be triggered when
	 * its file never reached disk. A caller building a dependency chain
	 * (write A, then on success
	 * write B, then on success append an event) should nest calls to
	 * this method — each level only proceeds if the one before it
	 * actually succeeded.
	 */
	public void write(Filepath target, Object document, Runnable onWritten)
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("write() called while LocalStateStore is not started; dropping write to {}", target);
			return;
		}

		String json = gson.toJson(document);
		executor.submit(() ->
		{
			if (writeNow(target, json))
			{
				onWritten.run();
			}
		});
	}

	/**
	 * Blocking variant, used only where a caller genuinely needs to
	 * know a write finished (and whether it succeeded) before
	 * proceeding — currently just the shutdown-time bank-snapshot
	 * finalization (see ContainerCollector.flushPendingAndWait()).
	 * Ordinary collectors should use the async write() above; blocking
	 * on the calling thread is only acceptable here because it's used
	 * exclusively from the plugin's own shutDown(), never from an
	 * event handler on the client thread.
	 */
	public boolean writeAndWait(Filepath target, Object document, long timeoutMs)
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("writeAndWait() called while LocalStateStore is not started; dropping write to {}", target);
			return false;
		}

		String json = gson.toJson(document);
		java.util.concurrent.Future<Boolean> future = executor.submit(() -> writeNow(target, json));
		try
		{
			return future.get(timeoutMs, TimeUnit.MILLISECONDS);
		}
		catch (Exception e)
		{
			log.warn("writeAndWait timed out or failed for {}", target, e);
			return false;
		}
	}

	/** @return true if the file was successfully and durably written. */
	private boolean writeNow(Filepath target, String json)
	{
		Filepath tmp = target.getParent().joinSegment(target.getFileName() + ".tmp");
		try
		{
			tmp.write(json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("Failed writing telemetry state to {}", target, e);
			return false;
		}

		try
		{
			// ATOMIC_MOVE where the filesystem supports it (all major
			// filesystems on Linux/macOS; NTFS on Windows for
			// same-volume moves, which this always is since tmp and
			// target share a parent directory). Falls back to a
			// plain (non-atomic) replace only where the OS/filesystem
			// genuinely cannot do better.
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			return true;
		}
		catch (AtomicMoveNotSupportedException e)
		{
			try
			{
				tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
				return true;
			}
			catch (IOException e2)
			{
				log.warn("Non-atomic fallback move also failed for {}", target, e2);
				return false;
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to move {} into place at {}", tmp, target, e);
			return false;
		}
	}

	/**
	 * Graceful drain: stop accepting new work, wait briefly for
	 * queued writes to finish, and only log a warning if they don't --
	 * this never forcibly terminates the executor and never
	 * re-asserts this thread's own interrupt status if it is itself
	 * interrupted while waiting, per this project's Plugin Hub review
	 * requirement against any active thread interruption. A write that
	 * outlives the drain window keeps running to completion in the
	 * background on its own (already-daemon, so it can never keep the
	 * JVM alive) thread instead of being forcibly killed mid-write --
	 * a slower worst case than before, but one that can never leave a
	 * half-written file, and never interrupts I/O that may itself be
	 * mid-syscall.
	 */
	public void shutdown()
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("LocalStateStore writer did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the LocalStateStore writer; leaving it to keep draining in the background");
		}
	}

	/**
	 * Best-effort synchronous read. Added for the bank-snapshot
	 * deduplication feature (seeding an in-memory baseline from
	 * previously-persisted state) — not used by the write path at all.
	 *
	 * Returns null on ANY failure — missing file, malformed JSON, IO
	 * error — by design: this is a fail-open primitive. It does not
	 * depend on the write executor's started/shut-down state, since
	 * reads have no threading concerns of their own; it's the caller's
	 * responsibility to decide whether it's appropriate to call this
	 * from the client thread (see ContainerCollector's bank-baseline
	 * loading for why that's an accepted, bounded, one-time cost
	 * rather than something this method tries to offload itself).
	 */
	public <T> T readIfExists(Filepath file, Class<T> type)
	{
		if (!file.exists())
		{
			return null;
		}
		try (InputStream in = file.openInputStream())
		{
			String json = new String(in.readAllBytes(), StandardCharsets.UTF_8);
			return gson.fromJson(json, type);
		}
		catch (Exception e)
		{
			log.warn("Failed reading {}; treating as absent (fail-open)", file, e);
			return null;
		}
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.Session;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.time.ZoneId;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * The top-level component wired into {@code OsrsTelemetryPanel}'s own
 * Session/Loot/History tab row as the single "History" card -- owns its
 * OWN internal {@link CardLayout} switching between a recent-sessions
 * LIST card and a {@link HistoryDetailView} DETAIL card, so
 * {@code OsrsTelemetryPanel} itself never needs to know History has any
 * internal navigation at all (it only ever sees one component, exactly
 * like {@code CurrentSessionView}/{@code LootTrackerView}).
 *
 * ARCHITECTURE (matches CurrentSessionView's own established pattern):
 * this class has NO reference to {@code HistoryCoordinator} -- it is
 * handed already-built {@link HistoryEntry} summaries via {@link #render}
 * (called on every poll tick, same cadence and off-EDT-safe cheap read
 * as every other tab -- see {@code HistoryCoordinator#getRecentEntries()}'s
 * own javadoc) and reports "the player opened this session" purely via
 * the constructor-supplied {@code onEntryOpened} callback, exactly the
 * same opaque-Runnable/Consumer shape {@code CurrentSessionView}'s
 * "Re-evaluate Session" button already uses. {@code OsrsTelemetryPanel}
 * is the only class that actually calls
 * {@code HistoryCoordinator.loadDetail(...)}, and it does so entirely
 * off this class's own knowledge -- see that class's own wiring.
 *
 * LAZY DETAIL LOADING: clicking a row does NOT eagerly
 * pre-fetch anything -- it calls {@code onEntryOpened} once, which
 * triggers exactly one background {@code loadDetail()} call in
 * {@code OsrsTelemetryPanel}. {@link #showDetailLoading} is shown
 * immediately (so the click feels responsive even though the real
 * detail read is asynchronous), then {@link #showDetail}/
 * {@link #showDetailUnavailable} replaces it once that background read
 * completes and is marshalled back onto the EDT by the caller.
 *
 * RENDER-KEY SKIP (list card only -- mirrors LootTrackerView's own
 * mechanism): a poll tick whose entry set is identical to what is
 * already on screen (same session ids, same order) is a pure string
 * comparison, no Swing tree rebuild.
 *
 * NO OWN JScrollPane -- see CurrentSessionView/LootTrackerView's own
 * SCROLLING notes; RuneLite's outer sidebar scrollpane does all
 * scrolling for both the list and detail cards here too.
 *
 * VISUAL DIRECTION: the list card is a flat, dark
 * {@link SpyglassTheme#BACKGROUND_MAIN} background, matching
 * {@link OsrsTelemetryPanel}'s dark-bronze tab header above it. Row
 * chrome, text colors, and hover feedback all draw from the same
 * shared {@link SpyglassTheme} palette (a warm
 * {@link SpyglassTheme#SURFACE_CARD} card face, {@link SpyglassTheme#BORDER_SOFT}
 * border, {@link SpyglassTheme#TEXT_PRIMARY}/{@link SpyglassTheme#TEXT_SECONDARY}
 * text, lifting to {@link SpyglassTheme#SURFACE_RAISED}/{@link SpyglassTheme#BORDER_PRIMARY}
 * on hover).
 *
 * VERTICAL STRETCH: {@link #buildRow} deliberately does NOT declare an
 * unbounded {@code Short.MAX_VALUE} maximum height -- that pattern is
 * what causes a BoxLayout row to stretch once its CardLayout card
 * becomes the tallest of the three tabs (see LootTrackerView's own
 * {@code heightBoundedPanel} javadoc for the full root-cause writeup);
 * {@link #heightBoundedPanel} is the guard against it.
 */
final class HistoryView extends JPanel
{
	private static final String CARD_LIST = "list";
	private static final String CARD_DETAIL = "detail";

	private final Consumer<String> onEntryOpened;

	private final CardLayout cardLayout = new CardLayout();
	private final JPanel cards = new JPanel(cardLayout);
	private final JPanel listContent = new JPanel();
	private final HistoryDetailView detailView;

	private String lastRenderKey;

	HistoryView(SkillIconManager skillIconManager, ItemManager itemManager, ClientThread clientThread, OsrsTelemetryConfig config, Consumer<String> onEntryOpened)
	{
		this.onEntryOpened = onEntryOpened;

		setLayout(new BorderLayout());
		setBackground(SpyglassTheme.BACKGROUND_MAIN);

		listContent.setLayout(new BoxLayout(listContent, BoxLayout.Y_AXIS));
		listContent.setBackground(SpyglassTheme.BACKGROUND_MAIN);
		listContent.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		this.detailView = new HistoryDetailView(skillIconManager, itemManager, clientThread, config, () -> cardLayout.show(cards, CARD_LIST));

		cards.add(listContent, CARD_LIST);
		cards.add(detailView, CARD_DETAIL);
		add(cards, BorderLayout.CENTER);

		render(java.util.Collections.emptyList());
	}

	/** Called on every poll tick (see class javadoc) -- cheap, off-EDT-free, skips rebuilding when nothing changed. */
	void render(List<HistoryEntry> entries)
	{
		String key = computeRenderKey(entries);
		if (key.equals(lastRenderKey))
		{
			return;
		}
		lastRenderKey = key;

		listContent.removeAll();

		if (entries.isEmpty())
		{
			renderEmptyState();
		}
		else
		{
			for (HistoryEntry entry : entries)
			{
				listContent.add(buildRow(entry));
				listContent.add(Box.createVerticalStrut(6));
			}
		}

		listContent.revalidate();
		listContent.repaint();
	}

	/** Package-private, pure, testable -- see LootTrackerView.computeRenderKey()'s own javadoc for why this pattern exists. */
	static String computeRenderKey(List<HistoryEntry> entries)
	{
		StringBuilder key = new StringBuilder(entries.size() * 24);
		for (HistoryEntry entry : entries)
		{
			key.append(entry.getSessionId()).append('|').append(entry.getFinalizedAt()).append('\n');
		}
		return key.toString();
	}

	/** Immediately switches to the detail card showing a loading placeholder -- see class javadoc's LAZY DETAIL LOADING note. */
	void showDetailLoading()
	{
		detailView.showLoading();
		cardLayout.show(cards, CARD_DETAIL);
	}

	/** Called once OsrsTelemetryPanel's background loadDetail() call completes with a real Session. */
	void showDetail(Session session)
	{
		HistoryDetailModel model = HistoryDetailModel.from(session);
		if (model == null)
		{
			showDetailUnavailable();
			return;
		}
		detailView.render(model);
		cardLayout.show(cards, CARD_DETAIL);
	}

	/** Called when loadDetail() failed or returned a malformed/missing session -- see HistoryDetailModel.from()'s fail-open contract. */
	void showDetailUnavailable()
	{
		detailView.showUnavailable();
		cardLayout.show(cards, CARD_DETAIL);
	}

	private void renderEmptyState()
	{
		JLabel title = new JLabel("No completed sessions yet");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(SpyglassTheme.TEXT_PRIMARY);
		title.setAlignmentX(Component.CENTER_ALIGNMENT);

		// Wraps to the ACTUAL available width -- see WrappingHtmlLabel's
		// javadoc (the old fixed CSS width:180px was ~233px in Swing and clipped).
		JLabel subtitle = new WrappingHtmlLabel("Finalized sessions from the last 10 days will appear here.", true);
		subtitle.setFont(FontManager.getRunescapeSmallFont());
		subtitle.setForeground(SpyglassTheme.TEXT_SECONDARY);
		subtitle.setAlignmentX(Component.CENTER_ALIGNMENT);

		listContent.add(Box.createVerticalStrut(24));
		listContent.add(title);
		listContent.add(Box.createVerticalStrut(6));
		listContent.add(subtitle);
	}

	/**
	 * See this class's own javadoc VERTICAL STRETCH note and
	 * LootTrackerView's {@code heightBoundedPanel()} for the full
	 * root-cause writeup. A plain {@code JPanel} whose maximum height always equals its own
	 * current preferred height, so a BoxLayout parent with more height
	 * to give away than this row actually needs can never stretch it.
	 *
	 * Package-private (not {@code private}) so {@code HistoryViewTest}
	 * can directly regression-test its dynamic-height behavior -- same
	 * convention {@code LootTrackerViewTest} already establishes for its
	 * own equivalent factory.
	 */
	static JPanel heightBoundedPanel(LayoutManager layout)
	{
		return new JPanel(layout)
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
	}

	private JPanel buildRow(HistoryEntry entry)
	{
		JPanel row = heightBoundedPanel(new BorderLayout(6, 2));
		row.setOpaque(true);
		row.setBackground(SpyglassTheme.SURFACE_CARD);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(rowBorder(SpyglassTheme.BORDER_SOFT));
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		ActivityIdentity identity = entry.getActivityIdentity();
		String headline = identity == null || identity.getDisplayName() == null ? "Unknown activity" : identity.getDisplayName();

		JPanel textColumn = new JPanel();
		textColumn.setLayout(new BoxLayout(textColumn, BoxLayout.Y_AXIS));
		textColumn.setOpaque(false);

		JLabel headlineLabel = new JLabel(headline);
		headlineLabel.setFont(FontManager.getRunescapeBoldFont());
		headlineLabel.setForeground(SpyglassTheme.TEXT_PRIMARY);
		headlineLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		textColumn.add(headlineLabel);

		StringBuilder secondary = new StringBuilder();
		String when = formatRelativeOrAbsolute(entry.getFinalizedAt());
		if (when != null)
		{
			secondary.append(when);
		}
		secondary.append("   •   ").append(formatDuration(entry.getAccumulatedActiveDurationMillis()));
		if (entry.getTotalXpGained() > 0)
		{
			secondary.append("   •   ").append(formatNumber(entry.getTotalXpGained())).append(" XP");
		}
		if (entry.getLootDropCount() > 0)
		{
			secondary.append("   •   ").append(entry.getLootDropCount()).append(entry.getLootDropCount() == 1 ? " drop" : " drops");
		}
		JLabel secondaryLabel = new JLabel(secondary.toString());
		secondaryLabel.setFont(FontManager.getRunescapeSmallFont());
		secondaryLabel.setForeground(SpyglassTheme.TEXT_SECONDARY);
		secondaryLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		textColumn.add(secondaryLabel);

		row.add(textColumn, BorderLayout.CENTER);

		JLabel chevron = new JLabel("›");
		chevron.setFont(FontManager.getRunescapeBoldFont());
		chevron.setForeground(SpyglassTheme.TEXT_MUTED);
		row.add(chevron, BorderLayout.EAST);

		String sessionId = entry.getSessionId();
		row.addMouseListener(new ClickListener(() ->
		{
			showDetailLoading();
			if (onEntryOpened != null)
			{
				onEntryOpened.accept(sessionId);
			}
		}));

		// Raised-surface hover feedback (background AND border lift
		// together) while the cursor is over a row, reverting to the
		// row's normal card colors on exit. A second, separate
		// MouseListener on the same row -- purely
		// visual, does not affect the click behavior registered above.
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(SpyglassTheme.SURFACE_RAISED);
				row.setBorder(rowBorder(SpyglassTheme.BORDER_PRIMARY));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(SpyglassTheme.SURFACE_CARD);
				row.setBorder(rowBorder(SpyglassTheme.BORDER_SOFT));
			}
		});

		return row;
	}

	/** Small shared helper -- the row card's compound border (colored line + inner padding), reused for both its normal and hover states (see {@link #buildRow}) so the two never drift out of sync with each other. */
	private static javax.swing.border.Border rowBorder(java.awt.Color lineColor)
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(lineColor),
			BorderFactory.createEmptyBorder(6, 8, 6, 8));
	}

	private static String formatNumber(long value)
	{
		return String.format("%,d", value);
	}

	private static String formatDuration(long millis)
	{
		long totalSeconds = millis / 1000L;
		long hours = totalSeconds / 3600L;
		long minutes = (totalSeconds % 3600L) / 60L;
		long seconds = totalSeconds % 60L;
		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, seconds);
		}
		return String.format("%d:%02d", minutes, seconds);
	}

	/** Best-effort; returns null (never throws) on anything unparseable so a malformed timestamp never blanks out the row. */
	private static String formatRelativeOrAbsolute(String isoInstant)
	{
		if (isoInstant == null)
		{
			return null;
		}
		try
		{
			Instant instant = Instant.parse(isoInstant);
			return DateTimeFormatter.ofLocalizedDateTime(FormatStyle.MEDIUM, FormatStyle.SHORT)
				.withZone(ZoneId.systemDefault())
				.format(instant);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Mirrors LootTrackerView's own private ClickListener -- see that class's javadoc. */
	private static final class ClickListener extends MouseAdapter
	{
		private final Runnable action;

		ClickListener(Runnable action)
		{
			this.action = action;
		}

		@Override
		public void mouseClicked(MouseEvent e)
		{
			action.run();
		}
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.collectors.NpcInteractionTargetCollector;
import com.osrstelemetry.plugin.history.HistoryCoordinator;
import com.osrstelemetry.plugin.loottracker.LootTrackerCoordinator;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionRuntimeCoordinator;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import com.osrstelemetry.plugin.ui.model.LootTrackerSnapshot;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The top-level sidebar panel: a compact three-way tab row (Session /
 * Loot / History) over a {@link CardLayout} content area. Current
 * Session is the default/home view.
 *
 * NAVIGATION PATTERN: a plain {@code JPanel} of three flat, borderless
 * {@code JButton}s directly swapping a {@code CardLayout}'s visible
 * card -- the same "simple compact tab-like row of buttons" pattern
 * many real RuneLite multi-view sidebar plugins use, chosen over
 * {@code MaterialTabGroup} since plain Swing components carry no
 * dependency-version risk and are equally standard RuneLite-plugin
 * practice.
 *
 * LIVE UPDATES: a single {@code javax.swing.Timer} (NOT a raw
 * {@code java.util.Timer}/thread) polls roughly once per second, on
 * the EDT (a Swing {@code Timer}'s
 * listener always runs there), and rebuilds a fresh
 * {@link CurrentSessionSnapshot} from whatever
 * {@link SessionRuntimeCoordinator#getCurrentSessionSnapshot()} returns at
 * that instant. The read itself is cheap (a handful of getter calls
 * into a synchronized accessor -- see that method's own javadoc) and
 * never touches the RuneLite client thread; nothing here blocks it.
 * {@link #shutdown()} stops this timer -- it MUST be called from
 * {@code OsrsTelemetryPlugin.shutDown()} so a disabled/re-enabled
 * plugin never accumulates a second live timer.
 */
public final class OsrsTelemetryPanel extends PluginPanel
{
	private static final int POLL_INTERVAL_MILLIS = 1000;

	private final SessionRuntimeCoordinator sessionRuntimeCoordinator;
	// Read fresh on every poll tick, same cadence as the Current Session
	// snapshot -- see LootTrackerCoordinator's own javadoc for why its index
	// reference can change (a background rebuild populating it
	// progressively, or an account switch installing a fresh one).
	private final LootTrackerCoordinator lootTrackerCoordinator;
	private final LootTrackerPreferences lootTrackerPreferences;
	// The live source of "which
	// attackable NPC is the player currently targeting" -- read fresh on
	// every poll tick, same cadence as the session snapshot itself. See
	// NpcInteractionTargetCollector#getCurrentNpcName()/getCurrentNpcId().
	private final NpcInteractionTargetCollector npcInteractionTargetCollector;
	// Read fresh on every poll tick for the cheap recent-entries list (see
	// HistoryCoordinator#getRecentEntries()'s own "never blocks" contract)
	// and invoked directly (off the poll cadence) for a lazy detail load
	// the instant a History row is actually clicked -- see historyView's
	// onEntryOpened callback below.
	private final HistoryCoordinator historyCoordinator;
	private final CurrentSessionView currentSessionView;
	private final LootTrackerView lootTrackerView;
	private final HistoryView historyView;
	private final CardLayout cardLayout = new CardLayout();
	private final JPanel cards = new JPanel(cardLayout);
	private final Timer pollTimer;

	private JButton sessionTabButton;
	private JButton lootTabButton;
	private JButton historyTabButton;
	// Tracked so a tab button's
	// MouseAdapter hover handler (see tabButton()) can tell, on mouseExited,
	// whether to revert to the selected or unselected style -- see
	// styleTabButton(). Set explicitly in the constructor (not here) to
	// avoid a forward reference to the CARD_SESSION constant declared
	// further down this class.
	private String activeCard;

	private static final String CARD_SESSION = "session";
	private static final String CARD_LOOT = "loot";
	private static final String CARD_HISTORY = "history";

	public OsrsTelemetryPanel(
		SessionRuntimeCoordinator sessionRuntimeCoordinator,
		LootTrackerCoordinator lootTrackerCoordinator,
		LootTrackerPreferences lootTrackerPreferences,
		HistoryCoordinator historyCoordinator,
		SkillIconManager skillIconManager,
		ItemManager itemManager,
		ClientThread clientThread,
		NpcInteractionTargetCollector npcInteractionTargetCollector,
		OsrsTelemetryConfig config)
	{
		this.sessionRuntimeCoordinator = sessionRuntimeCoordinator;
		this.lootTrackerCoordinator = lootTrackerCoordinator;
		this.lootTrackerPreferences = lootTrackerPreferences;
		this.historyCoordinator = historyCoordinator;
		this.npcInteractionTargetCollector = npcInteractionTargetCollector;
		// The "Re-evaluate
		// Session" button's ENTIRE backend action, built here (where both
		// sessionRuntimeCoordinator and npcInteractionTargetCollector are
		// already available) and handed to CurrentSessionView as a single
		// opaque Runnable -- see that class's own onReEvaluateRequested
		// field javadoc for why it must never see either reference
		// directly. Reads the live current NPC target at the moment the
		// button is actually processed (inside the ClientThread.invokeLater()
		// dispatch, not before) -- getCurrentNpcName()/getCurrentNpcId()
		// are documented safe off the client thread, so reading them here
		// is fine too, but reading them at the point of use keeps this as
		// close to "look at what I am doing RIGHT NOW" as possible. The
		// invokeLater() call itself returns immediately -- this Runnable
		// never blocks whatever thread invokes it (the EDT, via
		// CurrentSessionView's button ActionListener).
		Runnable reEvaluateAction = () -> clientThread.invokeLater(() ->
			sessionRuntimeCoordinator.reEvaluateCurrentSession(
				npcInteractionTargetCollector.getCurrentNpcName(),
				npcInteractionTargetCollector.getCurrentNpcId(),
				Instant.now()));
		this.currentSessionView = new CurrentSessionView(skillIconManager, itemManager, clientThread, config, reEvaluateAction);
		this.lootTrackerView = new LootTrackerView(itemManager, clientThread, config, lootTrackerPreferences);
		// See HistoryView's own class javadoc for why it needs no direct
		// HistoryCoordinator reference -- onEntryOpened here is the ENTIRE
		// bridge: a lazy, off-EDT loadDetail() call whose result is
		// marshalled back onto the EDT (SwingUtilities.invokeLater()) before
		// touching historyView's Swing state, the same obligation every
		// other background-thread callback in this codebase already
		// carries (see HistoryCoordinator.loadDetail()'s own javadoc).
		this.historyView = new HistoryView(skillIconManager, itemManager, clientThread, config, sessionId ->
			historyCoordinator.loadDetail(sessionId, session ->
				SwingUtilities.invokeLater(() -> showHistoryDetail(session))));

		setLayout(new BorderLayout());

		add(buildTabRow(), BorderLayout.NORTH);

		cards.add(currentSessionView, CARD_SESSION);
		cards.add(lootTrackerView, CARD_LOOT);
		cards.add(historyView, CARD_HISTORY);
		add(cards, BorderLayout.CENTER);

		selectTab(CARD_SESSION);

		pollTimer = new Timer(POLL_INTERVAL_MILLIS, e -> refreshCurrentSession());
		pollTimer.setRepeats(true);
		pollTimer.start();

		// Populate immediately rather than waiting for the first tick.
		refreshCurrentSession();
	}

	/**
	 * Routes the History detail-load callback through this instance
	 * method instead of letting the constructor's lambda capture the
	 * {@code historyView} field directly inside that field's own
	 * initializer expression above. javac's definite-assignment
	 * analysis forbids reading a field from within a lambda that is
	 * part of that same field's own initializer -- even though the
	 * lambda itself only ever runs long after construction has
	 * finished (it fires from an async {@code HistoryCoordinator}
	 * callback, marshalled back onto the EDT). This method is never
	 * invoked until after the constructor returns, so {@code
	 * historyView} is always assigned by the time it runs.
	 */
	private void showHistoryDetail(Session session)
	{
		historyView.showDetail(session);
	}

	/**
	 * A plain flat {@link SpyglassTheme#BACKGROUND_PANEL} bar with a thin
	 * {@link SpyglassTheme#BORDER_SOFT} line along the bottom edge --
	 * same compact height, same Session/Loot/History button row, no
	 * gradient/scroll treatment of any kind (avoid gradients that make
	 * the header louder than the content). Applies
	 * identically regardless of which tab is active, so switching tabs
	 * stays visually cohesive -- see {@link #styleTabButton} for the
	 * dark-bronze selected/unselected/hover button colors.
	 */
	private JPanel buildTabRow()
	{
		// Player-facing order/labels: Session | Loot | History.
		JPanel row = new JPanel(new GridLayout(1, 3, 2, 0));
		row.setBackground(SpyglassTheme.BACKGROUND_PANEL);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, SpyglassTheme.BORDER_SOFT),
			BorderFactory.createEmptyBorder(4, 4, 3, 4)));

		sessionTabButton = tabButton("Session", CARD_SESSION);
		lootTabButton = tabButton("Loot", CARD_LOOT);
		historyTabButton = tabButton("History", CARD_HISTORY);

		row.add(sessionTabButton);
		row.add(lootTabButton);
		row.add(historyTabButton);
		return row;
	}

	private JButton tabButton(String text, String cardName)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		// Each tab paints a thin border (see styleTabButton()) rather
		// than none at all.
		button.setBorderPainted(true);
		button.setOpaque(true);
		button.setMargin(new java.awt.Insets(2, 2, 2, 2));
		button.addActionListener(e -> selectTab(cardName));
		// Restrained hover feedback. Purely visual: does not affect the
		// click behavior above, and
		// mouseExited always re-derives the correct resting style from
		// whichever tab is actually active (see styleTabButton()) rather
		// than assuming this button's own prior state.
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (!cardName.equals(activeCard))
				{
					button.setBackground(SpyglassTheme.SURFACE_RAISED);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				styleTabButton(button, cardName.equals(activeCard));
			}
		});
		return button;
	}

	private void selectTab(String cardName)
	{
		activeCard = cardName;
		cardLayout.show(cards, cardName);
		styleTabButton(sessionTabButton, CARD_SESSION.equals(cardName));
		styleTabButton(lootTabButton, CARD_LOOT.equals(cardName));
		styleTabButton(historyTabButton, CARD_HISTORY.equals(cardName));
	}

	/**
	 * INACTIVE: {@link SpyglassTheme#BACKGROUND_PANEL} fill,
	 * {@link SpyglassTheme#TEXT_SECONDARY} text, a subtle
	 * {@link SpyglassTheme#BORDER_SOFT} border. SELECTED: a slightly
	 * brighter {@link SpyglassTheme#SURFACE_RAISED} fill, strong
	 * {@link SpyglassTheme#ACCENT_GOLD} text, a stronger
	 * {@link SpyglassTheme#BORDER_PRIMARY} border -- unmistakably
	 * selected, and never a fully-gold fill (gold is reserved for text
	 * emphasis, never the default).
	 */
	private void styleTabButton(JButton button, boolean selected)
	{
		if (button == null)
		{
			return;
		}
		button.setBackground(selected ? SpyglassTheme.SURFACE_RAISED : SpyglassTheme.BACKGROUND_PANEL);
		button.setForeground(selected ? SpyglassTheme.ACCENT_GOLD : SpyglassTheme.TEXT_SECONDARY);
		button.setBorder(BorderFactory.createLineBorder(selected ? SpyglassTheme.BORDER_PRIMARY : SpyglassTheme.BORDER_SOFT));
	}

	private void refreshCurrentSession()
	{
		// This runs on the EDT (Timer listener), never the RuneLite
		// client thread -- see class javadoc's LIVE UPDATES note. The
		// current NPC target is read fresh here too, same cadence as
		// everything else -- see
		// npcInteractionTargetCollector's own field javadoc.
		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(
			sessionRuntimeCoordinator.getCurrentSessionSnapshot(),
			Instant.now(),
			npcInteractionTargetCollector.getCurrentNpcName(),
			npcInteractionTargetCollector.getCurrentNpcId());
		currentSessionView.render(snapshot);

		// Same cadence, same EDT -- LootTrackerCoordinator#getIndex()/
		// LootTrackerPreferences are both cheap, non-blocking, in-memory
		// reads (see their own class javadocs), same as
		// sessionRuntimeCoordinator.getCurrentSessionSnapshot() above.
		LootTrackerSnapshot lootTrackerSnapshot = LootTrackerSnapshot.from(lootTrackerCoordinator.getIndex(), lootTrackerPreferences);
		lootTrackerView.render(lootTrackerSnapshot);

		// Same cadence, same EDT -- HistoryCoordinator#getRecentEntries() never
		// blocks (returns a cached snapshot and kicks off its own background
		// refresh -- see that method's own javadoc), so this is exactly as
		// cheap as the two reads above it. historyView.render() itself
		// additionally skips any Swing rebuild when the entry set is
		// unchanged from what's already on screen (its own render-key
		// mechanism), so a steady-state tick with no newly-finalized session
		// costs one list comparison, nothing more.
		historyView.render(historyCoordinator.getRecentEntries());
	}

	/**
	 * Stops the live-update timer. Must be called from
	 * {@code OsrsTelemetryPlugin.shutDown()} -- see class javadoc.
	 */
	public void shutdown()
	{
		if (pollTimer.isRunning())
		{
			pollTimer.stop();
		}
	}
}

package com.osrstelemetry.plugin.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/**
 * A shared top-level {@code ui}-package class so LootTrackerView can
 * render item cells IDENTICALLY to Current Session's own loot grid
 * instead of duplicating this widget a second time.
 *
 * A single fixed-size loot slot: the authentic item sprite (always
 * {@link ItemManager#getImage(int)} via the caller -- never a
 * placeholder/fake icon) centered in a bank/inventory-style bordered
 * cell, with the stack quantity painted directly on top, and a hover
 * tooltip carrying the full item/value detail.
 */
final class LootGridCell extends JPanel
{
	private static final int CELL_SIZE = 40;

	/**
	 * SHARED LOOT-GRID GEOMETRY -- the one column count/gap every loot
	 * item grid (Current Session's LOOT card and the Loot tab's Grouped
	 * AND Individual source cards) builds its {@link GridLayout} from, via
	 * {@link #newGridLayout()}, so the two surfaces can never drift apart
	 * again. {@code GridLayout} divides the ACTUAL available width evenly
	 * among its columns -- CELL_SIZE is only each cell's preferred size,
	 * not a floor -- so at the normal sidebar width a 5-column grid
	 * renders ~33px cells (exactly what Current Session has always
	 * shown), and a narrower/wider container shrinks/grows the cells
	 * rather than clipping or scrolling horizontally.
	 */
	static final int GRID_COLUMNS = 5;

	/** Horizontal and vertical gap between cells, in pixels. */
	static final int GRID_GAP = 4;

	/** A fresh layout per grid (LayoutManagers are not shared between containers). */
	static GridLayout newGridLayout()
	{
		return new GridLayout(0, GRID_COLUMNS, GRID_GAP, GRID_GAP);
	}

	private final AsyncBufferedImage icon;
	private final String quantityText;
	private final Color quantityColor;

	LootGridCell(AsyncBufferedImage icon, long quantity, String tooltip)
	{
		this.icon = icon;
		this.quantityText = quantity > 1 ? QuantityFormatter.quantityToStackSize(quantity) : null;
		this.quantityColor = stackColor(quantity);
		setPreferredSize(new Dimension(CELL_SIZE, CELL_SIZE));
		// Background/border use SpyglassTheme's shared chrome tokens
		// rather than local color literals, so this cell never drifts
		// from the rest of the plugin's palette. The item sprite and the
		// per-stack-size quantity color below (see stackColor()) are
		// semantic/authentic-OSRS colors, not chrome, and stay local.
		setBackground(SpyglassTheme.BACKGROUND_PANEL);
		setBorder(BorderFactory.createLineBorder(SpyglassTheme.BORDER_SOFT));
		setToolTipText(tooltip);
		if (icon != null)
		{
			// The sprite loads asynchronously -- repaint once RuneLite
			// finishes decoding it, exactly like AsyncBufferedImage's own
			// addTo(JLabel) convenience does internally.
			icon.onLoaded(this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (icon != null)
		{
			int x = (getWidth() - icon.getWidth()) / 2;
			int y = (getHeight() - icon.getHeight()) / 2;
			g.drawImage(icon, x, y, null);
		}
		if (quantityText != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(Color.BLACK);
			// Four-offset outline (not one) -- legible over any sprite,
			// even a bright/busy backdrop that would wash out a single
			// shadow offset.
			g.drawString(quantityText, 2, 11);
			g.drawString(quantityText, 4, 11);
			g.drawString(quantityText, 2, 13);
			g.drawString(quantityText, 4, 13);
			g.setColor(quantityColor);
			g.drawString(quantityText, 3, 12);
		}
	}

	private static Color stackColor(long quantity)
	{
		if (quantity >= 10_000_000L)
		{
			return new Color(80, 220, 90);
		}
		if (quantity >= 100_000L)
		{
			return new Color(255, 193, 37);
		}
		return new Color(255, 224, 130);
	}

	/** Shared clamp -- ItemManager#getImage()'s quantity argument is an int; a loot total can exceed Integer.MAX_VALUE in extreme cases. */
	static int clampToInt(long value)
	{
		return (int) Math.max(1, Math.min(value, Integer.MAX_VALUE));
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.LoadoutSnapshot;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionAggregates;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;

/**
 * The pure, Swing-free transform from one finalized {@link Session} (as
 * read back by {@code HistoryCoordinator.loadDetail()}) into the
 * display-ready shape {@link HistoryDetailView} actually renders -- the
 * same runtime-&gt;snapshot-&gt;view split {@code CurrentSessionSnapshot}/
 * {@code LootTrackerSnapshot} already establish for the other two tabs.
 * Package-private, living beside {@link HistoryDetailView}.
 *
 * DELIBERATELY DOES NOT COMPUTE LEVEL-PROGRESS BARS THE WAY
 * {@code CurrentSessionSnapshot.XpEntry} DOES: a live session knows the
 * player's CURRENT absolute XP (via {@code LiveXpTracker}), so it can
 * compute "63% to level 97". A finalized History session's
 * {@link SessionAggregates#getXpGainedBySkill()} only ever stored a
 * DELTA (XP gained while this session was active), never an absolute
 * total -- there is no absolute XP value on disk to compute a level or
 * a progress percentage from. Fabricating one would violate this
 * project's consistent "never invent what the data does not actually
 * support" rule (see e.g. {@code LoadoutProvenance}'s own honest-labeling
 * design, or {@code CurrentSessionView}'s NPC-imagery section). XP
 * breakdown here is therefore skill + XP gained only, sorted by XP
 * gained descending -- still real skill icons, still real numbers,
 * just no invented level/progress figure.
 *
 * LOOT: every {@link SessionAggregates.LootDropGroup}'s items are
 * flattened and summed by item id across the WHOLE session (a
 * "session-owned loot" total, not per-drop-group rows) -- the same
 * total-stack-value-driven presentation {@code CurrentSessionView}'s own
 * loot section already uses via {@link LootPricing}, reused here
 * unchanged. {@link #getLootDropCount()} mirrors
 * {@code HistoryEntry.getLootDropCount()}'s own definition (number of
 * drop GROUPS/events observed, not summed item count).
 */
final class HistoryDetailModel
{
	@Getter
	static final class XpRow
	{
		private final String skill;
		private final long xpGained;

		XpRow(String skill, long xpGained)
		{
			this.skill = skill;
			this.xpGained = xpGained;
		}
	}

	@Getter
	static final class LootRow implements LootPricing.Priceable
	{
		private final Integer itemId;
		private final String itemName;
		private final long quantity;

		LootRow(Integer itemId, String itemName, long quantity)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
		}
	}

	private final String sessionId;
	private final ActivityIdentity activityIdentity;
	private final String startedAt;
	private final String finalizedAt;
	private final long accumulatedActiveDurationMillis;
	private final List<XpRow> xpRows;
	private final long totalXpGained;
	private final List<LootRow> lootRows;
	private final int lootDropCount;
	private final SessionAggregates.ReliableCount reliableCount;
	private final LoadoutSnapshot startingLoadout;
	private final LoadoutSnapshot endingLoadout;

	private HistoryDetailModel(String sessionId, ActivityIdentity activityIdentity, String startedAt, String finalizedAt,
		long accumulatedActiveDurationMillis, List<XpRow> xpRows, long totalXpGained, List<LootRow> lootRows,
		int lootDropCount, SessionAggregates.ReliableCount reliableCount, LoadoutSnapshot startingLoadout, LoadoutSnapshot endingLoadout)
	{
		this.sessionId = sessionId;
		this.activityIdentity = activityIdentity;
		this.startedAt = startedAt;
		this.finalizedAt = finalizedAt;
		this.accumulatedActiveDurationMillis = accumulatedActiveDurationMillis;
		this.xpRows = xpRows;
		this.totalXpGained = totalXpGained;
		this.lootRows = lootRows;
		this.lootDropCount = lootDropCount;
		this.reliableCount = reliableCount;
		this.startingLoadout = startingLoadout;
		this.endingLoadout = endingLoadout;
	}

	String getSessionId()
	{
		return sessionId;
	}

	ActivityIdentity getActivityIdentity()
	{
		return activityIdentity;
	}

	String getStartedAt()
	{
		return startedAt;
	}

	String getFinalizedAt()
	{
		return finalizedAt;
	}

	long getAccumulatedActiveDurationMillis()
	{
		return accumulatedActiveDurationMillis;
	}

	List<XpRow> getXpRows()
	{
		return xpRows;
	}

	long getTotalXpGained()
	{
		return totalXpGained;
	}

	List<LootRow> getLootRows()
	{
		return lootRows;
	}

	int getLootDropCount()
	{
		return lootDropCount;
	}

	SessionAggregates.ReliableCount getReliableCount()
	{
		return reliableCount;
	}

	/** Never null -- callers must check {@code getProvenance() == UNAVAILABLE} rather than null-check this. See LoadoutSnapshot#unavailable(). */
	LoadoutSnapshot getStartingLoadout()
	{
		return startingLoadout;
	}

	/** Never null -- see {@link #getStartingLoadout()}. */
	LoadoutSnapshot getEndingLoadout()
	{
		return endingLoadout;
	}

	/**
	 * Fail-open, same contract as {@code HistoryEntry.from()}: returns
	 * null for a null or structurally-incomplete session rather
	 * than throwing, so a single malformed/unexpected finalized session
	 * file can never crash the History detail view -- the caller (see
	 * {@code HistoryDetailView#showUnavailable()}) renders an explicit
	 * "could not be loaded" state instead.
	 */
	static HistoryDetailModel from(Session session)
	{
		if (session == null || session.getSessionId() == null || session.getActivityIdentity() == null)
		{
			return null;
		}

		SessionAggregates aggregates = session.getAggregates();

		List<XpRow> xpRows = new ArrayList<>();
		long totalXp = 0L;
		if (aggregates != null && aggregates.getXpGainedBySkill() != null)
		{
			for (Map.Entry<String, Long> entry : aggregates.getXpGainedBySkill().entrySet())
			{
				long xp = entry.getValue() == null ? 0L : entry.getValue();
				if (xp <= 0L)
				{
					continue;
				}
				xpRows.add(new XpRow(entry.getKey(), xp));
				totalXp += xp;
			}
		}
		xpRows.sort(Comparator.comparingLong(XpRow::getXpGained).reversed());

		Map<Integer, LootRow> loot = new LinkedHashMap<>();
		int lootDropCount = 0;
		if (aggregates != null && aggregates.getLootDrops() != null)
		{
			lootDropCount = aggregates.getLootDrops().size();
			for (SessionAggregates.LootDropGroup group : aggregates.getLootDrops())
			{
				if (group.getItems() == null)
				{
					continue;
				}
				for (SessionAggregates.LootItemAggregate item : group.getItems())
				{
					if (item.getItemId() == null)
					{
						continue;
					}
					LootRow existing = loot.get(item.getItemId());
					long newQuantity = (existing == null ? 0L : existing.getQuantity()) + item.getQuantity();
					loot.put(item.getItemId(), new LootRow(item.getItemId(), item.getItemName(), newQuantity));
				}
			}
		}
		List<LootRow> lootRows = new ArrayList<>(loot.values());

		LoadoutSnapshot starting = session.getStartingLoadout() == null ? LoadoutSnapshot.unavailable() : session.getStartingLoadout();
		LoadoutSnapshot ending = session.getEndingLoadout() == null ? LoadoutSnapshot.unavailable() : session.getEndingLoadout();

		return new HistoryDetailModel(
			session.getSessionId(),
			session.getActivityIdentity(),
			session.getStartedAt(),
			session.getFinalizedAt(),
			session.getAccumulatedActiveDurationMillis(),
			Collections.unmodifiableList(xpRows),
			totalXp,
			Collections.unmodifiableList(lootRows),
			lootDropCount,
			aggregates == null ? null : aggregates.getReliableCount(),
			starting,
			ending);
	}
}

package com.osrstelemetry.plugin.ui;

import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

/**
 * A generic, RuneLite-free thread-safe cache that separates "read an
 * already-resolved value" (safe from any thread, including the Swing
 * EDT) from "resolve a missing value" (expected to run exactly once
 * per key, typically on a privileged thread such as RuneLite's client
 * thread).
 *
 * This class has no knowledge of ItemManager, prices, or Swing -- it
 * is the pure/testable half. {@link
 * ItemValuationCache} is the thin RuneLite-coupled half that wires
 * this cache up to ItemManager and ClientThread.
 *
 * Safe publication between the resolving thread and reading threads
 * is provided by {@link ConcurrentHashMap} (a put on one thread is
 * guaranteed visible to a get on another thread with no external
 * locking needed).
 */
final class ResolvingCache<K, V>
{
	private final Map<K, V> resolved = new ConcurrentHashMap<>();
	private final Set<K> pending = ConcurrentHashMap.newKeySet();

	/**
	 * Returns the resolved value for {@code key}, or {@code null} if
	 * it has not been resolved yet. Safe to call from any thread.
	 */
	V getIfResolved(K key)
	{
		return resolved.get(key);
	}

	/**
	 * If {@code key} is not yet resolved and is not already pending
	 * resolution, marks it pending and invokes {@code resolver} for
	 * it exactly once. Returns {@code true} if this call triggered
	 * the resolver, {@code false} if a value was already resolved or
	 * a resolution was already in flight for this key.
	 *
	 * {@code resolver} is expected to eventually call {@link #put}
	 * for {@code key} (typically asynchronously, e.g. after a
	 * ClientThread round-trip) or {@link #clearPending} if resolution
	 * failed and a later call should be allowed to retry.
	 */
	boolean resolveIfAbsent(K key, Consumer<K> resolver)
	{
		if (resolved.containsKey(key))
		{
			return false;
		}

		if (!pending.add(key))
		{
			return false;
		}

		resolver.accept(key);
		return true;
	}

	/**
	 * Stores the resolved value for {@code key} and clears its
	 * pending state. Safe to call from any thread.
	 */
	void put(K key, V value)
	{
		resolved.put(key, value);
		pending.remove(key);
	}

	/**
	 * Clears {@code key}'s pending state without resolving it, so a
	 * later {@link #resolveIfAbsent} call is allowed to retry. Used
	 * when a resolution attempt fails.
	 */
	void clearPending(K key)
	{
		pending.remove(key);
	}
}

package com.osrstelemetry.plugin.ui.model;

import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.SessionAggregates;
import com.osrstelemetry.plugin.session.SessionSnapshot;
import com.osrstelemetry.plugin.session.SessionState;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Experience;

/**
 * ADDED (player-facing Current Session UI pass); REWRITTEN (Current
 * Session UI thread-safety hardening pass) to build from a
 * {@link SessionSnapshot} instead of a live
 * {@link com.osrstelemetry.plugin.session.Session}; EXTENDED (live
 * bug-fix pass, PART 6/7 -- Slayer "task remaining" display) with
 * slayerCurrentRemaining. A small, immutable, UI-shaped re-projection
 * of that ALREADY-immutable, already-defensively-copied runtime
 * snapshot — built fresh at read time by
 * {@link #from(SessionSnapshot, Instant)} and never shared/cached across
 * polls. Deliberately does NOT mirror Session's full persisted
 * structure: it carries only what the Current Session panel needs to
 * render, in already-display-shaped form (nonzero-only XP rows,
 * pre-summed loot rows, an already-computed "duration as of now"
 * figure) rather than making the Swing layer re-derive any of that
 * itself.
 *
 * ARCHITECTURE (per explicit instruction, revised in the thread-safety
 * hardening pass): telemetry/session runtime
 * (SessionLifecycleEngine/SessionRuntimeCoordinator) -&gt;
 * {@link SessionRuntimeCoordinator#getCurrentSessionSnapshot()}, which
 * captures a {@link SessionSnapshot} ATOMICALLY under the coordinator's
 * own monitor (see that method's and {@link SessionSnapshot}'s own
 * javadoc) -&gt; this class, a further, purely-cosmetic UI-shaped
 * re-projection of that already-safe, already-copied data (no further
 * defensive copying is needed at this layer — {@link SessionSnapshot}
 * already guarantees immutability) -&gt; the player-facing Swing panel.
 * The session package never depends on this ui package; this class
 * depends on {@link SessionSnapshot} only.
 *
 * PURITY: {@link #from(SessionSnapshot, Instant)} never mutates the
 * snapshot it is given (it only calls getters). Every collection
 * exposed by this class is its own new, unmodifiable copy — never a
 * live view over the input snapshot's own collections (which are
 * themselves already independent copies, per {@link SessionSnapshot}).
 *
 * DURATION SEMANTICS (see {@link #activeDurationMillis}'s own
 * javadoc): this is the one piece of real derivation this class does,
 * and it is deliberately kept here (pure, synchronous, testable with
 * synthetic Instants) rather than in Swing.
 *
 * SLAYER "TASK REMAINING" (live bug-fix pass, PART 6/7): slayerCurrentRemaining
 * is a plain pass-through of {@link SessionSnapshot#getLatestSlayerCurrentRemaining()}
 * -- the LATEST authoritative currentRemaining observed this session,
 * an absolute task-state number, deliberately kept separate from
 * slayerProgressDelta (an accumulated total, still exposed below for
 * future Recent Activity use). {@code CurrentSessionView} now renders
 * THIS field as the primary live Slayer number ("Task remaining N"),
 * not slayerProgressDelta.
 */
public final class CurrentSessionSnapshot
{
	/**
	 * Minimum active duration, in milliseconds, before an XP/hr (or any
	 * future per-hour rate) figure is included for a row. Below this,
	 * a rate would be dominated by rounding/extrapolation noise (a few
	 * seconds of real play projected out to an hour can read as an
	 * absurd, misleading number) — the honest choice is to omit the
	 * rate entirely rather than show one, per the task's explicit
	 * "recommend 60 seconds" guidance. Public so the panel/tests can
	 * reference the exact same constant rather than a duplicated
	 * magic number.
	 */
	public static final long MIN_DURATION_FOR_RATE_MILLIS = 60_000L;

	private static final CurrentSessionSnapshot EMPTY = new CurrentSessionSnapshot(
		false, null, null, null, null, 0L,
		Collections.emptyList(), null, null, Collections.emptyList(), null, null, null);

	/**
	 * ADDED (Current Session UI facelift, PART 1/16). The core combat
	 * skills a COMBAT/BOSSING session's primary signifier is chosen
	 * from -- see {@link #getPrimarySkill()}. Deliberately excludes
	 * Hitpoints (gains XP under every combat style, so it would always
	 * dominate and mask which style is actually being trained) and
	 * Slayer (SLAYER sessions short-circuit to "SLAYER" directly, never
	 * reaching this set).
	 */
	private static final List<String> CORE_COMBAT_SKILLS =
		Collections.unmodifiableList(Arrays.asList("ATTACK", "STRENGTH", "DEFENCE", "RANGED", "MAGIC"));

	private final boolean present;
	private final String sessionId;
	private final String displayName;
	private final ActivityType activityType;
	private final SessionState state;
	private final long activeDurationMillis;
	private final List<XpEntry> xpEntries;
	private final ReliableCountView reliableCount;
	private final Integer slayerProgressDelta;
	private final List<LootEntry> lootEntries;
	private final Integer slayerCurrentRemaining;

	/**
	 * ADDED (Current Session UI facelift, PART 2/7). The attackable NPC
	 * the player is CURRENTLY understood to be targeting, as reported
	 * live by {@code NpcInteractionTargetCollector} at snapshot-build
	 * time (see {@link #from(SessionSnapshot, Instant, String, Integer)}).
	 * Deliberately NOT part of {@link SessionSnapshot}/SessionAggregates
	 * -- this is per-account live combat-target state, not session-scoped
	 * durable truth, and carries no lifecycle/classification meaning of
	 * its own. Null whenever no attackable NPC is currently targeted
	 * (SKILLING activities, or no combat NPC currently engaged).
	 */
	private final String currentNpcName;
	private final Integer currentNpcId;

	private CurrentSessionSnapshot(
		boolean present,
		String sessionId,
		String displayName,
		ActivityType activityType,
		SessionState state,
		long activeDurationMillis,
		List<XpEntry> xpEntries,
		ReliableCountView reliableCount,
		Integer slayerProgressDelta,
		List<LootEntry> lootEntries,
		Integer slayerCurrentRemaining,
		String currentNpcName,
		Integer currentNpcId)
	{
		this.present = present;
		this.sessionId = sessionId;
		this.displayName = displayName;
		this.activityType = activityType;
		this.state = state;
		this.activeDurationMillis = activeDurationMillis;
		this.xpEntries = xpEntries;
		this.reliableCount = reliableCount;
		this.slayerProgressDelta = slayerProgressDelta;
		this.lootEntries = lootEntries;
		this.slayerCurrentRemaining = slayerCurrentRemaining;
		this.currentNpcName = currentNpcName;
		this.currentNpcId = currentNpcId;
	}

	/** The empty-state snapshot ("no active session"). Test A. */
	public static CurrentSessionSnapshot empty()
	{
		return EMPTY;
	}

	/**
	 * Builds a snapshot from a {@code sessionSnapshot} as of {@code now}.
	 * {@code sessionSnapshot} may be null or {@link SessionSnapshot#absent()}
	 * (no current session — returns {@link #empty()}). Never mutates
	 * {@code sessionSnapshot} (it is already fully immutable).
	 */
	public static CurrentSessionSnapshot from(SessionSnapshot sessionSnapshot, Instant now)
	{
		return from(sessionSnapshot, now, null, null);
	}

	/**
	 * ADDED (Current Session UI facelift). Same contract as
	 * {@link #from(SessionSnapshot, Instant)}, plus the NPC the player
	 * is currently understood to be targeting, as read live by the
	 * caller from {@code NpcInteractionTargetCollector} at the same
	 * moment (see {@code OsrsTelemetryPanel#refreshCurrentSession()} --
	 * the only production caller). Both null when no attackable NPC is
	 * currently targeted.
	 */
	public static CurrentSessionSnapshot from(SessionSnapshot sessionSnapshot, Instant now, String currentNpcName, Integer currentNpcId)
	{
		if (sessionSnapshot == null || !sessionSnapshot.isPresent())
		{
			return EMPTY;
		}

		long durationMillis = computeActiveDurationMillis(sessionSnapshot, now);
		List<XpEntry> xp = buildXpEntries(sessionSnapshot, durationMillis);
		ReliableCountView reliableCount = buildReliableCountView(sessionSnapshot);
		Integer slayerProgressDelta = sessionSnapshot.getSlayerProgressDelta();
		Integer slayerCurrentRemaining = sessionSnapshot.getLatestSlayerCurrentRemaining();
		List<LootEntry> loot = buildLootEntries(sessionSnapshot);

		return new CurrentSessionSnapshot(
			true,
			sessionSnapshot.getSessionId(),
			sessionSnapshot.getActivityDisplayName(),
			sessionSnapshot.getActivityType(),
			sessionSnapshot.getState(),
			durationMillis,
			xp,
			reliableCount,
			slayerProgressDelta,
			loot,
			slayerCurrentRemaining,
			currentNpcName,
			currentNpcId);
	}

	/**
	 * DURATION SEMANTICS: reuses exactly the fields
	 * {@code SessionLifecycleEngine} itself uses for active-duration
	 * accounting — never {@code now - startedAt} (see
	 * {@code Session#accumulatedActiveDurationMillis}'s own javadoc for
	 * why that would be wrong).
	 *
	 * {@code accumulatedActiveDurationMillis} only ever grows at the
	 * moment a qualifying heartbeat for the SAME activity actually
	 * arrives (see {@code SessionLifecycleEngine.accumulate()}) — so
	 * while a session is genuinely ACTIVE right now, the real elapsed
	 * time since its own {@code lastActiveAt} has not yet been folded
	 * into that field (it lags by construction until the next
	 * heartbeat). Showing only the lagging accumulated figure while
	 * ACTIVE would make the displayed duration visibly freeze between
	 * heartbeats even though the player is actively playing — so for a
	 * live, ACTIVE session this method adds the elapsed time since
	 * {@code lastActiveAt} on top of the accumulated figure, exactly
	 * mirroring what the engine itself will fold in at the very next
	 * heartbeat.
	 *
	 * That added live elapsed time is clamped to
	 * {@code SessionLifecycleEngine.SUSPEND_TIMEOUT} (reused directly,
	 * never a duplicated constant): the engine itself would never
	 * attribute more than that much continued activity to a single gap
	 * before suspending, so this display never counts further than the
	 * engine's own rule would eventually credit once its own
	 * suspend/advanceTime machinery actually catches up (which can lag
	 * a live UI poll by up to one GameTick under ordinary play — see
	 * SessionRuntimeCoordinator's own TICK-BATCH CLOSURE javadoc).
	 *
	 * A SUSPENDED (or FINALIZED) session's duration is exactly
	 * {@code accumulatedActiveDurationMillis} with nothing added — the
	 * time since suspension is genuinely idle and must never count
	 * (Test C).
	 */
	private static long computeActiveDurationMillis(SessionSnapshot session, Instant now)
	{
		long accumulated = session.getAccumulatedActiveDurationMillis();
		if (session.getState() != SessionState.ACTIVE)
		{
			return accumulated;
		}

		String lastActiveAt = session.getLastActiveAt();
		if (lastActiveAt == null || now == null)
		{
			return accumulated;
		}

		Instant lastActive = Instant.parse(lastActiveAt);
		long liveElapsedMillis = Duration.between(lastActive, now).toMillis();
		if (liveElapsedMillis < 0)
		{
			// Defensive only (out-of-order `now`) — never subtract.
			liveElapsedMillis = 0L;
		}
		long suspendTimeoutMillis = com.osrstelemetry.plugin.session.SessionLifecycleEngine.SUSPEND_TIMEOUT.toMillis();
		if (liveElapsedMillis > suspendTimeoutMillis)
		{
			liveElapsedMillis = suspendTimeoutMillis;
		}
		return accumulated + liveElapsedMillis;
	}

	/**
	 * XP RENDERING: nonzero skills only (Test D), sorted by XP gained
	 * descending — the simplest, most immediately useful ordering
	 * (highest-impact skill first) — with skill name ascending as a
	 * deterministic tie-break. XP/hr is included only when
	 * {@code durationMillis >= MIN_DURATION_FOR_RATE_MILLIS} (Test I);
	 * otherwise the row's rate is left null and the panel omits it
	 * rather than showing a misleadingly huge extrapolated number.
	 *
	 * LIVE-DEBUG PASS, PART 2 (immediate Current Session XP display):
	 * each row's displayed {@code xp} is now the CANONICAL durable
	 * amount from {@code aggregates.getXpGainedBySkill()} PLUS whatever
	 * live, not-yet-durably-flushed amount
	 * {@code aggregates.getLivePendingXpBySkill()} currently holds for
	 * that same skill (see {@code LiveXpTracker}'s own javadoc for why
	 * this sum is exact-once: the live portion is reset to zero the
	 * instant a real XP_CHANGE flush durably represents it). A skill
	 * with ONLY a live pending amount (no durable XP at all yet -- the
	 * very first gain this session, before XP_CHANGE has ever flushed)
	 * still gets its own row immediately, from the union of both maps'
	 * keys -- not merely the durable map's keys. XP/hr below is derived
	 * from this SAME combined total, so it too reflects the live amount
	 * immediately rather than waiting for a durable flush.
	 */
	private static List<XpEntry> buildXpEntries(SessionSnapshot aggregates, long durationMillis)
	{
		if (aggregates == null || aggregates.getXpGainedBySkill() == null)
		{
			return Collections.emptyList();
		}

		Map<String, Long> durableBySkill = aggregates.getXpGainedBySkill();
		Map<String, Long> livePendingBySkill = aggregates.getLivePendingXpBySkill();

		Set<String> skills = new LinkedHashSet<>(durableBySkill.keySet());
		if (livePendingBySkill != null)
		{
			skills.addAll(livePendingBySkill.keySet());
		}

		List<XpEntry> entries = new ArrayList<>();
		for (String skill : skills)
		{
			// ADDED (Current Session UI facelift, PART 5/16): Skill.OVERALL
			// is a synthetic RuneLite "skill" (the account total) that can
			// arrive via StatChanged like any real skill -- it must never
			// get its own Current Session card.
			if ("OVERALL".equals(skill))
			{
				continue;
			}

			Long durable = durableBySkill.get(skill);
			Long livePending = livePendingBySkill == null ? null : livePendingBySkill.get(skill);
			long xp = (durable == null ? 0L : durable) + (livePending == null ? 0L : livePending);
			if (xp == 0L)
			{
				continue;
			}
			Long xpPerHour = null;
			if (durationMillis >= MIN_DURATION_FOR_RATE_MILLIS)
			{
				xpPerHour = Math.round(xp * 3_600_000.0 / durationMillis);
			}
			Long absoluteXp = aggregates.getAbsoluteXpBySkill() == null
				? null
				: aggregates.getAbsoluteXpBySkill().get(skill);
			LevelProgress levelProgress = absoluteXp == null ? null : computeLevelProgress(absoluteXp);
			entries.add(new XpEntry(skill, xp, xpPerHour, levelProgress));
		}

		entries.sort((a, b) ->
		{
			int byXp = Long.compare(b.getXpGained(), a.getXpGained());
			if (byXp != 0)
			{
				return byXp;
			}
			return a.getSkill().compareTo(b.getSkill());
		});

		return Collections.unmodifiableList(entries);
	}

	/**
	 * ADDED (Current Session XP level-progress pass). Derives real
	 * account-level progression from one raw absolute XP value, using
	 * RuneLite's OWN canonical XP table ({@link Experience}) rather than
	 * a hand-maintained one -- {@link Experience#getLevelForXp(int)} /
	 * {@link Experience#getXpForLevel(int)} are exactly the values the
	 * real game client itself derives level-up/progress-bar state from.
	 *
	 * REAL LEVELS ONLY (per explicit instruction): {@code getLevelForXp}
	 * returns a VIRTUAL level up to {@link Experience#MAX_VIRT_LEVEL}
	 * (126) once xp exceeds the level-99 threshold -- this method
	 * deliberately clamps to {@link Experience#MAX_REAL_LEVEL} (99) and
	 * switches to the MAX state there, never computing or displaying a
	 * virtual level or "progress toward 100+".
	 *
	 * {@code absoluteXp} is cast to {@code int} -- safe because
	 * {@link Experience#MAX_SKILL_XP} (200,000,000) already fits
	 * comfortably within the int range Experience's own API is defined
	 * in terms of.
	 */
	private static LevelProgress computeLevelProgress(long absoluteXp)
	{
		int xp = (int) Math.min(absoluteXp, Experience.MAX_SKILL_XP);
		int level = Math.min(Experience.getLevelForXp(xp), Experience.MAX_REAL_LEVEL);

		if (level >= Experience.MAX_REAL_LEVEL)
		{
			return new LevelProgress(Experience.MAX_REAL_LEVEL, true, null, null);
		}

		int xpForCurrentLevel = Experience.getXpForLevel(level);
		int xpForNextLevel = Experience.getXpForLevel(level + 1);
		int xpIntoLevel = xp - xpForCurrentLevel;
		int xpSpanOfLevel = xpForNextLevel - xpForCurrentLevel;
		int progressPercent = xpSpanOfLevel <= 0 ? 0 : (int) (100L * xpIntoLevel / xpSpanOfLevel);
		long xpRemaining = xpForNextLevel - xp;

		return new LevelProgress(level, false, progressPercent, xpRemaining);
	}

	/**
	 * RELIABLE-COUNT RENDERING: only rendered at all when
	 * {@code SessionAggregates.reliableCount} is non-null (Tests E/F) —
	 * per that field's own javadoc, this is already the honest
	 * "no row until a qualifying authoritative signal has been
	 * observed" policy; this method just carries it through. Both
	 * numbers the model actually tracks are surfaced (sessionOccurrences
	 * and, when present, authoritativeCurrentValue) — no third number
	 * (e.g. a synthesized "before this session" baseline) is invented,
	 * since the model does not track one.
	 */
	private static ReliableCountView buildReliableCountView(SessionSnapshot aggregates)
	{
		if (aggregates == null || aggregates.getReliableCount() == null)
		{
			return null;
		}
		SessionAggregates.ReliableCount rc = aggregates.getReliableCount();
		return new ReliableCountView(rc.getKind(), rc.getSessionOccurrences(), rc.getAuthoritativeCurrentValue());
	}

	/**
	 * LOOT RENDERING: a presentation-only transformation — atomic
	 * {@code LootDropGroup}s (one per observed loot notification) are
	 * summed here by item across every group in the session, purely to
	 * build this snapshot's own new list. The underlying
	 * {@code SessionAggregates.lootDrops} list/its groups are only ever
	 * read (getters), never mutated, added to, or replaced (Test H).
	 * Items are keyed by itemId when present, falling back to itemName
	 * (an item without a resolved id is still summed correctly rather
	 * than creating one row per drop). Sorted by summed quantity
	 * descending, item name ascending as a tie-break, for a stable,
	 * deterministic display order.
	 */
	private static List<LootEntry> buildLootEntries(SessionSnapshot aggregates)
	{
		if (aggregates == null || aggregates.getLootDrops() == null || aggregates.getLootDrops().isEmpty())
		{
			return Collections.emptyList();
		}

		Map<String, LootAccumulator> byKey = new LinkedHashMap<>();
		for (SessionAggregates.LootDropGroup group : aggregates.getLootDrops())
		{
			if (group == null || group.getItems() == null)
			{
				continue;
			}
			for (SessionAggregates.LootItemAggregate item : group.getItems())
			{
				if (item == null)
				{
					continue;
				}
				String key = item.getItemId() != null ? ("id:" + item.getItemId()) : ("name:" + item.getItemName());
				LootAccumulator acc = byKey.get(key);
				if (acc == null)
				{
					acc = new LootAccumulator(item.getItemId(), item.getItemName());
					byKey.put(key, acc);
				}
				acc.quantity += item.getQuantity();
			}
		}

		List<LootEntry> entries = new ArrayList<>();
		for (LootAccumulator acc : byKey.values())
		{
			entries.add(new LootEntry(acc.itemId, acc.itemName, acc.quantity));
		}

		entries.sort((a, b) ->
		{
			int byQty = Long.compare(b.getQuantity(), a.getQuantity());
			if (byQty != 0)
			{
				return byQty;
			}
			String nameA = a.getItemName() == null ? "" : a.getItemName();
			String nameB = b.getItemName() == null ? "" : b.getItemName();
			return nameA.compareTo(nameB);
		});

		return Collections.unmodifiableList(entries);
	}

	private static final class LootAccumulator
	{
		private final Integer itemId;
		private final String itemName;
		private long quantity;

		private LootAccumulator(Integer itemId, String itemName)
		{
			this.itemId = itemId;
			this.itemName = itemName;
		}
	}

	public boolean isPresent()
	{
		return present;
	}

	public String getSessionId()
	{
		return sessionId;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public ActivityType getActivityType()
	{
		return activityType;
	}

	public SessionState getState()
	{
		return state;
	}

	public long getActiveDurationMillis()
	{
		return activeDurationMillis;
	}

	public List<XpEntry> getXpEntries()
	{
		return xpEntries;
	}

	public ReliableCountView getReliableCount()
	{
		return reliableCount;
	}

	public Integer getSlayerProgressDelta()
	{
		return slayerProgressDelta;
	}

	/**
	 * ADDED (live bug-fix pass, PART 6/7 -- Slayer "task remaining"
	 * display). The LATEST authoritative currentRemaining observed this
	 * session (an absolute task-state number), or null when none has
	 * been observed yet. This -- not {@link #getSlayerProgressDelta()}
	 * -- is what {@code CurrentSessionView} now renders as the primary
	 * live Slayer number.
	 */
	public Integer getSlayerCurrentRemaining()
	{
		return slayerCurrentRemaining;
	}

	/**
	 * ADDED (Slayer task-complete presentation pass). True only when this
	 * session has genuinely observed the assigned Slayer task reach
	 * exactly zero remaining ({@link #getSlayerCurrentRemaining()} == 0)
	 * -- never null, never negative (this field only ever holds an
	 * authoritative currentRemaining or null; see
	 * {@code SessionAggregates#latestSlayerCurrentRemaining}'s own
	 * javadoc). {@code CurrentSessionView} uses this -- not a raw
	 * {@code == 0} check duplicated in the Swing layer -- to decide
	 * whether to render the compact "Task complete / Grab a new task"
	 * state instead of the numeric remaining-count row. Deliberately
	 * does not affect session lifecycle/state in any way -- a completed
	 * task does not finalize or otherwise change the session; loot/XP
	 * arriving afterward keeps belonging to this same session exactly as
	 * before this pass.
	 */
	public boolean isSlayerTaskComplete()
	{
		return slayerCurrentRemaining != null && slayerCurrentRemaining == 0;
	}

	/**
	 * REMOVED (Slayer task-unit/physical-kill semantics audit): this
	 * snapshot no longer exposes a Slayer "kills/hr" figure.
	 * {@link #getSlayerProgressDelta()} is a Slayer TASK-UNIT total, not
	 * a physical NPC-kill count -- game mechanics can make one physical
	 * kill consume more or fewer than one task unit (e.g. an
	 * expeditious-bracelet-style proc, or a bracelet-of-slaughter-style
	 * save), so a rate derived from it is not a "kills/hr" figure and
	 * must not be labeled or rendered as one. No reliable, independent
	 * physical-player-kill signal exists for an ordinary Slayer
	 * session (see NpcDeathCollector's own javadoc for why NPC_DEATH
	 * cannot be used for this), so the honest choice is to omit the
	 * figure entirely rather than mislabel task units as kills or
	 * fabricate a substitute. {@link #getSlayerProgressDelta()} itself
	 * remains available for task-unit-based calculations (e.g.
	 * {@link #getEstimatedSlayerXpRemaining()}), which stay valid since
	 * both their numerator and denominator are consistently task units.
	 */

	/**
	 * ADDED (Spyglass Phase 1C). Minimum Slayer task units observed
	 * before {@link #getEstimatedSlayerXpRemaining()} will produce a
	 * value -- a single task unit's XP delta could be a boundary
	 * artifact (e.g. XP that landed just before this session's own
	 * first qualifying evidence arrived), so the average is only
	 * trusted once it is drawn from more than one independent sample.
	 * Named for task units, not kills: {@link #getSlayerProgressDelta()}
	 * is a task-unit total, never a physical NPC-kill count -- see that
	 * field's own javadoc.
	 */
	public static final int MIN_SLAYER_TASK_UNITS_FOR_XP_ESTIMATE = 2;

	/**
	 * ADDED (Spyglass Phase 1C). Estimated Slayer XP remaining on the
	 * current task, computed ENTIRELY from THIS session's own
	 * already-observed data: (Slayer XP gained this session / Slayer
	 * task units consumed this session -- the same
	 * {@link #getSlayerProgressDelta()} counter, a TASK-UNIT total,
	 * never a physical NPC-kill count) multiplied by
	 * {@link #getSlayerCurrentRemaining()}. Both the denominator and the
	 * multiplied remaining value are task units, so this calculation
	 * stays correct even when a physical kill consumes more or fewer
	 * than one task unit (e.g. an expeditious-bracelet-style proc or a
	 * bracelet-of-slaughter-style save) -- it naturally reflects the
	 * observed XP-per-task-unit rate rather than assuming
	 * XP-per-physical-kill. Never a hardcoded/Wiki per-monster XP
	 * table -- this project has no such table and must never invent
	 * one; a task with genuinely variable XP per task unit simply
	 * yields a rougher estimate, which is exactly why the panel presents
	 * this as an approximation ("~", not an exact figure). Null (render
	 * nothing) whenever there are fewer than
	 * {@link #MIN_SLAYER_TASK_UNITS_FOR_XP_ESTIMATE} task units
	 * consumed, no remaining count (including an already-complete task,
	 * which is exactly {@code remaining == 0}), or no Slayer XP has
	 * actually been observed yet this session.
	 */
	public Long getEstimatedSlayerXpRemaining()
	{
		if (slayerProgressDelta == null || slayerProgressDelta < MIN_SLAYER_TASK_UNITS_FOR_XP_ESTIMATE
			|| slayerCurrentRemaining == null || slayerCurrentRemaining <= 0)
		{
			return null;
		}

		long slayerXpGained = 0L;
		for (XpEntry entry : xpEntries)
		{
			if ("SLAYER".equals(entry.getSkill()))
			{
				slayerXpGained = entry.getXpGained();
				break;
			}
		}
		if (slayerXpGained <= 0L)
		{
			return null;
		}

		double averageXpPerTaskUnit = (double) slayerXpGained / slayerProgressDelta;
		long estimatedRemaining = Math.round(averageXpPerTaskUnit * slayerCurrentRemaining);
		return estimatedRemaining <= 0L ? null : estimatedRemaining;
	}

	/**
	 * ADDED (Spyglass Phase 1D); CORRECTED (Slayer task-unit/physical-
	 * kill semantics audit): the reliable session PHYSICAL-KILL count
	 * the Current Session loot header ("LOOT &#215;36") should show, or
	 * null when nothing reliable is available -- never a fabricated
	 * "0" and never a Slayer task-unit total standing in for a kill
	 * count. Slayer task units ({@link #getSlayerProgressDelta()}) are
	 * deliberately NOT used here: game mechanics can make one physical
	 * kill consume more or fewer than one task unit (see that field's
	 * own javadoc), so a task-unit total is not a physical-kill count
	 * and must never be rendered as "&#215;N". Returns the existing
	 * reliable-count mechanism (currently BOSS_KILL-sourced -- see
	 * {@code SessionAggregates.ReliableCount}'s own javadoc) when one is
	 * available for this session, and null otherwise -- an ordinary
	 * Slayer session with no independently-authoritative kill count
	 * renders a plain "LOOT" header, never a fabricated or mislabeled
	 * count. Introduces no new counter of its own.
	 */
	public Integer getLootHeaderKillCount()
	{
		if (reliableCount != null && reliableCount.getSessionOccurrences() > 0)
		{
			return reliableCount.getSessionOccurrences();
		}
		return null;
	}

	public List<LootEntry> getLootEntries()
	{
		return lootEntries;
	}

	/** See {@link #currentNpcName}'s own javadoc. */
	public String getCurrentNpcName()
	{
		return currentNpcName;
	}

	/** See {@link #currentNpcName}'s own javadoc (same target's NPC id). */
	public Integer getCurrentNpcId()
	{
		return currentNpcId;
	}

	/**
	 * ADDED (Current Session UI facelift, PART 1/16). Which single skill
	 * should headline the activity header as the session's primary
	 * signifier. Derived purely from data this snapshot already carries
	 * (activityType + xpEntries, already sorted by XP gained descending)
	 * -- no new session/classifier state, no hardcoded boss/activity
	 * name table.
	 *
	 * SLAYER: always "SLAYER", regardless of which combat skills are
	 * actually gaining XP underneath -- the task assignment is the
	 * player-facing point of a Slayer session.
	 *
	 * COMBAT/BOSSING: the highest-XP entry among {@link #CORE_COMBAT_SKILLS}
	 * that is actually gaining XP this session -- deliberately excluding
	 * Hitpoints (see that constant's own javadoc for why). Falls back to
	 * the single highest-XP entry of any kind if no core combat skill has
	 * session XP yet (e.g. the very first moments of a fresh BOSSING
	 * session) -- never fabricates a skill that isn't in xpEntries.
	 *
	 * SKILLING (and any other/null activityType): the single highest-XP
	 * entry, since a skilling session ordinarily trains exactly one
	 * skill.
	 *
	 * Null only when xpEntries is empty and this is not a SLAYER session
	 * -- {@code CurrentSessionView} omits the header's skill-icon slot
	 * entirely in that case, per the task's empty-state discipline.
	 */
	public String getPrimarySkill()
	{
		if (activityType == ActivityType.SLAYER)
		{
			return "SLAYER";
		}

		if (xpEntries.isEmpty())
		{
			return null;
		}

		if (activityType == ActivityType.COMBAT || activityType == ActivityType.BOSSING)
		{
			for (XpEntry entry : xpEntries)
			{
				if (CORE_COMBAT_SKILLS.contains(entry.getSkill()))
				{
					return entry.getSkill();
				}
			}
		}

		return xpEntries.get(0).getSkill();
	}

	/** One nonzero-XP skill row, with an optional (threshold-gated) hourly rate. */
	public static final class XpEntry
	{
		private final String skill;
		private final long xpGained;
		private final Long xpPerHour;
		private final LevelProgress levelProgress;

		XpEntry(String skill, long xpGained, Long xpPerHour, LevelProgress levelProgress)
		{
			this.skill = skill;
			this.xpGained = xpGained;
			this.xpPerHour = xpPerHour;
			this.levelProgress = levelProgress;
		}

		public String getSkill()
		{
			return skill;
		}

		public long getXpGained()
		{
			return xpGained;
		}

		/** Null when the session's active duration is below {@link #MIN_DURATION_FOR_RATE_MILLIS}. */
		public Long getXpPerHour()
		{
			return xpPerHour;
		}

		/**
		 * ADDED (Current Session XP level-progress pass). Null only when no
		 * absolute XP has ever been observed this session for this skill
		 * (see {@link CurrentSessionSnapshot#buildXpEntries} -- in practice
		 * this cannot happen for a skill that already has nonzero session
		 * XP, since gaining XP requires at least one StatChanged
		 * observation, and every such observation unconditionally feeds
		 * {@code SessionRuntimeCoordinator.noteAbsoluteXp()} -- this is
		 * simply defense in depth for an otherwise-impossible gap).
		 */
		public LevelProgress getLevelProgress()
		{
			return levelProgress;
		}
	}

	/** The one reliable-count row, when a qualifying authoritative signal has been observed this session. */
	public static final class ReliableCountView
	{
		private final SessionAggregates.ReliableCountKind kind;
		private final int sessionOccurrences;
		private final Integer authoritativeCurrentValue;

		ReliableCountView(SessionAggregates.ReliableCountKind kind, int sessionOccurrences, Integer authoritativeCurrentValue)
		{
			this.kind = kind;
			this.sessionOccurrences = sessionOccurrences;
			this.authoritativeCurrentValue = authoritativeCurrentValue;
		}

		public SessionAggregates.ReliableCountKind getKind()
		{
			return kind;
		}

		/** How many of these occurred DURING this session — the only count safe to label a session statistic. */
		public int getSessionOccurrences()
		{
			return sessionOccurrences;
		}

		/** The raw account-wide absolute value last observed, if the source event carried one. May be null. */
		public Integer getAuthoritativeCurrentValue()
		{
			return authoritativeCurrentValue;
		}
	}

	/**
	 * One display-aggregated loot row — quantities of the same item
	 * summed across every atomic loot group this session.
	 *
	 * IMPLEMENTS LootPricing.Priceable (Spyglass Phase 2): lets
	 * {@code LootPricing.valueAndSort}/its callers treat this and the
	 * persistent Loot Tracker's own {@code LootTrackerSnapshot.ItemEntry}
	 * identically — see that interface's own javadoc for why this is the
	 * one shared valuation/sort implementation rather than a duplicated
	 * one.
	 */
	public static final class LootEntry implements com.osrstelemetry.plugin.ui.LootPricing.Priceable
	{
		private final Integer itemId;
		private final String itemName;
		private final long quantity;

		LootEntry(Integer itemId, String itemName, long quantity)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
		}

		public Integer getItemId()
		{
			return itemId;
		}

		public String getItemName()
		{
			return itemName;
		}

		public long getQuantity()
		{
			return quantity;
		}
	}

	/**
	 * ADDED (Current Session XP level-progress pass). Compact,
	 * read-only account-level progression for one skill, derived from
	 * that skill's real absolute XP via RuneLite's own {@link Experience}
	 * table (see {@link #computeLevelProgress(long)}). Never a durable
	 * session aggregate -- purely a UI-shaped derivation recomputed
	 * fresh every {@link #from(SessionSnapshot, Instant)} call, exactly
	 * like every other field on this class.
	 */
	public static final class LevelProgress
	{
		private final int currentLevel;
		private final boolean maxLevel;
		private final Integer progressPercent;
		private final Long xpRemainingToNextLevel;

		LevelProgress(int currentLevel, boolean maxLevel, Integer progressPercent, Long xpRemainingToNextLevel)
		{
			this.currentLevel = currentLevel;
			this.maxLevel = maxLevel;
			this.progressPercent = progressPercent;
			this.xpRemainingToNextLevel = xpRemainingToNextLevel;
		}

		/** The real (never virtual) current level, 1-99. */
		public int getCurrentLevel()
		{
			return currentLevel;
		}

		/** True at real level 99 -- {@link #getProgressPercent()}/{@link #getXpRemainingToNextLevel()} are null whenever this is true. */
		public boolean isMaxLevel()
		{
			return maxLevel;
		}

		/** 0-100, progress toward {@link #getCurrentLevel()} + 1. Null when {@link #isMaxLevel()}. */
		public Integer getProgressPercent()
		{
			return progressPercent;
		}

		/** Exact XP still needed to reach {@link #getCurrentLevel()} + 1. Null when {@link #isMaxLevel()}. */
		public Long getXpRemainingToNextLevel()
		{
			return xpRemainingToNextLevel;
		}
	}
}

package com.osrstelemetry.plugin.ui.model;

import java.time.Instant;
import java.util.Comparator;

/**
 * ADDED (Loot Tracker source-ordering fix pass); CORRECTED (small
 * UI/loot polish pass -- Favorites must not reorder the All list). The
 * single, pure, directly-unit-testable definition of "most recent
 * activity first" for the Loot Tracker's source cards -- factored out of
 * {@link LootTrackerSnapshot#from} so the ordering rule itself can be
 * tested with plain {@link LootTrackerSnapshot.SourceEntry} instances,
 * no index/preferences/Swing required.
 *
 * ORDER (product decision, corrected by this pass): plain recent-first,
 * with NO favorite grouping at all -- the source whose newest (post
 * reset-watermark) record is most recent comes first, regardless of
 * favorite state. Favoriting a source makes it available on the
 * Favorites sub-tab; it must never move that source's position within
 * the All list. Applying this ONE comparator to the full source list is
 * what makes both {@link LootTrackerSnapshot#getAllSources()} (plain
 * recent-first, favorite-state-independent) and
 * {@link LootTrackerSnapshot#getFavoriteSources()} (a plain filter over
 * that same already-sorted list, so it comes out recent-first among
 * favorites "for free," with no separate sort of its own) correct from
 * one place.
 *
 * SUPERSEDED: this comparator previously sorted favorites as a group
 * before non-favorites (see this class's prior javadoc / the live
 * bug-fix report the "small UI/loot polish" pass corrected). That
 * behavior made the All view visibly jump/reorder the instant a card was
 * favorited -- confirmed by product decision to be wrong: the point of
 * Favorites is a separate filtered view, not a mutation of the normal
 * list's ordering. Removing the favorite-first comparison is the entire
 * fix; recency-then-sourceKey below is unchanged from before.
 *
 * TIE-BREAK: sources with an equal (or equally absent) last-activity
 * instant are ordered by sourceKey ascending -- stable source identity,
 * never sourceName alone (two different sourceIds sharing a display name
 * must still sort deterministically relative to each other -- see
 * LootTrackerIndex's own "never merged" javadoc). A null lastObservedAt
 * (should not occur for a real, non-empty source -- defensive only)
 * sorts as LEAST recent, never crashes the comparator and never
 * silently ties with a real timestamp.
 */
final class LootTrackerSourceOrdering
{
	private LootTrackerSourceOrdering()
	{
	}

	static final Comparator<LootTrackerSnapshot.SourceEntry> COMPARATOR = (a, b) ->
	{
		int byRecency = compareRecencyDescending(a.getLastObservedAt(), b.getLastObservedAt());
		if (byRecency != 0)
		{
			return byRecency;
		}
		return a.getSourceKey().compareTo(b.getSourceKey());
	};

	/** Descending by instant -- more recent first; null sorts after every real instant. */
	private static int compareRecencyDescending(Instant a, Instant b)
	{
		if (a == null && b == null)
		{
			return 0;
		}
		if (a == null)
		{
			return 1;
		}
		if (b == null)
		{
			return -1;
		}
		return b.compareTo(a);
	}
}

package com.osrstelemetry.plugin.ui.model;

import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.loottracker.LootTrackerSource;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * ADDED (Spyglass Phase 2 -- persistent Loot Tracker). The ONE place
 * pure UI-shaped derivation happens for the Loot Tracker -- immutable,
 * built fresh from {@link LootTrackerIndex}/{@link LootTrackerPreferences}
 * at poll time, unit-testable without Swing. Mirrors
 * {@link CurrentSessionSnapshot}'s own architectural role for Current
 * Session exactly (same project convention: a mutable live
 * index/aggregate is never hand	ed to a Swing view directly -- a fresh
 * immutable snapshot is built from it instead, never handed to a Swing
 * view directly).
 *
 * COMBINES two independent inputs that must never be confused with each
 * other: {@link LootTrackerIndex} (pure telemetry-derived truth -- which
 * sources/records/items actually happened) and
 * {@link LootTrackerPreferences} (pure UI preference -- favorites,
 * hidden items, collapsed cards, reset watermarks, show-hidden toggle).
 * Neither of those two classes knows the other exists; this class is
 * where they meet.
 *
 * RESET WATERMARK APPLICATION: each RAW (sourceName, sourceId) source's
 * records are filtered via {@link LootTrackerSource#filteredAfter} using
 * that raw source's own persisted watermark (if any) BEFORE anything
 * else is derived from it (item totals, kill count, individual-drop
 * list, and -- see CANONICAL PLAYER-FACING IDENTITY below -- BEFORE
 * grouping into a player-facing card too). A raw source left with zero
 * records after filtering is omitted entirely (nothing meaningful to
 * show). Resetting one raw variant never resets another, and "reset this
 * NPC" (see below) works by resetting every raw variant currently
 * grouped under it to the same watermark instant -- no separate
 * canonical-watermark storage/migration is needed at all.
 *
 * CANONICAL PLAYER-FACING IDENTITY (Loot Tracker duplicate-card fix
 * pass): {@link LootTrackerIndex} keys raw telemetry by (sourceName,
 * sourceId) -- see its own javadoc -- because OSRS/RuneLite's
 * {@code NPCComposition#getId()} genuinely varies for what is visually
 * ONE logical monster to the player (confirmed live: e.g. "Desert Wolf"/
 * "Goat"-style duplicate cards, each a different composition id under
 * the identical display name). That RAW identity is exactly right for
 * {@link LootTrackerIndex} (telemetry/diagnostics must never lose real
 * source-id information) but is WRONG for what the player sees: spec
 * requires ONE card per logical NPC/activity. This class is therefore
 * the ONE place that raw (sourceName, sourceId) sources get grouped into
 * a single player-facing {@link SourceEntry} by {@link #canonicalDisplayName}
 * (sourceName alone, case-sensitive, exact match -- see that method's
 * own javadoc for why name-only is the right, deliberately simple
 * canonicalization here and why it is safe never to special-case two
 * genuinely-different sources sharing one display name). Every raw
 * sourceKey a canonical entry represents is preserved on it via
 * {@link SourceEntry#getRawSourceKeys()} -- nothing about the raw
 * telemetry identity is lost or merged away in {@link LootTrackerIndex}
 * itself, only in this presentation layer. Preference lookups
 * (favorite/collapsed/hidden) are OR-ed across every raw member of a
 * canonical group -- e.g. a source already favorited under its OLD raw
 * key before this fix shipped is still shown favorited afterward, with
 * no explicit migration/rewrite of the persisted preferences file
 * needed (see {@link SourceEntry#getRawSourceKeys()}'s own javadoc for
 * how the view layer writes new favorite/hide/collapse/reset actions
 * back across the whole group so this stays consistent going forward).
 *
 * VALUATION IS INTENTIONALLY ABSENT: unlike Current Session's
 * equivalent, this snapshot carries only itemId/itemName/quantity (no
 * price/value fields) -- pricing must be resolved off the EDT via
 * {@code ItemValuationCache}/{@code ClientThread} exactly like Current
 * Session's own loot section (see LootPricing's own class javadoc for
 * why valuation can never happen here), so LootTrackerView applies
 * {@code LootPricing.valueAndSort}/{@code buildTooltipHtml} to this
 * snapshot's item lists at render time, the SAME shared valuation/sort
 * code Current Session already uses -- never a second pricing/sorting
 * implementation.
 */
public final class LootTrackerSnapshot
{
	private static final LootTrackerSnapshot EMPTY = new LootTrackerSnapshot(Collections.emptyList(), false);

	/** Null-safe, oldest-first: a null observedAt (should not occur for a real record) sorts last rather than throwing. */
	private static final Comparator<LootTrackerRecord> BY_OBSERVED_AT_ASCENDING = (a, b) ->
	{
		Instant ai = a.getObservedAt();
		Instant bi = b.getObservedAt();
		if (ai == null && bi == null)
		{
			return 0;
		}
		if (ai == null)
		{
			return 1;
		}
		if (bi == null)
		{
			return -1;
		}
		return ai.compareTo(bi);
	};

	private final List<SourceEntry> sources;
	private final boolean showHidden;

	private LootTrackerSnapshot(List<SourceEntry> sources, boolean showHidden)
	{
		this.sources = Collections.unmodifiableList(sources);
		this.showHidden = showHidden;
	}

	public static LootTrackerSnapshot empty()
	{
		return EMPTY;
	}

	public static LootTrackerSnapshot from(LootTrackerIndex index, LootTrackerPreferences preferences)
	{
		if (index == null)
		{
			return empty();
		}

		// Raw (sourceName, sourceId) sources, watermark-filtered -- see
		// class javadoc's RESET WATERMARK APPLICATION note. Grouped by
		// canonical player-facing display name immediately below, in
		// first-observed-raw-source order (a LinkedHashMap, so grouping
		// itself never introduces HashMap-iteration-order nondeterminism
		// -- final presentation order is still entirely decided by
		// LootTrackerSourceOrdering.COMPARATOR at the very end).
		Map<String, List<LootTrackerSource>> rawByCanonicalName = new LinkedHashMap<>();
		for (LootTrackerSource source : index.snapshotSources())
		{
			Instant watermark = preferences == null ? null : preferences.getResetWatermark(source.getSourceKey());
			LootTrackerSource filtered = source.filteredAfter(watermark);
			if (filtered.getRecords().isEmpty())
			{
				continue;
			}
			String canonicalName = canonicalDisplayName(filtered.getSourceName());
			rawByCanonicalName.computeIfAbsent(canonicalName, k -> new ArrayList<>()).add(filtered);
		}

		List<SourceEntry> entries = new ArrayList<>();
		for (List<LootTrackerSource> group : rawByCanonicalName.values())
		{
			entries.add(buildCanonicalEntry(group, preferences));
		}

		// ADDED (Loot Tracker source-ordering fix); CORRECTED (small
		// UI/loot polish pass). "Most recent activity first" -- the source
		// with the newest POST-WATERMARK lastObservedAt first (so a reset
		// source's ordering reflects only what's actually still visible,
		// exactly like its displayed totals already do), with NO favorite
		// grouping: favorite state must never move a source's position in
		// the All list (product decision -- see
		// LootTrackerSourceOrdering's own javadoc for the corrected
		// ordering and why the old favorites-first behavior was removed).
		// getFavoriteSources() below is a simple filter over this same
		// already-sorted list, so it comes out recent-first among
		// favorites "for free" with no separate sort of its own. Never
		// HashMap iteration/discovery/creation order, never alphabetical
		// -- see LootTrackerSourceOrdering's own javadoc for the
		// deterministic tie-break.
		entries.sort(LootTrackerSourceOrdering.COMPARATOR);

		boolean showHidden = preferences != null && preferences.isShowHidden();
		return new LootTrackerSnapshot(entries, showHidden);
	}

	/**
	 * The player-facing canonical grouping key: the raw sourceName,
	 * exactly as observed (case-sensitive, no trimming/normalization
	 * beyond that -- OSRS composition names are already clean, and
	 * inventing fuzzy normalization here would be exactly the kind of
	 * "clever" canonicalization this fix deliberately avoids). Two raw
	 * sources with the identical display name are, to the player,
	 * visually the SAME logical NPC/activity -- there is no product
	 * concept of two different things that both legitimately look like
	 * "Desert Wolf" and must still be told apart on screen -- so grouping
	 * purely by name is both simple and correct here. A null sourceName
	 * groups together as its own canonical bucket (displayed as
	 * "Unknown" by the view, same as before this fix).
	 */
	private static String canonicalDisplayName(String sourceName)
	{
		return sourceName == null ? "" : sourceName;
	}

	/**
	 * Merges one canonical-name group of raw {@link LootTrackerSource}s
	 * (already watermark-filtered) into the single player-facing
	 * {@link SourceEntry} the view renders as one card. Kill count sums
	 * across every raw member (each is still an honest per-raw-source
	 * SERVER_NPC_LOOT occurrence count -- see LootTrackerSource's own
	 * javadoc -- summing them keeps that same honesty for the merged
	 * total). Individual records are concatenated across every member and
	 * re-sorted oldest-first by observedAt, so the Individual view still
	 * shows one true chronological timeline even when it spans multiple
	 * raw composition ids.
	 */
	private static SourceEntry buildCanonicalEntry(List<LootTrackerSource> group, LootTrackerPreferences preferences)
	{
		List<String> rawSourceKeys = new ArrayList<>(group.size());
		int killCount = 0;
		Instant first = null;
		Instant last = null;
		boolean favorite = false;
		boolean collapsed = false;
		List<LootTrackerRecord> allRecords = new ArrayList<>();

		for (LootTrackerSource member : group)
		{
			rawSourceKeys.add(member.getSourceKey());
			killCount += member.getKillCount();
			Instant memberFirst = member.getFirstObservedAt();
			if (memberFirst != null && (first == null || memberFirst.isBefore(first)))
			{
				first = memberFirst;
			}
			Instant memberLast = member.getLastObservedAt();
			if (memberLast != null && (last == null || memberLast.isAfter(last)))
			{
				last = memberLast;
			}
			if (preferences != null && preferences.isFavorite(member.getSourceKey()))
			{
				favorite = true;
			}
			if (preferences != null && preferences.isCollapsed(member.getSourceKey()))
			{
				collapsed = true;
			}
			allRecords.addAll(member.getRecords());
		}
		allRecords.sort(BY_OBSERVED_AT_ASCENDING);

		Map<Integer, Long> quantityByItemId = new LinkedHashMap<>();
		Map<Integer, String> nameByItemId = new LinkedHashMap<>();
		for (LootTrackerRecord record : allRecords)
		{
			for (LootTrackerItem item : record.getItems())
			{
				quantityByItemId.merge(item.getItemId(), item.getQuantity(), Long::sum);
				nameByItemId.putIfAbsent(item.getItemId(), item.getItemName());
			}
		}

		List<ItemEntry> itemTotals = new ArrayList<>();
		for (Map.Entry<Integer, Long> entry : quantityByItemId.entrySet())
		{
			int itemId = entry.getKey();
			itemTotals.add(new ItemEntry(itemId, nameByItemId.get(itemId), entry.getValue(), isItemHiddenInGroup(rawSourceKeys, itemId, preferences)));
		}

		List<RecordEntry> individualRecords = new ArrayList<>();
		for (LootTrackerRecord record : allRecords)
		{
			List<ItemEntry> recordItems = new ArrayList<>();
			for (LootTrackerItem item : record.getItems())
			{
				recordItems.add(new ItemEntry(item.getItemId(), item.getItemName(), item.getQuantity(), isItemHiddenInGroup(rawSourceKeys, item.getItemId(), preferences)));
			}
			individualRecords.add(new RecordEntry(record.getObservedAt(), Collections.unmodifiableList(recordItems)));
		}

		LootTrackerSource representative = group.get(0);
		return new SourceEntry(
			canonicalSourceKey(representative.getSourceName()),
			representative.getSourceName(),
			representative.getSourceId(),
			killCount,
			first,
			last,
			favorite,
			collapsed,
			Collections.unmodifiableList(itemTotals),
			Collections.unmodifiableList(individualRecords),
			Collections.unmodifiableList(rawSourceKeys));
	}

	/** An item is treated as hidden for the merged card if hidden under ANY raw variant it was hidden from before grouping -- see class javadoc's preference-migration note. */
	private static boolean isItemHiddenInGroup(List<String> rawSourceKeys, int itemId, LootTrackerPreferences preferences)
	{
		if (preferences == null)
		{
			return false;
		}
		for (String rawKey : rawSourceKeys)
		{
			if (preferences.isItemHidden(rawKey, itemId))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The player-facing canonical entry's own identity string -- DELIBERATELY
	 * a different, unambiguous format ({@code "canon:" + name}) from
	 * {@link LootTrackerIndex#sourceKey}'s raw ({@code "name id"}) format, so
	 * the two can never collide even for a name that happens to end in
	 * something that looks like a trailing id token. Used for ordering
	 * tie-breaks and render-key fingerprinting; NEVER used as a
	 * {@link LootTrackerPreferences} key directly -- preference reads/writes
	 * always go through {@link SourceEntry#getRawSourceKeys()} instead (see
	 * that method's own javadoc), so this format never needs to appear in
	 * the persisted preferences document at all.
	 */
	private static String canonicalSourceKey(String sourceName)
	{
		return "canon:" + (sourceName == null ? "" : sourceName);
	}

	/** Every known source (post reset-watermark filtering, post canonical-identity grouping) -- the "All" sub-tab. */
	public List<SourceEntry> getAllSources()
	{
		return sources;
	}

	/** The subset of {@link #getAllSources()} the player has favorited -- the "Favorites" sub-tab. Never a separate/different data source from All. */
	public List<SourceEntry> getFavoriteSources()
	{
		List<SourceEntry> favorites = new ArrayList<>();
		for (SourceEntry entry : sources)
		{
			if (entry.isFavorite())
			{
				favorites.add(entry);
			}
		}
		return favorites;
	}

	/** Spec: "Show hidden" toggle state, default off -- callers decide whether to render a hidden ItemEntry based on this. */
	public boolean isShowHidden()
	{
		return showHidden;
	}

	public static final class SourceEntry
	{
		private final String sourceKey;
		private final String sourceName;
		private final Integer sourceId;
		private final int killCount;
		private final Instant firstObservedAt;
		private final Instant lastObservedAt;
		private final boolean favorite;
		private final boolean collapsed;
		private final List<ItemEntry> itemTotals;
		private final List<RecordEntry> records;
		private final List<String> rawSourceKeys;

		private SourceEntry(String sourceKey, String sourceName, Integer sourceId, int killCount,
			Instant firstObservedAt, Instant lastObservedAt, boolean favorite, boolean collapsed,
			List<ItemEntry> itemTotals, List<RecordEntry> records, List<String> rawSourceKeys)
		{
			this.sourceKey = sourceKey;
			this.sourceName = sourceName;
			this.sourceId = sourceId;
			this.killCount = killCount;
			this.firstObservedAt = firstObservedAt;
			this.lastObservedAt = lastObservedAt;
			this.favorite = favorite;
			this.collapsed = collapsed;
			this.itemTotals = itemTotals;
			this.records = records;
			this.rawSourceKeys = rawSourceKeys;
		}

		/** The CANONICAL (player-facing) identity -- see class javadoc's CANONICAL PLAYER-FACING IDENTITY note. Never a valid {@link LootTrackerPreferences} key on its own; use {@link #getRawSourceKeys()} for preference reads/writes. */
		public String getSourceKey()
		{
			return sourceKey;
		}

		public String getSourceName()
		{
			return sourceName;
		}

		/** The FIRST raw member's sourceId -- representative only (a merged canonical entry can span several raw composition ids); not used for identity or preference keys. */
		public Integer getSourceId()
		{
			return sourceId;
		}

		/** Same authoritative per-raw-source occurrence count as {@link LootTrackerSource#getKillCount()}, summed across every raw variant this canonical entry represents -- see that method's own honest-kill-count javadoc. */
		public int getKillCount()
		{
			return killCount;
		}

		public Instant getFirstObservedAt()
		{
			return firstObservedAt;
		}

		public Instant getLastObservedAt()
		{
			return lastObservedAt;
		}

		public boolean isFavorite()
		{
			return favorite;
		}

		public boolean isCollapsed()
		{
			return collapsed;
		}

		/** Grouped view -- one entry per distinct item, quantity summed across every (post-watermark) record from every raw variant this canonical entry represents. */
		public List<ItemEntry> getItemTotals()
		{
			return itemTotals;
		}

		/** Individual-drop view -- one entry per atomic SERVER_NPC_LOOT record from every raw variant this canonical entry represents, merged into one true oldest-first chronological timeline. */
		public List<RecordEntry> getRecords()
		{
			return records;
		}

		/**
		 * Every raw {@link LootTrackerIndex#sourceKey} (sourceName+sourceId)
		 * this canonical, player-facing entry represents -- almost always
		 * one, sometimes several when OSRS/RuneLite assigns multiple
		 * composition ids to what is visually one logical NPC (see class
		 * javadoc's CANONICAL PLAYER-FACING IDENTITY note). Raw telemetry
		 * identity is NEVER lost -- this list is exactly how a caller finds
		 * it again. {@link LootTrackerPreferences} (favorite/collapsed/
		 * hidden-item/reset-watermark) is keyed ONLY by raw sourceKey, never
		 * by this entry's own canonical {@link #getSourceKey()} -- a UI
		 * action on this card (favorite/hide/collapse/reset) must be applied
		 * to EVERY key in this list so it stays consistent with how this
		 * entry's favorite/collapsed/hidden flags above were themselves
		 * computed (OR across the group), and so a raw variant discovered
		 * later under the same display name inherits the group's already-set
		 * preferences the next time an action is taken on the merged card.
		 */
		public List<String> getRawSourceKeys()
		{
			return rawSourceKeys;
		}
	}

	/**
	 * IMPLEMENTS LootPricing.Priceable (Spyglass Phase 2) -- see that
	 * interface's own javadoc for why this and Current Session's own
	 * {@code CurrentSessionSnapshot.LootEntry} share the one valuation/
	 * sort implementation rather than duplicating it.
	 */
	public static final class ItemEntry implements com.osrstelemetry.plugin.ui.LootPricing.Priceable
	{
		private final int itemId;
		private final String itemName;
		private final long quantity;
		private final boolean hidden;

		private ItemEntry(int itemId, String itemName, long quantity, boolean hidden)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
			this.hidden = hidden;
		}

		/** Never null -- a LootTrackerRecord's itemId is always a real, non-nullable int (see LootTrackerItem). Boxed here only to satisfy LootPricing.Priceable's shared shape. */
		public Integer getItemId()
		{
			return itemId;
		}

		/** The unboxed form, for callers that never need the Priceable-shared shape (e.g. hidden-item lookups by raw id). */
		public int getItemIdValue()
		{
			return itemId;
		}

		public String getItemName()
		{
			return itemName;
		}

		public long getQuantity()
		{
			return quantity;
		}

		/** Spec: hidden is source-specific and presentation-only -- a hidden item still counts toward every total. */
		public boolean isHidden()
		{
			return hidden;
		}
	}

	public static final class RecordEntry
	{
		private final Instant observedAt;
		private final List<ItemEntry> items;

		private RecordEntry(Instant observedAt, List<ItemEntry> items)
		{
			this.observedAt = observedAt;
			this.items = items;
		}

		public Instant getObservedAt()
		{
			return observedAt;
		}

		public List<ItemEntry> getItems()
		{
			return items;
		}
	}
}

