package com.osrstelemetry.plugin.loottracker;

/**
 * One item stack within one atomic {@code SERVER_NPC_LOOT} drop record -- the Loot
 * Tracker's own equivalent of {@code EventPayloads.ServerNpcLootItem},
 * kept as a SEPARATE, package-independent type rather than reusing that
 * events-package payload class directly. This mirrors the existing
 * project convention of a durable telemetry payload (events package)
 * being distinct from the pure UI/domain shape derived from it (see
 * CurrentSessionSnapshot.LootEntry vs SessionAggregates.LootItemAggregate)
 * -- the Loot Tracker's own domain model must not take on a compile-time
 * dependency on the telemetry envelope shape, so a future change to one
 * never silently breaks the other.
 *
 * Immutable value type -- plain equals/hashCode by field, no Lombok
 * dependency needed for a type this small.
 */
public final class LootTrackerItem
{
	private final int itemId;
	private final String itemName;
	private final long quantity;

	public LootTrackerItem(int itemId, String itemName, long quantity)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.quantity = quantity;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getItemName()
	{
		return itemName;
	}

	public long getQuantity()
	{
		return quantity;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof LootTrackerItem))
		{
			return false;
		}
		LootTrackerItem other = (LootTrackerItem) o;
		return itemId == other.itemId
			&& quantity == other.quantity
			&& java.util.Objects.equals(itemName, other.itemName);
	}

	@Override
	public int hashCode()
	{
		return java.util.Objects.hash(itemId, itemName, quantity);
	}

	@Override
	public String toString()
	{
		return "LootTrackerItem{itemId=" + itemId + ", itemName=" + itemName + ", quantity=" + quantity + "}";
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonSyntaxException;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Durable rebuild: reads this account's {@code events.jsonl} directly (the SAME
 * append-only file {@code EventLedger} writes -- see
 * TelemetryPaths.eventsFile()'s own javadoc), extracts every
 * {@code SERVER_NPC_LOOT} line, and applies each one to a
 * {@link LootTrackerIndex}. This is what lets the Loot Tracker survive
 * a client restart with its full history intact, entirely independent
 * of any session-state file (Phase 2's "independence from session
 * lifecycle" requirement) and without needing a second, competing
 * persisted-state format of its own -- events.jsonl already IS the
 * durable source of truth for every SERVER_NPC_LOOT this account has
 * ever produced.
 *
 * PERFORMANCE (spec requirement -- "no full events.jsonl reread per
 * Swing tick"): this rebuild is a ONE-TIME cost, run exactly once at
 * plugin startup (see LootTrackerCoordinator), never on any Swing
 * Timer tick. After rebuild completes, every live update flows through
 * {@link LootTrackerIndex#apply(LootTrackerRecord)} directly (O(1)
 * amortized, no file IO) and every panel read flows through
 * {@link LootTrackerIndex#snapshotSources()} (an in-memory copy, no
 * file IO) -- this class is never touched again until the next full
 * plugin restart.
 *
 * RETENTION (spec requirement -- "~365 day retention, display only,
 * raw telemetry never deleted"): {@code minObservedAt} bounds what this
 * rebuild loads into the LIVE in-memory index -- lines older than that
 * are simply not parsed into a LootTrackerRecord at all. This is a
 * memory-bounding decision for the live read-model only; events.jsonl
 * ITSELF is never read destructively (a plain sequential read, never a
 * rewrite) and nothing on disk is ever deleted, trimmed, or modified by
 * this class. A caller wanting a longer effective retention window
 * simply passes an earlier {@code minObservedAt} (or {@code null} for
 * "no bound, load everything") -- the bound lives entirely at the call
 * site, not hardcoded here.
 *
 * DEDUP: relies entirely on {@link LootTrackerIndex#apply}'s own
 * eventId-based dedup (see that method's javadoc) -- this class does no
 * deduplication of its own, so re-running a rebuild against the same
 * index is always safe (idempotent) by construction.
 *
 * FAILURE HANDLING: matches this project's established
 * {@code LocalStateStore.readIfExists()} fail-open discipline -- a
 * missing events.jsonl, an unreadable file, or an individual malformed
 * line never crashes plugin startup. A malformed/unparseable LINE is
 * skipped and logged (the rest of the file is still processed); a
 * missing file simply yields an empty index (a brand new account, or
 * telemetry collection never enabled yet).
 */
@Slf4j
public final class LootTrackerPersistence
{
	private final Gson gson;

	/**
	 * @param gson RuneLite's injected Gson (passed down from
	 * LootTrackerCoordinator's own constructor injection) -- this class
	 * is not itself Guice-managed, so it is not annotated {@code @Inject}.
	 */
	public LootTrackerPersistence(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Reads {@code events.jsonl} for {@code accountHash} line by line
	 * (streamed, never loading the whole file into memory at once --
	 * this file can grow to contain every telemetry event this account
	 * has ever produced, not just loot) and applies every qualifying
	 * {@code SERVER_NPC_LOOT} record to {@code index}.
	 *
	 * @param minObservedAt records observed strictly before this instant
	 * are not loaded (retention bound -- see class javadoc); pass null
	 * for no bound.
	 * @return the number of records newly applied (post-dedup) -- purely
	 * informational, for startup logging.
	 */
	public int rebuild(long accountHash, LootTrackerIndex index, Instant minObservedAt)
	{
		Filepath eventsFile = TelemetryPaths.eventsFile(accountHash);
		if (!eventsFile.exists())
		{
			return 0;
		}

		int applied = 0;
		int lineNumber = 0;
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(eventsFile.openInputStream(), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				lineNumber++;
				if (line.isEmpty())
				{
					continue;
				}
				LootTrackerRecord record = parseIfServerNpcLoot(line, lineNumber, minObservedAt);
				if (record != null && index.apply(record))
				{
					applied++;
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed reading events.jsonl for account {} during Loot Tracker rebuild; proceeding with whatever was applied so far", accountHash, e);
		}

		return applied;
	}

	/**
	 * Minimal envelope shape -- ONLY the fields this rebuild actually
	 * needs (eventId, eventType, occurredAt), plus the payload kept as a
	 * raw {@link JsonElement} so it is only deserialized into a concrete
	 * {@code EventPayloads.ServerNpcLoot} for lines that actually are
	 * one. Deliberately does NOT reuse {@code events.TelemetryEvent}
	 * itself as the read-side type: that class's {@code payload} field
	 * is typed {@code Object}, which Gson cannot deserialize back into a
	 * concrete payload class on its own (it would produce a raw
	 * {@code LinkedTreeMap}, not an {@code EventPayloads.ServerNpcLoot})
	 * -- reading a polymorphic envelope back is a fundamentally different
	 * operation from writing one, so a separate, read-side-only shape is
	 * the correct fix, not a shared type.
	 */
	private static final class RawEnvelope
	{
		String eventId;
		EventType eventType;
		String occurredAt;
		JsonElement payload;
	}

	private LootTrackerRecord parseIfServerNpcLoot(String line, int lineNumber, Instant minObservedAt)
	{
		RawEnvelope envelope;
		try
		{
			envelope = gson.fromJson(line, RawEnvelope.class);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Skipping malformed events.jsonl line {} during Loot Tracker rebuild", lineNumber, e);
			return null;
		}

		if (envelope == null || envelope.eventType != EventType.SERVER_NPC_LOOT || envelope.payload == null)
		{
			return null;
		}

		Instant observedAt = parseInstantOrNull(envelope.occurredAt);
		if (observedAt != null && minObservedAt != null && observedAt.isBefore(minObservedAt))
		{
			return null;
		}

		EventPayloads.ServerNpcLoot payload;
		try
		{
			payload = gson.fromJson(envelope.payload, EventPayloads.ServerNpcLoot.class);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Skipping events.jsonl line {} with malformed SERVER_NPC_LOOT payload during Loot Tracker rebuild", lineNumber, e);
			return null;
		}
		if (payload == null)
		{
			return null;
		}

		List<LootTrackerItem> items = new ArrayList<>();
		if (payload.getItems() != null)
		{
			for (EventPayloads.ServerNpcLootItem item : payload.getItems())
			{
				items.add(new LootTrackerItem(item.getItemId(), item.getItemName(), item.getQuantity()));
			}
		}

		return new LootTrackerRecord(envelope.eventId, payload.getSourceName(), payload.getSourceId(), observedAt, items);
	}

	private static Instant parseInstantOrNull(String occurredAt)
	{
		if (occurredAt == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(occurredAt);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.time.Instant;
import java.util.Collections;
import java.util.List;

/**
 * ONE atomic {@code SERVER_NPC_LOOT} notification, exactly as it happened -- the
 * Loot Tracker's fundamental unit of truth. Deliberately preserves the
 * SAME atomic event boundary {@code EventPayloads.ServerNpcLoot}
 * itself carries (one record = one real {@code net.runelite.client.
 * events.ServerNpcLoot} notification, i.e. one RuneLite-Loot-Tracker-
 * equivalent "kill" -- see LootTrackerIndex's own javadoc for the full
 * honest-kill-count audit) -- a "grouped" view is always a DERIVED
 * aggregation over a list of these records, never a replacement
 * representation, so the individual-drop view (spec requirement) can
 * always reconstruct real event boundaries rather than fabricating
 * them.
 *
 * eventId is the durable-rebuild dedup key (see LootTrackerPersistence):
 * the SAME UUID TelemetryEvent/EventLedger already generates for every
 * durably-appended envelope. It is nullable ONLY for the narrow case of
 * a live-applied record arriving through TelemetryEventListener, which
 * (by that interface's own existing contract -- see its javadoc) does
 * not currently pass the envelope's eventId through to listeners.
 * LootTrackerCoordinator synthesizes a fresh, process-local, guaranteed-
 * unique id for that case (see its own javadoc for why this is still
 * exact-once-safe) rather than leaving eventId genuinely null, so in
 * practice every record this project ever constructs has a real,
 * non-null eventId -- null is only ever a theoretical/defensive state
 * for this class's own dedup logic to fail safe against (treated as
 * "never dedup-skip" -- see LootTrackerIndex.apply()).
 */
public final class LootTrackerRecord
{
	private final String eventId;
	private final String sourceName;
	private final Integer sourceId;
	private final Instant observedAt;
	private final List<LootTrackerItem> items;

	public LootTrackerRecord(String eventId, String sourceName, Integer sourceId, Instant observedAt, List<LootTrackerItem> items)
	{
		this.eventId = eventId;
		this.sourceName = sourceName;
		this.sourceId = sourceId;
		this.observedAt = observedAt;
		this.items = Collections.unmodifiableList(new java.util.ArrayList<>(items));
	}

	public String getEventId()
	{
		return eventId;
	}

	public String getSourceName()
	{
		return sourceName;
	}

	public Integer getSourceId()
	{
		return sourceId;
	}

	public Instant getObservedAt()
	{
		return observedAt;
	}

	/** Immutable -- the exact item stacks from one real drop notification, in original order. */
	public List<LootTrackerItem> getItems()
	{
		return items;
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The one durable, in-memory read-model the Loot Tracker feature is
 * built on: a pure, RuneLite/Swing
 * -independent accumulator of {@link LootTrackerRecord}s, keyed by
 * STABLE source identity. Deliberately its own class, entirely
 * independent of {@code Session}/{@code SessionAggregates}/{@code
 * SessionLifecycleEngine} -- the spec's explicit "independence from
 * session lifecycle" requirement: this index has no concept of a
 * session at all, and is updated from EVERY {@code SERVER_NPC_LOOT}
 * event this account ever produces, whether or not a session happens to
 * be active at the time.
 *
 * SOLE AUTHORITATIVE SOURCE: only {@code EventType.SERVER_NPC_LOOT}
 * ever feeds this index (via {@link LootTrackerCoordinator} for live
 * events, {@link LootTrackerPersistence} for durable rebuild) -- never
 * {@code NPC_LOOT_ATTRIBUTED} (diagnostic-only, never proof of player
 * ownership -- see that SignalKind's own javadoc) and never any
 * session/XP/kill-count signal.
 *
 * HONEST KILL-COUNT SEMANTICS: each
 * {@link LootTrackerRecord} is exactly one real {@code
 * net.runelite.client.events.ServerNpcLoot} notification (see
 * ServerNpcLootCollector's own class javadoc for the verified-against-
 * source confirmation that this fires once per {@code addLoot(...)}
 * call in RuneLite's OWN core {@code LootTrackerPlugin}). Counting
 * records per source is therefore not an invented/approximated kill
 * count -- it is the exact same per-NPC-name occurrence count RuneLite's
 * own official Loot Tracker plugin already displays as that NPC's kill
 * count. This is never derived from NPC_DEATH (which this index never
 * even reads).
 *
 * STABLE SOURCE IDENTITY: keyed by (sourceName, sourceId) together --
 * see {@link #sourceKey(String, Integer)}. Two different sourceIds
 * under the same display name (e.g. a reskinned/instanced variant) are
 * DIFFERENT sources and are never merged, exactly per spec; a null
 * sourceId (see EventPayloads.ServerNpcLoot's own nullability javadoc)
 * is its own stable identity too, distinct from any real numeric id
 * sharing the same name.
 *
 * DEDUP: {@link #apply(LootTrackerRecord)} skips (returns false for) a
 * record whose non-null eventId has already been applied -- this is
 * what makes {@link LootTrackerPersistence}'s durable rebuild safe to
 * re-run without double-counting, and defends against a theoretically
 * corrupted/duplicated events.jsonl line. A record with a null eventId
 * is NEVER dedup-skipped (see LootTrackerRecord's own javadoc for why
 * this is fail-safe, not a real gap in practice).
 *
 * THREAD-SAFETY: {@code synchronized} methods -- the same simple,
 * well-understood concurrency primitive this project already prefers
 * over anything bespoke (see SessionRuntimeCoordinator's own
 * synchronized accessor). apply() is called from whatever thread
 * EventLedger's synchronous listener notification runs on (normally the
 * RuneLite client thread) or from the one-time durable-rebuild pass
 * (a plugin-startup background thread); {@link #snapshotSources()} is
 * called from the EDT on every panel poll tick. Neither call is
 * expensive enough for synchronized contention to matter in practice.
 */
public final class LootTrackerIndex
{
	private final Map<String, String> sourceNameByKey = new LinkedHashMap<>();
	private final Map<String, Integer> sourceIdByKey = new LinkedHashMap<>();
	private final Map<String, List<LootTrackerRecord>> recordsByKey = new LinkedHashMap<>();
	private final Set<String> appliedEventIds = new HashSet<>();

	/**
	 * @return true if this record was newly applied; false if it was
	 * skipped as an already-seen eventId (see class javadoc). Never
	 * throws on malformed input -- a record with a null/blank
	 * sourceName is still applied (grouped under a stable "unknown
	 * source" key) rather than dropped, matching this project's
	 * existing "never silently discard real telemetry" discipline.
	 */
	public synchronized boolean apply(LootTrackerRecord record)
	{
		if (record == null)
		{
			return false;
		}
		if (record.getEventId() != null && !appliedEventIds.add(record.getEventId()))
		{
			return false;
		}

		String key = sourceKey(record.getSourceName(), record.getSourceId());
		sourceNameByKey.putIfAbsent(key, record.getSourceName());
		sourceIdByKey.putIfAbsent(key, record.getSourceId());
		recordsByKey.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
		return true;
	}

	/**
	 * A fresh, immutable snapshot of every source currently known, in
	 * first-observed order. Cheap enough for an EDT poll tick (a handful
	 * of list copies, no file IO -- see LootTrackerPersistence for the
	 * one place any file IO happens) but still a real copy, never a live
	 * view, so a caller iterating this list is never affected by a
	 * concurrent apply().
	 */
	public synchronized List<LootTrackerSource> snapshotSources()
	{
		List<LootTrackerSource> sources = new ArrayList<>();
		for (Map.Entry<String, List<LootTrackerRecord>> entry : recordsByKey.entrySet())
		{
			String key = entry.getKey();
			if (entry.getValue().isEmpty())
			{
				continue;
			}
			sources.add(new LootTrackerSource(key, sourceNameByKey.get(key), sourceIdByKey.get(key), entry.getValue()));
		}
		return sources;
	}

	/**
	 * One source's snapshot by key, or null if unknown -- used by
	 * per-source operations (reset watermark, hide-item lookups) that
	 * already know which source they mean rather than re-scanning
	 * {@link #snapshotSources()}.
	 */
	public synchronized LootTrackerSource snapshotSource(String sourceKey)
	{
		List<LootTrackerRecord> records = recordsByKey.get(sourceKey);
		if (records == null || records.isEmpty())
		{
			return null;
		}
		return new LootTrackerSource(sourceKey, sourceNameByKey.get(sourceKey), sourceIdByKey.get(sourceKey), records);
	}

	/**
	 * Stable identity key: sourceName and sourceId joined by a single
	 * space, with the id ALWAYS rendered last as either decimal digits
	 * or the literal word "null" -- see class javadoc for why the two
	 * are never merged independently. Because the trailing token is
	 * always purely numeric-or-"null" (an id can never itself contain a
	 * space), the split between name and id stays unambiguous even when
	 * sourceName itself contains spaces -- e.g. name="A 2" id=3 ("A 2
	 * 3") can never collide with name="A" id=23 ("A 23"), since those
	 * produce different strings. A null sourceId becomes the literal
	 * string "null" (distinct from a real id, which can never
	 * legitimately render as that word), and a null sourceName becomes
	 * "" (empty) -- deterministic, and never fabricates a fallback
	 * display value itself; that is the caller's concern.
	 */
	public static String sourceKey(String sourceName, Integer sourceId)
	{
		String namePart = sourceName == null ? "" : sourceName;
		String idPart = sourceId == null ? "null" : sourceId.toString();
		return namePart + '�' + idPart;
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * One immutable snapshot of everything observed for one STABLE source identity
 * (sourceName + sourceId -- see LootTrackerIndex.sourceKey()'s own
 * javadoc for why the two are never merged even when only one of them
 * differs). Produced fresh by {@link LootTrackerIndex#snapshotSources()}
 * every time it is called; never itself mutated afterward -- the same
 * "immutable snapshot built fresh from mutable live state" split this
 * project's Current Session architecture already uses
 * (SessionAggregates -> CurrentSessionSnapshot).
 *
 * {@link #getRecords()} preserves the exact atomic
 * {@code SERVER_NPC_LOOT} event boundaries in observation order --
 * required by the spec's individual-drop view, which must reconstruct
 * real event boundaries rather than a fabricated one. {@link #getItemTotals()}
 * is a SEPARATE, derived aggregation over those same records for the
 * grouped view -- both views read from the same underlying records, so
 * they can never disagree with each other.
 */
public final class LootTrackerSource
{
	private final String sourceKey;
	private final String sourceName;
	private final Integer sourceId;
	private final List<LootTrackerRecord> records;

	LootTrackerSource(String sourceKey, String sourceName, Integer sourceId, List<LootTrackerRecord> records)
	{
		this.sourceKey = sourceKey;
		this.sourceName = sourceName;
		this.sourceId = sourceId;
		this.records = Collections.unmodifiableList(new ArrayList<>(records));
	}

	public String getSourceKey()
	{
		return sourceKey;
	}

	public String getSourceName()
	{
		return sourceName;
	}

	public Integer getSourceId()
	{
		return sourceId;
	}

	/** Every atomic drop record observed for this source, in observation order. Never empty (a source with zero records is never surfaced -- see LootTrackerIndex). */
	public List<LootTrackerRecord> getRecords()
	{
		return records;
	}

	/**
	 * The one reliable "kill count" for this source: the number of
	 * distinct atomic {@code SERVER_NPC_LOOT} notifications observed --
	 * exactly RuneLite's own core Loot Tracker's kill-count semantics
	 * (see LootTrackerIndex's own javadoc for the full source audit).
	 * Never derived from NPC_DEATH or any other signal.
	 */
	public int getKillCount()
	{
		return records.size();
	}

	public Instant getFirstObservedAt()
	{
		return records.isEmpty() ? null : records.get(0).getObservedAt();
	}

	public Instant getLastObservedAt()
	{
		return records.isEmpty() ? null : records.get(records.size() - 1).getObservedAt();
	}

	/**
	 * A new snapshot containing only records strictly AFTER
	 * {@code afterExclusive} (or this exact object, unfiltered, if
	 * {@code afterExclusive} is null) -- used by the UI-facing snapshot
	 * layer to apply a per-source RESET WATERMARK (see
	 * LootTrackerPreferences's own javadoc) without this class or
	 * {@link LootTrackerIndex} needing any concept of "reset" baked into
	 * their own pure telemetry-derivation logic. A reset is "forget
	 * everything AT OR BEFORE this point," so a record with
	 * {@code observedAt} exactly equal to {@code afterExclusive} is
	 * excluded too. A record with a null {@code observedAt} is always
	 * KEPT -- never silently dropped by a filter it has no timestamp to
	 * compare against.
	 */
	public LootTrackerSource filteredAfter(Instant afterExclusive)
	{
		if (afterExclusive == null)
		{
			return this;
		}
		List<LootTrackerRecord> filtered = new ArrayList<>();
		for (LootTrackerRecord record : records)
		{
			if (record.getObservedAt() == null || record.getObservedAt().isAfter(afterExclusive))
			{
				filtered.add(record);
			}
		}
		return new LootTrackerSource(sourceKey, sourceName, sourceId, filtered);
	}

	/**
	 * Grouped view: one entry per distinct itemId, quantity summed
	 * across every record, in FIRST-SEEN item order (a stable,
	 * deterministic base order -- callers doing value-based sorting,
	 * e.g. LootPricing, re-sort this themselves; this method makes no
	 * value/price assumption of its own).
	 */
	public List<LootTrackerItem> getItemTotals()
	{
		Map<Integer, Long> quantityByItemId = new LinkedHashMap<>();
		Map<Integer, String> nameByItemId = new LinkedHashMap<>();
		for (LootTrackerRecord record : records)
		{
			for (LootTrackerItem item : record.getItems())
			{
				quantityByItemId.merge(item.getItemId(), item.getQuantity(), Long::sum);
				nameByItemId.putIfAbsent(item.getItemId(), item.getItemName());
			}
		}

		List<LootTrackerItem> totals = new ArrayList<>();
		for (Map.Entry<Integer, Long> entry : quantityByItemId.entrySet())
		{
			totals.add(new LootTrackerItem(entry.getKey(), nameByItemId.get(entry.getKey()), entry.getValue()));
		}
		return totals;
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The Loot Tracker's own top-level runtime coordinator -- registered as a
 * {@link TelemetryEventListener} exactly like {@code
 * SessionRuntimeCoordinator} (see OsrsTelemetryPlugin's own
 * startUp()/shutDown() wiring for the paired addListener()/
 * removeListener() this class requires too), but otherwise entirely
 * UNRELATED to it: this class has no session/lifecycle/classifier
 * dependency of any kind (the spec's "independence from session
 * lifecycle" requirement), and owns its own {@link LootTrackerIndex}
 * rather than sharing or reading from {@code SessionAggregates}.
 *
 * ACCOUNT LOADING (mirrors SessionRuntimeCoordinator.ensureAccountLoaded()'s
 * own idempotency contract -- see its javadoc): a same-account call
 * (fresh plugin start already loaded, or a world hop/relog) is a
 * deliberate no-op; a genuine account change installs a brand-new,
 * empty index immediately (so the panel never shows one account's loot
 * under another's identity, even briefly) and kicks off a background
 * durable rebuild (see below) to repopulate it from that account's own
 * events.jsonl.
 *
 * WHY THE REBUILD RUNS ON A BACKGROUND THREAD, NOT THE CALLER'S: unlike
 * {@code SessionPersistence.loadCurrent()} (one small JSON file),
 * {@link LootTrackerPersistence#rebuild} reads this account's ENTIRE
 * events.jsonl -- potentially every telemetry event this account has
 * ever produced, not just loot. {@code ensureAccountLoaded()} is called
 * from {@code OsrsTelemetryPlugin.handleLogin()} via
 * {@code ClientThread.invokeLater()} (see that method's own javadoc for
 * why Client-thread-marshalled login handling exists at all) -- running
 * a potentially large sequential file read there would block the
 * client thread, exactly the class of mistake
 * {@code TelemetryEventListener}'s own javadoc warns listeners against.
 * {@link LootTrackerIndex} is fully thread-safe (synchronized methods),
 * so installing the fresh (initially empty) index synchronously and
 * then populating it progressively from a background thread is safe:
 * an EDT poll mid-rebuild simply sees a partially-populated, still
 * internally-consistent snapshot, never a torn/corrupted one.
 *
 * LIVE UPDATES: {@link #onEvent} applies every {@code SERVER_NPC_LOOT}
 * event directly to the CURRENT index (the same one
 * {@code ensureAccountLoaded()} installed/is populating), with no file
 * IO of its own -- cheap enough to run synchronously on whatever thread
 * {@code EventLedger} calls listeners from (normally the RuneLite
 * client thread), matching every other lightweight listener in this
 * project.
 *
 * SYNTHETIC eventId FOR LIVE RECORDS: {@code TelemetryEventListener.onEvent()}
 * does not currently pass the durable envelope's own eventId through to
 * listeners (see that interface's javadoc) -- this class assigns a
 * fresh, process-local {@code UUID} per live record instead. This is
 * safe because {@code EventLedger} calls every listener exactly once
 * per real {@code append()} (never replayed, never retried in-process
 * -- see EventLedger's own javadoc), so a live record can never need
 * dedup against ANOTHER live record; the only place real eventId-based
 * dedup matters is the durable rebuild reading actual envelope eventIds
 * back off disk (see LootTrackerPersistence), which this class never
 * interferes with because rebuild-for-account-N always completes (or is
 * in early, exclusively-background-thread progress) before any live
 * event for account N could plausibly be produced by actual gameplay.
 */
@Slf4j
@Singleton
public final class LootTrackerCoordinator implements TelemetryEventListener
{
	/**
	 * Spec: "~365 day retention (display only, raw telemetry never
	 * deleted)". Bounds what {@link #ensureAccountLoaded} loads into the
	 * LIVE in-memory index -- see LootTrackerPersistence's own javadoc
	 * for why this never touches anything on disk.
	 */
	public static final int RETENTION_DAYS = 365;

	private static final long NO_ACCOUNT = -1L;

	private final LootTrackerPersistence persistence;

	private volatile LootTrackerIndex index = new LootTrackerIndex();
	private volatile long currentAccountHash = NO_ACCOUNT;
	private ExecutorService rebuildExecutor;

	@Inject
	public LootTrackerCoordinator(Gson gson)
	{
		this.persistence = new LootTrackerPersistence(gson);
	}

	/** Paired with {@link #shutdown()} -- same start()/shutdown() lifecycle convention as EventLedger/LocalStateStore. */
	public synchronized void start()
	{
		if (rebuildExecutor != null && !rebuildExecutor.isShutdown())
		{
			return;
		}
		rebuildExecutor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-loot-tracker-rebuild");
			t.setDaemon(true);
			return t;
		});
	}

	public synchronized void shutdown()
	{
		ExecutorService executor = this.rebuildExecutor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("LootTrackerCoordinator rebuild executor did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the LootTrackerCoordinator rebuild executor; leaving it to keep draining in the background");
		}
	}

	/**
	 * Called from {@code OsrsTelemetryPlugin.handleLogin()} on every
	 * LOGGED_IN transition, exactly like
	 * {@code SessionRuntimeCoordinator.ensureAccountLoaded()} -- see
	 * class javadoc for the full idempotency/threading contract.
	 */
	public synchronized void ensureAccountLoaded(long accountHash)
	{
		if (accountHash == currentAccountHash)
		{
			return;
		}

		currentAccountHash = accountHash;
		LootTrackerIndex fresh = new LootTrackerIndex();
		index = fresh;

		ExecutorService executor = this.rebuildExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("ensureAccountLoaded() called while LootTrackerCoordinator is not started; Loot Tracker will remain empty for account {}", accountHash);
			return;
		}
		Instant cutoff = Instant.now().minus(RETENTION_DAYS, ChronoUnit.DAYS);
		executor.submit(() ->
		{
			int applied = persistence.rebuild(accountHash, fresh, cutoff);
			log.debug("Loot Tracker rebuild for account {} applied {} record(s)", accountHash, applied);
		});
	}

	@Override
	public void onEvent(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		if (type != EventType.SERVER_NPC_LOOT || !(payload instanceof EventPayloads.ServerNpcLoot))
		{
			return;
		}

		EventPayloads.ServerNpcLoot loot = (EventPayloads.ServerNpcLoot) payload;
		List<LootTrackerItem> items = new ArrayList<>();
		if (loot.getItems() != null)
		{
			for (EventPayloads.ServerNpcLootItem item : loot.getItems())
			{
				items.add(new LootTrackerItem(item.getItemId(), item.getItemName(), item.getQuantity()));
			}
		}

		LootTrackerRecord record = new LootTrackerRecord(
			UUID.randomUUID().toString(), loot.getSourceName(), loot.getSourceId(), observedAt, items);
		index.apply(record);
	}

	/** The current account's live index -- see class javadoc for why this reference can change on an account switch. */
	public LootTrackerIndex getIndex()
	{
		return index;
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Every piece of Loot Tracker UI PREFERENCE state that must survive a
 * restart, kept entirely SEPARATE from {@link LootTrackerIndex} (pure
 * telemetry-derived truth) -- the same "durable telemetry vs. durable
 * UI preference" split TelemetryPaths already draws between
 * {@code events.jsonl} and every {@code stateFile()} document. Nothing
 * in this class is telemetry: losing this file loses favorites/hidden
 * items/collapsed cards/reset points, never any actual loot history
 * (that always survives, unconditionally, in events.jsonl).
 *
 * FAVORITES ARE SOURCES, NOT ITEMS (spec requirement): {@link #favoriteSourceKeys}
 * holds {@link LootTrackerIndex#sourceKey} values.
 *
 * HIDDEN ITEMS ARE SOURCE-SPECIFIC (spec requirement): "hide" removes
 * one item from one source's PRESENTATION only -- see
 * {@link #isItemHidden}/{@link #hideItem}. Hidden loot still counts
 * toward every total (this class has no opinion on totals at all; it
 * only answers "hidden or not" -- the UI/valuation layer is what
 * decides whether to still include a hidden item's value, and the spec
 * requires that it does).
 *
 * RESET IS A LOGICAL WATERMARK, NEVER A DELETE (spec requirement):
 * {@link #getResetWatermark}/{@link #resetSource} store a per-source
 * Instant, "forget everything AT OR BEFORE this point" for DISPLAY
 * purposes only. {@link LootTrackerIndex} itself is never told about
 * this and never has anything removed from it -- the watermark is
 * applied at the UI-facing snapshot layer (see the Loot Tracker view
 * model), which is what makes a reset survive a full durable rebuild
 * (a rebuild re-applies every historical record exactly as before; the
 * watermark alone is what keeps them display-suppressed) without this
 * class or {@link LootTrackerIndex} needing to coordinate rebuild
 * ordering with each other at all.
 *
 * PERSISTENCE: one small JSON document, {@code loot_tracker_preferences.json},
 * written via the existing {@link LocalStateStore} (async, atomic
 * rename -- same durability guarantees every other state document in
 * this project already gets). An in-memory copy is kept authoritative
 * between writes (read-your-own-write consistency for the UI, which
 * polls this class far more often than any write actually happens) --
 * mirrors LiveXpTracker/lastKnownAbsoluteXpBySkill's own "authoritative
 * in-memory, asynchronously durable" split elsewhere in this project.
 */
@Singleton
public final class LootTrackerPreferences
{
	private static final String CATEGORY = "loot_tracker_preferences";

	/** The exact document persisted to disk -- a plain data holder, deliberately with no behavior of its own. */
	static final class Document
	{
		Set<String> favoriteSourceKeys = new HashSet<>();
		Map<String, Set<Integer>> hiddenItemIdsBySourceKey = new HashMap<>();
		Set<String> collapsedSourceKeys = new HashSet<>();
		/** sourceKey -> ISO-8601 Instant string (this project's established timestamp convention). */
		Map<String, String> resetWatermarkBySourceKey = new HashMap<>();
		/** Spec: "Show hidden" toggle, default OFF. */
		boolean showHidden = false;
	}

	private static final long NO_ACCOUNT = -1L;

	private final LocalStateStore store;
	private long accountHash = NO_ACCOUNT;
	private Document document = new Document();

	@Inject
	public LootTrackerPreferences(LocalStateStore store)
	{
		this.store = store;
	}

	/**
	 * Loads this account's persisted preferences (or starts a fresh,
	 * all-default document if none exist yet -- a brand-new account, or
	 * a pre-Phase-2 install that never had this file). Safe to call on
	 * EVERY {@code OsrsTelemetryPlugin.handleLogin()} transition
	 * unconditionally (mirrors {@code SessionRuntimeCoordinator.
	 * ensureAccountLoaded()}'s own same-account-is-a-no-op contract): a
	 * same-account call (a world hop/relog, or a duplicate fresh-start
	 * call) is a deliberate no-op, so an in-flight but not-yet-durably-
	 * written preference mutation from just before the hop is never
	 * discarded by re-reading a possibly-stale copy off disk. A best-
	 * effort synchronous read (see LocalStateStore.readIfExists()'s own
	 * fail-open javadoc), acceptable here for the exact same reason it's
	 * already acceptable there: a single small JSON document, read at
	 * most once per genuine account change, not on any hot path.
	 */
	public synchronized void loadForAccount(long accountHash)
	{
		if (accountHash == this.accountHash)
		{
			return;
		}
		this.accountHash = accountHash;
		Document loaded = store.readIfExists(TelemetryPaths.stateFile(accountHash, CATEGORY), Document.class);
		this.document = loaded != null ? loaded : new Document();
		if (document.favoriteSourceKeys == null)
		{
			document.favoriteSourceKeys = new HashSet<>();
		}
		if (document.hiddenItemIdsBySourceKey == null)
		{
			document.hiddenItemIdsBySourceKey = new HashMap<>();
		}
		if (document.collapsedSourceKeys == null)
		{
			document.collapsedSourceKeys = new HashSet<>();
		}
		if (document.resetWatermarkBySourceKey == null)
		{
			document.resetWatermarkBySourceKey = new HashMap<>();
		}
	}

	private synchronized void persist()
	{
		store.write(TelemetryPaths.stateFile(accountHash, CATEGORY), document);
	}

	public synchronized boolean isFavorite(String sourceKey)
	{
		return document.favoriteSourceKeys.contains(sourceKey);
	}

	public synchronized void setFavorite(String sourceKey, boolean favorite)
	{
		if (favorite)
		{
			document.favoriteSourceKeys.add(sourceKey);
		}
		else
		{
			document.favoriteSourceKeys.remove(sourceKey);
		}
		persist();
	}

	public synchronized boolean isItemHidden(String sourceKey, int itemId)
	{
		Set<Integer> hidden = document.hiddenItemIdsBySourceKey.get(sourceKey);
		return hidden != null && hidden.contains(itemId);
	}

	public synchronized void setItemHidden(String sourceKey, int itemId, boolean hidden)
	{
		if (hidden)
		{
			document.hiddenItemIdsBySourceKey.computeIfAbsent(sourceKey, k -> new HashSet<>()).add(itemId);
		}
		else
		{
			Set<Integer> set = document.hiddenItemIdsBySourceKey.get(sourceKey);
			if (set != null)
			{
				set.remove(itemId);
				if (set.isEmpty())
				{
					document.hiddenItemIdsBySourceKey.remove(sourceKey);
				}
			}
		}
		persist();
	}

	public synchronized boolean isShowHidden()
	{
		return document.showHidden;
	}

	public synchronized void setShowHidden(boolean showHidden)
	{
		document.showHidden = showHidden;
		persist();
	}

	public synchronized boolean isCollapsed(String sourceKey)
	{
		return document.collapsedSourceKeys.contains(sourceKey);
	}

	public synchronized void setCollapsed(String sourceKey, boolean collapsed)
	{
		if (collapsed)
		{
			document.collapsedSourceKeys.add(sourceKey);
		}
		else
		{
			document.collapsedSourceKeys.remove(sourceKey);
		}
		persist();
	}

	/** Null if this source has never been reset. */
	public synchronized Instant getResetWatermark(String sourceKey)
	{
		String iso = document.resetWatermarkBySourceKey.get(sourceKey);
		if (iso == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(iso);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	/**
	 * Requires the CALLER to have already obtained user confirmation
	 * (spec requirement -- "requires confirmation"); this method itself
	 * performs the reset unconditionally once called. {@code at} is
	 * normally {@code Instant.now()} -- passed in rather than computed
	 * here so this stays unit-testable with a fixed clock, matching this
	 * project's existing style (see CurrentSessionSnapshotTest's own
	 * fixed-Instant convention).
	 */
	public synchronized void resetSource(String sourceKey, Instant at)
	{
		document.resetWatermarkBySourceKey.put(sourceKey, at.toString());
		persist();
	}
}

