	/**
	 * Registers `taskName` with the union of its explicit `aliases` and
	 * its own singular form (trailing "s" stripped) -- see class javadoc
	 * ALGORITHM section. Both are always combined, exactly mirroring
	 * RuneLite's own `SlayerPlugin.rebuildTargetNames()`.
	 */
	private static void register(Map<String, Set<String>> table, String taskName, String... aliases)
	{
		String normalizedTask = normalize(taskName);
		Set<String> members = new HashSet<>();
		members.add(singularize(normalizedTask));
		for (String alias : aliases)
		{
			members.add(normalize(alias));
		}
		table.put(normalizedTask, Collections.unmodifiableSet(members));
	}

	/**
	 * @return true if `npcName` is a legitimate member of the NPC family
	 * `taskName` covers -- either an explicitly known alternative/
	 * superior/boss-form NPC (from the catalogued table above) or the
	 * task's own singular form. Never true for an NPC merely
	 * "similar-looking" to the task name; every comparison is an exact,
	 * normalized string match. False for a null taskName/npcName.
	 */
	static boolean belongsToTaskFamily(String taskName, String npcName)
	{
		if (taskName == null || npcName == null)
		{
			return false;
		}
		String normalizedNpc = normalize(npcName);
		String normalizedTask = normalize(taskName);
		Set<String> members = FAMILY_MEMBERS_NORMALIZED.get(normalizedTask);
		if (members != null)
		{
			return members.contains(normalizedNpc);
		}
		// UNCATALOGUED task (not in the table above -- see class javadoc's
		// "known coverage gaps" note, and the classifier report's own
		// coverage-gaps section). No explicit alias list exists to pair
		// with a singular-suffix strip, so -- and ONLY here, never for a
		// catalogued task -- that one fixed, deterministic transform
		// (identical to RuneLite's own unconditional
		// `taskName.replaceAll("s$", "")`) is applied alone. This is
		// still not fuzzy matching: it is one exact string comparison
		// against one exact, fixed transform of the task name, never an
		// approximate or scored match.
		return normalizedNpc.equals(singularize(normalizedTask));
	}

	private static String singularize(String normalizedTaskName)
	{
		return normalizedTaskName.endsWith("s")
			? normalizedTaskName.substring(0, normalizedTaskName.length() - 1)
			: normalizedTaskName;
	}

	private static String normalize(String s)
	{
		return s.trim().toLowerCase(Locale.ROOT);
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;

/**
 * The narrow runtime orchestration component: receives already-normalized
 * telemetry facts (via TelemetryEventListener, registered on
 * EventLedger), attaches account/tick/time context, converts them to
 * SessionSignal objects (via SessionEventMapper), batches same-tick
 * signals, resolves them (SessionSignalBatchResolver), updates
 * lifecycle (SessionLifecycleEngine), updates aggregates
 * (SessionAggregateUpdater), and persists the result
 * (SessionPersistence). Lives inside com.osrstelemetry.plugin.session
 * specifically because SessionSignalBatchResolver, its BatchResolution,
 * and MetricUpdate are package-private.
 *
 * THREADING MODEL: every method that touches currentAccountHash, engine,
 * classifierContext, or pendingSignals is `synchronized` on this
 * instance. This is a single, coherent ownership model -- "all
 * coordinator state mutation is serialized through one monitor" --
 * rather than field-by-field locking. It is required, not merely
 * defensive: onEvent() is NOT always called from the RuneLite client
 * thread (SkillsCollector's final XP-window flush can call
 * EventLedger.append() from shutDown() on the AWT thread -- see its own
 * audit note), onGameTick()/ensureAccountLoaded() run on the client
 * thread, and finalizeForClientShutdownBlocking() runs on RuneLite's
 * shared scheduledExecutor thread via the ClientShutdown hook below.
 * Without one shared monitor, `engine`/`classifierContext` -- plain
 * fields reassigned on one thread and read on another with no
 * synchronization at all -- would be a genuine, unguarded data race
 * (not just "stale value": no happens-before edge existed at all in the
 * pre-hardening version of this class). None of these methods block on
 * I/O while holding the monitor except finalizeForClientShutdownBlocking()'s
 * one bounded, synchronous persistCurrentAndWait() call, which happens
 * only once, at genuine client shutdown, and calls nothing that could
 * ever need this same monitor back -- no deadlock risk.
 *
 * DOES NOT RE-PARSE events.jsonl, DOES NOT DUPLICATE COLLECTOR TRUTH
 * LOGIC -- unchanged from the original design; see SessionEventMapper's
 * own javadoc.
 *
 * TICK-BATCH CLOSURE: the original version resolved every pending signal on every
 * GameTick, on the assumption that "GameTick fires after all of that
 * tick's other events." That assumption covers ordinary state-change
 * events (StatChanged, VarbitChanged, ActorDeath, NpcLootReceived,
 * ServerNpcLoot -- all confirmed posted before GameTick), but NOT
 * telemetry emitted from within ANOTHER subscriber's OWN onGameTick()
 * handler for the very same tick -- e.g. this plugin's own periodic
 * skillsCollector.closeXpWindowsIfDue()/questCollector.checkAndFlush()
 * calls, both invoked from OsrsTelemetryPlugin.onGameTick(). RuneLite's
 * EventBus does not guarantee this coordinator's onGameTick() runs
 * AFTER every other subscriber's onGameTick() for the same event, so a
 * same-tick XP_CHANGE emitted that way could have been enqueued into
 * pendingSignals AFTER this coordinator had already drained and
 * resolved that same tick -- silently deferring it into the WRONG
 * (next) tick's batch and reproducing exactly the "transient wrong
 * activity before the real one" bug the whole batching design exists
 * to prevent.
 *
 * FIX: a signal is only ever resolved once a STRICTLY LATER tick number
 * has actually been observed (see processTick()/isClosed()) -- never
 * merely because "a GameTick callback started." RuneLite only posts
 * GameTick for tick N+1 after every subscriber's handling of tick N
 * (including any telemetry emitted mid-handling) is completely done, so
 * observing tick N+1 is a genuine, structural proof that tick N is
 * closed -- no sleep, no subscriber-order assumption. This defers
 * ordinary per-tick resolution by at most one tick (~600ms), which is
 * an explicitly acceptable trade-off (no test in this project requires
 * zero-latency resolution). At real shutdown/ClientShutdown, nothing
 * more can ever arrive for any tick, so flushPendingAndShutdown()/
 * finalizeForClientShutdownBlocking() flush EVERYTHING unconditionally
 * via flushAllPendingSignals(), bypassing the closed-tick wait entirely
 * -- never lose the final pending batch merely because the client stops.
 */
@Slf4j
@Singleton
public final class SessionRuntimeCoordinator implements TelemetryEventListener
{
	private static final long NO_ACCOUNT = -1L;

	// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A) -- lifecycle
	// distinction between a REAL client shutdown and a manual plugin
	// disable. Set (never by timing inference) the moment RuneLite's
	// ClientShutdown event reaches this coordinator; flushPendingAndShutdown()
	// reads it so a Plugin.shutDown() that follows a client shutdown does
	// not finalize/clear the candidate ClientShutdown just preserved for
	// the next process. Never reset: nothing in this process runs after
	// ClientShutdown except exit. Guarded by this instance's monitor.
	private boolean clientShutdownBegun;

	@Inject
	private Client client;

	@Inject
	private ScheduledExecutorService scheduledExecutor;

	private final SessionPersistence persistence;
	private final ActivitySignalClassifier classifier = new ActivitySignalClassifier();
	private List<SessionSignal> pendingSignals = new ArrayList<>();

	private long currentAccountHash = NO_ACCOUNT;
	private SessionLifecycleEngine engine = new SessionLifecycleEngine();
	private ClassifierContext classifierContext = new ClassifierContext();

	/**
	 * See {@link LiveXpTracker}'s own javadoc for the full
	 * contract. Owned here (never durable, never persisted) alongside
	 * `engine`/`classifierContext` -- reset on account switch (see
	 * ensureAccountLoaded()), fed by recordLiveXpDelta() (raw
	 * StatChanged, via SkillsCollector), reconciled inside
	 * applyMetrics() whenever a real durable XP metric lands, and read
	 * by getCurrentSessionSnapshot() under this same monitor.
	 */
	private final LiveXpTracker liveXpTracker = new LiveXpTracker();

	/**
	 * The most recently observed ABSOLUTE XP value for every
	 * skill, fed continuously by SkillsCollector's own raw StatChanged
	 * stream (see noteAbsoluteXp()'s own javadoc) -- the SAME underlying
	 * observations LiveXpTracker's own pending deltas are built from,
	 * just kept as running absolute totals here instead of pending
	 * deltas. NOT session-scoped by itself (it is simply "the latest
	 * known XP per skill, full stop") -- it only becomes session-boundary
	 * data at the exact moment a real switch is detected, when its
	 * current contents are snapshotted into ClassifierContext (see
	 * resolveAndApplyBatches()'s own call to
	 * classifierContext.noteSessionSwitchXpBaseline()). Reset on account
	 * switch (see ensureAccountLoaded()) so a brand-new account never
	 * inherits another account's absolute XP figures.
	 */
	private final Map<String, Long> lastKnownAbsoluteXpBySkill = new HashMap<>();

	// Live in SessionRuntimeCoordinatorTest.java (a real,
	// extensive existing test suite -- device-tree inspection found
	// two call sites, `new SessionRuntimeCoordinator(store)`) --
	// changing this signature outright would have broken that whole
	// file's compilation. Kept exactly as-is, no longer @Inject
	// (Guice only ever uses ONE constructor; the new two-arg one below
	// is what production wiring now uses), delegating to a null
	// archive -- LoadoutResolver treats that as "always unavailable"
	// rather than throwing (see its own javadoc), so every existing
	// test using this constructor keeps compiling and behaving exactly
	// as before.
	public SessionRuntimeCoordinator(LocalStateStore store)
	{
		this(store, null);
	}

	// Purely mechanical constructor-injection wiring so
	// SessionPersistence's starting/ending loadout resolution (see its
	// own javadoc) has real archive data to resolve against in
	// production. One new constructor parameter threaded straight
	// through to SessionPersistence's own (already backward-compatible)
	// two-arg constructor. No lifecycle/classifier/hysteresis/Slayer
	// logic anywhere in this class is touched; every synchronized
	// method, every field below, and the entire threading model
	// described in this class's own javadoc are unchanged.
	@Inject
	public SessionRuntimeCoordinator(LocalStateStore store, LoadoutArchive loadoutArchive)
	{
		this.persistence = new SessionPersistence(store, loadoutArchive);
	}

	/**
	 * Rehydration entry point. Called
	 * from OsrsTelemetryPlugin.handleLogin() on every LOGGED_IN
	 * transition; a same-account call (fresh start already loaded, or a
	 * world hop/relog) is a deliberate no-op (see class javadoc).
	 *
	 * ACCOUNT-SWITCH PENDING BATCH: a real switch away from account A now FLUSHES (not
	 * silently discards) anything still pending for A first -- that
	 * telemetry genuinely already occurred under A before the switch was
	 * observed, so finishing A's own already-occurred batch and
	 * persisting A's resulting state is the honest, no-fabrication
	 * choice, and it can never be applied to B's session (B's engine/
	 * context/pendingSignals do not exist yet at the point this runs).
	 */
	public synchronized void ensureAccountLoaded(long accountHash)
	{
		if (accountHash == currentAccountHash)
		{
			return;
		}

		if (currentAccountHash != NO_ACCOUNT)
		{
			flushAllPendingSignals();
			// CASE C (never-resolved boss-task candidate) -- account
			// switch: a pending self-consumption candidate that never got
			// to confirm/abort before this switch must not be silently
			// discarded by the fresh ClassifierContext below -- commit
			// its buffered metric(s) once, as a normal contextual metric,
			// to whatever session is legitimately current for the OLD
			// account right now (see flushAbandonedBossTaskCandidateIfMatching()'s
			// own javadoc).
			flushAbandonedBossTaskCandidateIfMatching(engine.getCurrentSession());
			persistence.persistCurrent(currentAccountHash, engine.getCurrentSession());

			// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): "no
			// candidate may disappear silently" -- an account switch is
			// exactly the account boundary this rule targets. The OLD
			// account's ONE parked interrupted candidate, if any, is
			// unconditionally resolved now, AT ITS OWN ORIGINAL
			// INTERRUPTION INSTANT (never `now`), and persisted under the
			// OLD accountHash ONLY -- never carried into, or attributed
			// to, the new account below.
			Session flushedInterruptedCandidate = engine.flushInterruptedCandidateForAccountBoundary();
			if (flushedInterruptedCandidate != null)
			{
				persistence.persistAdditionalFinalized(currentAccountHash, flushedInterruptedCandidate);
			}
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
		else
		{
			pendingSignals = new ArrayList<>();
		}

		currentAccountHash = accountHash;
		classifierContext = new ClassifierContext();
		// A brand-new account must never inherit
		// a stale live-XP owner/pending amount left over from whichever
		// account was previously loaded -- see LiveXpTracker.reset()'s
		// own javadoc.
		liveXpTracker.reset();
		// A brand-new account must never inherit
		// another account's absolute XP figures as a stale session-
		// boundary baseline -- see lastKnownAbsoluteXpBySkill's own
		// javadoc.
		lastKnownAbsoluteXpBySkill.clear();

		Session persisted = persistence.loadCurrent(accountHash);
		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): loaded
		// independently of `persisted` above -- the two have completely
		// separate lifecycle clocks (see class/feature javadoc), so one
		// missing/expiring never affects how the other rehydrates. Null
		// interruptedCandidateRecord (the common case -- most accounts
		// never have one parked) means "nothing to restore," fully
		// backward compatible with an account that predates this
		// feature.
		InterruptedCandidateRecord interruptedCandidateRecord = persistence.loadInterruptedCandidate(accountHash);
		SessionLifecycleEngine.RehydrationResult rehydrated = SessionLifecycleEngine.rehydrate(persisted, Instant.now(),
			interruptedCandidateRecord == null ? null : interruptedCandidateRecord.getSession(),
			interruptedCandidateRecord == null ? null : interruptedCandidateRecord.interruptedAtInstant(),
			interruptedCandidateRecord == null ? null : interruptedCandidateRecord.expiresAtInstant());
		engine = rehydrated.getEngine();

		if (rehydrated.getFinalizedDuringRehydration() != null)
		{
			persistence.persistFinalized(accountHash, rehydrated.getFinalizedDuringRehydration(), engine.getCurrentSession());
		}
		else
		{
			persistence.persistCurrent(accountHash, engine.getCurrentSession());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): if the
		// restored candidate's own window had already elapsed by now,
		// rehydrate() already finalized it (never resurrected) --
		// persist that exactly once and make sure no stale candidate
		// record lingers. Otherwise it is now restored onto `engine` as
		// the ONE resumable prior candidate -- re-persist it verbatim so
		// the on-disk record and the in-memory engine agree (a pure
		// no-op write when nothing changed).
		if (rehydrated.getFinalizedInterruptedCandidateDuringRehydration() != null)
		{
			persistence.persistAdditionalFinalized(accountHash, rehydrated.getFinalizedInterruptedCandidateDuringRehydration());
			persistence.clearInterruptedCandidate(accountHash);
		}
		else
		{
			syncInterruptedCandidatePersistence();
		}
	}

	/**
	 * TelemetryEventListener: called synchronously by EventLedger from
	 * inside append()/appendAndWait(), AFTER the durable write has
	 * already been accepted (see EventLedger's own ordering javadoc) --
	 * on whatever thread called append() (see class javadoc's THREADING
	 * MODEL). Deliberately cheap and in-memory only: builds a
	 * SessionSignal (or drops the event, if session-irrelevant) and
	 * queues it. No disk I/O, no lifecycle mutation happens here.
	 */
	@Override
	public synchronized void onEvent(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		if (accountHash != currentAccountHash)
		{
			// A stray event for an account this coordinator is no longer
			// (or not yet) tracking -- e.g. a late off-thread flush racing
			// an account switch. Conservatively dropped rather than
			// misattributed.
			return;
		}

		SessionSignal signal = SessionEventMapper.map(type, payload, observedAt);
		if (signal == null)
		{
			return;
		}

		Long tick = safeTickCount();
		if (tick != null)
		{
			signal = signal.withGameTick(tick);
		}

		pendingSignals.add(signal);
	}

	private Long safeTickCount()
	{
		try
		{
			if (client.isClientThread())
			{
				return (long) client.getTickCount();
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read game tick while ingesting a session signal", e);
		}
		return null;
	}

	/**
	 * The deterministic per-tick flush
	 * point. Reads the CURRENT tick from the client thread (this method
	 * is only ever invoked from onGameTick(), always on the client
	 * thread), then: (1) resolves and applies every pending signal
	 * belonging to a now-PROVABLY-CLOSED tick (strictly less than the
	 * current one -- see class javadoc's TICK-BATCH CLOSURE section);
	 * (2) advances the timeout clock. Step (1) always runs before step
	 * (2) -- events before a timeout boundary are applied before
	 * finalization, for every tick that is actually closed as of this
	 * call.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		processTick(client.getTickCount(), Instant.now());
	}

	synchronized void processTick(long currentTick, Instant now)
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}

		// TIMEOUT WATERMARK + SKIP-ADVANCE-AFTER-RESOLVE: two DIFFERENT
		// concerns addressing the same underlying principle -- EVENT-TIME ORDERING, NOT
		// PROCESSING-TIME ORDERING must govern a suspend/resume/finalize
		// decision whenever real qualifying evidence is already known.
		//
		// (a) flushClosedBatches() resolves every signal from a tick
		// that is now provably closed. If any of those batches actually
		// applied a real lifecycle transition (RESOLVED -- see
		// resolveAndApplyBatches()'s own javadoc), that transition
		// already used the BATCH's own event-time timestamp (via
		// SessionLifecycleEngine.onQualifyingActivity()/refineIdentity(),
		// which have their own correct, event-time-driven suspend/
		// resume/finalize logic built in). Calling advanceTime() again
		// immediately afterward, in this SAME call, using this call's
		// raw wall-clock `now`, would re-evaluate suspend/finalize using
		// PROCESSING time instead -- and if this tick's own processing
		// happened to run late (a slow tick, a delayed batch), that
		// stale `now` could immediately re-suspend/re-finalize a session
		// that the batch itself had just correctly resumed/extended from
		// its own true occurrence time. So when a real transition was
		// just applied, advanceTime() is deliberately NOT called here
		// -- any further idle-time evaluation is deferred to the
		// NEXT processTick() call, whose own `now` will by then be
		// genuinely current (at most one more tick, ~600ms, later under
		// ordinary play -- see class javadoc's TICK-BATCH CLOSURE
		// section for the same accepted latency trade-off).
		//
		// (b) When nothing was just resolved, timeoutWatermark() still
		// guards the ordinary advanceTime() call below against a
		// DIFFERENT case: a signal already sitting pending for the
		// CURRENT (still-open) tick that hasn't closed yet -- see its
		// own javadoc.
		boolean lifecycleTransitionJustApplied = flushClosedBatches(currentTick);
		if (lifecycleTransitionJustApplied)
		{
			return;
		}

		Instant watermark = timeoutWatermark(currentTick, now);

		Session before = engine.getCurrentSession();
		SessionState beforeState = before == null ? null : before.getState();

		LifecycleResult timeoutResult = engine.advanceTime(watermark);

		// Unconfirmed-candidate metrics duplicated across
		// sessions, Case 4: a pending weak-evidence candidate whose original
		// session's resume window simply expired here still had real,
		// never-confirmed metrics buffered against it -- commit them once,
		// as contextual metrics, to whichever session is finalizing as a
		// result of this same call, BEFORE that session is persisted, so
		// the immutable finalized record actually contains them.
		if (timeoutResult.getContextualMetricsTarget() != null)
		{
			applyMetrics(timeoutResult.getContextualMetricsTarget(), timeoutResult.getContextualMetrics());
		}

		// CASE C (never-resolved boss-task candidate) -- pure idle
		// timeout: a pending self-consumption candidate (an entirely
		// different, classifier-layer mechanism from the weak-evidence
		// candidate just above) is armed only while its boss session is ACTIVE. If
		// that session times out here (ACTIVE -> SUSPENDED, or, on a
		// later call, an already-SUSPENDED session's resume window
		// expiring to FINALIZED) with STILL no same-boss BOSS_KILL or
		// confirming loot ever having arrived, the candidate's buffered
		// metric(s) must not simply evaporate -- commit them once to
		// whichever of `beforeState`'s own session identities is still
		// legitimately current after this call (see
		// flushAbandonedBossTaskCandidateIfMatching()'s own javadoc),
		// BEFORE that session is persisted/finalized below.
		if (timeoutResult.getFinalized() != null)
		{
			flushAbandonedBossTaskCandidateIfMatching(timeoutResult.getFinalized());
		}
		else if (beforeState == SessionState.ACTIVE && timeoutResult.getCurrent() != null
			&& timeoutResult.getCurrent().getState() == SessionState.SUSPENDED)
		{
			flushAbandonedBossTaskCandidateIfMatching(timeoutResult.getCurrent());
		}

		if (timeoutResult.getFinalized() != null)
		{
			persistence.persistFinalized(currentAccountHash, timeoutResult.getFinalized(), timeoutResult.getCurrent());
		}
		else if (timeoutResult.getCurrent() != null && timeoutResult.getCurrent().getState() != beforeState)
		{
			persistence.persistCurrent(currentAccountHash, timeoutResult.getCurrent());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): independent of
		// timeoutResult.getFinalized() above -- "handle the edge case
		// where candidate expiry and current-session lifecycle work occur
		// on the same processing call/tick." advanceTime() never parks or
		// resumes anything itself (only onQualifyingActivity()'s real-
		// switch sites do), so the ONLY way the interrupted candidate
		// changes here is by quietly expiring in the background -- a
		// completely independent event from whatever `current`/B did this
		// same tick, and neither one is ever lost or duplicated.
		if (timeoutResult.getAdditionalFinalized() != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, timeoutResult.getAdditionalFinalized());
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
	}

	/**
	 * Caps `now` at the earliest observedAt among signals still pending
	 * for the CURRENT, not-yet-closed tick (gameTick == currentTick) --
	 * i.e. signals that are already known to have occurred, are already
	 * enqueued, and will be resolved the instant this tick closes (the
	 * very next processTick() call), but have not been applied yet.
	 * Intentionally scoped to gameTick == currentTick only, NOT to
	 * every pending signal: an untagged (off-client-thread) signal is a
	 * separate, pre-existing, documented case (see class javadoc's
	 * OFF-CLIENT-THREAD note) that is deliberately left pending until an
	 * unconditional flush (shutdown/account-switch) rather than ordinary
	 * tick closure, and folding it into this watermark would let one
	 * stray off-thread signal freeze timeout advancement indefinitely
	 * during otherwise-idle ordinary play -- a strictly worse outcome
	 * than the bug being fixed here. A signal tagged with an OLDER tick
	 * (< currentTick) is excluded too: flushClosedBatches() above has
	 * already resolved and applied it before this method is ever called,
	 * so it can no longer affect the watermark.
	 *
	 * STRICT INEQUALITY, NOT EQUALITY: the cap is the pending signal's own observedAt
	 * MINUS ONE NANOSECOND, not the observedAt itself. SessionLifecycleEngine
	 * deliberately treats "exactly at" a suspend/resume-expiry boundary
	 * as belonging to a REAL qualifying event arriving at that instant
	 * (onQualifyingActivity()'s inclusive !isAfter(resumeExpiry) check --
	 * see its own class javadoc's EXACT-BOUNDARY ASYMMETRY note), while
	 * advanceTime() alone reaching that same instant with no accompanying
	 * activity treats it as already-expired (its own inclusive
	 * !isBefore(expiry) check). If this watermark were allowed to equal
	 * the pending signal's observedAt exactly, advanceTime() would apply
	 * the "no accompanying activity" boundary rule at the very instant
	 * real, already-known, still-pending activity actually occurred --
	 * finalizing/suspending a session ahead of the qualifying event that
	 * was about to legitimately resume or extend it. Backing off by one
	 * nanosecond keeps advanceTime() strictly on the "before" side of
	 * that instant, leaving the exact-boundary decision entirely to the
	 * eventual onQualifyingActivity()/refineIdentity() call once the
	 * tick actually closes -- which is the only place that decision is
	 * allowed to be made from event-time.
	 *
	 * When nothing is pending for the current tick, returns `now`
	 * unchanged -- an idle session with no open activity times out on
	 * ordinary wall-clock time exactly as before this fix.
	 */
	private Instant timeoutWatermark(long currentTick, Instant now)
	{
		Instant watermark = now;
		for (SessionSignal signal : pendingSignals)
		{
			Long tick = signal.getGameTick();
			if (tick != null && tick == currentTick)
			{
				Instant cap = signal.getObservedAt().minusNanos(1);
				if (cap.isBefore(watermark))
				{
					watermark = cap;
				}
			}
		}
		return watermark;
	}

	/**
	 * Splits off and resolves every pending signal belonging to a tick
	 * strictly before currentTick -- i.e. a tick RuneLite has already
	 * fully finished dispatching, including every subscriber's own
	 * onGameTick()-driven telemetry for it (see class javadoc). Signals
	 * tagged with currentTick itself (still open -- this very GameTick
	 * dispatch may not be done yet) and any signal with no tick at all
	 * (the rare off-thread case -- see safeTickCount()) are left pending
	 * for a later call; an untagged signal is conservatively treated the
	 * same as "not yet provably closed" rather than flushed immediately,
	 * so it still gets at least one full tick to be joined by anything
	 * else from the same real game action before being resolved.
	 *
	 * @return true if any batch resolved here actually applied a real
	 * lifecycle transition (a RESOLVED outcome -- see
	 * resolveAndApplyBatches()'s own return-value javadoc). processTick()
	 * uses this to decide whether it is safe to also run advanceTime()
	 * in the same call -- see its own javadoc for why it must not.
	 */
	private boolean flushClosedBatches(long currentTick)
	{
		List<SessionSignal> closed = new ArrayList<>();
		List<SessionSignal> stillOpen = new ArrayList<>();
		for (SessionSignal signal : pendingSignals)
		{
			Long tick = signal.getGameTick();
			if (tick != null && tick < currentTick)
			{
				closed.add(signal);
			}
			else
			{
				stillOpen.add(signal);
			}
		}
		pendingSignals = stillOpen;
		return resolveAndApplyBatches(closed);
	}

	/**
	 * Unconditional flush of everything pending, regardless of tick
	 * closure -- used only when nothing more can possibly arrive for any
	 * tick (plugin disable, real account switch, client shutdown). See
	 * class javadoc's TICK-BATCH CLOSURE section for why the ordinary
	 * per-GameTick path (flushClosedBatches()) must NOT do this. Return
	 * value intentionally ignored by every caller of this method (none
	 * of them ever call advanceTime() afterward).
	 */
	private boolean flushAllPendingSignals()
	{
		List<SessionSignal> toProcess = pendingSignals;
		pendingSignals = new ArrayList<>();
		return resolveAndApplyBatches(toProcess);
	}

	/**
	 * @return true if at least one batch in `toProcess` had a RESOLVED
	 * outcome -- i.e. actually called engine.onQualifyingActivity()/
	 * refineIdentity() and mutated the session's lifecycle state (ACTIVE/
	 * SUSPENDED/FINALIZED, lastActiveAt, or activityIdentity). false for
	 * an empty input, or when every batch was NO_EVIDENCE/AMBIGUOUS
	 * (metrics may still have been applied to an already-current
	 * session in that case, but no lifecycle transition occurred).
	 */
	private boolean resolveAndApplyBatches(List<SessionSignal> toProcess)
	{
		if (toProcess.isEmpty())
		{
			return false;
		}

		boolean anyLifecycleTransitionApplied = false;

		List<List<SessionSignal>> batches = SessionSignalBatchResolver.groupIntoBatches(toProcess);
		for (List<SessionSignal> batch : batches)
		{
			Session preBatchCurrent = engine.getCurrentSession();
			SessionSignalBatchResolver.BatchResolution resolution =
				SessionSignalBatchResolver.resolve(batch, preBatchCurrent, classifier, classifierContext);

			// LOOT-WHILE-ACTIVE OWNERSHIP: applied directly to the pre-batch
			// `current` session, unconditionally, BEFORE any lifecycle
			// transition below -- see SessionSignalBatchResolver.resolve()'s
			// own comment for the full rationale. Whatever preBatchCurrent
			// goes on to become in this same call (unchanged `current`,
			// re-keyed via refineIdentity(), or finalized by a same-tick
			// switch) already carries this loot once this mutates it, so
			// it is never lost and never rides onto an unrelated new
			// session purely because that session happened to win this
			// batch's lifecycle decision.
			if (preBatchCurrent != null && !resolution.getPreBatchCurrentMetricUpdates().isEmpty())
			{
				applyMetrics(preBatchCurrent, resolution.getPreBatchCurrentMetricUpdates());
			}

			if (resolution.getOutcome() == BatchLifecycleOutcome.RESOLVED)
			{
				SignalClassification winning = resolution.getLifecycleClassification();
				// EVIDENCE STRENGTH: only
				// onQualifyingActivity() ever gates a transition behind the
				// weak-evidence candidate mechanism (see
				// SessionLifecycleEngine's own javadoc) -- refineIdentity()
				// never gates (it re-keys the SAME continuous activity, not
				// a competing one), so it has no strength parameter to
				// receive.
				LifecycleResult result = winning.getDecisionKind() == SignalDecisionKind.REFINE
					? engine.refineIdentity(winning.getIdentity(), resolution.getLifecycleTimestamp(), resolution.getMetricUpdates())
					: engine.onQualifyingActivity(winning.getIdentity(), resolution.getLifecycleTimestamp(), resolution.getMetricUpdates(), resolution.getLifecycleEvidenceStrength());
				anyLifecycleTransitionApplied = true;

				// A GENUINE session-identity switch
				// -- result.getCurrent() is a different session id than
				// whatever was current immediately before this batch
				// (never true for refineIdentity(), which always re-keys
				// the SAME continuous session/id) -- captures an exact
				// per-skill absolute-XP baseline for the brand-new
				// session, from whatever this coordinator has most
				// recently observed via SkillsCollector's raw StatChanged
				// stream. This is what lets a LATER XP_CHANGE, whose own
				// aggregation window spans this exact switch, be split
				// exactly into its pre-switch and post-switch portions --
				// see ClassifierContext.noteSessionSwitchXpBaseline()'s
				// own javadoc and classifyXpChange()'s boundary-ownership
				// rule for the full mechanism this baseline enables.
				if (result.getCurrent() != null
					&& (preBatchCurrent == null || !preBatchCurrent.getSessionId().equals(result.getCurrent().getSessionId())))
				{
					classifierContext.noteSessionSwitchXpBaseline(result.getCurrent().getSessionId(), lastKnownAbsoluteXpBySkill);
				}

				// CASE C (never-resolved boss-task candidate) -- an
				// UNRELATED real switch (a different boss's BOSS_KILL, a
				// SKILLING switch, any other authoritative evidence that
				// has nothing to do with this candidate) just finalized
				// the boss session a self-consumption candidate is still
				// pending for, without ever going through
				// classifyBossKill()/classifyServerNpcLoot()'s own
				// confirm/abort branches (those already clear the
				// candidate themselves -- this is a pure no-op whenever
				// they already ran). The candidate's buffered metric(s)
				// belong to real activity that genuinely occurred during
				// THAT now-finalizing session, so they are committed
				// there, once, BEFORE it is persisted -- never onto the
				// new, unrelated session this batch just started.
				if (result.getFinalized() != null)
				{
					flushAbandonedBossTaskCandidateIfMatching(result.getFinalized());
				}
				else if (result.getCurrent() != null
					&& (preBatchCurrent == null || !preBatchCurrent.getSessionId().equals(result.getCurrent().getSessionId()))
					&& engine.getInterruptedCandidate() != null)
				{
					// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): a
					// genuine switch just happened (result.getCurrent() is
					// a different session id than preBatchCurrent) but
					// result.getFinalized() is null -- the ONLY way that
					// combination arises is applyRealSwitch()'s PARK
					// outcome (see its own javadoc: RESUME and LEGACY
					// IMMEDIATE FINALIZE both always populate
					// result.getFinalized()). preBatchCurrent was just
					// parked as engine.getInterruptedCandidate() rather
					// than finalized -- exactly the same "stopped being
					// current for some other reason" case
					// flushAbandonedBossTaskCandidateIfMatching()'s own
					// javadoc already covers, just via parking instead of
					// finalizing.
					flushAbandonedBossTaskCandidateIfMatching(engine.getInterruptedCandidate());
				}

				// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A):
				// independent of result.getFinalized() above -- see
				// LifecycleResult's own javadoc on the dual-finalization
				// edge case. Never touches session_state.json (the
				// interrupted candidate, whether displaced or resumed-
				// away-from, is never what `current` is right now).
				if (result.getAdditionalFinalized() != null)
				{
					persistence.persistAdditionalFinalized(currentAccountHash, result.getAdditionalFinalized());
				}

				// Unconfirmed-candidate metrics duplicated
				// across sessions: this batch's own metrics no longer go
				// unconditionally to result.getCurrent() -- while a
				// weak-evidence candidate is merely being armed/replaced,
				// result.getCurrent() is still the OLD established
				// session, not any kind of holding area for this batch.
				// The engine now tells us exactly where this batch's own
				// metrics belong (metricsForCurrent -- empty when they
				// were only buffered as a pending candidate) and,
				// separately, whether an ABANDONED candidate's previously-
				// buffered metrics must be committed once, as contextual
				// metrics, to whichever session they actually occurred
				// during (contextualMetricsTarget/contextualMetrics --
				// see LifecycleResult's own javadoc). Applying both here,
				// to their own correct targets, is what makes every real
				// metric land exactly once.
				applyMetrics(result.getCurrent(), result.getMetricsForCurrent());
				if (result.getContextualMetricsTarget() != null)
				{
					applyMetrics(result.getContextualMetricsTarget(), result.getContextualMetrics());
				}

				if (result.getFinalized() != null)
				{
					// Immutable finalized record written before the
					// pointer is cleared/replaced -- SessionPersistence's
					// own existing write-then-callback ordering guarantee
					// (unchanged finalization ordering). The contextual-metrics apply
					// above already ran before this write whenever its
					// target was this same finalized session, so the
					// committed-once contextual metrics are included in
					// the immutable record.
					persistence.persistFinalized(currentAccountHash, result.getFinalized(), result.getCurrent());
				}
				else
				{
					persistence.persistCurrent(currentAccountHash, result.getCurrent());
				}
				syncInterruptedCandidatePersistence();
			}
			else
			{
				// NO_EVIDENCE or AMBIGUOUS: no lifecycle transition, but
				// every metric in the batch is still credited to whatever
				// session is ALREADY current -- never fabricated a place
				// to put it if there is none. preBatchCurrentMetricUpdates
				// (if any) were already applied to this exact same session
				// object above, so persistence just needs to fire whenever
				// EITHER list was non-empty.
				Session target = engine.getCurrentSession();
				boolean hasOrdinaryMetrics = !resolution.getMetricUpdates().isEmpty();
				boolean hasPreBatchCurrentMetrics = preBatchCurrent != null && !resolution.getPreBatchCurrentMetricUpdates().isEmpty();
				if (target != null && hasOrdinaryMetrics)
				{
					applyMetrics(target, resolution.getMetricUpdates());
				}
				if (target != null && (hasOrdinaryMetrics || hasPreBatchCurrentMetrics))
				{
					persistence.persistCurrent(currentAccountHash, target);
				}
			}
		}

		return anyLifecycleTransitionApplied;
	}

	private void applyMetrics(Session target, List<MetricUpdate> metrics)
	{
		if (target == null)
		{
			return;
		}
		for (MetricUpdate metric : metrics)
		{
			SessionAggregateUpdater.apply(target.getAggregates(), metric);
			// This durable application, the
			// instant it happens, now fully represents every raw StatChanged
			// gain for this (session, skill) pair up to this point -- so
			// the live, not-yet-represented portion resets to zero here,
			// in the SAME call that just made it durable. See
			// LiveXpTracker.reconcile()'s own javadoc for why this is
			// what guarantees an exact-once DISPLAY total (never double-
			// counts once XP_CHANGE catches up). A no-op for any metric
			// that isn't an XP metric (getXpSkill() null), and a no-op
			// whenever `target` isn't this tracker's current live-XP
			// owner (an abandoned/finalized session's own delayed
			// XP_CHANGE landing here via the contextual-metrics path --
			// never this tracker's live view of whatever is current now).
			if (metric.getXpSkill() != null)
			{
				liveXpTracker.reconcile(target.getSessionId(), metric.getXpSkill());
			}
		}
	}

	/**
	 * CASE C (never-resolved boss-task candidate) -- the deterministic
	 * fallback DESIRED RESOLUTION C asks for: a pending self-consumption
	 * candidate (see ClassifierContext's own javadoc) that never got to
	 * confirm (a same-boss BOSS_KILL) or abort (a real-switch-confirming
	 * loot) before its own boss session stops being current for ANY
	 * OTHER reason -- a pure idle timeout suspending/finalizing it, an
	 * unrelated authoritative switch finalizing it, or an account switch
	 * -- must not silently lose that candidate's buffered metric(s).
	 *
	 * `target` is always one of: the SAME session object the candidate
	 * was armed against (now merely SUSPENDED, still "legitimately
	 * current"), or that same session having just been FINALIZED this
	 * same call (about to be persisted as an immutable record). Never a
	 * brand-new, unrelated session -- this is exactly what "commit to
	 * whatever session is legitimately current at that point, never to a
	 * session that's already been finalized and persisted with
	 * different, already-locked-in contents" means: the flush always
	 * happens strictly BEFORE the persist/finalize call that makes
	 * `target` immutable, so there is never any retroactive mutation of
	 * an already-durable record -- mirroring exactly how
	 * SessionLifecycleEngine's own unrelated SUSPENDED
	 * weak-evidence candidate mechanism commits its own abandoned
	 * candidate's pendingCandidateMetrics.
	 *
	 * A no-op whenever `target` is null (nothing to attach to) or
	 * classifierContext holds no candidate for EXACTLY `target`'s own
	 * activity identity -- in particular, whenever
	 * classifyBossKill()/classifyServerNpcLoot() already resolved
	 * (confirmed or aborted) the candidate themselves during
	 * classification, this is already a no-op by the time it is called
	 * (the candidate is already cleared), so it never double-applies
	 * anything.
	 */
	private void flushAbandonedBossTaskCandidateIfMatching(Session target)
	{
		if (target == null || !classifierContext.hasBossTaskCandidateFor(target.getActivityIdentity()))
		{
			return;
		}
		List<MetricUpdate> buffered = classifierContext.getPendingBossTaskCandidateMetrics();
		classifierContext.clearBossTaskCandidate();
		applyMetrics(target, buffered);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A). Keeps the
	 * persisted interrupted-candidate record (see
	 * TelemetryPaths.interruptedCandidateFile()) in sync with
	 * engine.getInterruptedCandidate()'s own in-memory state for the
	 * CURRENT account -- called after any lifecycle-mutating engine call
	 * that could have parked, resumed, or displaced the ONE resumable
	 * candidate, so a client crash immediately afterward can never lose
	 * or resurrect stale candidate state ("persist the ONE interrupted
	 * candidate additively"). A pure no-op write (persist the same
	 * candidate again, or clear an already-absent one) whenever nothing
	 * actually changed -- correctness over write-avoidance here, since
	 * this file is small and this call site is not a hot per-tick path
	 * (see processTick()'s own comment for why THAT path does its own,
	 * narrower thing instead of calling this).
	 */
	private void syncInterruptedCandidatePersistence()
	{
		Session candidate = engine.getInterruptedCandidate();
		if (candidate != null)
		{
			persistence.persistInterruptedCandidate(currentAccountHash, candidate,
				engine.getInterruptedCandidateInterruptedAt(), engine.getInterruptedCandidateExpiresAt());
		}
		else
		{
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
	}

	/**
	 * Called from OsrsTelemetryPlugin.shutDown() -- see the fixed
	 * ordering note there: this MUST
	 * run, with the EventLedger listener still registered, AFTER every
	 * collector flush able to emit final telemetry (Bank, XP window).
	 * Flushes unconditionally (flushAllPendingSignals(), not the
	 * closed-tick-only path -- there is no further GameTick coming) and
	 * persists current state exactly as it is, WITHOUT calling
	 * advanceTime(): disabling the plugin is not itself a real
	 * inactivity gap.
	 */
	public synchronized void flushPendingAndShutdown()
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		flushAllPendingSignals();
		persistence.persistCurrent(currentAccountHash, engine.getCurrentSession());

		if (clientShutdownBegun)
		{
			// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): this
			// Plugin.shutDown() is part of a REAL client shutdown -- the
			// candidate is being preserved for the next process's
			// rehydrate(), never finalized/cleared here. Re-persisted
			// (not skipped) so the on-disk record is correct even if
			// this ran before ClientShutdown's own blocking write got
			// the monitor; LocalStateStore.shutdown() drains this write.
			syncInterruptedCandidatePersistence();
			return;
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): MANUAL plugin
		// disable (no ClientShutdown). Spyglass cannot observe gameplay
		// while disabled, so continuity with the parked candidate is
		// unknown -- it must not survive into a later re-enable.
		// Finalized exactly once AT ITS OWN ORIGINAL INTERRUPTION
		// INSTANT and cleared, exactly like the account-switch boundary.
		Session flushedInterruptedCandidate = engine.flushInterruptedCandidateForAccountBoundary();
		if (flushedInterruptedCandidate != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, flushedInterruptedCandidate);
		}
		persistence.clearInterruptedCandidate(currentAccountHash);
	}

	/**
	 * Mirrors
	 * ContainerCollector's own already-proven ClientShutdown durability
	 * pattern. Entirely separate from ContainerCollector's own hook --
	 * does not touch Bank's path.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		event.waitFor(beginClientShutdownFinalization());
	}

	CompletableFuture<Void> beginClientShutdownFinalization()
	{
		markClientShutdownBegun();
		return CompletableFuture.runAsync(this::finalizeForClientShutdownBlocking, scheduledExecutor);
	}

	/**
	 * Runs on RuneLite's shared scheduledExecutor thread, NOT the client
	 * thread -- this is exactly why every field this touches is guarded
	 * by this instance's monitor (see class javadoc's THREADING MODEL).
	 * The single persistCurrentAndWait() call blocks (bounded, 5s) while
	 * holding that monitor; nothing it calls can ever need the monitor
	 * back, so this cannot deadlock against onGameTick()/onEvent() --
	 * they simply wait if they happen to be called during this window.
	 */
	/** Records, synchronously on the thread delivering ClientShutdown,
	 * that this is a real client shutdown -- before the async
	 * finalization below is even scheduled, so a Plugin.shutDown()
	 * racing it can never mistake this for a manual disable. */
	synchronized void markClientShutdownBegun()
	{
		clientShutdownBegun = true;
	}

	synchronized void finalizeForClientShutdownBlocking()
	{
		clientShutdownBegun = true;
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		flushAllPendingSignals();
		persistence.persistCurrentAndWait(currentAccountHash, engine.getCurrentSession(), 5000);

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A) -- RESTART
		// DURABILITY FIX. Real client shutdown is exactly the restart
		// this feature must survive, so the parked candidate is NOT
		// finalized here (that previously made "A -> B -> close ->
		// restart -> A" always mint a fresh A whenever the async
		// finalize/clear writes happened to land before JVM exit). It is
		// instead durably re-persisted, BLOCKING like session_state.json
		// above (the JVM may exit as soon as this future completes), and
		// the next startup's rehydrate() restores it if still eligible or
		// finalizes it exactly once at its own T1 if not.
		persistence.persistInterruptedCandidateAndWait(currentAccountHash, engine.getInterruptedCandidate(),
			engine.getInterruptedCandidateInterruptedAt(), engine.getInterruptedCandidateExpiresAt(), 5000);
	}

	// =====================================================================
	// Test-only hooks (package-private; same "no Mockito, drive the real
	// production object directly" convention as every other test in this
	// package).
	// =====================================================================

	/** Bypasses onEvent()'s account filter and Client-dependent gameTick
	 * tagging -- tests build already-tick-tagged SessionSignal instances
	 * directly via its public static factories + withGameTick(). */
	synchronized void testEnqueueSignal(SessionSignal signal)
	{
		pendingSignals.add(signal);
	}

	/** Drives the same closed-tick-flush-then-advance-time pipeline
	 * onGameTick() does, without requiring a real GameTick event or
	 * Client. `currentTick` plays the role of client.getTickCount() --
	 * pass a value strictly greater than any pending signal's own
	 * gameTick to make it eligible for this call to resolve. */
	void testProcessTick(long currentTick, Instant now)
	{
		processTick(currentTick, now);
	}

	/**
	 * See SessionSnapshot's
	 * own javadoc for the exact defect this replaces. The panel's ONLY
	 * read path into runtime session state: builds and returns a fully
	 * immutable, defensively-copied {@link SessionSnapshot} of whatever
	 * session is currently ACTIVE/SUSPENDED (or {@link SessionSnapshot#absent()}
	 * if none), with the copy itself happening INSIDE this synchronized
	 * method -- i.e. under the exact same monitor every runtime-mutating
	 * method in this class (onEvent()/processTick()/ensureAccountLoaded()/
	 * finalizeForClientShutdownBlocking()) already holds while mutating
	 * this same Session/its aggregates. That is what makes the copy
	 * atomic with respect to concurrent runtime mutation: no client-
	 * thread/scheduledExecutor-thread mutation can be interleaved with
	 * {@link SessionSnapshot#capture(Session)}'s field-by-field reads,
	 * because both would require this same monitor.
	 *
	 * This deliberately supersedes the earlier {@code getCurrentSession()},
	 * which handed the UI the SAME live, mutable {@link Session} object
	 * the engine keeps mutating after the synchronized call returned --
	 * a genuine data race the moment the EDT read more than one field off
	 * it (see SessionSnapshot's javadoc for the full explanation). Once
	 * this method returns, the caller holds zero references to any live
	 * mutable Session/SessionAggregates/collection this coordinator owns.
	 *
	 * @return an immutable snapshot of the current session, or
	 * {@link SessionSnapshot#absent()} if none. Never reflects a
	 * FINALIZED session (see {@link SessionLifecycleEngine#getCurrentSession()}).
	 */
	public synchronized SessionSnapshot getCurrentSessionSnapshot()
	{
		Session current = engine.getCurrentSession();
		String sessionId = current == null ? null : current.getSessionId();
		// Threads a
		// defensive copy of lastKnownAbsoluteXpBySkill through the same
		// synchronized capture call as the live-pending-XP map above --
		// see SessionSnapshot#getAbsoluteXpBySkill()'s own javadoc for why
		// this is the one extra piece of state the Current Session panel's
		// level/progress display needs and nothing else already carries.
		return SessionSnapshot.capture(
			current,
			liveXpTracker.getPendingForSession(sessionId),
			new HashMap<>(lastKnownAbsoluteXpBySkill));
	}

	/**
	 * The separate live-XP notification path raw
	 * StatChanged feeds (see SkillsCollector.onStatChanged()'s own
	 * evaluateLiveXpDelta()) -- deliberately NOT routed through
	 * EventLedger/TelemetryEventListener/SessionSignal/the classifier at
	 * all: this is purely cosmetic, in-memory, non-durable bookkeeping
	 * for the player-facing panel, never lifecycle evidence and never a
	 * second XP MetricUpdate. `skillName` is attributed to whichever
	 * session is current AT THE MOMENT this is called (see
	 * LiveXpTracker.recordDelta()'s own javadoc for the exact ownership/
	 * session-switch rule) -- silently dropped if there is no current
	 * session yet to attach it to. `delta` must already be a genuine,
	 * positive gain (SkillsCollector's own evaluateLiveXpDelta() is
	 * responsible for filtering out first-observation reseeds and any
	 * decrease/reset before ever calling this); this method also
	 * independently ignores delta &lt;= 0 as defense in depth (see
	 * LiveXpTracker.recordDelta()).
	 */
	public synchronized void recordLiveXpDelta(String skillName, long delta)
	{
		Session current = engine.getCurrentSession();
		String sessionId = current == null ? null : current.getSessionId();
		liveXpTracker.recordDelta(sessionId, skillName, delta);
	}

	/**
	 * Called by SkillsCollector.onStatChanged() for EVERY
	 * skill on every raw StatChanged observation -- deliberately
	 * UNCONDITIONALLY, unlike recordLiveXpDelta() above (which is gated
	 * on a positive live delta): this is not a display concern, it is
	 * "the latest known absolute XP for this skill, full stop," and even
	 * a skill's very first (seed-only, zero-delta) observation is a
	 * genuine, exact absolute baseline worth keeping. See
	 * lastKnownAbsoluteXpBySkill's own javadoc for how this feeds the
	 * exact session-boundary split; a no-op for a null skill name.
	 */
	public synchronized void noteAbsoluteXp(String skillName, long absoluteXp)
	{
		if (skillName == null)
		{
			return;
		}
		lastKnownAbsoluteXpBySkill.put(skillName, absoluteXp);
	}

	/**
	 * The single backend hook
	 * behind the Current Session header's "Re-evaluate Session" button --
	 * "look at what I am doing RIGHT NOW and classify it again," never
	 * "forget all session rules." Called from CurrentSessionView's button
	 * handler via a non-blocking ClientThread.invokeLater() dispatch (see
	 * OsrsTelemetryPanel's own wiring) -- never directly on the EDT.
	 *
	 * EVIDENCE SOURCE: `currentNpcName`/`currentNpcId` are expected to be
	 * read by the caller, on the calling thread, from
	 * NpcInteractionTargetCollector.getCurrentNpcName()/getCurrentNpcId()
	 * immediately before this call (that collector's own javadoc documents
	 * both as safe off the client thread) -- the genuine, live, right-now
	 * interaction target, never a replayed/stale signal. `now` is expected
	 * to be Instant.now() at the same moment.
	 *
	 * INSUFFICIENT EVIDENCE -&gt; SAFE NO-OP: no current attackable NPC
	 * target at all (`currentNpcName` null/blank), or no account loaded
	 * yet, leaves the current session (if any) completely untouched -- no
	 * identity is ever invented or guessed. Likewise, whenever
	 * ActivitySignalClassifier.classifyManualNpcTarget() itself determines
	 * this observation makes no safe identity claim right now (its own
	 * METRIC_ONLY carve-out for generic combat evidence against a
	 * SUSPENDED specific session -- see decideCombatBranch()'s own
	 * javadoc), this is honored exactly like the ordinary pipeline does:
	 * no lifecycle mutation.
	 *
	 * REUSES EXISTING RULES, NEVER A COMPETING CLASSIFIER: identity
	 * construction and the refine-vs-switch-vs-ignore decision are both
	 * delegated entirely to ActivitySignalClassifier.classifyManualNpcTarget()
	 * (see its own javadoc) -- this method only threads the result through
	 * SessionLifecycleEngine exactly the way resolveAndApplyBatches() does
	 * for an ordinary RESOLVED batch (same applyMetrics()/
	 * flushAbandonedBossTaskCandidateIfMatching()/persistence calls). The
	 * ONLY thing manual about this call is EvidenceStrength.SPECIFIC,
	 * which is what lets it bypass SessionLifecycleEngine's ORDINARY-only
	 * weak-evidence candidate/stickiness gate for this one observation
	 * (see EvidenceStrength's own javadoc) -- every other safety rule
	 * (never fabricate SLAYER from bare task assignment; never downgrade a
	 * more-specific ACTIVE session via generic evidence; Slayer
	 * task-family membership; boss/task affinity) remains fully enforced,
	 * completely unchanged. Using SPECIFIC strength also means any
	 * still-pending weak-evidence candidate (stale candidate-activity
	 * state) is unconditionally ABANDONED by this call exactly as any
	 * other authoritative/specific arrival would abandon it -- its
	 * buffered metrics are safely, honestly committed once as contextual
	 * metrics to whichever session they actually occurred during (see
	 * SessionLifecycleEngine's own "AUTHORITATIVE/SPECIFIC evidence ...
	 * immediate switch" branches), never lost and never duplicated. This
	 * call also unconditionally refreshes the recent-NPC-target watch (see
	 * ClassifierContext.onNpcInteractionTarget()) to this exact
	 * observation, clearing any staleness there too.
	 *
	 * NEVER REWRITES HISTORY: this call always carries an EMPTY metrics
	 * list -- it can start/refine/switch session IDENTITY, but can never
	 * itself add a single point of XP/loot to any session's aggregates.
	 * Combined with SessionLifecycleEngine's own transition rules (a real
	 * switch finalizes the OLD session exactly as it stood and starts a
	 * brand-new one from `now` forward; an already-FINALIZED session is
	 * never touched by any later call), this can only ever affect the
	 * session current AT `now`, going forward -- never earlier XP, loot,
	 * duration, or an already-finalized record.
	 */
	public synchronized void reEvaluateCurrentSession(String currentNpcName, Integer currentNpcId, Instant now)
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		if (currentNpcName == null || currentNpcName.trim().isEmpty())
		{
			// No current live combat-target evidence -- never invent an
			// activity. Safe no-op.
			return;
		}

		Session before = engine.getCurrentSession();
		SignalClassification classification = classifier.classifyManualNpcTarget(currentNpcName, before, EvidenceStrength.SPECIFIC);

		if (classification.getDecisionKind() != SignalDecisionKind.START_OR_HEARTBEAT
			&& classification.getDecisionKind() != SignalDecisionKind.REFINE)
		{
			// e.g. METRIC_ONLY (generic combat evidence against a
			// SUSPENDED specific session) -- no safe identity claim right
			// now. Honor that exactly like the ordinary pipeline does:
			// nothing invented, nothing mutated. This call never carries
			// metrics of its own, so there is nothing to apply here even
			// for METRIC_ONLY.
			return;
		}

		SessionState beforeState = before == null ? null : before.getState();
		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A):
		// allowInterruptedResume=false -- a manual identity correction
		// must never manufacture a hidden resumable prior session/History
		// entry (see onQualifyingActivity()'s 5-arg overload javadoc).
		// This preserves this method's own pre-existing, unchanged
		// corrective semantics byte-for-byte: a real switch here still
		// finalizes the old session immediately, exactly as it always
		// has.
		LifecycleResult result = classification.getDecisionKind() == SignalDecisionKind.REFINE
			? engine.refineIdentity(classification.getIdentity(), now, Collections.<MetricUpdate>emptyList())
			: engine.onQualifyingActivity(classification.getIdentity(), now, Collections.<MetricUpdate>emptyList(), classification.getEvidenceStrength(), false);

		if (result.getCurrent() != null
			&& (before == null || !before.getSessionId().equals(result.getCurrent().getSessionId())))
		{
			classifierContext.noteSessionSwitchXpBaseline(result.getCurrent().getSessionId(), lastKnownAbsoluteXpBySkill);
		}

		// Same metric-routing discipline as resolveAndApplyBatches()'s own
		// RESOLVED branch: metricsForCurrent is always empty for this call
		// (see method javadoc's NEVER REWRITES HISTORY section), but an
		// abandoned candidate's own previously-buffered, real metrics
		// (contextualMetricsTarget/contextualMetrics) must still be
		// committed exactly once, never dropped.
		applyMetrics(result.getCurrent(), result.getMetricsForCurrent());
		if (result.getContextualMetricsTarget() != null)
		{
			applyMetrics(result.getContextualMetricsTarget(), result.getContextualMetrics());
		}

		if (result.getFinalized() != null)
		{
			flushAbandonedBossTaskCandidateIfMatching(result.getFinalized());
			persistence.persistFinalized(currentAccountHash, result.getFinalized(), result.getCurrent());
		}
		else if (result.getCurrent() != null && result.getCurrent().getState() != beforeState)
		{
			persistence.persistCurrent(currentAccountHash, result.getCurrent());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): even with
		// allowInterruptedResume=false above, the background candidate-
		// expiry housekeeping every timestamped entry point performs is
		// NOT gated by that flag (see expireInterruptedCandidateIfNeeded()'s
		// own javadoc) -- an already-parked, already-decided candidate can
		// still legitimately expire exactly during a manual re-evaluate
		// call, and must not be dropped.
		if (result.getAdditionalFinalized() != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, result.getAdditionalFinalized());
			persistence.clearInterruptedCandidate(currentAccountHash);
		}

		classifierContext.onNpcInteractionTarget(currentNpcId, currentNpcName, safeTickCount(), now);
	}

	synchronized Session testCurrentSession()
	{
		return engine.getCurrentSession();
	}

	synchronized Session testInterruptedCandidate()
	{
		return engine.getInterruptedCandidate();
	}

	synchronized long testPendingSignalCount()
	{
		return pendingSignals.size();
	}
}

package com.osrstelemetry.plugin.session;

import java.util.Objects;

/**
 * A small,
 * immutable value describing "what counts as the same activity" for
 * lifecycle resume/switch decisions — nothing more. This class does
 * NOT implement the gameplay logic that produces these (no
 * XP_CHANGE-means-Woodcutting, no SERVER_NPC_LOOT-means-this-boss
 * heuristics anywhere in this class or elsewhere); the
 * engine only ever receives already-classified identities from a
 * separate classifier/router.
 *
 * activityKey is the stable semantic identity ("gargoyles:catacombs",
 * "zulrah", "woodcutting") — the thing that must match for a resume to
 * be considered "the same activity." displayName ("Gargoyles",
 * "Zulrah", "Woodcutting") is presentation-only and deliberately
 * EXCLUDED from equals()/hashCode(): two ActivityIdentity instances
 * with the same activityType+activityKey but a different displayName
 * (e.g. a future localization or a refined display label) must still
 * compare equal for resume purposes, per the explicit instruction that
 * "equality for resume/switch decisions must use stable semantic
 * identity, not display text alone." This is written out by hand
 * (not Lombok @Data/@EqualsAndHashCode) specifically so that
 * exclusion is impossible to silently break by an unrelated Lombok
 * annotation edit later.
 */
public final class ActivityIdentity
{
	private final ActivityType activityType;
	private final String activityKey;
	private final String displayName;

	public ActivityIdentity(ActivityType activityType, String activityKey, String displayName)
	{
		this.activityType = Objects.requireNonNull(activityType, "activityType");
		this.activityKey = Objects.requireNonNull(activityKey, "activityKey");
		this.displayName = displayName;
	}

	public ActivityType getActivityType()
	{
		return activityType;
	}

	public String getActivityKey()
	{
		return activityKey;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/**
	 * Deliberately activityType + activityKey ONLY — see class javadoc.
	 * displayName never participates in equality.
	 */
	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ActivityIdentity))
		{
			return false;
		}
		ActivityIdentity other = (ActivityIdentity) o;
		return activityType == other.activityType && activityKey.equals(other.activityKey);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(activityType, activityKey);
	}

	@Override
	public String toString()
	{
		return "ActivityIdentity{" + activityType + ":" + activityKey + " (" + displayName + ")}";
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.session.LoadoutSnapshot;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * A standalone, minimally-invasive collector feeding {@link LoadoutArchive}
 * -- see that class's own javadoc for why a short in-memory archive is
 * needed at all: ContainerCollector's own inventory.json/equipment.json
 * are CURRENT-STATE-ONLY overwritten pointers with no history, and its
 * inventory representation is deliberately sparse
 * (ContainerCollector.buildSparseItems()) rather than slot-exact -- the
 * right choice for its own purpose, but not for History's slot-exact
 * starting/ending loadout requirement.
 *
 * DELIBERATELY INDEPENDENT of ContainerCollector: this class touches
 * zero lines of that already-hardened file. It subscribes to the exact
 * same ItemContainerChanged event completely independently -- RuneLite's
 * EventBus supports any number of independent subscribers to the same
 * event type, so there is no coordination needed between the two, and
 * no risk of this collector affecting ContainerCollector's own
 * bank-snapshot/dedup/shutdown-durability machinery in any way.
 *
 * SLOT-EXACT, UNLIKE ContainerCollector.buildSparseItems(): builds a
 * COMPLETE {@link LoadoutSnapshot#INVENTORY_SIZE}-slot inventory list
 * (explicit empty-slot entries, itemId=-1) the same way
 * ContainerCollector.buildEquipmentItems() already does for equipment
 * -- see buildCompleteInventoryItems() below, the same technique
 * applied to inventory. buildCompleteEquipmentItems() below is a
 * deliberate re-implementation of that same equipment technique rather
 * than a shared call, since ContainerCollector's own method is
 * private on a file this collector deliberately does not touch.
 *
 * WHEN A PAIR IS RECORDED: inventory and equipment are both
 * continuously observable (see StorageState's own "continuouslyObservable"
 * contract), so on ANY change to either container this collector
 * re-reads BOTH current containers directly via
 * client.getItemContainer(...) -- the same technique
 * ContainerCollector.captureInitialContinuousState() already uses to
 * seed both independently of any specific change event -- and archives
 * them together as one complete pair. If either container is not yet
 * available (e.g. a change fires before the other has ever been
 * observed this login), nothing is recorded for that observation --
 * never a partial/incomplete pair, which would silently corrupt
 * LoadoutArchive's "every entry is complete" invariant.
 */
@Slf4j
public class LoadoutArchiveCollector
{
	private static final Map<Integer, String> EQUIPMENT_SLOT_NAMES = new HashMap<>();

	static
	{
		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			EQUIPMENT_SLOT_NAMES.put(slot.getSlotIdx(), slot.name());
		}
	}

	private final Client client;
	private final ItemManager itemManager;
	private final OsrsTelemetryConfig config;
	private final LoadoutArchive archive;

	@Inject
	public LoadoutArchiveCollector(Client client, ItemManager itemManager, OsrsTelemetryConfig config, LoadoutArchive archive)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.archive = archive;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId != InventoryID.INV && containerId != InventoryID.WORN)
		{
			return;
		}
		captureIfBothAvailable();
	}

	/**
	 * Called once on login (see OsrsTelemetryPlugin.handleLogin()) so
	 * the archive can start holding real data immediately -- the same
	 * "seed immediately, don't wait for an incidental event" reasoning
	 * ContainerCollector.captureInitialContinuousState() already
	 * follows for inventory.json/equipment.json.
	 */
	public void captureInitialState()
	{
		captureIfBothAvailable();
	}

	private void captureIfBothAvailable()
	{
		if (!config.collectInventoryEquipment())
		{
			return;
		}
		ItemContainer inventoryContainer = client.getItemContainer(InventoryID.INV);
		ItemContainer equipmentContainer = client.getItemContainer(InventoryID.WORN);
		if (inventoryContainer == null || equipmentContainer == null)
		{
			return;
		}
		List<StorageState.StorageItem> inventory = buildCompleteInventoryItems(inventoryContainer);
		List<StorageState.StorageItem> equipment = buildCompleteEquipmentItems(equipmentContainer);
		archive.record(Instant.now(), inventory, equipment);
	}

	/**
	 * Slot-exact -- see class javadoc. Mirrors
	 * ContainerCollector.buildEquipmentItems()'s empty-slot convention
	 * (itemId=-1, name=null, quantity=0), applied to inventory's fixed
	 * LoadoutSnapshot.INVENTORY_SIZE slots instead of the equipment
	 * slot table.
	 */
	private List<StorageState.StorageItem> buildCompleteInventoryItems(ItemContainer container)
	{
		List<StorageState.StorageItem> items = new ArrayList<>(LoadoutSnapshot.INVENTORY_SIZE);
		Item[] rawItems = container.getItems();
		for (int slot = 0; slot < LoadoutSnapshot.INVENTORY_SIZE; slot++)
		{
			Item item = slot < rawItems.length ? rawItems[slot] : null;
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				items.add(new StorageState.StorageItem(slot, -1, null, 0, null));
			}
			else
			{
				String name = itemManager.getItemComposition(item.getId()).getName();
				items.add(new StorageState.StorageItem(slot, item.getId(), name, item.getQuantity(), null));
			}
		}
		return items;
	}

	private List<StorageState.StorageItem> buildCompleteEquipmentItems(ItemContainer container)
	{
		List<StorageState.StorageItem> items = new ArrayList<>(EQUIPMENT_SLOT_NAMES.size());
		Item[] rawItems = container.getItems();
		for (int slot = 0; slot < EQUIPMENT_SLOT_NAMES.size(); slot++)
		{
			Item item = slot < rawItems.length ? rawItems[slot] : null;
			String equipmentSlotName = EQUIPMENT_SLOT_NAMES.get(slot);
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				items.add(new StorageState.StorageItem(slot, -1, null, 0, equipmentSlotName));
			}
			else
			{
				String name = itemManager.getItemComposition(item.getId()).getName();
				items.add(new StorageState.StorageItem(slot, item.getId(), name, item.getQuantity(), equipmentSlotName));
			}
		}
		return items;
	}

	/** See OsrsTelemetryPlugin.handleLogin(). */
	public void resetForAccountSwitch()
	{
		archive.resetForAccountSwitch();
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.model.SlayerState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.slayer.SlayerPluginService;

/**
 * Task-resolution reads go through RuneLite's published
 * net.runelite.client.plugins.slayer.SlayerPluginService. Points/streak/
 * master still read directly via varbits, since the service doesn't
 * expose those.
 *
 * VARP VS VARBIT: SlayerPlugin.java's own onVarbitChanged shows that
 * SLAYER_COUNT, SLAYER_AREA, and SLAYER_TARGET are VarPlayer changes,
 * delivered via VarbitChanged.getVarpId(), NOT getVarbitId() -- a
 * collector that checked ONLY varbitId-based conditions would never
 * react to a kill (SLAYER_COUNT decrementing) or a new assignment
 * (SLAYER_TARGET changing). Both varpId and varbitId are watched below,
 * mirroring the real plugin's actual condition exactly (see
 * isRelevantSlayerVarbitChange()).
 *
 * ON MORTIMER: verified against the
 * complete current SlayerPlugin.java. There is no MORTIMER_SLAYER_MASTER
 * constant, no VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, no
 * SLAYER_MODIFIER_* varbits, anywhere in the file. The only
 * master-specific streak logic that exists is the same two-way check:
 *   client.getVarbitValue(VarbitID.SLAYER_MASTER) == KRYSTILIA_SLAYER_MASTER
 *       ? WILDERNESS_TASKS_COMPLETED : SLAYER_TASKS_COMPLETED
 * masterId is still captured correctly for every master including
 * Mortimer; his streak specifically stays unverified since his numeric
 * master id is not available from any source this project can reach,
 * so the code cannot special-case detection of "this might be wrong."
 */
public class SlayerCollector
{
	private static final int KRYSTILIA_MASTER_ID = 7;

	private final Client client;
	private final ClientThread clientThread;
	private final SlayerPluginService slayerPluginService;
	private final LocalStateStore store;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;

	/**
	 * A naive design -- a synchronous "no task"
	 * read leaving hydration open for "the first async check," then
	 * treating THAT first async check as automatically final -- has a
	 * lifecycle hole: the first async check can ALSO observe a transient
	 * "no task" (racing
	 * RuneLite's own SlayerPlugin, which independently resolves
	 * SlayerPluginService's cached task fields off the same varbits via
	 * its own clientThread.invokeLater(this::updateTask)). That would still
	 * allow: sync=no-task -> first async=no-task (locked in as the
	 * baseline) -> next async=Gargoyles/124 (diffed against the wrong
	 * "no task" baseline) -> fabricated SLAYER_TASK_ASSIGNED.
	 *
	 * Instead, all mutable hydration state is
	 * owned by
	 * SlayerBaselineHydration (below), and "no task" is never
	 * trusted merely for being first -- it must be OBSERVED STABLE
	 * across NONE_STABILIZATION_TICKS consecutive GameTicks with no
	 * further relevant VarbitChanged resetting the countdown (see that
	 * field's javadoc). A REAL named task, at any point before that
	 * countdown completes, still hydrates immediately and silently --
	 * a real task can never be a sync
	 * artifact. This is a small, deterministic, GameTick-driven
	 * stabilization rule -- not an arbitrary sleep -- mirroring this
	 * codebase's own precedent for exactly this class of problem
	 * (ContainerCollector's debounced bank-snapshot settle window,
	 * trySeedIdentity()'s GameTick-based readiness retry).
	 */
	private final SlayerBaselineHydration hydration = new SlayerBaselineHydration();

	// A tick-counted deferral: pendingRecheck/armedAtTick, resolved
	// from onGameTick() once client.getTickCount() has genuinely advanced
	// past the tick the relevant VarbitChanged fired on -- see
	// onVarbitChanged()'s own comment for why this specific mechanism is
	// required (an invokeAtTickEnd()-based approach does not work).
	private volatile boolean pendingRecheck = false;
	private volatile int armedAtTick = -1;

	@Inject
	public SlayerCollector(
		Client client,
		ClientThread clientThread,
		SlayerPluginService slayerPluginService,
		LocalStateStore store,
		EventLedger eventLedger,
		OsrsTelemetryConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.slayerPluginService = slayerPluginService;
		this.store = store;
		this.eventLedger = eventLedger;
		this.config = config;
	}

	public void resetForAccountSwitch()
	{
		hydration.reset();
		pendingRecheck = false;
		armedAtTick = -1;
	}

	/**
	 * Gated on config — called on
	 * re-enable via ConfigChanged, and must not seed Slayer state at
	 * all while the category is disabled.
	 *
	 * NOT called from login (see
	 * captureInitialStateWithoutBaseline() below for why) — this
	 * remains correct for the re-enable case specifically because
	 * there is no post-login client-sync gap to worry about there: the
	 * category was merely toggled off/on mid-session, RuneLite's
	 * varp/varbit values are already fully settled, and no
	 * VarbitChanged has fired yet for this reseed to race against.
	 * Hydrating immediately and directly (bypassing the stabilization
	 * window entirely) is what correctly prevents whatever changed
	 * while the category was disabled (e.g. a task completed) from
	 * being fabricated as a transition the moment collection resumes.
	 */
	public void seedSilently()
	{
		if (!config.collectSlayer())
		{
			return;
		}
		SlayerState current = resolveCurrent();
		hydration.hydrateDirectly(current);
		writeState(current);
	}

	/**
	 * Called from
	 * OsrsTelemetryPlugin.handleLogin() INSTEAD of seedSilently().
	 *
	 * A naive approach -- diffing the login-time reading directly against
	 * whatever state was last known -- produces a real bug: a
	 * SLAYER_TASK_ASSIGNED event firing on a plain login into an
	 * account that already had an assigned task (Gargoyles), when no new
	 * task was actually assigned. A subtler follow-up hole: even with
	 * that direct-diff path removed, a REPEATED transient "no task" reading
	 * (sync read, then the first async check too) could still lock in
	 * a wrong baseline before the real task settled. See
	 * SlayerBaselineHydration's javadoc for the stabilization
	 * rule this method and performCoalescedCheck()/onGameTick() all
	 * feed into.
	 *
	 * This method persists current state to disk unconditionally
	 * (freshness — slayer.json should not sit stale/absent between
	 * login and hydration completing) and hands its own reading to
	 * hydration.observeBeforeHydration() — which locks immediately if
	 * it already shows a real task, or arms/restarts the NONE
	 * stabilization countdown otherwise.
	 *
	 * A same-account world hop is
	 * NOT exempt from this. RuneLite's Slayer state (SlayerPluginService/
	 * varps) can transiently blank out mid-hop, and carrying an OLD
	 * trusted baseline across that gap would let the transient blank reading
	 * get diffed as a genuine COMPLETED, then the real post-hop settle
	 * diffed as a genuine ASSIGNED — two fabricated events for what was
	 * actually continuity. OsrsTelemetryPlugin.handleLogin() calls
	 * slayerCollector.resetForAccountSwitch() UNCONDITIONALLY on every
	 * LOGGED_IN transition (fresh start, real switch, or a same-account
	 * hop/relog), not only on a real account switch — see its own
	 * comment. That reset is what makes this method's
	 * observeBeforeHydration() call meaningful again on a hop: hydration
	 * is freshly reopened first, so this reading re-establishes the
	 * baseline through the exact same stabilization-tolerant,
	 * no-fabricated-event machinery already proven correct for a fresh
	 * client launch — no separate suppression system.
	 */
	public void captureInitialStateWithoutBaseline()
	{
		if (!config.collectSlayer())
		{
			return;
		}
		SlayerState current = resolveCurrent();
		writeState(current);

		if (!hydration.isHydrated())
		{
			hydration.observeBeforeHydration(current);
		}
	}

	/**
	 * The
	 * deterministic, GameTick-driven stabilization signal. While hydration has a "no task" candidate armed (see
	 * SlayerBaselineHydration.observeBeforeHydration()), this ticks the
	 * countdown down once per GameTick; reaching zero with the
	 * countdown never having been reset by an intervening relevant
	 * VarbitChanged is what finally confirms NONE as a genuinely
	 * trustworthy baseline. A no-op (and cheap: a single volatile-ish
	 * field read) once hydrated or when no countdown is armed, so this
	 * is safe to leave subscribed for the collector's entire lifetime.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.collectSlayer())
		{
			return;
		}
		if (hydration.onGameTick())
		{
			writeState(hydration.getLastKnown());
		}

		// See onVarbitChanged()'s comment for the root cause this
		// resolves. Resolves the
		// coalesced recheck exactly once client.getTickCount() has
		// genuinely moved past the tick that armed it -- see
		// shouldResolvePendingRecheck()'s own javadoc for why this is the
		// deterministic point RuneLite's own SlayerPlugin.updateTask() is
		// guaranteed to have already run.
		if (shouldResolvePendingRecheck(pendingRecheck, armedAtTick, client.getTickCount()))
		{
			pendingRecheck = false;
			armedAtTick = -1;
			performCoalescedCheck();
		}
	}

	/**
	 * Pure decision function (Hooks.tick()'s own posted
	 * order proves this): a coalesced recheck armed on tick T is only
	 * guaranteed to observe RuneLite SlayerPlugin's settled
	 * SlayerPluginService state once we are dispatched for a STRICTLY
	 * LATER tick than T -- never on tick T itself, no matter how late in
	 * tick T's own processing this check runs. See onVarbitChanged()'s
	 * comment for the full derivation from RuneLite's actual
	 * Hooks.tick()/tickEnd() source (GAME_TICK is posted, and our
	 * onGameTick() runs, BEFORE that same tick's clientThread.invoke()
	 * drains the invokeLater(this::updateTask) call SlayerPlugin's own
	 * onVarbitChanged queued this tick -- so even a same-tick,
	 * end-of-tick read via invokeAtTickEnd() can still run before
	 * updateTask() does. Only the NEXT tick's onGameTick() call is
	 * guaranteed to run after tick T's invoke() has fully drained).
	 * currentTick strictly greater than armedAtTick is exactly "at least
	 * one full tick boundary, and therefore at least one full
	 * clientThread.invoke() drain, has elapsed since arming" --
	 * regardless of how many ticks have actually passed, so a missed or
	 * delayed onGameTick() call never leaves this permanently stuck
	 * (first later tick observed resolves it).
	 */
	static boolean shouldResolvePendingRecheck(boolean pendingRecheck, int armedAtTick, int currentTick)
	{
		return pendingRecheck && currentTick > armedAtTick;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!config.collectSlayer())
		{
			return;
		}

		if (!isRelevantSlayerVarbitChange(event.getVarpId(), event.getVarbitId()))
		{
			return;
		}

		// ============================================================
		// WHY invokeAtTickEnd() DOES NOT WORK HERE: it is tempting to
		// assume that invokeAtTickEnd()'s queue drains strictly after
		// invokeLater()'s queue WITHIN THE SAME TICK, so a same-tick
		// invokeAtTickEnd() recheck would always see SlayerPlugin's
		// already-updated state -- that is true about ClientThread's queue
		// STRUCTURE, but false about WHEN each queue actually drains
		// relative to VarbitChanged, once RuneLite's real client-loop
		// hook (net.runelite.client.callback.Hooks, which is what
		// actually calls clientThread.invoke()/invokeTickEnd() -- not
		// ClientThread itself) is inspected instead of ClientThread in
		// isolation:
		//
		//   Hooks.tick():     eventBus.post(GAME_TICK); clientThread.invoke();
		//   Hooks.tickEnd():  clientThread.invokeTickEnd(); eventBus.post(new PostClientTick());
		//
		// Both `tick()` and `tickEnd()` fire once per client tick, and
		// `tick()` (which drains invokeLater()) runs BEFORE `tickEnd()`
		// (which drains invokeAtTickEnd()) -- so structurally
		// invokeAtTickEnd() SHOULD still observe a same-tick
		// invokeLater() task. The actual problem is finer-grained: varp
		// diffing/VarbitChanged posting for a tick's server update
		// happens as its own step, and by the time our onVarbitChanged()
		// runs and arms a recheck, that tick's `Hooks.tick()` call --
		// the one that would drain SlayerPlugin's freshly-queued
		// invokeLater(this::updateTask) -- has, in the observed live
		// failure, ALREADY happened for the tick in which the varp
		// changed. That leaves updateTask() queued but not yet run until
		// the FOLLOWING tick's `Hooks.tick()` call -- one full tick
		// later than an invokeAtTickEnd()-deferred read, which resolves
		// at THIS tick's `tickEnd()`, still before updateTask() ever
		// executes. This produces a deterministic (not racy) one-decrement
		// lag: invokeAtTickEnd()
		// always resolves one tick too early relative to when
		// updateTask() actually runs.
		//
		// Instead, this does not schedule anything via ClientThread at all here.
		// It records the CURRENT tick number (client.getTickCount())
		// as `armedAtTick`, and defers resolution to onGameTick() --
		// specifically, only once client.getTickCount() has advanced to
		// a STRICTLY LATER value than armedAtTick (see
		// shouldResolvePendingRecheck()'s javadoc). Since onGameTick()
		// itself only runs once per tick and (per Hooks.tick() above) is
		// posted BEFORE that same tick's clientThread.invoke() drains,
		// waiting for the NEXT tick's onGameTick() call guarantees the
		// PRIOR tick's entire `Hooks.tick()` call -- GAME_TICK post AND
		// clientThread.invoke() drain, i.e. updateTask() -- has already
		// completed before we read. This is a bounded, deterministic
		// ONE-GAMETICK latency (~0.6s), never a guess, never a race, and
		// never a per-kill accumulating lag: every relevant VarbitChanged
		// arms (or, if already armed, coalesces into) exactly one
		// pending recheck, resolved on the first later tick observed.
		if (!pendingRecheck)
		{
			pendingRecheck = true;
			armedAtTick = client.getTickCount();
		}
	}

	/**
	 * Pure predicate (package-private, directly unit-testable with no
	 * RuneLite runtime) mirroring exactly what current
	 * SlayerPlugin.java's own onVarbitChanged checks -- see class
	 * javadoc for how that was independently reconfirmed against the
	 * complete current source. Extracted from onVarbitChanged() so the
	 * "which varp/varbit changes matter" decision is testable without a
	 * real Client/VarbitChanged-dispatch pipeline.
	 */
	static boolean isRelevantSlayerVarbitChange(int varpId, int varbitId)
	{
		return varpId == VarPlayerID.SLAYER_COUNT
			|| varpId == VarPlayerID.SLAYER_AREA
			|| varpId == VarPlayerID.SLAYER_TARGET
			|| varpId == VarPlayerID.SLAYER_COUNT_ORIGINAL
			|| varbitId == VarbitID.SLAYER_TARGET_BOSSID
			|| varbitId == VarbitID.SLAYER_POINTS
			|| varbitId == VarbitID.SLAYER_TASKS_COMPLETED
			|| varbitId == VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED
			|| varbitId == VarbitID.SLAYER_MASTER;
	}

	/**
	 * Test-only hooks (package-private, same convention as
	 * SessionRuntimeCoordinator's testProcessTick()/testEnqueueSignal()
	 * elsewhere in this project): let a test drive the pendingRecheck/
	 * armedAtTick state machine directly, without needing a real
	 * Client/SlayerPluginService (this project's test suite deliberately
	 * never mocks those -- no Mockito dependency).
	 */
	void testArmPendingRecheck(int tick)
	{
		if (!pendingRecheck)
		{
			pendingRecheck = true;
			armedAtTick = tick;
		}
	}

	boolean testIsPendingRecheck()
	{
		return pendingRecheck;
	}

	int testGetArmedAtTick()
	{
		return armedAtTick;
	}

	void testResetPendingRecheck()
	{
		pendingRecheck = false;
		armedAtTick = -1;
	}

	private void performCoalescedCheck()
	{
		// pendingRecheck/armedAtTick are already reset by the caller
		// (onGameTick()'s shouldResolvePendingRecheck() branch) before
		// this method runs -- see that method's own comment.
		SlayerState current = resolveCurrent();

		if (!hydration.isHydrated())
		{
			// This
			// async, VarbitChanged-triggered read is never trusted
			// as automatically final just for being first. observeBeforeHydration() hydrates immediately only
			// if `current` already shows a real task; otherwise it
			// arms/restarts the NONE stabilization countdown, and
			// onGameTick() is what eventually confirms NONE once that
			// countdown genuinely elapses undisturbed. Either way,
			// nothing is ever diffed/emitted from this branch.
			hydration.observeBeforeHydration(current);
			writeState(current);
			return;
		}

		SlayerState previous = hydration.getLastKnown();
		if (current.equals(previous))
		{
			return;
		}

		emitTransitionEvents(previous, current);
		hydration.commit(current);
		writeState(current);
	}

	/**
	 * Owns ALL mutable Slayer baseline-hydration state, extracted so
	 * SlayerCollectorTest can drive the exact stabilization rule
	 * directly with plain SlayerState inputs and simulated GameTicks --
	 * no Client/SlayerPluginService/ClientThread mocking needed (this
	 * project has no Mockito dependency). SlayerCollector's
	 * captureInitialStateWithoutBaseline()/performCoalescedCheck()/
	 * onGameTick()/seedSilently()/resetForAccountSwitch() all delegate
	 * here; production and tests share this exact class.
	 *
	 * THE STABILIZATION RULE: a
	 * real, named task observed at ANY point before hydration completes
	 * hydrates immediately -- an empty/default varp state can never
	 * spontaneously resolve into a specific, already-named monster that
	 * doesn't genuinely exist, so seeing one is never a false positive
	 * (only ever genuine, or stale-from-a-prior-account, which
	 * SlayerCollector.resetForAccountSwitch() already handles
	 * separately by calling reset() first). A "no task" observation,
	 * by contrast, remains genuinely ambiguous (really no task, vs. not
	 * yet synced) and is NEVER trusted merely for being first: it is held as a candidate, and
	 * only becomes the confirmed baseline once NONE_STABILIZATION_TICKS
	 * consecutive GameTicks elapse with NOTHING resetting the
	 * countdown -- and ANY further "no task" observation during that
	 * window (a relevant varbit firing again, still showing no task)
	 * is itself evidence something may still be settling, so it
	 * restarts the countdown from the top rather than counting as one
	 * of the confirming ticks. This directly closes the reproduced
	 * race (sync=no-task, first async=no-task, next=Gargoyles/124):
	 * neither no-task observation ever locks anything in, so the
	 * eventual Gargoyles/124 reading -- whenever it arrives -- always
	 * hydrates silently via the "real task" branch, never gets diffed
	 * against a wrongly-confirmed NONE baseline. Once NONE genuinely IS
	 * confirmed (no further activity for the full stabilization
	 * window -- i.e. truly no task, not just "not yet settled"), a
	 * LATER genuine assignment still produces exactly one
	 * SLAYER_TASK_ASSIGNED, since that assignment is now a normal
	 * post-hydration diff against a trustworthy NONE baseline.
	 */
	static final class SlayerBaselineHydration
	{
		/**
		 * How many consecutive, undisturbed GameTicks a "no task"
		 * reading must survive before it's trusted as the confirmed
		 * baseline. Deliberately small, deterministic, and GameTick-
		 * driven (RuneLite's own tick cadence, ~0.6s each) rather than
		 * an arbitrary wall-clock sleep -- 2 full ticks is comfortably
		 * beyond the single-tick ordering race identified above (our own VarbitChanged-triggered read
		 * landing before RuneLite's own SlayerPlugin has resolved its
		 * task cache for the same tick), while staying short enough
		 * that a genuinely-no-task account is confirmed within ~1.2s of
		 * login, not stuck open indefinitely.
		 */
		static final int NONE_STABILIZATION_TICKS = 2;

		private SlayerState lastKnown;
		private boolean hydrated;
		private SlayerState pendingNoTaskCandidate;
		private int noTaskTicksRemaining = -1;

		void reset()
		{
			lastKnown = null;
			hydrated = false;
			pendingNoTaskCandidate = null;
			noTaskTicksRemaining = -1;
		}

		/** seedSilently()'s immediate, un-stabilized seed (re-enable
		 * path only -- see its own javadoc for why no stabilization
		 * window is needed there). */
		void hydrateDirectly(SlayerState state)
		{
			lastKnown = state;
			hydrated = true;
			pendingNoTaskCandidate = null;
			noTaskTicksRemaining = -1;
		}

		boolean isHydrated()
		{
			return hydrated;
		}

		SlayerState getLastKnown()
		{
			return lastKnown;
		}

		/** Post-hydration: records a real, diffed observation as the
		 * new baseline. Never called while !hydrated. */
		void commit(SlayerState current)
		{
			lastKnown = current;
		}

		/**
		 * Pre-hydration observation, from either
		 * captureInitialStateWithoutBaseline()'s synchronous read or
		 * performCoalescedCheck()'s async one -- both feed the exact
		 * same rule. Returns true if this call hydrated (a real task
		 * was observed); false if it only armed/restarted the NONE
		 * stabilization countdown.
		 */
		boolean observeBeforeHydration(SlayerState observed)
		{
			if (hydrated)
			{
				return false;
			}
			if (observed.getTaskName() != null)
			{
				lastKnown = observed;
				hydrated = true;
				pendingNoTaskCandidate = null;
				noTaskTicksRemaining = -1;
				return true;
			}
			// Still no task -- (re)arm the stabilization countdown.
			// Deliberately restarts from the top even if a countdown
			// was already running: this observation itself is evidence
			// a relevant varbit just fired, i.e. something may still be
			// settling, so it must not count as one of the confirming
			// quiet ticks.
			pendingNoTaskCandidate = observed;
			noTaskTicksRemaining = NONE_STABILIZATION_TICKS;
			return false;
		}

		/**
		 * One GameTick's worth of stabilization progress. Returns true
		 * exactly on the tick NONE becomes confirmed (caller should
		 * persist getLastKnown() then, matching every other hydration
		 * path's "state written during hydration" requirement).
		 */
		boolean onGameTick()
		{
			if (hydrated || noTaskTicksRemaining < 0)
			{
				return false;
			}
			// Must
			// decrement BEFORE checking for zero. Checking-then-
			// decrementing made the documented "2 undisturbed
			// GameTicks" actually require 3 onGameTick() calls (2->1,
			// 1->0, then a third call to see 0 and confirm).
			noTaskTicksRemaining--;
			if (noTaskTicksRemaining == 0)
			{
				lastKnown = pendingNoTaskCandidate;
				hydrated = true;
				pendingNoTaskCandidate = null;
				noTaskTicksRemaining = -1;
				return true;
			}
			return false;
		}
	}

	private void emitTransitionEvents(SlayerState previous, SlayerState current)
	{
		SlayerTransitionResult result = evaluateSlayerTransition(previous, current);

		switch (result.kind)
		{
			case COMPLETED:
				eventLedger.append(
					client.getAccountHash(),
					EventType.SLAYER_TASK_COMPLETED,
					new EventPayloads.SlayerTaskCompleted(
						previous.getTaskName(), current.getStreak(), current.getStreakLabel(), current.getPoints())
				);
				break;
			case ASSIGNED:
				eventLedger.append(
					client.getAccountHash(),
					EventType.SLAYER_TASK_ASSIGNED,
					new EventPayloads.SlayerTaskAssigned(
						current.getTaskName(), current.getAmountRemaining(), current.getTaskLocation(), current.getMasterId())
				);
				break;
			case PROGRESS:
				// current.getInitialAmount()/getMasterId() are safe to
				// read unfabricated here: PROGRESS only fires when
				// hadTask && hasTask (see evaluateSlayerTransition()),
				// so current.getAmountRemaining() > 0, which is exactly
				// the condition resolveCurrent() requires before it sets
				// initialAmount/taskName/taskLocation at all — these
				// fields are genuinely known on this observation, not
				// defaulted/guessed.
				eventLedger.append(
					client.getAccountHash(),
					EventType.SLAYER_TASK_PROGRESS,
					new EventPayloads.SlayerTaskProgress(
						current.getTaskName(), current.getTaskLocation(),
						result.previousRemaining, result.currentRemaining,
						result.remainingDelta, result.taskUnitsConsumed,
						current.getInitialAmount(), current.getMasterId())
				);
				break;
			case NONE:
			default:
				break;
		}
	}

	/**
	 * Pure,
	 * Client/EventLedger-independent core of the Slayer transition
	 * decision — factored out of emitTransitionEvents() for the same
	 * reason as QuestCollector.justFinished()/SkillsCollector.
	 * evaluateXpWindow(): unit-testable without mocking RuneLite's
	 * Client. SlayerState itself has no Client dependency (see its
	 * class javadoc), so it can be constructed directly in a test.
	 *
	 * TASK IDENTITY vs. TASK PROGRESS/METADATA: identity is taskName + taskLocation only.
	 * amountRemaining, initialAmount, points, streak, streakLabel,
	 * streakSourceVerified, and masterId are all progress/metadata —
	 * none of them ever contribute to sameTaskIdentity below.
	 * masterId is deliberately excluded from identity: its absence is only a THEORETICAL risk (a same-name/
	 * location task reassigned by a different master would be missed),
	 * with no production evidence it's ever actually happened — not
	 * fixed without evidence.
	 *
	 * previous == null means this is the first observation since login
	 * or a reset — must always be NONE (silent seed), never a
	 * fabricated ASSIGNED, regardless of what current looks like. This
	 * is the exact invariant that, combined with
	 * captureInitialStateWithoutBaseline() never pre-setting
	 * lastKnown at login, avoids a false
	 * SLAYER_TASK_ASSIGNED-on-plain-login: the first genuine
	 * performCoalescedCheck() after login always calls this with
	 * previous == null.
	 *
	 * Same-identity + unchanged amountRemaining -> NONE. Same-identity +
	 * changed amountRemaining (in EITHER direction — a decrement from a
	 * kill, or an increase, which is never reinterpreted as a new
	 * assignment) -> PROGRESS, carrying the observed delta. A normal decrement
	 * (e.g. 138 Gargoyles -> 137 Gargoyles) must NEVER return ASSIGNED —
	 * it is explicitly
	 * PROGRESS, never ASSIGNED and never silently indistinguishable from
	 * "nothing happened." A different identity (whether or
	 * not the two assignments' remaining counts happen to differ) is
	 * always ASSIGNED/COMPLETED, never PROGRESS — the two are mutually
	 * exclusive by construction below (the PROGRESS branch is only
	 * reached after both the COMPLETED and ASSIGNED conditions have
	 * already tested false, i.e. only when sameTaskIdentity is true).
	 */
	static SlayerTransitionResult evaluateSlayerTransition(SlayerState previous, SlayerState current)
	{
		if (previous == null)
		{
			return SlayerTransitionResult.none();
		}

		// Task
		// presence/absence must be determined from the actual task
		// identity fields (taskName), never from amountRemaining alone.
		// amountRemaining == 0 is progress/metadata, not "no task" --
		// treating it as identity-absence would fabricate
		// SLAYER_TASK_ASSIGNED for an identical task whose remaining
		// count happened to cross the 0/1 boundary (e.g. 0 -> 1).
		boolean hadTask = previous.getTaskName() != null;
		boolean hasTask = current.getTaskName() != null;
		boolean sameTaskIdentity = Objects.equals(previous.getTaskName(), current.getTaskName())
			&& Objects.equals(previous.getTaskLocation(), current.getTaskLocation());

		if (hadTask && !hasTask)
		{
			return SlayerTransitionResult.completed();
		}
		if (hasTask && (!hadTask || !sameTaskIdentity))
		{
			return SlayerTransitionResult.assigned();
		}

		// Reaching here means hadTask && hasTask && sameTaskIdentity —
		// the only case a progress reading is even meaningful, since
		// PROGRESS must never span two different assignments.
		int previousRemaining = previous.getAmountRemaining();
		int currentRemaining = current.getAmountRemaining();
		if (previousRemaining == currentRemaining)
		{
			return SlayerTransitionResult.none();
		}

		int remainingDelta = currentRemaining - previousRemaining;
		int taskUnitsConsumed = Math.max(0, previousRemaining - currentRemaining);
		return SlayerTransitionResult.progress(previousRemaining, currentRemaining, remainingDelta, taskUnitsConsumed);
	}

	/**
	 * Richer pure result type — needed since PROGRESS carries payload data alongside
	 * its classification, rather than duplicating decision logic elsewhere.
	 * previousRemaining/currentRemaining/remainingDelta/taskUnitsConsumed
	 * are meaningful only when kind == PROGRESS; left at 0 (unused) for
	 * every other kind, mirroring XpWindowResult/LevelTransitionResult's
	 * existing "unused fields default, only shouldEmit/kind is load-
	 * bearing" convention elsewhere in this codebase.
	 */
	static final class SlayerTransitionResult
	{
		enum Kind
		{
			NONE, ASSIGNED, COMPLETED, PROGRESS
		}

		final Kind kind;
		final int previousRemaining;
		final int currentRemaining;
		final int remainingDelta;
		final int taskUnitsConsumed;

		private SlayerTransitionResult(Kind kind, int previousRemaining, int currentRemaining, int remainingDelta, int taskUnitsConsumed)
		{
			this.kind = kind;
			this.previousRemaining = previousRemaining;
			this.currentRemaining = currentRemaining;
			this.remainingDelta = remainingDelta;
			this.taskUnitsConsumed = taskUnitsConsumed;
		}

		static SlayerTransitionResult none()
		{
			return new SlayerTransitionResult(Kind.NONE, 0, 0, 0, 0);
		}

		static SlayerTransitionResult assigned()
		{
			return new SlayerTransitionResult(Kind.ASSIGNED, 0, 0, 0, 0);
		}

		static SlayerTransitionResult completed()
		{
			return new SlayerTransitionResult(Kind.COMPLETED, 0, 0, 0, 0);
		}

		static SlayerTransitionResult progress(int previousRemaining, int currentRemaining, int remainingDelta, int taskUnitsConsumed)
		{
			return new SlayerTransitionResult(Kind.PROGRESS, previousRemaining, currentRemaining, remainingDelta, taskUnitsConsumed);
		}
	}

	private SlayerState resolveCurrent()
	{
		SlayerState state = new SlayerState();

		int remaining = slayerPluginService.getRemainingAmount();
		state.setAmountRemaining(Math.max(remaining, 0));

		// Task identity
		// (taskName/taskLocation) must be captured from the service's
		// own task fields, never gated on amountRemaining > 0 --
		// amountRemaining == 0 does not by itself mean "no task exists"
		// (see evaluateSlayerTransition()'s javadoc). A blank/null task name from the
		// service is still the correct "no task" signal.
		String taskName = slayerPluginService.getTask();
		if (taskName != null && !taskName.isEmpty())
		{
			state.setTaskName(taskName);
			state.setTaskLocation(slayerPluginService.getTaskLocation());
			state.setInitialAmount(slayerPluginService.getInitialAmount());
		}

		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		state.setMasterId(masterId);
		state.setPoints(client.getVarbitValue(VarbitID.SLAYER_POINTS));

		if (masterId == KRYSTILIA_MASTER_ID)
		{
			state.setStreak(client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED));
			state.setStreakLabel("WILDERNESS");
			state.setStreakSourceVerified(true);
		}
		else
		{
			state.setStreak(client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED));
			state.setStreakLabel("NORMAL");
			state.setStreakSourceVerified(true);
		}

		return preserveTrustworthyInitialAmount(state);
	}

	/**
	 * Live evidence: immediately after login
	 * hydration, telemetry showed a real, already-named task
	 * (amountRemaining=116, taskName="Gargoyles") with initialAmount=0;
	 * a later read of the SAME task showed initialAmount=137. Root
	 * cause, traced against RuneLite's own SlayerPlugin.updateTask():
	 * `initialAmount` (like `taskName`) is only ever committed via
	 * setTask() -- read at that moment from the SLAYER_COUNT_ORIGINAL
	 * varp. If SLAYER_COUNT/SLAYER_TARGET (which drive amountRemaining
	 * and taskName) have already synced client-side at login but
	 * SLAYER_COUNT_ORIGINAL genuinely has not yet arrived from the
	 * server, that FIRST setTask() call legitimately captures
	 * initialAmount=0 -- this is SlayerPluginService's real "not yet
	 * populated" transient state for that one field, not a lie about
	 * the task itself (taskName/amountRemaining are still correct at
	 * the same moment).
	 *
	 * 0 is never persisted as if it were authoritative task
	 * metadata once we have already observed a real (non-zero)
	 * initialAmount for this EXACT task identity (taskName+taskLocation
	 * match against hydration's last committed baseline) -- the
	 * previously-trustworthy value is carried forward instead. This
	 * never fabricates a number that was never actually observed: if
	 * hydration has no prior baseline yet (very first-ever read of a
	 * brand new task), or the prior baseline is for a DIFFERENT task, or
	 * the prior baseline's own initialAmount was itself still 0, this is
	 * a no-op and 0 passes through unchanged -- honestly representing
	 * "not yet known" rather than guessing. The moment
	 * SlayerPluginService itself reports a real value for this task
	 * (e.g. once SLAYER_COUNT_ORIGINAL syncs and triggers another
	 * recheck), this method stops intervening and the real value flows
	 * through untouched, correcting slayer.json without ever emitting a
	 * spurious SLAYER_TASK_PROGRESS (evaluateSlayerTransition() only
	 * looks at amountRemaining/task identity, never initialAmount, so a
	 * pure initialAmount correction is silently absorbed into the next
	 * writeState() call).
	 */
	private SlayerState preserveTrustworthyInitialAmount(SlayerState state)
	{
		if (state.getTaskName() == null || state.getInitialAmount() != 0)
		{
			return state;
		}

		SlayerState previous = hydration.getLastKnown();
		if (previous != null
			&& previous.getInitialAmount() != 0
			&& Objects.equals(previous.getTaskName(), state.getTaskName())
			&& Objects.equals(previous.getTaskLocation(), state.getTaskLocation()))
		{
			state.setInitialAmount(previous.getInitialAmount());
		}

		return state;
	}

	private void writeState(SlayerState state)
	{
		state.setLastUpdated(Instant.now().toString());
		store.write(TelemetryPaths.stateFile(client.getAccountHash(), "slayer"), state);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.util.Text;

/**
 * See EventType.SERVER_NPC_LOOT's javadoc for the full producer-fact
 * naming rationale; summarized here for anyone reading only this file.
 *
 * SOURCE VERIFICATION (direct fetch of RuneLite source, not remembered
 * API names): confirmed the exact shape of every symbol this collector
 * depends on before writing any code against it.
 *
 *  - net.runelite.client.events.ServerNpcLoot: Lombok @Value, two
 *    fields — {@code NPCComposition composition} and
 *    {@code Collection<ItemStack> items} — with getters
 *    {@code getComposition()}/{@code getItems()}. Javadoc: "NPC loot
 *    received from the in-game loot tracker."
 *  - net.runelite.client.game.ItemStack: Lombok @Value, {@code int id},
 *    {@code int quantity} (a third, deprecated location-carrying
 *    constructor/accessor exists and is deliberately not used here).
 *  - net.runelite.client.plugins.loottracker.LootTrackerPlugin's own
 *    current {@code onServerNpcLoot(ServerNpcLoot event)}:
 *    <pre>
 *    final NPCComposition npc = event.getComposition();
 *    final Collection&lt;ItemStack&gt; items = event.getItems();
 *    final String name = Text.removeTags(npc.getName());
 *    final int combat = npc.getCombatLevel();
 *    if (ignorePickpocketLoot == client.getTickCount())
 *    {
 *        // server sends npc loot for pickpockets, ignore it
 *        return;
 *    }
 *    addLoot(name, combat, LootRecordType.NPC, buildNpcMetadata(npc), items);
 *    </pre>
 *  - The exact pickpocket regex that arms that same-tick guard, from
 *    the same file: {@code "You pick (the )?(?<target>.+)'s? pocket.*"},
 *    matched with {@code .matches()} (not {@code .find()}) against a
 *    chat message, in {@code onChatMessage()}, which then sets
 *    {@code ignorePickpocketLoot = client.getTickCount();} before
 *    handling the pickpocket loot itself via a separate
 *    inventory-diff path this project does not replicate (see the WHY
 *    THE PICKPOCKET FILTER EXISTS note below — this collector only
 *    needs to SUPPRESS ServerNpcLoot on that tick, not record
 *    pickpocket loot itself).
 *  - NPCComposition identity is read via {@code getName()}/{@code getId()}
 *    (and RuneLite's own handler additionally reads
 *    {@code getCombatLevel()}, not used here since this payload has no
 *    combat-level field — see EventPayloads.ServerNpcLoot).
 *
 * WHY THE PICKPOCKET FILTER EXISTS: {@code ServerNpcLoot} also fires for
 * pickpocket loot (a Thieving mechanic, not an NPC-death loot event),
 * and RuneLite's own core Loot Tracker has to explicitly filter it back
 * out for exactly that reason — see the source quoted above. This
 * collector replicates only the semantic effect (suppress
 * {@code ServerNpcLoot} on the tick a pickpocket chat message was just
 * observed), not RuneLite's fuller pickpocket-loot-recording machinery
 * (target-name disambiguation, inventory-diff collection): this
 * project has no Thieving/pickpocket telemetry goal, and broadening
 * into one is explicitly out of scope. Chat message text
 * is never persisted or written to telemetry — only whether it matched
 * the pickpocket pattern, and only the current game tick plus (when
 * resolvable) the identity of the NPC the local player was interacting
 * with at that instant, is retained, and only transiently.
 *
 * IDENTITY-AWARE PICKPOCKET SUPPRESSION: the ORIGINAL guard above
 * (unchanged from RuneLite's own core plugin, confirmed via the
 * verbatim source quote above) suppresses
 * {@code ServerNpcLoot} purely by same-tick coincidence, with NO check
 * that the suppressed loot notification actually belongs to the same
 * NPC the pickpocket message was about. Investigation of a live account
 * (Bandit {@code NPC_LOOT_ATTRIBUTED} events present, but zero Bandit
 * {@code SERVER_NPC_LOOT} events across the entire account history —
 * the only source with a complete blackout) confirmed this collector's
 * own suppression guard, not anything upstream of Spyglass, as the root
 * cause: Bandits are a common pickpocket target, so an unrelated
 * pickpocket-success message landing on the same tick as a genuine
 * Bandit-kill {@code ServerNpcLoot} was silently discarding the kill's
 * loot.
 *
 * The fix: {@code onChatMessage()} now additionally captures, at the
 * exact instant a pickpocket message is observed, the identity (NPC id
 * and/or name, when resolvable) of whatever NPC
 * {@code client.getLocalPlayer().getInteracting()} currently points at
 * — bundled with the tick into one immutable
 * {@link PickpocketSuppressionState}, published atomically via a single
 * volatile field so a concurrent reader never sees a torn combination.
 * {@link #shouldSuppress(PickpocketSuppressionState, int, String, int)}
 * then suppresses a same-tick {@code ServerNpcLoot} only when the
 * event's own source identity actually matches that captured identity
 * (NPC id first when both sides have one, otherwise a normalized name
 * comparison) — an unrelated NPC's kill loot landing on the same tick
 * as someone else's pickpocket message is no longer suppressed. When no
 * identity could be captured at all at pickpocket-message time (the
 * local player's interaction target could not be resolved to an NPC at
 * that instant), suppression falls back to the original tick-only rule,
 * so the "never allow duplicate pickpocket loot" guarantee still holds
 * in that narrow case. This fix applies uniformly to every NPC name —
 * there is no Bandit-specific (or any other name-specific) branch
 * anywhere in this file.
 *
 * HONEST LIMITATION: {@code net.runelite.client.events.ServerNpcLoot}'s
 * {@code NPCComposition} is DEFINITION-level (shared by every on-screen
 * instance of the same NPC type), not instance-level — RuneLite exposes
 * no per-instance NPC reference on this event at all. Identity-aware
 * suppression, however implemented, can therefore only ever confirm
 * "same NPC type," never "same specific NPC instance." Two different
 * instances of the exact same NPC type acting on the exact same tick
 * (one pickpocketed, one killed) remain indistinguishable by this or
 * any fix built on this event — a structural ceiling imposed by the
 * RuneLite API this collector consumes, not a shortcut taken here.
 *
 * INDEPENDENCE (see EventType.SERVER_NPC_LOOT's javadoc): this event
 * never depends on, gates on, or correlates with NPC_DEATH,
 * NPC_LOOT_ATTRIBUTED, SLAYER_TASK_PROGRESS, BOSS_KILL, or any
 * raid/activity completion event. No local-player kill is synthesized
 * from the mere existence of server loot, and no NPC_DEATH/kill
 * reference field exists anywhere on this payload. This collector's
 * only two inputs are RuneLite's own {@code ServerNpcLoot} event and
 * the pickpocket chat-message pattern (plus, now, the local player's
 * interaction target at that instant) used solely to suppress it —
 * nothing else.
 *
 * NPC_LOOT_ATTRIBUTED (LootCollector, built on the separate
 * {@code NpcLootReceived}/{@code LootManager} tile+tick-correlation
 * signal) is a separate, weaker signal, unmodified by this collector —
 * see LootCollector's own class javadoc.
 */
public class ServerNpcLootCollector
{
	/**
	 * Verified verbatim against current LootTrackerPlugin.java source —
	 * see class javadoc. Matched with {@code .matches()}, exactly as
	 * RuneLite's own handler does (a partial/{@code .find()} match
	 * against this pattern could behave differently for messages that
	 * merely contain, rather than consist of, matching text).
	 */
	private static final Pattern PICKPOCKET_REGEX =
		Pattern.compile("You pick (the )?(?<target>.+)'s? pocket.*");

	/**
	 * Sentinel meaning "no pickpocket message observed yet this
	 * client run" — deliberately NOT RuneLite's own default of {@code 0}
	 * (an {@code int} field's implicit initial value), since RuneLite's
	 * {@code client.getTickCount()} could theoretically already be
	 * {@code 0} at the moment this collector is constructed, which
	 * would make an unset guard falsely equal a real tick count. Tick
	 * counts are never negative, so {@code -1} is a safe, real "not
	 * armed" sentinel — the same "non-positive means not available"
	 * discipline this project already applies to nullable NPC ids
	 * elsewhere (see NpcDeathCollector.buildPayload()).
	 */
	private static final int NOT_ARMED_TICK = -1;

	/**
	 * Immutable snapshot of what this collector knows about the most
	 * recently observed pickpocket chat message: the tick it occurred
	 * on, and — when resolvable — the identity of the NPC the local
	 * player was interacting with at that exact instant. Bundled into a
	 * single object (rather than parallel fields on the collector)
	 * specifically so the whole snapshot can be published atomically
	 * via one volatile reference — see {@code pickpocketSuppression}
	 * below — with no risk of a concurrent reader ever observing a torn
	 * combination of tick/id/name assembled from two different
	 * pickpocket messages.
	 *
	 * {@code npcId}/{@code npcName} are both {@code null} exactly when
	 * no NPC identity could be resolved at pickpocket-message time
	 * (the local player's {@code getInteracting()} target was null, not
	 * an {@code NPC}, or its composition could not be read) — this is
	 * the explicit "identity unknown" case
	 * {@link #shouldSuppress(PickpocketSuppressionState, int, String, int)}
	 * falls back to the original tick-only behavior for.
	 *
	 * Package-private (not private) so
	 * {@code ServerNpcLootCollectorTest} can construct and inspect it
	 * directly, exactly like every other pure/testable piece of this
	 * collector.
	 */
	static final class PickpocketSuppressionState
	{
		private static final PickpocketSuppressionState NOT_ARMED =
			new PickpocketSuppressionState(NOT_ARMED_TICK, null, null);

		final int tick;
		final Integer npcId;
		final String npcName;

		private PickpocketSuppressionState(int tick, Integer npcId, String npcName)
		{
			this.tick = tick;
			this.npcId = npcId;
			this.npcName = npcName;
		}

		static PickpocketSuppressionState notArmed()
		{
			return NOT_ARMED;
		}

		static PickpocketSuppressionState armed(int tick, Integer npcId, String npcName)
		{
			return new PickpocketSuppressionState(tick, npcId, npcName);
		}
	}

	private final Client client;
	private final ItemManager itemManager;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;

	private volatile PickpocketSuppressionState pickpocketSuppression = PickpocketSuppressionState.notArmed();

	@Inject
	public ServerNpcLootCollector(Client client, ItemManager itemManager, EventLedger eventLedger, OsrsTelemetryConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.eventLedger = eventLedger;
		this.config = config;
	}

	/**
	 * Defensive reset on a real account switch, mirroring every other
	 * collector's resetForAccountSwitch() convention (see
	 * OsrsTelemetryPlugin.handleLogin()) even though the risk here is
	 * small (leftover suppression state from the outgoing account could
	 * only matter if the very next ServerNpcLoot for the new account
	 * arrived on the exact same client tick count AND matched the
	 * leftover captured identity) — consistent with this project's
	 * existing "never diff/suppress across an account boundary on
	 * leftover state" discipline.
	 */
	public void resetForAccountSwitch()
	{
		pickpocketSuppression = PickpocketSuppressionState.notArmed();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.collectLoot())
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (isPickpocketMessage(message))
		{
			Integer npcId = null;
			String npcName = null;

			NPC interactingNpc = safeInteractingNpc(client);
			if (interactingNpc != null)
			{
				NPCComposition composition = safeTransformedComposition(interactingNpc);
				if (composition != null)
				{
					npcId = safeNpcId(interactingNpc);
					npcName = safeName(composition);
				}
			}

			pickpocketSuppression = PickpocketSuppressionState.armed(client.getTickCount(), npcId, npcName);
		}
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!config.collectLoot())
		{
			return;
		}

		NPCComposition composition = event.getComposition();
		String sourceName = composition.getName();
		int rawSourceId = composition.getId();

		if (shouldSuppress(pickpocketSuppression, client.getTickCount(), sourceName, rawSourceId))
		{
			// RuneLite's own Loot Tracker suppresses ServerNpcLoot on the
			// same tick a pickpocket chat message was just observed — see
			// class javadoc. This collector additionally requires the
			// suppressed loot to actually match the NPC identity captured
			// at pickpocket-message time (or, when no identity could be
			// captured at all, falls back to the original tick-only
			// guard) — see shouldSuppress()'s own javadoc for why.
			return;
		}

		List<EventPayloads.ServerNpcLootItem> items = new ArrayList<>();
		for (ItemStack itemStack : event.getItems())
		{
			String itemName = itemManager.getItemComposition(itemStack.getId()).getName();
			items.add(new EventPayloads.ServerNpcLootItem(itemStack.getId(), itemName, itemStack.getQuantity()));
		}

		EventPayloads.ServerNpcLoot payload = buildPayload(sourceName, rawSourceId, items);
		eventLedger.append(client.getAccountHash(), EventType.SERVER_NPC_LOOT, payload);
	}

	/**
	 * Defensive read of the local player's current interaction target,
	 * narrowed to an {@code NPC} — mirrors
	 * NpcInteractionTargetCollector's identical
	 * {@code InteractingChanged}-source-is-local-player technique, but
	 * reads the live value synchronously at pickpocket-message time
	 * instead of subscribing to a separate event, so this collector
	 * stays self-contained (no new cross-collector coupling for what
	 * should be a collector correctness fix, not a rewrite). Returns
	 * null for every unresolved/non-NPC/unavailable case rather than
	 * propagating — never treated as "an NPC by default."
	 */
	private static NPC safeInteractingNpc(Client client)
	{
		try
		{
			Actor localPlayer = client.getLocalPlayer();
			if (localPlayer == null)
			{
				return null;
			}
			Actor interacting = localPlayer.getInteracting();
			return (interacting instanceof NPC) ? (NPC) interacting : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Same defensive {@code getTransformedComposition()} idiom
	 * NpcInteractionTargetCollector already uses — the current
	 * visible-form composition, correct across multi-form/transforming
	 * NPCs, never null-by-default.
	 */
	private static NPCComposition safeTransformedComposition(NPC npc)
	{
		try
		{
			return npc.getTransformedComposition();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String safeName(NPCComposition composition)
	{
		try
		{
			return composition.getName();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * npcId mirrors NpcDeathCollector.buildPayload()'s/this file's own
	 * buildPayload()'s "do not fabricate missing values" precedent: any
	 * non-positive raw id is treated as "not available" and left null.
	 */
	private static Integer safeNpcId(NPC npc)
	{
		try
		{
			int rawId = npc.getId();
			return rawId > 0 ? rawId : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Pure — unit-testable without a Client. Exact same regex/match
	 * style as RuneLite's own PICKPOCKET_REGEX handling (see class
	 * javadoc) so this collector suppresses on exactly the same
	 * messages RuneLite's own Loot Tracker would. */
	static boolean isPickpocketMessage(String message)
	{
		return PICKPOCKET_REGEX.matcher(message).matches();
	}

	/**
	 * Pure — unit-testable without a Client. Suppresses a
	 * {@code ServerNpcLoot} notification only when there is sufficient
	 * evidence it represents the SAME pickpocket action as the most
	 * recently observed pickpocket chat message — not merely that some
	 * pickpocket message happened to land on the same game tick as an
	 * unrelated NPC kill. Matching rule, in order:
	 *
	 * <ol>
	 *   <li>Different tick — never suppress (unchanged from the
	 *   original tick-only guard; {@code NOT_ARMED_TICK} (-1) never
	 *   equals a real, non-negative tick).</li>
	 *   <li>Same tick, but NO NPC identity was captured at
	 *   pickpocket-message time ({@code suppressionState.npcId} and
	 *   {@code suppressionState.npcName} both null — e.g. the local
	 *   player's interaction target could not be resolved to an NPC at
	 *   that instant) — fall back to the original tick-only
	 *   suppression, preserving the "never allow duplicate pickpocket
	 *   loot" guarantee in this narrow case where identity is simply
	 *   unavailable.</li>
	 *   <li>Same tick, identity WAS captured — suppress only when the
	 *   {@code ServerNpcLoot} event's own source identity matches:
	 *   compare by NPC id when both sides have a resolvable (positive)
	 *   id, otherwise fall back to a normalized ({@code Text.removeTags})
	 *   name comparison. A same-tick {@code ServerNpcLoot} for a
	 *   DIFFERENT NPC (by id, or by name when no id is available on
	 *   either side) is never suppressed — this is the fix for "an
	 *   unrelated NPC kill's loot disappears merely because a pickpocket
	 *   message for a different NPC happened to land on the same tick."
	 *   Applies uniformly to every NPC name — there is no Bandit-
	 *   specific (or any other name-specific) branch anywhere in this
	 *   method or this file.</li>
	 * </ol>
	 *
	 * {@code NPCComposition} identity as exposed by RuneLite's
	 * {@code ServerNpcLoot} event is definition-level (shared by every
	 * on-screen instance of the same NPC type), not instance-level —
	 * RuneLite exposes no per-instance NPC reference on this event at
	 * all. This match can therefore only ever confirm "same NPC type,"
	 * never "same specific NPC instance" — an honest ceiling imposed by
	 * the RuneLite API this collector consumes, not a shortcut taken
	 * here (see class javadoc's HONEST LIMITATION section).
	 */
	static boolean shouldSuppress(
		PickpocketSuppressionState suppressionState,
		int currentTick,
		String sourceName,
		int rawSourceId)
	{
		if (suppressionState.tick != currentTick)
		{
			return false;
		}

		if (suppressionState.npcId == null && suppressionState.npcName == null)
		{
			// No identity captured at pickpocket-message time at all —
			// fall back to the original tick-only behavior.
			return true;
		}

		Integer sourceId = rawSourceId > 0 ? rawSourceId : null;
		if (suppressionState.npcId != null && sourceId != null)
		{
			return suppressionState.npcId.equals(sourceId);
		}

		return namesMatch(suppressionState.npcName, sourceName);
	}

	private static boolean namesMatch(String a, String b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		return Text.removeTags(a).equals(Text.removeTags(b));
	}

	/**
	 * Pure, Client/EventLedger/RuneLite-API-independent core of the
	 * SERVER_NPC_LOOT payload construction — factored out for the same
	 * reason as every other collector's buildPayload() helper in this
	 * project (see LootCollector.buildPayload()/NpcDeathCollector.
	 * buildPayload()): unit-testable without mocking NPCComposition/
	 * ItemStack/Client. This is a pass-through, not a decision — every
	 * value already read off RuneLite's own objects is stored exactly
	 * as given, never defaulted or fabricated, except sourceId's
	 * documented non-positive-means-unavailable normalization below.
	 *
	 * rawSourceId nullability: NPCComposition#getId() carries no
	 * documented guarantee of always returning a real, usable value —
	 * mirroring the same treatment NpcDeathCollector.buildPayload()
	 * already applies to NPC#getId(): any non-positive raw value is
	 * treated as "not available" and left null rather than stored as a
	 * misleading not-actually-real id.
	 *
	 * items is stored exactly as given, including when empty — an
	 * empty items list is never fabricated into "no event at all" or
	 * padded with an invented item; whatever RuneLite's own
	 * ServerNpcLoot notification actually carried is what this payload
	 * carries.
	 */
	static EventPayloads.ServerNpcLoot buildPayload(
		String sourceName,
		int rawSourceId,
		List<EventPayloads.ServerNpcLootItem> items)
	{
		Integer sourceId = rawSourceId > 0 ? rawSourceId : null;
		return new EventPayloads.ServerNpcLoot(sourceName, sourceId, items);
	}
}

package com.osrstelemetry.plugin.collectors;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Singleton;

/**
 * An earlier design resolved a candidate boss name ONLY after
 * ActivityKillCountCollector had already parsed a "Your X kill count
 * is:" message for that account in the CURRENT runtime. That defeated
 * the entire point of the feature: a fresh plugin start facing a
 * brand-new boss (e.g. Zulrah) could never be recognized as
 * BOSS_ACTIVITY_CONTEXT until AFTER its first BOSS_KILL landed. See
 * this class's own tests for the regression coverage.
 *
 * A small, per-account registry of boss names this plugin can
 * recognize, used to resolve an NPC name (from InteractingChanged --
 * see BossActivityContextCollector) into a canonical boss display
 * name for the NEW, non-authoritative BOSS_ACTIVITY_CONTEXT signal.
 * Deliberately dependency-free: no RuneLite API type appears anywhere
 * in this class, so it is fully unit-testable with plain JUnit, same
 * as every other pure/testable class this project already has.
 *
 * TWO SOURCES OF TRUTH now feed recognition:
 *
 *  1. STATIC_SEED_BOSS_NAMES_NORMALIZED -- a small, explicit,
 *     project-owned, hardcoded map of normalized-name -> canonical
 *     display name for well-known boss encounters, present from the
 *     moment the plugin starts, with ZERO dependency on having
 *     observed any kill-count message in the current runtime. This is
 *     what makes fresh-start recognition possible at all. Keying by
 *     normalized name -> canonical display name (rather than a plain
 *     Set<String> of normalized names) is what lets seeded resolution
 *     return the correct canonical casing regardless of how the
 *     candidate name itself was cased/whitespaced.
 *
 *     IMPORTANT / HONEST SCOPE: no authoritative local RuneLite data
 *     source was available to derive this list from (re-audited: no
 *     RuneLite client jar is vendored or present in any Gradle/Maven
 *     cache in this environment -- `runeLiteVersion = 'latest.release'`
 *     in build.gradle is resolved fresh over the network at build
 *     time, never fetched or cached here; no NpcID/NpcNames/
 *     NpcOverrides/BossTimersPlugin reference exists anywhere in this
 *     repo; no vendor/docs/reference directory carries any upstream
 *     RuneLite source; no src/main/resources boss data file exists).
 *     This list is therefore a project-owned, manually curated SEED,
 *     not something derived from or verified against RuneLite
 *     internals. Kept deliberately small and limited to boss names
 *     the author is confident are canonical, single, unambiguous
 *     in-game NPC/encounter names -- extend it over time as more
 *     bosses are confirmed correct, rather than trying to be
 *     exhaustive up front.
 *
 *  2. CONFIRMED BOSS NAMES (per account) -- harvested for free from
 *     ActivityKillCountCollector's own existing "Your X kill count
 *     is:" chat-message parsing, the exact same authoritative source
 *     BOSS_KILL already trusts. See recordConfirmedBoss(), called from
 *     ActivityKillCountCollector.recordKillCount() once a boss name is
 *     parsed from a real kill-count message -- never fabricated,
 *     never guessed. This AUGMENTS the static seed: a boss not in the
 *     seed list still gets pre-kill recognition on its SECOND and
 *     later encounters, once its name has been confirmed once. It is
 *     never a PREREQUISITE for a boss already in the static seed.
 *
 * NPC_NAME_ALIASES -- a minimal, explicit, hand-maintained table ONLY
 * for the disclosed multi-NPC-name case: Dawn and Dusk (the two NPCs
 * that together make up the Grotesque Guardians boss encounter) both
 * alias to the single canonical boss display name "Grotesque
 * Guardians". This table is deliberately NOT a general NPC-ID-to-boss
 * database -- every other supported boss is resolved purely via
 * direct name equality (the NPC's own name matches the canonical boss
 * name directly, e.g. interacting with an NPC named "Zulrah" resolves
 * because "Zulrah" itself is either in the static seed or has been
 * confirmed). The alias TARGET string stored here is only ever used as
 * a lookup key into the same static-seed/confirmed resolution path
 * (see resolveRecognizedDisplayName()) -- it is never returned
 * literally, so a typo or miscasing in this table can never itself
 * leak into a returned display name; the canonical casing always comes
 * from STATIC_SEED_BOSS_NAMES_NORMALIZED or the per-account confirmed
 * map. KNOWN COVERAGE GAP: other bosses with multi-NPC-name or
 * phase-based naming (differently-named forms/phases) are NOT
 * supported by this alias table today -- only the Dawn/Dusk case has
 * been explicitly verified and added; do not assume broad generic
 * coverage of every multi-phase boss.
 *
 * An alias only ever resolves once the ALIAS TARGET itself is
 * actually recognized (via the static seed OR a per-account confirmed
 * kill) -- see resolveCandidateBossName() -- the alias table alone is
 * never sufficient proof by itself.
 *
 * This class never produces the final session ActivityIdentity/
 * activityKey itself -- ActivitySignalClassifier.bossIdentity() (the
 * SAME canonicalization BOSS_KILL already uses) is what turns the
 * display name this class resolves into a session identity, so there
 * is exactly one place in this codebase that owns that canonicalization.
 * This class's own normalize() is a separate, much smaller thing: pure
 * case/whitespace-insensitive MATCHING against the recognized-name
 * set, not identity-key production.
 */
@Singleton
public class KnownBossRegistry
{
	/**
	 * Project-owned static seed of normalized boss name -> canonical
	 * boss display name, present at construction with no
	 * account/runtime dependency. See class javadoc for the honest
	 * scope of this list -- it is a curated seed, NOT derived from any
	 * verified RuneLite data source available in this environment.
	 * Keyed by normalized name so lookup is case/whitespace-insensitive
	 * while the VALUE always preserves the canonical display casing --
	 * this is what lets seeded resolution return the correct canonical
	 * name regardless of how the candidate itself was cased/
	 * whitespaced. Kept modest and limited to boss names the author is
	 * confident are canonical, single, unambiguous in-game names.
	 * Extend as more bosses are confirmed.
	 */
	private static final Map<String, String> STATIC_SEED_BOSS_NAMES_NORMALIZED;

	static
	{
		Map<String, String> seed = new HashMap<>();
		addSeed(seed, "Zulrah");
		addSeed(seed, "Grotesque Guardians");
		addSeed(seed, "Vorkath");
		addSeed(seed, "General Graardor");
		addSeed(seed, "Kree'arra");
		addSeed(seed, "K'ril Tsutsaroth");
		addSeed(seed, "Commander Zilyana");
		addSeed(seed, "Kalphite Queen");
		addSeed(seed, "Giant Mole");
		addSeed(seed, "Dagannoth Rex");
		addSeed(seed, "Dagannoth Prime");
		addSeed(seed, "Dagannoth Supreme");
		addSeed(seed, "Cerberus");
		addSeed(seed, "Thermonuclear Smoke Devil");
		addSeed(seed, "Alchemical Hydra");
		addSeed(seed, "Callisto");
		addSeed(seed, "Venenatis");
		addSeed(seed, "Vet'ion");
		addSeed(seed, "Scorpia");
		STATIC_SEED_BOSS_NAMES_NORMALIZED = Collections.unmodifiableMap(seed);
	}

	private static void addSeed(Map<String, String> seed, String canonicalDisplayName)
	{
		seed.put(normalize(canonicalDisplayName), canonicalDisplayName);
	}

	/**
	 * NPC name (as it appears on the NPC actor / in InteractingChanged)
	 * -> canonical boss display name. Deliberately tiny -- see class
	 * javadoc. Extend this table only if a future boss encounter is
	 * confirmed to use multiple differently-named NPCs the same way
	 * Grotesque Guardians does; do not add single-NPC bosses here, they
	 * already resolve via direct name equality.
	 */
	private static final Map<String, String> NPC_NAME_ALIASES = new ConcurrentHashMap<>();

	static
	{
		NPC_NAME_ALIASES.put(normalize("Dawn"), "Grotesque Guardians");
		NPC_NAME_ALIASES.put(normalize("Dusk"), "Grotesque Guardians");
	}

	/**
	 * accountHash -> (normalized boss name -> confirmed display name).
	 * The display name preserves the exact casing
	 * ActivityKillCountCollector observed in the real kill-count
	 * message, so a resolved BOSS_ACTIVITY_CONTEXT candidate and a
	 * later BOSS_KILL for the same boss present identically. Per-account
	 * so confirming a boss for one account never leaks to another (see
	 * resetForAccountSwitch()). Additive on top of the static seed --
	 * never required by it.
	 */
	private final Map<Long, Map<String, String>> confirmedByAccount = new ConcurrentHashMap<>();

	/**
	 * Called from ActivityKillCountCollector.recordKillCount() once a
	 * boss name is parsed from a real, authoritative "Your X kill count
	 * is:" message -- never called speculatively, never called with a
	 * guessed name.
	 */
	public void recordConfirmedBoss(long accountHash, String displayName)
	{
		if (displayName == null || displayName.trim().isEmpty())
		{
			return;
		}
		confirmedByAccount
			.computeIfAbsent(accountHash, key -> new ConcurrentHashMap<>())
			.put(normalize(displayName), displayName.trim());
	}

	/**
	 * @return the canonical boss display name if `npcName` resolves to
	 * a boss this class recognizes -- either because it (or its alias
	 * target) is in the static seed list, or because it (or its alias
	 * target) has actually been confirmed for this account via a real
	 * kill-count message; null otherwise. An unrecognized NPC name, or
	 * a recognized alias whose target is neither seeded nor confirmed,
	 * both resolve to null rather than a guess.
	 */
	public String resolveCandidateBossName(long accountHash, String npcName)
	{
		if (npcName == null || npcName.trim().isEmpty())
		{
			return null;
		}

		String normalizedNpcName = normalize(npcName);
		Map<String, String> confirmed = confirmedByAccount.get(accountHash);

		String aliasTarget = NPC_NAME_ALIASES.get(normalizedNpcName);
		if (aliasTarget != null)
		{
			// Dawn/Dusk -> only resolves once "Grotesque Guardians" itself
			// is actually recognized (seed or confirmed) -- see class
			// javadoc. The alias table alone is never sufficient proof.
			// aliasTarget is used only as a lookup key here -- the actual
			// returned value always comes from the seed/confirmed map, so
			// the canonical casing is never taken from this literal.
			return resolveRecognizedDisplayName(aliasTarget, confirmed);
		}

		return resolveRecognizedDisplayName(npcName, confirmed);
	}

	/**
	 * Shared recognition check: seed first (present from construction,
	 * canonical casing looked up from STATIC_SEED_BOSS_NAMES_NORMALIZED's
	 * value, never the raw candidate string), then falls back to this
	 * account's confirmed set (canonical casing as observed in the real
	 * kill-count message).
	 */
	private static String resolveRecognizedDisplayName(String candidateName, Map<String, String> confirmedForAccount)
	{
		String normalizedCandidate = normalize(candidateName);

		String seededDisplayName = STATIC_SEED_BOSS_NAMES_NORMALIZED.get(normalizedCandidate);
		if (seededDisplayName != null)
		{
			return seededDisplayName;
		}

		if (confirmedForAccount != null)
		{
			String confirmedDisplayName = confirmedForAccount.get(normalizedCandidate);
			if (confirmedDisplayName != null)
			{
				return confirmedDisplayName;
			}
		}

		return null;
	}

	/**
	 * Per-account reset, mirroring every other collector's own
	 * resetForAccountSwitch() convention in this project (see
	 * ActivityKillCountCollector.resetForAccountSwitch(),
	 * ServerNpcLootCollector.resetForAccountSwitch()) -- confirming a
	 * boss for account A must never leak into account B's resolution.
	 * The static seed is unaffected -- it is not per-account state.
	 */
	public void resetForAccountSwitch(long accountHash)
	{
		confirmedByAccount.remove(accountHash);
	}

	/** Pure -- unit-testable without a Client. Trim + lowercase matching
	 * only, deliberately NOT the same method as
	 * ActivitySignalClassifier.bossIdentity() (this class never imports
	 * the session package) -- see class javadoc for why this is not
	 * "duplicated normalization logic": this is small, local, one-line
	 * MATCHING, while bossIdentity() alone owns producing the actual
	 * session ActivityIdentity/activityKey. */
	static String normalize(String s)
	{
		return s.trim().toLowerCase(Locale.ROOT);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/**
 * The event this collector emits was renamed LOOT_DROP ->
 * NPC_LOOT_ATTRIBUTED after a read-only audit of the exact RuneLite
 * source path that produces it, summarized here.
 *
 * SOURCE (unchanged): net.runelite.client.events.NpcLootReceived, the
 * same event RuneLite's own core Loot Tracker plugin subscribes to
 * (LootTrackerPlugin#onNpcLootReceived). Produced by
 * net.runelite.client.game.LootManager.
 *
 * WHAT THE AUDIT CONFIRMED (direct read of LootManager.java's current
 * source, not inferred): LootManager.onItemSpawned() adds EVERY
 * ItemSpawned observation to a per-scene-tile map unconditionally —
 * TileItem#getOwnership() (OWNERSHIP_SELF/OWNERSHIP_OTHER/
 * OWNERSHIP_GROUP/OWNERSHIP_NONE) and TileItem#isPrivate() are never
 * called anywhere in that file. When an NPC despawns,
 * getDropLocations(npc) computes the tile(s) its loot should appear
 * on (npc.getWorldArea() for ordinary NPCs; special-cased offsets for
 * bosses like Vorkath/Kraken), and getItemStacksFromAreas() then just
 * reads whatever TileItem(s) are sitting there — converted to
 * ItemStack by id+quantity only, with itemSpawns/killPoints cleared
 * every single onGameTick(). This is pure tile + same-tick spatial/
 * temporal correlation to a despawn — NOT ownership-verified. It can
 * genuinely include another visible player's drop that happens to
 * land on the same tile in the same tick, or an item the game itself
 * marks OWNERSHIP_OTHER/OWNERSHIP_GROUP/OWNERSHIP_NONE, since none of
 * that is ever read. It is also despawn-correlated, not strictly
 * death-correlated: for certain monsters that "die" with >0 HP
 * (gargoyles, rockslugs, lizards, zygomites — code comment: "these
 * monsters die with >0 hp, so we just look for coincident item spawn
 * with despawn"), attribution leans on despawn timing rather than a
 * true death signal at all.
 *
 * CONCLUSION: NpcLootReceived proves "RuneLite's LootManager
 * attributed an observed item stack to an NPC (by tile+tick
 * correlation to its despawn)." It does NOT prove the item was
 * actually awarded to or owned by the local player. "LOOT_DROP"
 * (and "LootDrop") read as "my loot" — that's the overclaim this
 * rename corrects. Nothing about the actual filtering/collection
 * logic below changed, only the event/payload name.
 *
 * ServerNpcLoot (net.runelite.client.events.ServerNpcLoot, "NPC loot
 * received from the in-game loot tracker") was investigated as a
 * possible stronger-ownership alternative and deliberately NOT
 * switched to: RuneLite's own core LootTrackerPlugin has to
 * explicitly filter pickpocket loot back OUT of it (a tick-based
 * `ignorePickpocketLoot` guard, comment: "server sends npc loot for
 * pickpockets, ignore it") — since pickpocketing only ever rewards
 * the local player, that filtering need is itself real evidence
 * ServerNpcLoot IS scoped to the local player's own loot-granting
 * events specifically (materially stronger ownership semantics than
 * NpcLootReceived). But it carries only NPCComposition (no specific
 * NPC instance/location data) and conflates a non-death loot
 * mechanic (pickpocketing) unless filtered — switching would trade
 * this event's tile/location and "any observed attribution" coverage
 * for a narrower, differently-shaped signal, not simply strengthen
 * it. Left as future work for a possible separate, genuinely
 * player-owned-loot event, rather than combining two semantically
 * different signals under one event type.
 *
 * PlayerLootReceived (PvP loot, e.g. Wilderness kills) exists as a
 * sibling event but is deliberately out of scope: this project targets
 * Group Ironman accounts, for whom PvP loot isn't a normal data
 * source, and adding it now would be scope creep.
 */
public class LootCollector
{
	private final Client client;
	private final ItemManager itemManager;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;

	@Inject
	public LootCollector(Client client, ItemManager itemManager, EventLedger eventLedger, OsrsTelemetryConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.eventLedger = eventLedger;
		this.config = config;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		if (!config.collectLoot())
		{
			return;
		}

		NPC npc = event.getNpc();
		String sourceName = npc.getName();
		int sourceId = npc.getId();

		for (ItemStack itemStack : event.getItems())
		{
			String itemName = itemManager.getItemComposition(itemStack.getId()).getName();
			eventLedger.append(
				client.getAccountHash(),
				EventType.NPC_LOOT_ATTRIBUTED,
				buildPayload("NPC", sourceName, sourceId, itemStack.getId(), itemName, itemStack.getQuantity())
			);
		}
	}

	/**
	 * Pure, Client/EventLedger/RuneLite-API-independent core
	 * of the NPC_LOOT_ATTRIBUTED payload construction — factored out
	 * purely so LootCollectorTest can exercise it without mocking
	 * RuneLite's NPC/Client/ItemManager/NpcLootReceived types (this
	 * project has no Mockito dependency — see BankSnapshotBaselineTest's
	 * javadoc for the same constraint noted before). This is a pass-
	 * through, not a decision: every value already read off RuneLite's
	 * own objects (sourceType/sourceName/sourceId/itemId/itemName/
	 * quantity) is stored on the payload exactly as given, never
	 * defaulted, normalized, or fabricated when something upstream
	 * (e.g. npc.getName()) happens to be null — that's the specific
	 * "do not fabricate missing values" contract LootCollectorTest
	 * pins down.
	 *
	 * No behavior changed by this extraction: onNpcLootReceived() calls
	 * this with the exact same arguments it previously passed directly
	 * to `new EventPayloads.NpcLootAttributed(...)`.
	 */
	static EventPayloads.NpcLootAttributed buildPayload(
		String sourceType,
		String sourceName,
		int sourceId,
		int itemId,
		String itemName,
		int quantity)
	{
		return new EventPayloads.NpcLootAttributed(sourceType, sourceName, sourceId, itemId, itemName, quantity);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Individual task completion fires live as a chat message and is
 * reliable to detect that way (VERIFY exact current wording — this is
 * the kind of string Jagex has tweaked before). Tags stripped via
 * Text.removeTags() same as the collection log collector.
 *
 * totalPoints and unlockedTier are NOT derivable from this message —
 * they live in the Combat Achievements interface (varbit or widget,
 * not yet verified). Left unimplemented here rather than invented;
 * the completion EVENT below is real and doesn't depend on that gap.
 */
public class CombatAchievementCollector
{
	private static final Pattern TASK_COMPLETED =
		Pattern.compile("Congratulations, you(?:'ve| have) completed an? (\\w+) combat task: (.+)\\.");

	private final Client client;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;

	@Inject
	public CombatAchievementCollector(Client client, EventLedger eventLedger, OsrsTelemetryConfig config)
	{
		this.client = client;
		this.eventLedger = eventLedger;
		this.config = config;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.collectCombatAchievements())
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		Matcher matcher = TASK_COMPLETED.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String tier = matcher.group(1);
		String taskName = matcher.group(2).trim();

		eventLedger.append(
			client.getAccountHash(),
			EventType.COMBAT_ACHIEVEMENT_COMPLETED,
			new EventPayloads.CombatAchievementCompleted(tier, taskName)
		);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.model.AccountIdentity;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.api.Client;

/**
 * `Client#getAccountType()` is confirmed via a direct fetch of the
 * current Client.java source — exact signature
 * `AccountType getAccountType();`, importing
 * `net.runelite.api.vars.AccountType` (NOT plain `net.runelite.api.AccountType`).
 * The method IS marked `@Deprecated` in current RuneLite source, with
 * its javadoc pointing callers at `Varbits#ACCOUNT_TYPE` instead.
 * Deprecated is not the same as wrong: the method still exists, still
 * compiles, and still returns a real enum with a working `.name()` —
 * nothing here is demonstrably broken, so the call below is left
 * as-is. Flagged as a real (not fabricated) future-work item:
 * migrating to `Varbits#ACCOUNT_TYPE` would remove a dependency on a
 * deprecated API, but was not done here. The existing try/catch below
 * already protects identity capture from any future incompatibility
 * either way.
 */
public class IdentityCollector
{
	private final Client client;
	private final LocalStateStore store;

	@Inject
	public IdentityCollector(Client client, LocalStateStore store)
	{
		this.client = client;
		this.store = store;
	}

	public void captureOnLogin()
	{
		long accountHash = client.getAccountHash();
		AccountIdentity identity = new AccountIdentity(Long.toString(accountHash));
		identity.setDisplayName(client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null);
		identity.setCapturedAt(Instant.now().toString());

		try
		{
			identity.setAccountType(client.getAccountType().name());
		}
		catch (RuntimeException | NoSuchMethodError e)
		{
			// Defensive: if the accessor name/shape turns out to be
			// different once compiled, don't let identity capture
			// (the one thing every other collector's file path
			// depends on via accountHash) fail entirely over a
			// non-essential field.
			identity.setAccountType(null);
		}

		store.write(TelemetryPaths.stateFile(accountHash, "identity"), identity);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.model.ActivityState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Deliberately generic, not a per-boss enum.
 *
 * A "completion count" message alone does not by itself imply
 * RAID_COMPLETION. Only the three verified raids
 * (Chambers of Xeric, Theatre of Blood, Tombs of Amascut) get that
 * event type; the Corrupted Gauntlet, minigames, and anything else
 * that happens to print a completion-count line get the generic
 * ACTIVITY_COMPLETION type instead. RAID_IDS is intentionally a small,
 * explicit allowlist rather than a guess at what "sounds like" a raid.
 */
public class ActivityKillCountCollector
{
	private static final Pattern BOSS_KC =
		Pattern.compile("Your (.+?) kill count is:? (\\d[\\d,]*)\\.?");

	private static final Pattern COMPLETION_COUNT =
		Pattern.compile("Your (?:completed )?(.+?) (?:completion )?count is:? (\\d[\\d,]*)\\.?");

	/**
	 * Slugs (see slugify()) for the only three activities this
	 * collector will ever label RAID_COMPLETION. VERIFY: exact
	 * in-game wording for each (e.g. Challenge Mode variants) may
	 * slugify differently than assumed here — check against real
	 * completion messages during manual testing and extend this set
	 * rather than loosening the classification logic itself.
	 */
	static final Set<String> RAID_IDS = new HashSet<>();
	static
	{
		RAID_IDS.add("chambers_of_xeric");
		RAID_IDS.add("theatre_of_blood");
		RAID_IDS.add("tombs_of_amascut");
	}

	private final Client client;
	private final LocalStateStore store;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;
	private final KnownBossRegistry knownBossRegistry;

	/**
	 * eventId uniqueness only protects against uploading the same event
	 * twice — it does nothing to
	 * stop this collector from OBSERVING and emitting the same real
	 * game event twice in the first place (e.g. two chat messages
	 * with an identical count due to a client redraw, or genuinely
	 * re-processing the same message). Tracked per accountHash so one
	 * account's kill counts never suppress another's, and cleared on
	 * account switch (see resetForAccountSwitch()).
	 */
	private final Map<String, Integer> lastObservedCount = new ConcurrentHashMap<>();

	@Inject
	public ActivityKillCountCollector(Client client, LocalStateStore store, EventLedger eventLedger, OsrsTelemetryConfig config, KnownBossRegistry knownBossRegistry)
	{
		this.client = client;
		this.store = store;
		this.eventLedger = eventLedger;
		this.config = config;
		this.knownBossRegistry = knownBossRegistry;
	}

	public void resetForAccountSwitch()
	{
		lastObservedCount.clear();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.collectBossKc())
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());

		Matcher bossMatch = BOSS_KC.matcher(message);
		if (bossMatch.find())
		{
			recordKillCount(bossMatch.group(1), parseCount(bossMatch.group(2)));
			return;
		}

		Matcher completionMatch = COMPLETION_COUNT.matcher(message);
		if (completionMatch.find())
		{
			recordCompletionCount(completionMatch.group(1), parseCount(completionMatch.group(2)));
		}
	}

	/** Pure — unit-testable without a Client. Stable and idempotent:
	 * the same display name always slugifies to the same activityId,
	 * so re-observing the same message (e.g. after a client restart)
	 * updates the same activity file rather than creating a duplicate. */
	static String slugify(String displayName)
	{
		return displayName.trim().toLowerCase().replaceAll("[^a-z0-9]+", "_");
	}

	/** Pure — unit-testable without a Client. */
	static EventType classifyCompletion(String activityId)
	{
		return RAID_IDS.contains(activityId) ? EventType.RAID_COMPLETION : EventType.ACTIVITY_COMPLETION;
	}

	private int parseCount(String raw)
	{
		return Integer.parseInt(raw.replace(",", ""));
	}

	private void recordKillCount(String rawDisplayName, int count)
	{
		String displayName = rawDisplayName.trim();
		String activityId = slugify(displayName);

		// Task 5: recorded BEFORE the countAdvanced() early-return below --
		// a real, authoritative kill-count message confirms this boss name
		// for BossActivityContextCollector's resolution regardless of
		// whether the count itself advanced (e.g. a duplicate/redraw
		// re-observation of the same message is still genuine confirmation
		// that this boss name is real for this account, even though it is
		// not new forward progress for the KC state file/BOSS_KILL event
		// below). See KnownBossRegistry's own javadoc.
		knownBossRegistry.recordConfirmedBoss(client.getAccountHash(), displayName);

		if (!countAdvanced(activityId, count))
		{
			return;
		}

		writeState(activityId, displayName, count);
		eventLedger.append(
			client.getAccountHash(),
			EventType.BOSS_KILL,
			new EventPayloads.BossKill(activityId, displayName, count, "AUTHORITATIVE")
		);
	}

	private void recordCompletionCount(String rawDisplayName, int count)
	{
		String displayName = rawDisplayName.trim();
		String activityId = slugify(displayName);

		if (!countAdvanced(activityId, count))
		{
			return;
		}

		writeState(activityId, displayName, count);

		EventType eventType = classifyCompletion(activityId);
		Object payload = eventType == EventType.RAID_COMPLETION
			? new EventPayloads.RaidCompletion(activityId, displayName, count, "AUTHORITATIVE")
			: new EventPayloads.ActivityCompletion(activityId, displayName, count, "AUTHORITATIVE");

		eventLedger.append(client.getAccountHash(), eventType, payload);
	}

	/**
	 * @return true if this observation represents real forward
	 * progress (count strictly greater than the last one seen for
	 * this activity) and should therefore produce state/event output.
	 * A duplicate or non-advancing observation (same count seen
	 * again, or a stale/out-of-order lower count) is silently ignored
	 * — not written, not emitted.
	 */
	private boolean countAdvanced(String activityId, int count)
	{
		String key = client.getAccountHash() + ":" + activityId;
		Integer previous = lastObservedCount.get(key);
		if (!isAdvancing(previous, count))
		{
			return false;
		}
		lastObservedCount.put(key, count);
		return true;
	}

	/** Pure — unit-testable without a Client. previous == null means
	 * "never seen before", which always counts as advancing (it's new
	 * information, not a duplicate). */
	static boolean isAdvancing(Integer previous, int newCount)
	{
		return previous == null || newCount > previous;
	}

	private void writeState(String activityId, String displayName, int count)
	{
		ActivityState state = new ActivityState(activityId);
		state.setDisplayName(displayName);
		state.setSource(ActivityState.Source.AUTHORITATIVE);
		state.setKillCount(count);
		state.setLastUpdatedAt(Instant.now().toString());

		store.write(
			TelemetryPaths.activityFile(client.getAccountHash(), activityId),
			state
		);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Duration;
import java.time.Instant;
import java.util.List;

/**
 * Deduplication baseline for immutable bank snapshots. Deliberately
 * split into two independent pieces:
 *
 * 1. shouldWriteNewSnapshot() — pure, no I/O, no Client — the actual
 *    decision rule, unit-testable in isolation.
 * 2. loadFrom() — the only piece that touches disk, isolated so it can
 *    fail open cleanly and be tested with just a LocalStateStore
 *    (no RuneLite Client needed either, since it only needs the raw
 *    accountHash long, not a live game session).
 *
 * "Absent" (items == null, createdAt == null) represents both cases
 * where no valid baseline exists: never observed before, AND a failed
 * or corrupt load. Both must behave identically — always write a new
 * snapshot rather than risk suppressing a real one — which is why
 * there's a single isPresent() check rather than separate flags for
 * "never loaded" vs "load failed".
 *
 * The baseline also carries the snapshotId of the immutable file it
 * was built from -- an earlier version of this class tracked only
 * items/createdAt, so nothing in memory remembered which immutable
 * snapshot bank.json's pointer
 * should keep referencing between real snapshots. ContainerCollector
 * uses getSnapshotId() to re-stamp bank.json's latestSnapshotId on
 * every ordinary write (Path A) and on dedup-skip refreshes (Path B),
 * instead of leaving the field null (and therefore omitted by Gson)
 * whenever an immutable snapshot isn't being written on that exact
 * observation.
 */
final class BankSnapshotBaseline
{
	private final List<StorageState.StorageItem> items;
	private final Instant createdAt;
	private final String snapshotId;

	private BankSnapshotBaseline(List<StorageState.StorageItem> items, Instant createdAt, String snapshotId)
	{
		this.items = items;
		this.createdAt = createdAt;
		this.snapshotId = snapshotId;
	}

	static BankSnapshotBaseline absent()
	{
		return new BankSnapshotBaseline(null, null, null);
	}

	/**
	 * Convenience overload for tests/call sites that don't care about
	 * snapshotId tracking (pure decision-rule tests A-F). snapshotId is
	 * left null in that case — fine, since shouldWriteNewSnapshot()
	 * never reads it.
	 */
	static BankSnapshotBaseline of(List<StorageState.StorageItem> items, Instant createdAt)
	{
		return of(items, createdAt, null);
	}

	static BankSnapshotBaseline of(List<StorageState.StorageItem> items, Instant createdAt, String snapshotId)
	{
		return new BankSnapshotBaseline(items, createdAt, snapshotId);
	}

	boolean isPresent()
	{
		return items != null && createdAt != null;
	}

	/**
	 * The immutable snapshot id this baseline was built from — the
	 * value bank.json's latestSnapshotId should keep pointing at until
	 * a NEW immutable snapshot is successfully written and replaces it.
	 * Null when isPresent() is false; callers must check isPresent()
	 * (or tolerate null) before relying on this.
	 */
	String getSnapshotId()
	{
		return snapshotId;
	}

	/** Package-private test hook — production code has no legitimate
	 * reason to read this back (the whole point of the pure decision
	 * rule is that callers pass "now" in and get a boolean out), but
	 * tests need it to assert the createdAt clock genuinely didn't
	 * advance across a run of refresh-only observations. */
	Instant getCreatedAt()
	{
		return createdAt;
	}

	/**
	 * Loads the persisted baseline for one account: bank.json's
	 * latestSnapshotId, then that snapshot file's items/lastObservedAt.
	 * Fails open (returns absent()) on literally anything unexpected —
	 * missing pointer, missing/unset latestSnapshotId, missing
	 * snapshot file, missing/malformed fields, a timestamp that
	 * doesn't parse. A failed load must never be distinguishable from
	 * "never observed before" in terms of behavior — both mean "write
	 * a fresh snapshot," per the project's existing "unknown is not
	 * zero" principle applied here to "unknown baseline is not a
	 * matching baseline."
	 */
	static BankSnapshotBaseline loadFrom(LocalStateStore store, long accountHash)
	{
		try
		{
			StorageState pointer = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
			if (pointer == null || pointer.getLatestSnapshotId() == null)
			{
				return absent();
			}

			StorageState snapshot = store.readIfExists(
				TelemetryPaths.bankSnapshotFile(accountHash, pointer.getLatestSnapshotId()), StorageState.class);
			if (snapshot == null || snapshot.getItems() == null || snapshot.getLastObservedAt() == null)
			{
				return absent();
			}

			return of(snapshot.getItems(), Instant.parse(snapshot.getLastObservedAt()), pointer.getLatestSnapshotId());
		}
		catch (Exception e)
		{
			// Instant.parse can throw on a malformed timestamp; treat
			// exactly like every other failure mode here — fail open.
			return absent();
		}
	}

	/**
	 * Pure decision rule — no I/O, no Client, fully unit-testable.
	 *
	 *   shouldWrite = no valid baseline
	 *              OR bank contents changed
	 *              OR baseline is >= maxAge old
	 *
	 * Content equality is plain List.equals() on StorageItem, which
	 * (being @Data) already compares slot/itemId/name/quantity/
	 * equipmentSlot per element — reordering changes which item sits
	 * at which slot, which List.equals() correctly detects without
	 * needing any custom comparison logic.
	 *
	 * baseline.createdAt means "timestamp of the most recent
	 * SUCCESSFULLY WRITTEN immutable snapshot" — NOT "timestamp of the
	 * most recent bank observation." Callers must only ever advance it
	 * via a successful snapshot write (see ContainerCollector's
	 * recordBankBaseline(), called exclusively from a write's
	 * onWritten/writeAndWait-success callback), never from an ordinary
	 * refresh-only observation. This method has no way to enforce that
	 * itself — it only ever reads baseline.createdAt — so the guarantee
	 * lives entirely in when/where the caller constructs a new
	 * baseline.
	 */
	static boolean shouldWriteNewSnapshot(
		BankSnapshotBaseline baseline,
		List<StorageState.StorageItem> candidateItems,
		Instant now,
		Duration maxAge)
	{
		if (!baseline.isPresent())
		{
			return true;
		}
		if (!baseline.items.equals(candidateItems))
		{
			return true;
		}
		return Duration.between(baseline.createdAt, now).compareTo(maxAge) >= 0;
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.model.SkillsState;
import com.osrstelemetry.plugin.session.SessionRuntimeCoordinator;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * State-file freshness and XP_CHANGE event
 * cadence are two independent things, driven by two separate
 * calls from the plugin's GameTick handler. flushStateIfDirty() can
 * still run every tick (cheap — one small JSON write) so skills.json
 * stays current, but closeXpWindowsIfDue() only actually emits/resets
 * on the slow cadence (~30s, see plugin's tick counter) — training
 * continuously no longer produces one XP_CHANGE event every 0.6s.
 *
 * LEVEL_UP remains immediate/undebounced in onStatChanged(), since
 * it's a discrete milestone, not a rate to aggregate.
 */
public class SkillsCollector
{
	private final Client client;
	private final LocalStateStore store;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;
	private final SessionRuntimeCoordinator sessionRuntimeCoordinator;
	private final SkillsState state = new SkillsState();

	private final Map<String, Integer> windowBaselineXp = new HashMap<>();
	private final Map<String, String> windowStart = new HashMap<>();

	/**
	 * Separate baseline for LEVEL_UP
	 * detection, independent of state.getSkills() and of
	 * windowBaselineXp. See onStatChanged()'s javadoc for the full
	 * root-cause trace — this is what actually fixes the confirmed
	 * live-validation bug (a LEVEL_UP per skill, all with
	 * previousLevel=0, firing within milliseconds of login).
	 */
	private final Map<String, Integer> lastKnownLevel = new HashMap<>();

	/**
	 * The exact combat skills EventType.RAW_COMBAT_XP_OBSERVED
	 * is allowed to fire for -- Skill enum constants, not strings, so
	 * there is no casing ambiguity with skill.name(). Deliberately
	 * EXCLUDES Skill.MAGIC: mirrors ActivitySignalClassifier.isMagicXpSkill()'s
	 * own "Magic XP is lifecycle-ambiguous, never lifecycle proof" rule
	 * (teleports/alchemy/utility casts, not just combat) -- see that
	 * method's own javadoc. This set exists purely to bound EVENT VOLUME
	 * at the source (this collector emits far more often than
	 * closeXpWindowsIfDue()'s slow cadence, since it reacts to every raw
	 * StatChanged); ActivitySignalClassifier.classifyRawCombatXpObserved()
	 * independently re-checks isCombatSkill()/isMagicXpSkill() as
	 * defense in depth, so this set is never the sole guarantee.
	 */
	private static final Set<Skill> RAW_COMBAT_SKILLS = EnumSet.of(
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS);

	/**
	 * Per-skill "last observed XP" baseline for the
	 * IMMEDIATE raw-pulse detection in onStatChanged() below --
	 * deliberately a SEPARATE map from windowBaselineXp (XP_CHANGE's own
	 * aggregation baseline): this code path must never change XP_CHANGE's
	 * accounting, so its own baseline map is left completely
	 * untouched. Same "seed-once-then-diff"
	 * discipline as windowBaselineXp/lastKnownLevel -- a skill's first
	 * observation this session (or since a reset) always seeds silently,
	 * never emits (see evaluateRawCombatXpPulse()).
	 */
	private final Map<String, Integer> lastKnownXpForRawPulse = new HashMap<>();

	/**
	 * Per-skill "last observed XP" baseline for the GENERIC
	 * (all-skills, not just combat) live-delta notification in
	 * onStatChanged() below -- a THIRD, separate baseline map from both
	 * windowBaselineXp (XP_CHANGE's own aggregation baseline) and
	 * lastKnownXpForRawPulse (RAW_COMBAT_XP_OBSERVED's own, combat-only
	 * lifecycle-evidence baseline): this code path must never change either of
	 * those, so its own baseline map is left completely
	 * untouched. Same "seed-once-then-diff,
	 * positive-only" discipline as the other two -- see
	 * evaluateLiveXpDelta().
	 */
	private final Map<String, Integer> lastKnownXpForLiveDelta = new HashMap<>();

	private volatile boolean dirty = false;

	@Inject
	public SkillsCollector(
		Client client,
		LocalStateStore store,
		EventLedger eventLedger,
		OsrsTelemetryConfig config,
		SessionRuntimeCoordinator sessionRuntimeCoordinator)
	{
		this.client = client;
		this.store = store;
		this.eventLedger = eventLedger;
		this.config = config;
		this.sessionRuntimeCoordinator = sessionRuntimeCoordinator;
	}

	/**
	 * Called on account switch, BEFORE AccountContext's stored
	 * accountHash is advanced to the new account — oldAccountHash is
	 * passed explicitly so any outstanding XP_CHANGE window is
	 * attributed to the account that actually earned it, not
	 * whichever account happens to be current by the time this runs.
	 */
	public void resetForAccountSwitch(long oldAccountHash)
	{
		closeXpWindowsFor(oldAccountHash);
		state.getSkills().clear();
		windowBaselineXp.clear();
		windowStart.clear();
		lastKnownLevel.clear();
		lastKnownXpForRawPulse.clear();
		lastKnownXpForLiveDelta.clear();
		dirty = false;
	}

	/**
	 * Called once on login/plugin enable to seed current levels/XP
	 * immediately rather than waiting for the next StatChanged. Gated
	 * on config, since this is
	 * called both on login and on re-enable via ConfigChanged — if
	 * Skills is disabled, this must not write state at all, not just
	 * skip emitting events.
	 *
	 * This deliberately does NOT ALSO seed
	 * windowBaselineXp/windowStart directly from this same read. Real
	 * telemetry forensics showed a burst of ~24 false XP_CHANGE events firing ~30s after
	 * every login, timed to XP_FLUSH_INTERVAL_TICKS — only possible if
	 * client.getSkillExperience(skill) here, called immediately on
	 * GameStateChanged(LOGGED_IN), was reading unsettled/incomplete XP
	 * for some skills, seeding a too-low baseline that the next,
	 * fully-synced periodic read then looked like a genuine gain
	 * against.
	 *
	 * This still writes state.getSkills() (so skills.json stays fresh
	 * immediately — freshness is not sacrificed) but no longer touches
	 * windowBaselineXp/windowStart at all. That job is now solely
	 * closeXpWindowsFor()'s: its own first-sighting guard (see its
	 * javadoc) silently establishes the baseline the first time each
	 * skill is evaluated on the plugin's existing periodic cadence,
	 * by which point RuneLite's data is reliably settled.
	 */
	public void captureInitialState()
	{
		if (!config.collectSkills())
		{
			return;
		}
		for (Skill skill : Skill.values())
		{
			int xp = client.getSkillExperience(skill);
			int level = client.getRealSkillLevel(skill);
			int boostedLevel = client.getBoostedSkillLevel(skill);
			state.getSkills().put(skill.name(), new SkillsState.SkillEntry(level, boostedLevel, xp));
		}
		dirty = true;
	}

	/**
	 * LEVEL_UP compares against lastKnownLevel rather than
	 * state.getSkills().get(skillName), because that map is
	 * populated by captureInitialState()'s own immediate, unsettled
	 * login-time read of client.getRealSkillLevel(skill) (the same
	 * client-sync-gap class of bug already fixed for quests/XP -- see
	 * QuestCollector/SkillsCollector's
	 * captureInitialState() javadocs). A prior implementation using that
	 * map produced ~10 LEVEL_UP events firing within milliseconds of
	 * login, every one with previousLevel=0 — only possible because
	 * captureInitialState() had already written a wrong level=0 entry
	 * into state.getSkills() for those skills, and the first genuine
	 * (correctly-synced) StatChanged then diffed against that poisoned
	 * baseline instead of treating it as a first observation.
	 *
	 * This is architecturally independent from the windowBaselineXp
	 * baseline: state.getSkills() is a DIFFERENT map
	 * from windowBaselineXp, seeded at a different point
	 * (captureInitialState(), not closeXpWindowsFor()), so the
	 * XP-window baseline and this one must each be handled on their own.
	 *
	 * LEVEL_UP compares against lastKnownLevel, a map that
	 * captureInitialState() deliberately never seeds (see its javadoc)
	 * — so the first StatChanged for each skill this session (or since
	 * the last reset) always finds previousLevel == null and silently
	 * seeds via evaluateLevelTransition() below, exactly mirroring
	 * evaluateXpWindow()'s null-baseline contract. Only a real later
	 * transition (e.g. 87 -> 88) against an already-established
	 * baseline emits LEVEL_UP.
	 *
	 * state.getSkills() itself is unchanged — it still updates on every
	 * StatChanged and is what skills.json is written from; it's simply
	 * no longer used as the LEVEL_UP comparison baseline.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!config.collectSkills())
		{
			return;
		}

		Skill skill = event.getSkill();
		String skillName = skill.name();

		state.getSkills().put(
			skillName,
			new SkillsState.SkillEntry(event.getLevel(), event.getBoostedLevel(), event.getXp())
		);
		dirty = true;

		if (!windowBaselineXp.containsKey(skillName))
		{
			windowBaselineXp.put(skillName, event.getXp());
			windowStart.put(skillName, Instant.now().toString());
		}

		Integer previousLevel = lastKnownLevel.get(skillName);
		LevelTransitionResult result = evaluateLevelTransition(previousLevel, event.getLevel());

		if (result.shouldEmit)
		{
			eventLedger.append(
				client.getAccountHash(),
				EventType.LEVEL_UP,
				new EventPayloads.LevelUp(skillName, previousLevel, event.getLevel(), event.getXp())
			);
		}

		lastKnownLevel.put(skillName, event.getLevel());

		if (RAW_COMBAT_SKILLS.contains(skill))
		{
			Integer previousRawXp = lastKnownXpForRawPulse.get(skillName);
			lastKnownXpForRawPulse.put(skillName, event.getXp());
			RawCombatXpPulseResult pulseResult = evaluateRawCombatXpPulse(previousRawXp, event.getXp());
			if (pulseResult.shouldEmit)
			{
				eventLedger.append(
					client.getAccountHash(),
					EventType.RAW_COMBAT_XP_OBSERVED,
					new EventPayloads.RawCombatXpObserved(skillName)
				);
			}
		}

		// Deliberately GENERIC across every RuneLite skill above -- unlike
		// RAW_COMBAT_SKILLS above, which exists only to bound
		// RAW_COMBAT_XP_OBSERVED's own lifecycle-evidence volume. This is
		// a SEPARATE, small live-XP notification path (see
		// SessionRuntimeCoordinator.recordLiveXpDelta()'s own javadoc):
		// it never reuses RAW_COMBAT_XP_OBSERVED as an XP-value transport
		// (that signal structurally carries no XP value at all -- see its
		// own javadoc), never touches EventLedger/durable storage, and
		// never affects windowBaselineXp/lastKnownXpForRawPulse in any
		// way. lastKnownXpForLiveDelta is its own third, independent
		// baseline map -- see evaluateLiveXpDelta()'s own javadoc for the
		// seed-once-then-diff, positive-only contract that keeps a first
		// observation (or an account switch's fresh baseline) from ever
		// being misread as an instantaneous live gain, and a decrease/
		// reset/reseed from ever fabricating a positive one.
		Integer previousLiveXp = lastKnownXpForLiveDelta.get(skillName);
		lastKnownXpForLiveDelta.put(skillName, event.getXp());
		long liveDelta = evaluateLiveXpDelta(previousLiveXp, event.getXp());
		if (liveDelta > 0)
		{
			sessionRuntimeCoordinator.recordLiveXpDelta(skillName, liveDelta);
		}

		// Deliberately UNCONDITIONAL (unlike the gated
		// recordLiveXpDelta() dispatch above) -- this is not a display
		// concern, it is "the latest known absolute XP for this skill,
		// full stop," and even a skill's very first (seed-only)
		// observation is a genuine, exact absolute baseline worth
		// keeping. See SessionRuntimeCoordinator.noteAbsoluteXp()'s own
		// javadoc for how this feeds an exact split of an XP_CHANGE
		// window that spans a real session switch.
		sessionRuntimeCoordinator.noteAbsoluteXp(skillName, event.getXp());
	}

	/**
	 * Without this method, OsrsTelemetryPlugin's collectSkills
	 * re-enable branch calling ONLY captureInitialState() would leave a
	 * bug: since captureInitialState() correctly does not touch
	 * windowBaselineXp/windowStart/lastKnownLevel (see its own javadoc),
	 * and nothing else clears or reseeds those maps on disable either
	 * (onConfigChanged()'s disable branch is intentionally a no-op — see
	 * its own javadoc), they would simply keep whatever value they held
	 * from before Skills was disabled. Both onStatChanged() and
	 * closeXpWindowsFor() are gated
	 * on config.collectSkills() and no-op while disabled, so
	 * state.getSkills() also goes stale during that window — meaning any
	 * XP/level actually gained while disabled would, at the first real
	 * StatChanged after re-enable, get diffed against the STALE
	 * pre-disable baseline instead of a fresh one — fabricating a single
	 * XP_CHANGE/LEVEL_UP that misrepresents an entire disabled-period
	 * gap as an instantaneous post-re-enable change: "persistence state
	 * accidentally reused as comparison state." This method is what
	 * prevents it.
	 *
	 * Unlike the LOGIN case (where seeding must be deferred because the
	 * very first read can be unsettled — see captureInitialState()'s own
	 * javadoc), re-enabling mid-session has NO sync-gap risk: the client
	 * has already been logged in and running normally, so an immediate
	 * reseed from the read captureInitialState() just took is safe.
	 * Mirrors SlayerCollector.seedSilently() and
	 * QuestCollector.checkAndFlush() — both already reseed immediately
	 * and unconditionally at their own re-enable call sites for the same
	 * reason.
	 *
	 * Called ONLY from OsrsTelemetryPlugin.onConfigChanged()'s
	 * collectSkills re-enable branch, immediately after
	 * captureInitialState() has refreshed state.getSkills().
	 */
	public void reseedTransitionBaselinesSilently()
	{
		if (!config.collectSkills())
		{
			return;
		}
		windowBaselineXp.clear();
		windowStart.clear();
		lastKnownLevel.clear();
		lastKnownXpForRawPulse.clear();
		String now = Instant.now().toString();
		for (Map.Entry<String, SkillsState.SkillEntry> entry : state.getSkills().entrySet())
		{
			windowBaselineXp.put(entry.getKey(), entry.getValue().getXp());
			windowStart.put(entry.getKey(), now);
			lastKnownLevel.put(entry.getKey(), entry.getValue().getLevel());
			lastKnownXpForRawPulse.put(entry.getKey(), entry.getValue().getXp());
		}
	}

	/**
	 * Pure, Client/EventLedger-independent core of the LEVEL_UP
	 * decision — factored out for the same reason as
	 * evaluateXpWindow()/QuestCollector.justFinished(): unit-testable
	 * without mocking RuneLite's Client. previousLevel == null means
	 * this skill has never been observed since the last reset — always
	 * seed silently, never emit, regardless of currentLevel (this is
	 * the property that makes an initial/unsynced-then-corrected read
	 * safe: an existing level 87 first observed as 87 can never be
	 * misreported as 0 -> 87). A real transition only exists once a
	 * baseline is already established AND currentLevel is strictly
	 * greater than it.
	 */
	static LevelTransitionResult evaluateLevelTransition(Integer previousLevel, int currentLevel)
	{
		if (previousLevel == null)
		{
			return LevelTransitionResult.seed();
		}
		if (currentLevel > previousLevel)
		{
			return LevelTransitionResult.levelUp();
		}
		return LevelTransitionResult.noChange();
	}

	static final class LevelTransitionResult
	{
		final boolean shouldEmit;

		private LevelTransitionResult(boolean shouldEmit)
		{
			this.shouldEmit = shouldEmit;
		}

		static LevelTransitionResult seed()
		{
			return new LevelTransitionResult(false);
		}

		static LevelTransitionResult levelUp()
		{
			return new LevelTransitionResult(true);
		}

		static LevelTransitionResult noChange()
		{
			return new LevelTransitionResult(false);
		}
	}

	/**
	 * Pure, Client/EventLedger-independent core of the
	 * IMMEDIATE raw-combat-XP-pulse decision -- factored out for the
	 * exact same reason as evaluateXpWindow()/evaluateLevelTransition():
	 * unit-testable without mocking RuneLite's Client. previousXp ==
	 * null means this skill's raw-pulse baseline has never been observed
	 * since the last reset (fresh session, account switch, or Skills
	 * re-enable) -- always seed silently, never emit, regardless of
	 * currentXp's value, mirroring evaluateXpWindow()'s own "an existing
	 * large XP total must never be misread as an instantaneous gain on
	 * first observation" contract. A real pulse only exists once a
	 * baseline is already established AND currentXp is strictly greater
	 * than it (mirrors evaluateLevelTransition()'s strict-greater-than
	 * convention).
	 */
	static RawCombatXpPulseResult evaluateRawCombatXpPulse(Integer previousXp, int currentXp)
	{
		if (previousXp == null)
		{
			return RawCombatXpPulseResult.seed();
		}
		if (currentXp > previousXp)
		{
			return RawCombatXpPulseResult.pulse();
		}
		return RawCombatXpPulseResult.noChange();
	}

	static final class RawCombatXpPulseResult
	{
		final boolean shouldEmit;

		private RawCombatXpPulseResult(boolean shouldEmit)
		{
			this.shouldEmit = shouldEmit;
		}

		static RawCombatXpPulseResult seed()
		{
			return new RawCombatXpPulseResult(false);
		}

		static RawCombatXpPulseResult pulse()
		{
			return new RawCombatXpPulseResult(true);
		}

		static RawCombatXpPulseResult noChange()
		{
			return new RawCombatXpPulseResult(false);
		}
	}

	/**
	 * Pure, Client/EventLedger-independent core of the
	 * IMMEDIATE live-XP-delta decision, generalized across EVERY
	 * RuneLite skill -- unlike evaluateRawCombatXpPulse() above, this is
	 * never restricted to RAW_COMBAT_SKILLS, since Woodcutting/Agility/
	 * every other skill must update the live display too. Same
	 * "seed-once-then-diff, positive-only" discipline as
	 * evaluateRawCombatXpPulse()/evaluateXpWindow():
	 * {@code previousXp == null} means this skill's live-delta baseline
	 * has never been observed since the last reset (fresh session,
	 * account switch) -- always returns {@code 0L} (seed silently),
	 * regardless of {@code currentXp}'s value, exactly mirroring
	 * evaluateXpWindow()'s "an existing large XP total must never be
	 * misread as an instantaneous gain on first observation" contract.
	 * {@code currentXp <= previousXp} (no change, or a decrease/reset/
	 * reseed) also returns {@code 0L} -- this layer must never fabricate
	 * a positive live gain from either. Only a strictly-greater reading
	 * against an already-established baseline returns the genuine,
	 * positive delta.
	 */
	static long evaluateLiveXpDelta(Integer previousXp, int currentXp)
	{
		if (previousXp == null)
		{
			return 0L;
		}
		if (currentXp > previousXp)
		{
			return currentXp - previousXp;
		}
		return 0L;
	}

	public void flushStateIfDirty()
	{
		if (!config.collectSkills() || !dirty)
		{
			return;
		}
		dirty = false;
		state.setLastUpdated(Instant.now().toString());
		store.write(TelemetryPaths.stateFile(client.getAccountHash(), "skills"), state);
	}

	/** Called on the plugin's slow tick cadence (see plugin's
	 * XP_FLUSH_INTERVAL_TICKS), not every tick. */
	public void closeXpWindowsIfDue()
	{
		if (!config.collectSkills())
		{
			return;
		}
		closeXpWindowsFor(client.getAccountHash());
	}

	private void closeXpWindowsFor(long accountHash)
	{
		String now = Instant.now().toString();
		for (Map.Entry<String, SkillsState.SkillEntry> entry : state.getSkills().entrySet())
		{
			String skillName = entry.getKey();
			int currentXp = entry.getValue().getXp();

			Integer existingBaseline = windowBaselineXp.containsKey(skillName) ? windowBaselineXp.get(skillName) : null;
			XpWindowResult result = evaluateXpWindow(existingBaseline, currentXp);

			if (result.shouldSeed)
			{
				// First time this skill's window is evaluated this
				// session (or since a reset/clear) — silently establish
				// the baseline. See class javadoc: this is the FIX for
				// the startup false-XP_CHANGE-burst bug. Mirrors
				// QuestCollector.justFinished()'s null-previous guard:
				// XP that was already there before observation began
				// must never be reported as a gain. NOTE this also
				// fixes a pre-existing latent bug in the old
				// getOrDefault(...,currentXp) fallback, which computed
				// delta=0 correctly but never actually persisted a
				// baseline into the map — meaning an unseeded skill
				// could never self-bootstrap via this path at all.
				windowBaselineXp.put(skillName, currentXp);
				windowStart.put(skillName, now);
				continue;
			}

			if (result.delta > 0)
			{
				eventLedger.append(
					accountHash,
					EventType.XP_CHANGE,
					new EventPayloads.XpChange(
						skillName, existingBaseline, currentXp, result.delta,
						windowStart.getOrDefault(skillName, now), now
					)
				);
				windowBaselineXp.put(skillName, currentXp);
				windowStart.put(skillName, now);
			}
		}
	}

	/**
	 * Pure, Client/EventLedger-independent core of the "seed-once-then-
	 * diff" XP window decision — factored out for the same reason as
	 * QuestCollector.justFinished(): unit-testable without mocking
	 * RuneLite's Client. existingBaseline == null means this skill has
	 * never been evaluated since the last reset — always seed, never a
	 * delta, regardless of how large currentXp is (this is the
	 * property that makes an initial/incomplete-then-corrected read
	 * safe: whatever the first observed value is, it can only ever
	 * become the baseline, never a reported gain).
	 */
	static XpWindowResult evaluateXpWindow(Integer existingBaseline, int currentXp)
	{
		if (existingBaseline == null)
		{
			return XpWindowResult.seed();
		}
		return XpWindowResult.delta(currentXp - existingBaseline);
	}

	static final class XpWindowResult
	{
		final boolean shouldSeed;
		final int delta;

		private XpWindowResult(boolean shouldSeed, int delta)
		{
			this.shouldSeed = shouldSeed;
			this.delta = delta;
		}

		static XpWindowResult seed()
		{
			return new XpWindowResult(true, 0);
		}

		static XpWindowResult delta(int delta)
		{
			return new XpWindowResult(false, delta);
		}
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Two distinct data paths, deliberately not conflated:
 *
 * 1. NEW-ITEM NOTIFICATION (implemented here): the game prints "New
 *    item added to your collection log: <item name>" as a game
 *    message when you receive a log item, live, regardless of whether
 *    you've ever opened the collection log interface.
 *
 *    NOTE: this message's presence depends on the player's in-game
 *    "Collection log - New item"
 *    chat notification setting being turned on. If that setting is
 *    off, this collector observes nothing for that item — and,
 *    consistent with "unknown is not zero" throughout this project,
 *    the ABSENCE of this message must never be read as "no new item
 *    occurred." It only proves a new item occurred when it fires; it
 *    proves nothing when it doesn't.
 *
 *    Message text can carry RuneScape formatting tags (e.g. colour
 *    tags) — stripped via Text.removeTags() before matching, per the
 *    same utility RuneLite's own core plugins use for this.
 *
 * 2. FULL PAGE STATE (still NOT implemented): reconstructing a
 *    complete page (every item on e.g. the "Zulrah" page, obtained or
 *    not, with quantities) requires reading the collection log
 *    widget/script output when the player opens that page in-game. I
 *    still do not have confirmed, current widget/script IDs for this
 *    interface, and am not willing to guess them. RuneLite's own
 *    built-in net.runelite.client.plugins.collectionlog is the
 *    reference implementation to read before building this — that
 *    read has not happened yet; it remains an honest
 *    gap, not a silent one. Unseen/unopened pages must remain
 *    represented as unknown, never as "nothing obtained".
 */
public class CollectionLogCollector
{
	private static final Pattern NEW_ITEM =
		Pattern.compile("New item added to your collection log: (.+)");

	private final Client client;
	private final EventLedger eventLedger;
	private final OsrsTelemetryConfig config;

	@Inject
	public CollectionLogCollector(Client client, EventLedger eventLedger, OsrsTelemetryConfig config)
	{
		this.client = client;
		this.eventLedger = eventLedger;
		this.config = config;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!config.collectCollectionLog())
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		Matcher matcher = NEW_ITEM.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String itemName = matcher.group(1).trim();
		// itemId is deliberately null — the chat message doesn't carry
		// one, and resolving name -> ID by guessing would be worse than
		// leaving it unresolved (see EventPayloads.CollectionLogNewItem
		// javadoc). Fill this in once the full-page widget read exists.
		eventLedger.append(
			client.getAccountHash(),
			EventType.COLLECTION_LOG_NEW_ITEM,
			new EventPayloads.CollectionLogNewItem(null, itemName)
		);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Emits the non-authoritative, context-only
 * EventType.NPC_INTERACTION_TARGET signal -- see that constant's
 * javadoc for the full rationale.
 *
 * SIGNAL SELECTED: net.runelite.api.events.InteractingChanged, filtered
 * to event.getSource() == client.getLocalPlayer() and
 * event.getTarget() instanceof NPC -- the EXACT same technique
 * BossActivityContextCollector already uses (and Josh's own Windows
 * build already proved compiles/works against the real client jar for
 * that collector), deliberately reused rather than reinvented. The one
 * addition here is an explicit ATTACKABILITY check (see
 * isAttackableNpc()) so this collector never mistakes a banker,
 * shopkeeper, quest NPC, pet, or other merely-talked-to NPC for a
 * combat target merely because the player clicked it -- something
 * BossActivityContextCollector does not need, since KnownBossRegistry's
 * own name resolution already only ever matches previously-confirmed
 * boss names.
 *
 * ATTACKABLE NPC FILTERING: reads {@code npc.getTransformedComposition()}
 * (not the raw {@code npc.getComposition()}) -- the standard RuneLite
 * idiom for resolving an NPC's CURRENT visible form/composition,
 * correct across multi-form/transforming NPCs (quest-state swaps,
 * disguises, boss phase changes) without this collector needing to
 * understand any specific transform table itself. An NPC is treated as
 * genuinely attackable only when that composition's
 * {@code getActions()} array contains the exact menu-action string
 * "Attack" (the same right-click "Attack" option every attackable NPC
 * in OSRS exposes) -- a banker's "Bank"/"Collect"/"Exchange" actions,
 * a shopkeeper's "Trade", or a quest NPC's "Talk-to" never include
 * this, so they are correctly excluded with zero hand-maintained
 * NPC-name/ID list. {@code getTransformedComposition()} returning null
 * (an NPC mid-transform frame, or any other unresolved-composition
 * case) and a null/empty {@code getActions()} array are both handled
 * defensively as "not attackable" -- never as "attackable by default."
 *
 * DEDUP / HEARTBEAT DESIGN: mirrors BossActivityContextCollector's own
 * decide()/lastTrackedBossByAccount precedent exactly, for the exact
 * same reason -- a single continuous fight can produce many
 * InteractingChanged deliveries for the SAME attackable NPC name
 * (instance swaps, sub-target flicker) that would otherwise flood
 * events.jsonl with redundant NPC_INTERACTION_TARGET signals carrying
 * no new information. decide() tracks, per account, the attackable NPC
 * name the player is CURRENTLY understood to be targeting and only
 * emits when that name actually CHANGES -- including changing to null
 * when the interaction ends or moves to a non-attackable/non-NPC
 * target, so re-engaging the SAME NPC later (after a genuine break)
 * emits fresh context again rather than staying permanently deduped.
 * Deliberately keyed by NAME ONLY, not by NPC id -- see
 * ActivitySignalClassifier.genericNpcCombatIdentity()'s own javadoc for
 * why generic combat identity itself is name-based (a boss/monster that
 * legitimately changes runtime NPC id mid-fight, e.g. a phase
 * transition, must not read as "a different NPC" here either).
 *
 * NO PLAYER-FACING TOGGLE: matches BossActivityContextCollector's own
 * "runs unconditionally whenever the plugin/session runtime is
 * enabled" design -- there is deliberately no config item gating this
 * collector.
 */
public class NpcInteractionTargetCollector
{
	private final Client client;
	private final EventLedger eventLedger;

	/**
	 * Per-account "which attackable NPC name (if any) is the local
	 * player currently understood to be targeting" -- see class
	 * javadoc's DEDUP / HEARTBEAT DESIGN section. Absent/null means "not
	 * currently targeting a recognized attackable NPC."
	 */
	private final Map<Long, String> lastTrackedNpcNameByAccount = new ConcurrentHashMap<>();

	/**
	 * Parallel to lastTrackedNpcNameByAccount -- the numeric NPC id last observed for
	 * whichever attackable NPC the player is currently tracked as
	 * targeting (see onInteractingChanged()). Kept in sync whenever a
	 * name is tracked/cleared, independent of decide()'s own dedup gate,
	 * so it always reflects the freshest observed id for the current
	 * target even across an id change (e.g. a phase/instance swap) that
	 * decide() itself treats as "same NPC, no new signal." Purely
	 * read-only UI plumbing -- getCurrentNpcName()/getCurrentNpcId()
	 * below are the only new surface this adds; onInteractingChanged()'s
	 * own telemetry emission and decide()'s dedup logic are unchanged.
	 */
	private final Map<Long, Integer> lastTrackedNpcIdByAccount = new ConcurrentHashMap<>();

	@Inject
	public NpcInteractionTargetCollector(Client client, EventLedger eventLedger)
	{
		this.client = client;
		this.eventLedger = eventLedger;
	}

	public void resetForAccountSwitch(long accountHash)
	{
		lastTrackedNpcNameByAccount.remove(accountHash);
		lastTrackedNpcIdByAccount.remove(accountHash);
	}

	/**
	 * The attackable NPC name the local player is CURRENTLY understood to be targeting (the same
	 * value this collector would emit if decide() saw a change right
	 * now), or null. Safe to call off the client thread -- reads only
	 * this collector's own ConcurrentHashMaps and
	 * client.getAccountHash() (a cached identifier -- see
	 * OsrsTelemetryPlugin.shutDown()'s own comment on that same call
	 * being safe off-thread).
	 */
	public String getCurrentNpcName()
	{
		return lastTrackedNpcNameByAccount.get(client.getAccountHash());
	}

	/** Companion to getCurrentNpcName() -- the same target's NPC id, or null. */
	public Integer getCurrentNpcId()
	{
		return lastTrackedNpcIdByAccount.get(client.getAccountHash());
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Actor source = event.getSource();
		boolean sourceIsLocalPlayer = source != null && source == client.getLocalPlayer();
		if (!sourceIsLocalPlayer)
		{
			// Not the local player's own interaction -- irrelevant, and
			// left untouched: see decide()'s own doc for why this branch
			// never mutates tracked state either.
			return;
		}

		Actor target = event.getTarget();
		NPC npc = (target instanceof NPC) ? (NPC) target : null;

		String attackableNpcName = null;
		Integer npcId = null;
		if (npc != null)
		{
			NPCComposition composition = safeTransformedComposition(npc);
			String[] actions = composition == null ? null : safeActions(composition);
			if (isAttackableNpc(actions))
			{
				String name = safeName(composition);
				if (name != null)
				{
					attackableNpcName = name;
					npcId = safeNpcId(npc);
				}
			}
		}

		long accountHash = client.getAccountHash();

		// Keep the id map in sync with the name map on every call,
		// independent of decide()'s own dedup gate below -- see
		// lastTrackedNpcIdByAccount's own javadoc.
		if (attackableNpcName != null)
		{
			lastTrackedNpcIdByAccount.put(accountHash, npcId);
		}
		else
		{
			lastTrackedNpcIdByAccount.remove(accountHash);
		}

		String candidate = decide(true, attackableNpcName, accountHash, lastTrackedNpcNameByAccount);
		if (candidate == null)
		{
			return;
		}

		eventLedger.append(accountHash, EventType.NPC_INTERACTION_TARGET, new EventPayloads.NpcInteractionTarget(npcId, candidate));
	}

	private static NPCComposition safeTransformedComposition(NPC npc)
	{
		try
		{
			return npc.getTransformedComposition();
		}
		catch (RuntimeException e)
		{
			// Defensive only -- "handle null names/compositions/actions
			// safely" (HARD PRODUCT REQUIREMENT). Treated as
			// "unknown/not attackable" rather than propagating, exactly
			// like every other defensive read in this project (e.g.
			// SessionRuntimeCoordinator.safeTickCount()).
			return null;
		}
	}

	private static String[] safeActions(NPCComposition composition)
	{
		try
		{
			return composition.getActions();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static String safeName(NPCComposition composition)
	{
		try
		{
			return composition.getName();
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * npcId mirrors NpcDeathCollector.buildPayload()'s own "do not
	 * fabricate missing values" precedent: NPC#getId() carries no
	 * documented guarantee of always returning a real value (-1 is the
	 * conventional "not currently known" result, e.g. a mid-transform
	 * frame) -- any non-positive raw id is left null.
	 */
	private static Integer safeNpcId(NPC npc)
	{
		int rawId = npc.getId();
		return rawId >= 0 ? rawId : null;
	}

	/**
	 * Pure core attackability check, factored out so it is directly
	 * unit-testable with plain String[] input -- no NPCComposition
	 * mock/instance is needed (this project has no Mockito dependency).
	 * "Attack" is the exact, case-sensitive menu-action string OSRS/
	 * RuneLite uses for the ordinary attack option; a null actions array
	 * (unresolved composition) or a null-only/empty array (an NPC with
	 * no menu actions at all) both safely return false -- never true by
	 * default.
	 */
	static boolean isAttackableNpc(String[] actions)
	{
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if ("Attack".equals(action))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Pure core decision, factored out for the same reason as
	 * BossActivityContextCollector.decide() -- unit-testable without
	 * mocking RuneLite's EventBus/Client/Actor/NPC/NPCComposition types.
	 * `attackableNpcName` is null whenever the production caller already
	 * determined the interaction target is not the local player's own,
	 * not an NPC at all, not attackable, or has no resolvable name --
	 * this method makes no RuneLite-aware decision of its own, only the
	 * dedup/heartbeat one.
	 *
	 * `trackedByAccount` is mutated as a side effect, mirroring
	 * BossActivityContextCollector.decide()'s own documented tradeoff.
	 *
	 * @return the attackable NPC's display name to emit as a new
	 * NPC_INTERACTION_TARGET signal, or null if nothing should be
	 * emitted for this call (source not the local player, no attackable
	 * NPC target, or the tracked target name is unchanged from what is
	 * already tracked for this account).
	 */
	static String decide(
		boolean sourceIsLocalPlayer,
		String attackableNpcName,
		long accountHash,
		Map<Long, String> trackedByAccount)
	{
		if (!sourceIsLocalPlayer)
		{
			return null;
		}

		if (attackableNpcName == null)
		{
			// Interaction ended, target isn't an NPC, or the NPC isn't
			// genuinely attackable -- clear tracked state so a later
			// re-engagement with a genuinely attackable NPC (including
			// the SAME one) is treated as fresh evidence rather than
			// deduped away.
			trackedByAccount.remove(accountHash);
			return null;
		}

		String previouslyTracked = trackedByAccount.get(accountHash);
		if (attackableNpcName.equals(previouslyTracked))
		{
			return null;
		}

		trackedByAccount.put(accountHash, attackableNpcName);
		return attackableNpcName;
	}
}

